  method(cl, "opposite", function(d = NULL, ...) {
    return(m_index_of(self$offsets, neg(elem(self$offsets, d))))
    NULL
  })
  statik(cl, "shells", function(D = NULL, squared = NULL, ...) {
    radius <- r_add(elem(m_most(m_map(squared, function(s = NULL, ...) {
      return(m_floor(m_sqrt(s)))
      NULL
    }), function(r = NULL, ...) {
      return(r)
      NULL
    }), 0), 1)
    all <- m_sorted_by(filt(Geometry$box(D, radius), function(v = NULL, ...) {
      return(gt(v$norm, 0))
      NULL
    }), function(v = NULL, ...) {
      return(v$norm)
      NULL
