    chosen <- lst()
    .r <- for_each(squared, function(s) {
      .r <- for_each(all, function(v) {
        if (truthy(eq(v$dot(v), s))) {
          m_push(chosen, v)
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    joined <- m_join(squared, "+")
    return(Geometry$new(name = "shells-" %+% text_of(D) %+% "-" %+% text_of(joined) %+% "", offsets = chosen))
    NULL
  })
  statik(cl, "nearest", function(D = NULL, DEG = NULL, ...) {
    radius <- 1
    candidates <- lst()
    while (truthy(lt(len(candidates), DEG))) {
      .w("candidates", filt(Geometry$box(D, radius), function(v = NULL, ...) {
        return(gt(v$norm, 0))
        NULL
      }))
      .w("candidates", m_sorted_by(candidates, function(v = NULL, ...) {
        return(v$norm)
        NULL
      }))
      .w("radius", r_add(radius, 1))
