    cut <- elem(candidates, r_sub(DEG, 1))$norm
    chosen <- filt(candidates, function(v = NULL, ...) {
      return(le(v$norm, cut))
      NULL
    })
    if (!truthy(eq(len(chosen), DEG))) stop("eq(len(chosen), DEG)")
    return(Geometry$new(name = "nearest-" %+% text_of(D) %+% "-" %+% text_of(DEG) %+% "", offsets = chosen))
    NULL
  })
