    if (truthy(eq(tags, NULL))) {
      .w("tags", 1)
    }
    if (truthy(eq(D, NULL))) {
      .w("D", NULL)
    }
    return(Medium$new(theory = self, N = N, A = A, K = K, DEG = or_else(DEG, self$lattice$DEG), tags = tags, D = or_else(D, self$lattice$D)))
    NULL
  })
  getter(cl, "proved", function() {
    if (truthy(eq(elem(Prover$PROOFS, self$name), NULL))) {
      set_at(Prover$PROOFS, self$name, Prover$new(theory = self)$proof)
    }
    return(elem(Prover$PROOFS, self$name))
    NULL
  })
})

World <- ray_class("World", Node, function(cl) {
  field(cl, "theory", NULL)
  field(cl, "geometry", NULL)
  field(cl, "N", NULL)
  field(cl, "seed", NULL)
  field(cl, "bound", NULL)
  field(cl, "ticks", function() 0)
  field(cl, "vertices", function() lst())
  field(cl, "margin", function() 0)
  field(cl, "random", function() Random$new(seed = self$seed))
  field(cl, "expands", function() TRUE)
  field(cl, "folded", function() 0)
  field(cl, "annihilations", function() 0)
  field(cl, "created", function() 0)
  getter(cl, "laid", function() {
    .r <- for_each(self$positions(self$N), function(p) {
      self$place(p)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(self)
    NULL
  })
  method(cl, "positions", function(N = NULL, ...) {
    points <- lst(Vector$new(components = lst()))
    i <- 0
    while (truthy(lt(i, self$geometry$D))) {
      grown <- lst()
      .r <- for_each(points, function(p) {
        k <- 0
        while (truthy(lt(k, N))) {
          m_push(grown, Vector$new(components = m_concat(p$components, lst(k))))
          .w("k", r_add(k, 1))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .w("points", grown)
      .w("i", r_add(i, 1))
    }
    return(points)
    NULL
  })
  method(cl, "place", function(at = NULL, ...) {
    if (truthy(ge(len(self$vertices), self$bound))) {
      return(NULL)
    }
    if (truthy((!truthy(self$within_margin(at))))) {
      return(NULL)
    }
    standing <- self$at(at)
    v <- Vertex$new(world = self, at = at, ordinal = len(self$vertices))
    .r <- for_range(self$geometry$DEG, function(d) {
      r <- Ray$new(vertex = v, exit = d)
      .set(r$initial, "ray", r)
      .set(r$terminal, "ray", r)
      .set(r$initial, "vertex", v)
      .set(r$terminal, "vertex", v)
      m_push(v$rays, r)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .set(v, "folds", m_map(v$rays, function(v__ = NULL, ...) {
      return(0)
      NULL
    }))
    if (truthy((!eq(standing, NULL)))) {
      standing$hold(v)
    }
    m_push(self$vertices, v)
    if (truthy(v$alive)) {
      m_push(self$living, v)
    }
    if (truthy(v$alive)) {
      set_at(self$positions_index, v$at$key, v)
    }
    if (truthy((!eq(standing, NULL)))) {
      return(v)
    }
    .r <- for_range(self$geometry$DEG, function(d) {
      there <- self$at(r_add(at, elem(self$geometry$offsets, d)))
      if (truthy((!eq(there, NULL)))) {
        Edge$new()$link(elem(v$rays, d)$terminal, elem(there$rays, self$geometry$opposite(d))$terminal)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(v)
    NULL
  })
  method(cl, "within_margin", function(at = NULL, ...) {
    return(m_every(at$components, function(c = NULL, ...) {
      return((if (truthy(.x <- ge(c, r_sub(0, self$margin)))) lt(c, r_add(self$N, self$margin)) else .x))
      NULL
    }))
    NULL
  })
  method(cl, "make", function(here = NULL, d = NULL, ...) {
    return(self$place(r_add(here$at, elem(self$geometry$offsets, d))))
    NULL
  })
  method(cl, "grow", function(at = NULL, ...) {
    return(self$place(at))
    NULL
  })
  method(cl, "relocate", function(v = NULL, position = NULL, ...) {
    .set(v, "at", position)
    NULL
  })
  method(cl, "at", function(position = NULL, ...) {
    return(m_first(filt(self$vertices, function(v = NULL, ...) {
      return((if (truthy(.x <- v$alive)) eq(v$at, position) else .x))
      NULL
    })))
    NULL
  })
  getter(cl, "live", function() {
    return(filt(self$vertices, function(v = NULL, ...) {
      return(v$alive)
      NULL
    }))
    NULL
  })
  method(cl, "all", function(kind = NULL, ...) {
    if (truthy(eq(kind, "World"))) {
      return(lst(self))
    }
    if (truthy(eq(kind, "Vertex"))) {
      return(self$live)
    }
    if (truthy(eq(kind, "Source"))) {
      return(self$sources)
    }
    if (truthy(eq(kind, "Ray"))) {
      return(m_map(self$live, function(v = NULL, ...) {
        return(many(v$rays))
        NULL
      }))
    }
    rays <- lst()
    .r <- for_each(self$live, function(v) {
      .r <- for_each(v$rays, function(r) {
        m_push(rays, r)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    if (truthy(eq(kind, "Boundary"))) {
      return(m_map(rays, function(r = NULL, ...) {
        return(r$terminal)
        NULL
      }))
    }
    if (truthy(eq(kind, "Edge"))) {
      edges <- lst()
      .r <- for_each(rays, function(r) {
        there <- r$ahead
        if (truthy((if (truthy(.x <- (!eq(there, NULL)))) lt(r$vertex$ordinal, there$ordinal) else .x))) {
          m_push(edges, r$terminal$edge)
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      return(edges)
    }
    return(lst())
    NULL
  })
  getter(cl, "tick", function() {
    self$ticks <- r_add(self$ticks, 1)
    .r <- for_each(self$sources, function(s) {
      .set(s, "stepped", FALSE)
      .set(s, "moved_along", NULL)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_each(self$theory$rules, function(rule) {
      .r <- for_each(rule$matches(self), function(x) {
        rule$apply(x)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  method(cl, "draw", function(weights = NULL, outcomes = NULL, ...) {
    ws <- lst()
    os <- lst()
    .r <- for_range(len(weights), function(i) {
      if (truthy(is_list(elem(weights, i)))) {
        .r <- for_range(len(elem(weights, i)), function(j) {
          m_push(ws, elem(elem(weights, i), j))
          m_push(os, function(...) {
            return((elem(outcomes, i))(j))
            NULL
          })
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
      } else {
        m_push(ws, elem(weights, i))
        m_push(os, function(...) {
          return(elem(outcomes, i))
          NULL
        })
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    total <- m_sum(ws)
    pick <- r_mul(self$random$v_next, total)
    .r <- for_range(len(ws), function(i) {
      .w("pick", r_sub(pick, elem(ws, i)))
      if (truthy((if (truthy(.x <- le(pick, 0))) .x else eq(i, r_sub(len(ws), 1))))) {
        return((elem(os, i))())
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(NULL)
    NULL
  })
  getter(cl, "rays", function() {
    return(m_sum(m_map(self$live, function(v = NULL, ...) {
      return(len(filt(v$rays, function(r = NULL, ...) {
        return(r$active)
        NULL
      })))
      NULL
    })))
    NULL
  })
  getter(cl, "points", function() {
    return(len(self$live))
    NULL
  })
  field(cl, "living", function() lst())
  field(cl, "positions_index", function() Node$new())
  method(cl, "at_indexed", function(position = NULL, ...) {
    v <- elem(self$positions_index, position$key)
    if (truthy(eq(v, NULL))) {
      return(NULL)
    }
    if (truthy((!truthy(v$alive)))) {
      return(NULL)
    }
    if (truthy((!truthy((eq(v$at, position)))))) {
      return(NULL)
    }
    return(v)
    NULL
  })
  field(cl, "sources", function() lst())
  method(cl, "add", function(source = NULL, ...) {
    .set(source, "world", self)
    .set(source, "momentum", Vector$zero(self$geometry$D))
    .set(source, "advance", Vector$zero(self$geometry$D))
    .set(source, "cells", (if (truthy((!eq(source$half, NULL)))) self$box(source$at, source$half) else self$within(source$at, source$radius)))
    .r <- for_each(source$cells, function(c) {
      .set(c, "source", source)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    m_push(self$sources, source)
    return(source)
    NULL
  })
  method(cl, "within", function(centre = NULL, radius = NULL, ...) {
    return(filt(self$vertices, function(v = NULL, ...) {
      return(le((r_sub(v$at, centre))$norm, radius))
      NULL
    }))
    NULL
  })
  method(cl, "box", function(centre = NULL, half = NULL, ...) {
    return(filt(self$vertices, function(v = NULL, ...) {
      return(m_every(rng(self$geometry$D), function(i = NULL, ...) {
        return(le(m_abs((r_sub(elem(v$at$components, i), elem(centre$components, i)))), elem(half, i)))
        NULL
      }))
      NULL
    }))
    NULL
  })
})

