  field(cl, "advance", NULL)
  field(cl, "stepped", function() FALSE)
  field(cl, "moved_along", function() NULL)
  getter(cl, "spare", function() {
    return((!truthy(self$stepped)))
    NULL
  })
  getter(cl, "mass", function() {
    return((choose_(self, "mass"))())
    NULL
  })
  field(cl, "absorbs", function() TRUE)
  method(cl, "choose emit?", function(...) stop("the choice emit? is not defined by anyone"))
  method(cl, "choose mass", function(...) stop("the choice mass is not defined by anyone"))
  method(cl, "emits", function(exit = NULL, ...) {
    return((if (truthy(.x <- (choose_(self, "emit?"))(exit))) (!eq(self$moved_along, exit)) else .x))
    NULL
  })
  method(cl, "ahead", function(d = NULL, ...) {
    return(m_map(self$cells, function(c = NULL, ...) {
      return(c$outward(d))
      NULL
    }))
    NULL
  })
})

