Cell <- ray_class("Cell", Node, function(cl) {
  field(cl, "of", NULL)
  field(cl, "index", NULL)
  field(cl, "fine", function() FALSE)
  field(cl, "source", function() self$of$source_at(self$index))
  getter(cl, "vacuum", function() {
    return(eq(self$of$blocks_at(self$index), 0))
    NULL
  })
  method(cl, "emits", function(d = NULL, ...) {
    return((if (truthy(.x <- (!eq(self$source, NULL)))) self$source$emits(d) else .x))
    NULL
  })
  getter(cl, "folds", function() {
    return(self$of$folds_at(self$index))
    NULL
  })
  method(cl, "drift", function(d = NULL, ...) {
    return(self$of$drift_from(self$index, d))
    NULL
  })
  getter(cl, "sinks", function() {
    return(self$of$sinks_at(self$index))
    NULL
  })
  method(cl, "outward", function(d = NULL, ...) {
    c <- (if (truthy(self$fine)) self$of$near_from(self$index, d) else self$of$hop_from(self$index, d))
    if (truthy(lt(c, 0))) {
      return(NULL)
    }
    there <- Cell$new(of = self$of, index = c)
    .set(there, "fine", self$fine)
    return(there)
    NULL
  })
})

Beam <- ray_class("Beam", Node, function(cl) {
  field(cl, "vertex", NULL)
  field(cl, "exit", NULL)
  field(cl, "count", NULL)
  field(cl, "recoil", function() 0)
  field(cl, "tag", function() NULL)
  getter(cl, "active", function() {
    return(gt(self$count, 0))
    NULL
  })
  getter(cl, "activity", function() {
    return((if (truthy(gt(self$count, 1))) 1 else self$count))
    NULL
  })
  getter(cl, "along", function() {
    return(r_mul(self$vertex$of$geometry$V(self$exit), (r_mul(((if (truthy(gt(self$recoil, 0))) self$recoil else self$activity)), self$vertex$of$edge))))
    NULL
  })
  getter(cl, "steps", function() {
    there <- self$vertex$outward(self$exit)
    if (truthy(eq(there, NULL))) {
      return(NULL)
    }
    lit <- Beam$new(vertex = there, exit = self$exit, count = (if (truthy(eq(self$vertex$source, NULL))) 0 else self$vertex$source$per_way))
    .set(lit, "recoil", lit$count)
    .set(lit, "tag", (if (truthy(eq(self$vertex$source, NULL))) NULL else self$vertex$source$tag))
    return(lit)
    NULL
  })
  getter(cl, "deactivate", function() {
    if (truthy(gt(self$count, 0))) {
      self$vertex$of$absorb(self$exit, self$vertex$index, self$activity)
    }
    self$count <- 0
    NULL
  })
  getter(cl, "activate", function() {
    return(self$vertex$of$light(self$exit, self$vertex$index, self$count, self$tag))
    NULL
  })
})

