Bodies <- ray_class("Bodies", Node, function(cl) {
  statik(cl, "begin", function(holes = NULL, ...) {
    .r <- for_each(holes, function(h) {
      .set(h, "stepped", FALSE)
      .set(h, "moved_along", NULL)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  statik(cl, "radiate", function(of = NULL, rules = NULL, holes = NULL, ...) {
    about <- filt(rules, function(r = NULL, ...) {
      return(eq(r$over, "Boundary"))
      NULL
    })
    .r <- for_each(about, function(rule) {
      .r <- for_each(holes, function(h) {
        .r <- for_each(h$cells, function(cell) {
          here <- Cell$new(of = of, index = cell$index)
          .r <- for_range(of$geometry$DEG, function(a) {
            beam <- Beam$new(vertex = here, exit = a, count = of$was_at(a, cell$index))
            .set(beam, "recoil", h$per_way)
            port <- Port$new(vertex = here, ray = beam)
            if (truthy((if (truthy(.x <- eq(rule$where, NULL))) .x else rule$where(port)))) {
              rule$apply(port)
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  statik(cl, "enter", function(of = NULL, h = NULL, c = NULL, ...) {
    .set(h, "world", Around$new(geometry = of$fine_geometry, DEG = of$DEG))
    .set(h, "momentum", Vector$new(components = lst(h$px, h$py)))
    .set(h, "advance", Vector$zero(2))
    stood <- Cell$new(of = of, index = (if (truthy(lt(c, 0))) 0 else c))
    .set(stood, "fine", TRUE)
    .set(h, "cells", (if (truthy(lt(c, 0))) lst() else lst(stood)))
    NULL
  })
  statik(cl, "transport", function(of = NULL, rules = NULL, holes = NULL, ...) {
    about <- filt(rules, function(r = NULL, ...) {
      return(eq(r$over, "Source"))
      NULL
    })
    .r <- for_each(about, function(rule) {
      .r <- for_each(holes, function(h) {
        if (truthy((if (truthy(.x <- eq(rule$where, NULL))) .x else rule$where(h)))) {
          rule$apply(h)
        }
        if (truthy(h$stepped)) {
          .set(h, "moved", r_add(h$moved, 1))
          first_ <- elem(h$cells, 0)
          .set(h, "x", of$column_of(first_$index))
          .set(h, "y", of$row_of(first_$index))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
})

Hole <- ray_class("Hole", Source, function(cl) {
