  method(cl, "choose emit?", function(exit = NULL, ...) {
    return(TRUE)
    NULL
  })
  getter(cl, "per_way", function() {
    return(r_div(self$mass, self$world$DEG))
    NULL
  })
  getter(cl, "px_now", function() {
    return(elem(self$momentum$components, 0))
    NULL
  })
  getter(cl, "py_now", function() {
