    NULL
  })
})

Field <- ray_class("Field", Node, function(cl) {
  field(cl, "theory", NULL)
  field(cl, "N", NULL)
  field(cl, "A", NULL)
  field(cl, "K", NULL)
  field(cl, "DEG", function() 8)
  getter(cl, "edge", function() {
    return(r_div(self$DEG, self$A))
    NULL
  })
  field(cl, "seed", function() 0)
  getter(cl, "cells", function() {
    return(r_mul(self$N, self$N))
    NULL
  })
  field(cl, "ticks", function() 0)
  field(cl, "ambient", function() 0.5)
  field(cl, "seen", function() 0)
  field(cl, "n", function() filled(r_mul(self$cells, self$A), 0))
  field(cl, "was", function() filled(r_mul(self$cells, self$A), 0))
  field(cl, "dN", function() filled(r_mul(self$cells, self$A), 0))
  field(cl, "taken", function() filled(r_mul(self$cells, self$A), 0))
  field(cl, "absorbed", function() filled(r_mul(self$cells, self$A), 0))
  field(cl, "emitted", function() filled(r_mul(self$cells, self$A), 0))
  field(cl, "out", function() filled(r_mul(self$cells, self$A), 0))
  field(cl, "tags", function() 1)
  field(cl, "by", function() m_map(rng(r_sub(self$tags, 1)), function(z = NULL, ...) {
    return(filled(r_mul(self$cells, self$A), 0))
    NULL
  }))
  field(cl, "by_emitted", function() m_map(rng(r_sub(self$tags, 1)), function(z = NULL, ...) {
    return(filled(r_mul(self$cells, self$A), 0))
    NULL
  }))
  field(cl, "fold", function() filled(r_mul(self$cells, self$A), 0))
  field(cl, "fold_was", function() filled(r_mul(self$cells, self$A), 0))
  field(cl, "space", function() filled(self$cells, 0))
  field(cl, "folds", function() filled(self$cells, 0))
  field(cl, "destroyed", function() filled(self$cells, 0))
  field(cl, "cross", function() filled(self$cells, 0))
  field(cl, "blocks", function() filled(self$cells, 0))
  field(cl, "rho", function() filled(self$cells, 0))
  field(cl, "keep", function() filled(self$cells, 1))
  field(cl, "swallow", function() filled(r_mul(self$cells, self$A), 0))
  field(cl, "alive", function() filled(self$cells, 1))
  field(cl, "ux", function() m_map(rng(self$A), function(a = NULL, ...) {
    return(m_cos((r_div(r_mul((2 * pi), a), self$A))))
    NULL
  }))
  field(cl, "uy", function() m_map(rng(self$A), function(a = NULL, ...) {
    return(m_sin((r_div(r_mul((2 * pi), a), self$A))))
    NULL
  }))
  field(cl, "holes", function() lst())
  field(cl, "random", function() Random$new(seed = self$seed))
  method(cl, "opposite", function(a = NULL, ...) {
    return(r_mod((r_add(a, r_div(self$A, 2))), self$A))
    NULL
  })
  method(cl, "facing_of", function(a = NULL, b = NULL, ...) {
    return(r_div((r_sub(1, (r_add(r_mul(elem(self$ux, a), elem(self$ux, b)), r_mul(elem(self$uy, a), elem(self$uy, b)))))), 2))
    NULL
  })
  method(cl, "at", function(x = NULL, y = NULL, ...) {
    return((if (truthy(((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- lt(x, 0))) .x else lt(y, 0)))) .x else ge(x, self$N)))) .x else ge(y, self$N))))) neg(1) else r_add(r_mul(y, self$N), x)))
    NULL
  })
  method(cl, "index", function(a = NULL, c = NULL, ...) {
    return(r_add(r_mul(a, self$cells), c))
    NULL
  })
  method(cl, "taps", function(px = NULL, py = NULL, ...) {
    x0 <- m_floor(px)
    y0 <- m_floor(py)
    fx <- r_sub(px, x0)
    fy <- r_sub(py, y0)
    out <- lst()
    .r <- for_each(lst(lst(x0, y0, r_mul((r_sub(1, fx)), (r_sub(1, fy)))), lst(r_add(x0, 1), y0, r_mul(fx, (r_sub(1, fy)))), lst(x0, r_add(y0, 1), r_mul((r_sub(1, fx)), fy)), lst(r_add(x0, 1), r_add(y0, 1), r_mul(fx, fy))), function(t) {
      c <- self$at(elem(t, 0), elem(t, 1))
      if (truthy((if (truthy(.x <- ge(c, 0))) gt(elem(t, 2), 0) else .x))) {
        m_push(out, lst(c, elem(t, 2)))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  method(cl, "hop", function(c = NULL, a = NULL, ...) {
    return(self$taps(r_add(r_mod(c, self$N), r_mul(self$K, elem(self$ux, a))), r_add(r_div((r_sub(c, r_mod(c, self$N))), self$N), r_mul(self$K, elem(self$uy, a)))))
    NULL
  })
  method(cl, "back", function(c = NULL, a = NULL, ...) {
    return(self$taps(r_sub(r_mod(c, self$N), r_mul(self$K, elem(self$ux, a))), r_sub(r_div((r_sub(c, r_mod(c, self$N))), self$N), r_mul(self$K, elem(self$uy, a)))))
    NULL
  })
  method(cl, "back2", function(c = NULL, a = NULL, ...) {
    return(self$taps(r_sub(r_mod(c, self$N), r_mul(r_mul(2, self$K), elem(self$ux, a))), r_sub(r_div((r_sub(c, r_mod(c, self$N))), self$N), r_mul(r_mul(2, self$K), elem(self$uy, a)))))
    NULL
  })
  method(cl, "inside", function(ts = NULL, ...) {
    total <- 0
    .r <- for_each(ts, function(t) {
      .w("total", r_add(total, elem(t, 1)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(total)
    NULL
  })
