  method(cl, "activity", function(x = NULL, ...) {
    return((if (truthy(lt(x, 0))) 0 else ((if (truthy(gt(x, 1))) 1 else x))))
    NULL
  })
  method(cl, "symbols", function(c = NULL, ...) {
    s <- Node$new()
    .set(s, key_("ρ"), elem(self$rho, c))
    .set(s, key_("n_f"), elem(self$folds, c))
    .set(s, key_("DEG"), self$DEG)
    .set(s, key_("F"), 1)
    .set(s, key_("ω"), 1)
    src <- self$source_at(c)
    .set(s, key_("m_l"), (if (truthy(eq(src, NULL))) 0 else ((if (truthy(src$stepped)) 0 else src$mass))))
    .set(s, key_("β"), (if (truthy(eq(src, NULL))) 0 else ((if (truthy(src$stepped)) 1 else 0))))
    .r <- for_each(self$terms, function(t) {
      if (truthy((if (truthy(.x <- (!eq(t$rate, NULL)))) eq(elem(s, t$rate), NULL) else .x))) {
        set_at(s, t$rate, 1)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(s)
    NULL
  })
  method(cl, "share", function(t = NULL, c = NULL, ...) {
    v <- t$doing$share$at(self$symbols(c))
    return((if (truthy(lt(v, 0))) 0 else ((if (truthy(gt(v, 1))) 1 else v))))
    NULL
  })
  method(cl, "share_at", function(t = NULL, c = NULL, i = NULL, ...) {
    s <- self$symbols(c)
    .set(s, key_("ρ"), self$activity(elem(self$was, i)))
    v <- t$doing$share$at(s)
    return((if (truthy(lt(v, 0))) 0 else ((if (truthy(gt(v, 1))) 1 else v))))
    NULL
  })
  method(cl, "count", function(t = NULL, which = NULL, c = NULL, ...) {
    s <- self$symbols(c)
    if (truthy(eq(which, "rays"))) {
      return(t$doing$rays$at(s))
    }
    if (truthy(eq(which, "space"))) {
      return(t$doing$space$at(s))
    }
    return(t$doing$folds$at(s))
    NULL
  })
  method(cl, "view", function(i = NULL, ...) {
    m <- r_add(r_add(elem(self$was, i), elem(self$taken, i)), elem(self$absorbed, i))
    return((if (truthy(lt(m, 0))) 0 else m))
    NULL
  })
  getter(cl, "sweep", function() {
    .r <- for_range(self$cells, function(c) {
      set_at(self$rho, c, 0)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_range(self$A, function(a) {
      base <- r_mul(a, self$cells)
      .r <- for_range(self$cells, function(c) {
        set_at(self$rho, c, r_add(elem(self$rho, c), self$activity(elem(self$was, r_add(base, c)))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_range(self$cells, function(c) {
      set_at(self$rho, c, r_div(elem(self$rho, c), self$A))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  getter(cl, "tally", function() {
    .r <- for_range(self$cells, function(c) {
      nf <- 0
      .r <- for_range(self$A, function(b) {
        .w("nf", r_add(nf, elem(self$fold_was, r_add(r_mul(b, self$cells), c))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .w("nf", r_mul(nf, self$edge))
      set_at(self$folds, c, nf)
      set_at(self$keep, c, r_div(1, (r_add(1, nf))))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  getter(cl, "locate", function() {
    .r <- for_range(self$cells, function(c) {
      total <- 0
      now <- 0
      .r <- for_range(self$A, function(b) {
        h <- self$hop_from(c, b)
        j <- r_add(r_mul(self$opposite(b), self$cells), h)
        s <- (if (truthy(lt(h, 0))) 0 else r_mul(elem(self$fold_was, j), self$edge))
        if (truthy(gt(s, 1))) {
          .w("s", 1)
        }
        .w("total", r_add(total, s))
        r <- (if (truthy(lt(h, 0))) 0 else r_mul((r_sub(elem(self$fold, j), elem(self$fold_was, j))), self$edge))
        set_at(self$swallow, r_add(r_mul(b, self$cells), c), (if (truthy(lt(r, 0))) 0 else r))
        .w("now", r_add(now, ((if (truthy(lt(r, 0))) 0 else r))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      inside <- (if (truthy(gt(now, 1))) 1 else now)
      .r <- for_range(self$A, function(b) {
        set_at(self$swallow, r_add(r_mul(b, self$cells), c), (if (truthy(gt(now, 0))) r_div(r_mul(inside, elem(self$swallow, r_add(r_mul(b, self$cells), c))), now) else 0))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      set_at(self$alive, c, r_sub(1, inside))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  method(cl, "sinks_at", function(c = NULL, ...) {
    x <- 0
    y <- 0
    .r <- for_range(self$A, function(b) {
      s <- elem(self$swallow, r_add(r_mul(b, self$cells), c))
      .w("x", r_add(x, r_div(r_mul(s, self$hop_x(b)), self$K)))
      .w("y", r_add(y, r_div(r_mul(s, self$hop_y(b)), self$K)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(Vector$new(components = lst(x, y)))
    NULL
  })
  method(cl, "drift_from", function(c = NULL, d = NULL, ...) {
    x <- 0
    y <- 0
    came <- self$opposite(d)
    .r <- for_range(self$A, function(b) {
      s <- elem(self$swallow, r_add(r_mul(b, self$cells), c))
      along <- (if (truthy(eq(b, came))) d else b)
      .w("x", r_add(x, r_div(r_mul(s, self$hop_x(along)), self$K)))
      .w("y", r_add(y, r_div(r_mul(s, self$hop_y(along)), self$K)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(Vector$new(components = lst(x, y)))
    NULL
  })
  method(cl, "owns", function(c = NULL, a = NULL, ...) {
    s <- r_mul(elem(self$fold_was, r_add(r_mul(a, self$cells), c)), self$edge)
    return((if (truthy(gt(s, 1))) 1 else s))
    NULL
  })
  method(cl, "create", function(terms = NULL, ...) {
    .r <- for_each(terms, function(t) {
      .r <- for_range(self$cells, function(c) {
        fires <- r_mul(self$share(t, c), ((if (truthy(gt(t$degree, 0))) r_pow(elem(self$rho, c), t$degree) else 1)))
        if (truthy(gt(fires, 0))) {
          per <- r_div(self$count(t, "rays", c), self$DEG)
          .r <- for_range(self$A, function(a) {
            i <- r_add(r_mul(a, self$cells), c)
            made <- (if (truthy(t$doing$sets)) r_mul(self$share_at(t, c, i), ((if (truthy(gt(t$degree, 0))) r_pow(elem(self$rho, c), t$degree) else 1))) else fires)
            set_at(self$dN, i, r_add(elem(self$dN, i), r_mul(made, per)))
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          set_at(self$space, c, r_add(elem(self$space, c), r_mul(fires, self$count(t, "space", c))))
          df <- r_div(r_mul(fires, self$count(t, "folds", c)), self$DEG)
          .r <- for_range(self$A, function(a) {
            f <- r_add(elem(self$fold, r_add(r_mul(a, self$cells), c)), df)
            set_at(self$fold, r_add(r_mul(a, self$cells), c), (if (truthy(lt(f, 0))) 0 else f))
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  method(cl, "bodily", function(i = NULL, ...) {
    whole <- elem(self$was, i)
    if (truthy(le(whole, 0))) {
      return(0)
    }
    b <- 0
    .r <- for_range(r_sub(self$tags, 1), function(z) {
      .w("b", r_add(b, elem(elem(self$by, z), i)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .w("b", r_div(b, whole))
    return((if (truthy(lt(b, 0))) 0 else ((if (truthy(gt(b, 1))) 1 else b))))
    NULL
  })
  method(cl, "crossing", function(i = NULL, j = NULL, found = NULL, ...) {
    if (truthy(lt(self$tags, 3))) {
      return(0)
    }
    wi <- elem(found, i)
    wj <- elem(found, j)
    if (truthy((if (truthy(.x <- le(wi, 0))) .x else le(wj, 0)))) {
      return(0)
    }
    f1i <- r_div(elem(elem(self$by, 0), i), wi)
    f1j <- r_div(elem(elem(self$by, 0), j), wj)
    alli <- 0
    allj <- 0
    .r <- for_range(r_sub(self$tags, 1), function(z) {
      .w("alli", r_add(alli, elem(elem(self$by, z), i)))
      .w("allj", r_add(allj, elem(elem(self$by, z), j)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .w("alli", r_div(alli, wi))
    .w("allj", r_div(allj, wj))
    return(r_add(r_mul(f1i, (r_sub(allj, f1j))), r_mul((r_sub(alli, f1i)), f1j)))
    NULL
  })
  method(cl, "meet", function(terms = NULL, ...) {
    .r <- for_each(terms, function(t) {
      found <- self$was
      act <- m_map(rng(r_mul(self$cells, self$A)), function(i = NULL, ...) {
        return(self$activity(elem(self$was, i)))
        NULL
      })
      .r <- for_range(self$A, function(a) {
        o <- self$opposite(a)
        .r <- for_range(self$cells, function(c) {
          i <- r_add(r_mul(a, self$cells), c)
          ts <- self$hop(c, a)
          facing <- 0
          mixed <- 0
          there_b <- 0
          .r <- for_each(ts, function(tp) {
            j <- r_add(r_mul(o, self$cells), elem(tp, 0))
            .w("facing", r_add(facing, r_mul(elem(tp, 1), elem(act, j))))
            .w("mixed", r_add(mixed, r_mul(r_mul(elem(tp, 1), elem(act, j)), self$crossing(i, j, found))))
            .w("there_b", r_add(there_b, r_mul(elem(tp, 1), self$bodily(j))))
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          beyond <- r_sub(1, self$inside(ts))
          if (truthy(gt(beyond, 0))) {
            j <- r_add(r_mul(o, self$cells), c)
            .w("facing", r_add(facing, r_mul(beyond, elem(act, j))))
            .w("mixed", r_add(mixed, r_mul(r_mul(beyond, elem(act, j)), self$crossing(i, j, found))))
            .w("there_b", r_add(there_b, r_mul(beyond, self$bodily(j))))
          }
          w <- r_mul(r_mul(elem(act, i), facing), self$share(t, c))
          if (truthy(gt(w, 0))) {
            rays <- r_div(r_mul(w, self$count(t, "rays", c)), 2)
            set_at(self$taken, i, r_add(elem(self$taken, i), rays))
            ds <- r_div(r_mul(w, self$count(t, "space", c)), 2)
            set_at(self$space, c, r_add(elem(self$space, c), r_mul(ds, self$edge)))
            mine <- r_add(0.5, r_mul(0.5, (r_sub(self$bodily(i), there_b))))
            f <- r_add(elem(self$fold, i), r_mul(r_mul(w, self$count(t, "folds", c)), mine))
            set_at(self$fold, i, (if (truthy(lt(f, 0))) 0 else f))
            folded <- r_div(r_mul(w, self$count(t, "folds", c)), 2)
            lost <- (if (truthy(gt(folded, 0))) folded else 0)
            set_at(self$destroyed, c, r_add(elem(self$destroyed, c), r_mul(lost, self$edge)))
            set_at(self$cross, c, r_add(elem(self$cross, c), r_mul(r_mul(lost, self$edge), ((if (truthy(gt(facing, 0))) r_div(mixed, facing) else 0)))))
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  method(cl, "moving", function(a = NULL, c = NULL, ...) {
    return(self$view(r_add(r_mul(a, self$cells), c)))
    NULL
  })
  method(cl, "moving_of", function(z = NULL, a = NULL, c = NULL, ...) {
    i <- r_add(r_mul(a, self$cells), c)
    had <- elem(elem(self$by, z), i)
    whole <- elem(self$was, i)
    if (truthy((if (truthy(.x <- le(had, 0))) .x else le(whole, 0)))) {
      return(0)
    }
    f <- r_div((r_add(r_add(whole, elem(self$taken, i)), elem(self$absorbed, i))), whole)
    if (truthy(lt(f, 0))) {
      .w("f", 0)
    }
    return(r_mul(had, f))
    NULL
  })
  getter(cl, "turned", function() {
    t <- self$transport_term
    return((if (truthy(eq(t, NULL))) "kept" else t$turned))
    NULL
  })
  method(cl, "carried", function(pop = NULL, ...) {
    out <- filled(r_mul(self$cells, self$A), 0)
    onto_way <- eq(self$turned, "way")
    .r <- for_range(self$A, function(a) {
      .r <- for_range(self$cells, function(c) {
        got <- 0
        .r <- for_each(self$back(c, a), function(tp) {
          src <- elem(tp, 0)
          .w("got", r_add(got, r_mul(r_mul(r_mul(elem(tp, 1), (pop)(a, src)), elem(self$keep, src)), (r_sub(1, self$owns(src, a))))))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        .r <- for_each(self$back2(c, a), function(tp) {
          src <- elem(tp, 0)
          .w("got", r_add(got, r_mul(r_mul(r_mul(elem(tp, 1), (pop)(a, src)), elem(self$keep, src)), self$owns(src, a))))
          if (truthy(onto_way)) {
            fa <- elem(self$fold_was, r_add(r_mul(a, self$cells), src))
            if (truthy(gt(fa, 0))) {
              .r <- for_range(self$A, function(b) {
                .w("got", r_add(got, r_mul(r_mul(r_mul(r_mul(elem(tp, 1), (pop)(b, src)), fa), elem(self$keep, src)), self$edge)))
                CONTINUE
              })
              if (!is.null(.r)) return(.r[[1]])
            }
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        if (!truthy(onto_way)) {
          .r <- for_range(self$A, function(d) {
            .r <- for_each(self$back2(c, d), function(tp) {
              sd <- elem(tp, 0)
              fd <- elem(self$fold_was, r_add(r_mul(d, self$cells), sd))
              if (truthy(gt(fd, 0))) {
                .w("got", r_add(got, r_mul(r_mul(r_mul(r_mul(elem(tp, 1), (pop)(a, sd)), fd), elem(self$keep, sd)), self$edge)))
              }
              CONTINUE
            })
            if (!is.null(.r)) return(.r[[1]])
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
        }
        set_at(out, r_add(r_mul(a, self$cells), c), got)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(self$funnelled(out))
    NULL
  })
  method(cl, "funnelled", function(landed = NULL, ...) {
    out <- filled(r_mul(self$cells, self$A), 0)
    .r <- for_range(self$A, function(a) {
      .r <- for_range(self$cells, function(c) {
        x <- elem(landed, r_add(r_mul(a, self$cells), c))
        if (truthy(gt(x, 0))) {
          total <- 0
          .r <- for_range(self$A, function(b) {
            if (truthy((if (truthy(.x <- (!eq(b, self$opposite(a))))) ge(self$hop_from(c, b), 0) else .x))) {
              .w("total", r_add(total, elem(self$swallow, r_add(r_mul(b, self$cells), c))))
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          scale <- (if (truthy(gt(total, 1))) r_div(1, total) else 1)
          stays <- 1
          .r <- for_range(self$A, function(b) {
            s <- r_mul(elem(self$swallow, r_add(r_mul(b, self$cells), c)), scale)
            if (truthy((if (truthy(.x <- gt(s, 0))) (!eq(b, self$opposite(a))) else .x))) {
              h <- self$hop_from(c, b)
              if (truthy(ge(h, 0))) {
                set_at(out, r_add(r_mul(a, self$cells), h), r_add(elem(out, r_add(r_mul(a, self$cells), h)), r_mul(x, s)))
                .w("stays", r_sub(stays, s))
              }
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          set_at(out, r_add(r_mul(a, self$cells), c), r_add(elem(out, r_add(r_mul(a, self$cells), c)), r_mul(x, ((if (truthy(lt(stays, 0))) 0 else stays)))))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  getter(cl, "carry", function() {
    self$out <- self$carried(function(a = NULL, c = NULL, ...) {
      return(self$moving(a, c))
      NULL
    })
    .r <- for_range(r_sub(self$tags, 1), function(z) {
      set_at(self$by, z, self$carried(function(a = NULL, c = NULL, ...) {
        return(self$moving_of(z, a, c))
        NULL
      }))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    self$moved <- TRUE
    NULL
  })
  getter(cl, "settle", function() {
    if (truthy((!truthy(self$moved)))) {
      self$carry
    }
    .r <- for_range(r_mul(self$cells, self$A), function(i) {
      set_at(self$n, i, r_add(elem(self$out, i), elem(self$dN, i)))
      .r <- for_range(r_sub(self$tags, 1), function(z) {
        set_at(elem(self$by, z), i, r_add(elem(elem(self$by, z), i), elem(elem(self$by_emitted, z), i)))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    self$settled <- TRUE
    NULL
  })
  field(cl, "moved", function() FALSE)
  field(cl, "settled", function() FALSE)
  method(cl, "arrived", function(z = NULL, c = NULL, ...) {
    total <- 0
    .r <- for_range(self$A, function(a) {
      .w("total", r_add(total, elem(self$n, r_add(r_mul(a, self$cells), c))))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    if (truthy(eq(z, 0))) {
      .r <- for_range(r_sub(self$tags, 1), function(k) {
        .r <- for_range(self$A, function(a) {
          .w("total", r_sub(total, elem(elem(self$by, k), r_add(r_mul(a, self$cells), c))))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      return((if (truthy(lt(total, 0))) 0 else r_mul(total, self$edge)))
    }
    got <- 0
    .r <- for_range(self$A, function(a) {
      .w("got", r_add(got, elem(elem(self$by, r_sub(z, 1)), r_add(r_mul(a, self$cells), c))))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(r_mul(got, self$edge))
    NULL
  })
  method(cl, "crossed", function(c = NULL, ...) {
    return(elem(self$cross, c))
    NULL
  })
  getter(cl, "t", function() {
    return(self$ticks)
    NULL
  })
  getter(cl, "bodies", function() {
    return(self$holes)
    NULL
  })
  field(cl, "geometry", function() Geometry$new(name = "line-" %+% text_of(self$A) %+% "", offsets = m_map(rng(self$A), function(a = NULL, ...) {
    return(Vector$new(components = lst(r_div(self$hop_x(a), self$K), r_div(self$hop_y(a), self$K))))
    NULL
  })))
  method(cl, "column_of", function(c = NULL, ...) {
    return(r_mod(c, self$N))
    NULL
  })
  method(cl, "row_of", function(c = NULL, ...) {
    return(r_div((r_sub(c, r_mod(c, self$N))), self$N))
    NULL
  })
  statik(cl, "whole", function(x = NULL, ...) {
    y <- r_div(m_round((r_mul(x, 1000000))), 1000000)
    return((if (truthy(lt(y, 0))) r_sub(0, m_floor((r_add((r_sub(0, y)), 0.5)))) else m_floor((r_add(y, 0.5)))))
    NULL
  })
  method(cl, "hop_x", function(d = NULL, ...) {
    return(Field$whole(r_mul(self$K, elem(self$ux, d))))
    NULL
  })
  method(cl, "hop_y", function(d = NULL, ...) {
    return(Field$whole(r_mul(self$K, elem(self$uy, d))))
    NULL
  })
  method(cl, "hop_from", function(c = NULL, d = NULL, ...) {
    return(self$at(r_add(self$column_of(c), self$hop_x(d)), r_add(self$row_of(c), self$hop_y(d))))
    NULL
  })
  method(cl, "near_x", function(d = NULL, ...) {
    return(Field$whole(elem(self$ux, d)))
    NULL
  })
  method(cl, "near_y", function(d = NULL, ...) {
    return(Field$whole(elem(self$uy, d)))
    NULL
  })
  method(cl, "near_from", function(c = NULL, d = NULL, ...) {
    return(self$at(r_add(self$column_of(c), self$near_x(d)), r_add(self$row_of(c), self$near_y(d))))
    NULL
  })
  field(cl, "fine_geometry", function() Geometry$new(name = "cells-" %+% text_of(self$A) %+% "", offsets = m_map(rng(self$A), function(a = NULL, ...) {
    return(Vector$new(components = lst(r_div(self$near_x(a), self$K), r_div(self$near_y(a), self$K))))
    NULL
  })))
  method(cl, "blocks_at", function(c = NULL, ...) {
    return(elem(self$blocks, c))
    NULL
  })
  method(cl, "source_at", function(c = NULL, ...) {
    return((if (truthy(gt(elem(self$blocks, c), 0))) elem(self$holes, r_sub(elem(self$blocks, c), 1)) else NULL))
    NULL
  })
  method(cl, "was_at", function(a = NULL, c = NULL, ...) {
    return(self$view(r_add(r_mul(a, self$cells), c)))
    NULL
  })
  method(cl, "folds_at", function(c = NULL, ...) {
    return(m_map(rng(self$A), function(e = NULL, ...) {
      return(r_mul(elem(self$fold_was, r_add(r_mul(e, self$cells), c)), self$edge))
      NULL
    }))
    NULL
  })
  method(cl, "absorb", function(a = NULL, c = NULL, count = NULL, ...) {
    i <- r_add(r_mul(a, self$cells), c)
    set_at(self$dN, i, r_sub(elem(self$dN, i), count))
    set_at(self$absorbed, i, r_sub(elem(self$absorbed, i), count))
    NULL
  })
  method(cl, "light", function(a = NULL, c = NULL, count = NULL, tag = NULL, ...) {
    .r <- for_each(self$point_of(c), function(cell) {
      i <- r_add(r_mul(a, self$cells), cell)
      set_at(self$dN, i, r_add(elem(self$dN, i), count))
      set_at(self$emitted, i, r_add(elem(self$emitted, i), count))
      if (truthy((if (truthy(.x <- (if (truthy(.x <- (!eq(tag, NULL)))) gt(tag, 0) else .x))) lt(tag, self$tags) else .x))) {
        set_at(elem(self$by_emitted, r_sub(tag, 1)), i, r_add(elem(elem(self$by_emitted, r_sub(tag, 1)), i), count))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  method(cl, "point_of", function(c = NULL, ...) {
    x <- self$column_of(c)
    y <- self$row_of(c)
    half <- m_floor((r_div((r_sub(self$K, 1)), 2)))
    out <- lst()
    .r <- for_range(self$K, function(dy) {
      .r <- for_range(self$K, function(dx) {
        cell <- self$at(r_add(r_sub(x, half), dx), r_add(r_sub(y, half), dy))
        if (truthy(ge(cell, 0))) {
          m_push(out, cell)
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  getter(cl, "block", function() {
    .r <- for_range(self$cells, function(c) {
      set_at(self$blocks, c, 0)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_range(len(self$holes), function(k) {
      .r <- for_each(elem(self$holes, k)$cells, function(cell) {
        set_at(self$blocks, cell$index, r_add(k, 1))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  method(cl, "mass", function(h = NULL, ...) {
    return(h$mass)
    NULL
  })
  method(cl, "lean_toward", function(cx = NULL, cy = NULL, r = NULL, ...) {
    total <- 0
    count <- 0
    .r <- for_range(48, function(k) {
      th <- r_div(r_mul((2 * pi), k), 48)
      c <- self$at(r_add(cx, m_round((r_mul(r_mul(r, self$K), m_cos(th))))), r_add(cy, m_round((r_mul(r_mul(r, self$K), m_sin(th))))))
      if (truthy(ge(c, 0))) {
        inward <- 0
        .r <- for_range(self$A, function(b) {
          .w("inward", r_sub(inward, r_mul(elem(self$swallow, r_add(r_mul(b, self$cells), c)), (r_add(r_mul(elem(self$ux, b), m_cos(th)), r_mul(elem(self$uy, b), m_sin(th)))))))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        .w("total", r_add(total, inward))
        .w("count", r_add(count, 1))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return((if (truthy(eq(count, 0))) 0 else r_div(total, count)))
    NULL
  })
  method(cl, "thrown", function(x = NULL, y = NULL, mx = NULL, ways = NULL, px = NULL, py = NULL, tag = NULL, ...) {
    h <- Hole$new(x = x, y = y, mx = mx, ways = ways)
    .set(h, "tag", tag)
    .set(h, "moves", TRUE)
    .set(h, "px", px)
    .set(h, "py", py)
    self$add(h)
    return(self)
    NULL
  })
  getter(cl, "tick", function() {
    .r <- for_range(r_mul(self$cells, self$A), function(i) {
      set_at(self$was, i, elem(self$n, i))
      set_at(self$fold_was, i, elem(self$fold, i))
      set_at(self$dN, i, 0)
      set_at(self$taken, i, 0)
      set_at(self$absorbed, i, 0)
      set_at(self$emitted, i, 0)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_range(r_sub(self$tags, 1), function(z) {
      .r <- for_range(r_mul(self$cells, self$A), function(i) {
        set_at(elem(self$by_emitted, z), i, 0)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_range(self$cells, function(c) {
      set_at(self$destroyed, c, 0)
      set_at(self$cross, c, 0)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    self$moved <- FALSE
    self$settled <- FALSE
    Bodies$begin(self$holes)
    self$sweep
    self$tally
    .r <- for_each(self$theory$rules, function(rule) {
      if (truthy(eq(rule$over, "Boundary"))) {
        Bodies$radiate(self, lst(rule), self$holes)
      } else {
        if (truthy(eq(rule$over, "Source"))) {
          Bodies$transport(self, lst(rule), self$holes)
          self$block
        } else {
          ts <- filt(self$terms, function(t = NULL, ...) {
            return((if (truthy(.x <- (!eq(t$rule, NULL)))) eq(t$rule$id, rule$id) else .x))
            NULL
          })
          meetings <- filt(ts, function(t = NULL, ...) {
            return((if (truthy(.x <- (if (truthy(.x <- (!truthy(t$settles)))) (!truthy(t$transport)) else .x))) eq(t$degree, 2) else .x))
            NULL
          })
          points <- filt(ts, function(t = NULL, ...) {
            return((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (!truthy(t$settles)))) (!truthy(t$transport)) else .x))) (!eq(t$degree, 2)) else .x))) (!truthy(t$outside)) else .x))
            NULL
          })
          if (truthy((!truthy(m_empty(meetings))))) {
            self$meet(meetings)
          }
          if (truthy((!truthy(m_empty(points))))) {
            self$create(points)
          }
          if (truthy(m_some(ts, function(t = NULL, ...) {
            return(t$transport)
            NULL
          }))) {
            self$locate
            self$carry
          }
        }
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    self$settle
    self$sweep_n
    total <- 0
    .r <- for_range(self$cells, function(c) {
      .w("total", r_add(total, elem(self$rho, c)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    self$seen <- r_add(self$seen, 1)
    span <- (if (truthy(lt(self$seen, 512))) self$seen else 512)
    self$ambient <- r_add(self$ambient, r_div((r_sub(r_div(total, self$cells), self$ambient)), span))
    self$ticks <- r_add(self$ticks, 1)
    NULL
  })
  getter(cl, "sweep_n", function() {
    .r <- for_range(self$cells, function(c) {
      set_at(self$rho, c, 0)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_range(self$A, function(a) {
      base <- r_mul(a, self$cells)
      .r <- for_range(self$cells, function(c) {
        set_at(self$rho, c, r_add(elem(self$rho, c), self$activity(elem(self$n, r_add(base, c)))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_range(self$cells, function(c) {
      set_at(self$rho, c, r_div(elem(self$rho, c), self$A))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  method(cl, "add", function(h = NULL, ...) {
    m_push(self$holes, h)
    Bodies$enter(self, h, self$at(m_round(h$x), m_round(h$y)))
    self$block
    return(h)
    NULL
  })
  method(cl, "density", function(c = NULL, ...) {
    return(elem(self$rho, c))
    NULL
  })
  getter(cl, "mean", function() {
    total <- 0
    .r <- for_range(self$cells, function(c) {
      .w("total", r_add(total, elem(self$rho, c)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(r_div(total, self$cells))
    NULL
  })
})

Rates <- ray_class("Rates", Node, function(cl) {
  field(cl, "nu", NULL)
  field(cl, "sigma", NULL)
  field(cl, "F", NULL)
  field(cl, "DEG", NULL)
  field(cl, "D", NULL)
  field(cl, "g", function() 0)
})

Grid <- ray_class("Grid", Node, function(cl) {
  field(cl, "L", NULL)
  field(cl, "n", NULL)
  field(cl, "s", NULL)
  field(cl, "rho", NULL)
  field(cl, "passes", NULL)
  field(cl, "settled", NULL)
  field(cl, "imbalance", NULL)
})

Solve <- ray_class("Solve", Node, function(cl) {
  statik(cl, "settles", function(R = NULL, ...) {
    a <- r_mul(R$sigma, R$F)
    b <- R$nu
    c <- neg(R$nu)
    if (truthy(eq(a, 0))) {
      return(1)
    }
    return(r_div((r_add(neg(b), m_sqrt((r_sub(r_mul(b, b), r_mul(r_mul(4, a), c)))))), (r_mul(2, a))))
    NULL
  })
  statik(cl, "root", function(s = NULL, name = NULL, f = NULL, ...) {
    had <- elem(s, name)
    at <- function(x = NULL, ...) {
      set_at(s, name, x)
      return((f)(s))
      NULL
    }
    lo <- 0
    hi <- 1
    flo <- (at)(lo)
    fhi <- (at)(hi)
    if (truthy(gt(r_mul(flo, fhi), 0))) {
      set_at(s, name, had)
      return((if (truthy(lt(m_abs(flo), m_abs(fhi)))) lo else hi))
    }
    i <- 0
    while (truthy(lt(i, 60))) {
      mid <- r_div((r_add(lo, hi)), 2)
      fm <- (at)(mid)
      if (truthy(le(r_mul(fm, flo), 0))) {
        .w("hi", mid)
      } else {
        .w("lo", mid)
        .w("flo", fm)
      }
      .w("i", r_add(i, 1))
    }
    set_at(s, name, had)
    return(r_div((r_add(lo, hi)), 2))
    NULL
  })
  statik(cl, "sweep", function(R = NULL, geometry = NULL, radius = NULL, size = NULL, passes = NULL, tol = NULL, ...) {
    if (truthy(eq(size, NULL))) {
      .w("size", 41)
    }
    if (truthy(eq(passes, NULL))) {
      .w("passes", 400)
    }
    if (truthy(eq(tol, NULL))) {
      .w("tol", 0.000000000001)
    }
    L <- size
    D <- geometry$D
    rho <- Solve$settles(R)
    c <- r_div(r_sub(L, 1), 2)
    cells <- r_pow(L, D)
    stride <- m_map(rng(D), function(i = NULL, ...) {
      return(r_pow(L, i))
      NULL
    })
    step <- m_map(geometry$offsets, function(v = NULL, ...) {
      return(m_map(v$components, function(x = NULL, ...) {
        return(m_round(x))
        NULL
      }))
      NULL
    })
    M <- len(step)
    shift <- m_map(step, function(v = NULL, ...) {
      return(m_sum(m_map(rng(D), function(i = NULL, ...) {
        return(r_mul(elem(v, i), elem(stride, i)))
        NULL
      })))
      NULL
    })
    opp <- m_map(step, function(v = NULL, ...) {
      return(or_else(m_index_of(step, m_map(v, function(x = NULL, ...) {
        return(r_sub(0, x))
        NULL
      })), neg(1)))
      NULL
    })
    coord <- function(k = NULL, ...) {
      return(m_map(rng(D), function(i = NULL, ...) {
        return(r_mod(m_floor((r_div(k, elem(stride, i)))), L))
        NULL
      }))
      NULL
    }
    is_matter <- m_map(rng(cells), function(k = NULL, ...) {
      p <- (coord)(k)
      return(le(m_sqrt((m_sum(m_map(rng(D), function(i = NULL, ...) {
        return(r_pow((r_sub(elem(p, i), c)), 2))
        NULL
      })))), radius))
      NULL
    })
    n <- filled(r_mul(cells, M), r_div(rho, M))
    v_next <- filled(r_mul(cells, M), 0)
    s <- filled(cells, 1)
    settled <- FALSE
    done <- 0
    while (truthy((if (truthy(.x <- lt(done, passes))) (!truthy(settled)) else .x))) {
      .r <- for_range(r_mul(cells, M), function(i) {
        set_at(v_next, i, 0)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      moved <- 0
      .r <- for_range(cells, function(k) {
        tot <- m_sum(m_map(rng(M), function(d = NULL, ...) {
          return(elem(n, r_add(r_mul(k, M), d)))
          NULL
        }))
        made <- (if (truthy(elem(is_matter, k))) 0 else r_mul(R$nu, ((if (truthy(gt(r_sub(1, tot), 0))) r_sub(1, tot) else 0))))
        sp <- r_div(1, elem(s, k))
        .r <- for_range(M, function(d) {
          here <- elem(n, r_add(r_mul(k, M), d))
          facing <- elem(n, r_add(r_mul(k, M), ((if (truthy(lt(elem(opp, d), 0))) d else elem(opp, d)))))
          killed <- r_mul(r_mul(r_mul(r_mul(R$sigma, (r_sub(1, R$g))), here), facing), R$F)
          left <- r_sub(r_sub(r_add(here, r_div(made, M)), killed), ((if (truthy(elem(is_matter, k))) here else 0)))
          .w("left", (if (truthy(lt(left, 0))) 0 else left))
          p <- (coord)(k)
          inside <- m_every(rng(D), function(i = NULL, ...) {
            return((if (truthy(.x <- ge(r_add(elem(p, i), elem(elem(step, d), i)), 0))) lt(r_add(elem(p, i), elem(elem(step, d), i)), L) else .x))
            NULL
          })
          if (truthy(inside)) {
            set_at(v_next, r_add(r_mul((r_add(k, elem(shift, d))), M), d), r_add(elem(v_next, r_add(r_mul((r_add(k, elem(shift, d))), M), d)), r_mul(left, sp)))
            set_at(v_next, r_add(r_mul(k, M), d), r_add(elem(v_next, r_add(r_mul(k, M), d)), r_mul(left, (r_sub(1, sp)))))
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .r <- for_range(r_mul(cells, M), function(i) {
        delta <- m_abs((r_sub(elem(v_next, i), elem(n, i))))
        if (truthy(gt(delta, moved))) {
          .w("moved", delta)
        }
        set_at(n, i, elem(v_next, i))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .w("settled", lt(moved, tol))
      .w("done", r_add(done, 1))
    }
    dens <- m_map(rng(cells), function(k = NULL, ...) {
      return(m_sum(m_map(rng(M), function(d = NULL, ...) {
        return(elem(n, r_add(r_mul(k, M), d)))
        NULL
      })))
      NULL
    })
    imbalance <- m_map(rng(cells), function(k = NULL, ...) {
      p <- (coord)(k)
      f <- m_map(rng(D), function(i = NULL, ...) {
        return(m_sum(m_map(rng(M), function(d = NULL, ...) {
          return(r_mul(elem(n, r_add(r_mul(k, M), d)), elem(elem(step, d), i)))
          NULL
        })))
        NULL
      })
      r <- m_map(rng(D), function(i = NULL, ...) {
        return(r_sub(c, elem(p, i)))
        NULL
      })
      norm <- m_sqrt((m_sum(m_map(r, function(x = NULL, ...) {
        return(r_mul(x, x))
        NULL
      }))))
      return(r_div((m_sum(m_map(rng(D), function(i = NULL, ...) {
        return(r_mul(elem(f, i), elem(r, i)))
        NULL
      }))), ((if (truthy(gt(norm, 0))) norm else 1))))
      NULL
    })
    return(Grid$new(L = L, n = dens, s = s, rho = rho, passes = done, settled = settled, imbalance = imbalance))
    NULL
  })
})

Piece <- ray_class("Piece", Node, function(cl) {
  field(cl, "kind", NULL)
  field(cl, "text", function() "")
  field(cl, "of", function() lst())
  field(cl, "lo", function() lst())
  field(cl, "hi", function() lst())
  field(cl, "over", function() lst())
  field(cl, "under", function() lst())
  field(cl, "base", function() NULL)
  field(cl, "raised", function() NULL)
  field(cl, "lowered", function() NULL)
  field(cl, "key", function() "")
  statik(cl, "text_", function(t = NULL, ...) {
    p <- Piece$new(kind = "text")
    .set(p, "text", t)
    return(p)
    NULL
  })
  statik(cl, "wrap", function(kind = NULL, of = NULL, ...) {
    p <- Piece$new(kind = kind)
    .set(p, "of", of)
    return(p)
    NULL
  })
  statik(cl, "words", function(t = NULL, ...) {
    p <- Piece$new(kind = "words")
    .set(p, "text", t)
    return(p)
    NULL
  })
  statik(cl, "big", function(kind = NULL, lo = NULL, hi = NULL, ...) {
    p <- Piece$new(kind = kind)
    .set(p, "lo", lo)
    .set(p, "hi", hi)
    return(p)
    NULL
  })
  statik(cl, "stacked", function(kind = NULL, over = NULL, under = NULL, ...) {
    p <- Piece$new(kind = kind)
    .set(p, "over", over)
