                v_next <- Notation$sub_(src, r_add(i, 1), r_add(i, 2))
                e <- m_index_of(Notation$ESCAPE_KEYS, v_next)
                if (truthy((!eq(e, NULL)))) {
                  (flush)(i)
                  one <- elem(Notation$ESCAPE_TEXTS, e)
