          (flush)(i)
          Notation$attach(out, kind, Notation$parse(b$body))
          .w("i", b$end)
          .w("plain_from", b$end)
          .w("handled", TRUE)
        } else {
          bare <- Notation$alnums(src, r_add(i, 1))
          if (truthy((!truthy(m_empty(bare))))) {
