  })
  statik(cl, "plain", function(s = NULL, ...) {
    out <- lst()
    buf <- ""
    flush <- function(...) {
      if (truthy((!truthy(m_empty(buf))))) {
        m_push(out, Piece$text_(buf))
        .w("buf", "")
      }
      NULL
    }
    bits <- lst()
    k <- 0
    while (truthy(lt(k, len(s)))) {
      c <- elem(m_chars(s), k)
      if (truthy((if (truthy(.x <- Notation$is_letter(c))) .x else eq(c, 95)))) {
        j <- k
        while (truthy((if (truthy(.x <- lt(j, len(s)))) Notation$is_name(elem(m_chars(s), j)) else .x))) {
          .w("j", r_add(j, 1))
        }
        m_push(bits, Notation$sub_(s, k, j))
        .w("k", j)
      } else {
        j <- k
        while (truthy((if (truthy(.x <- lt(j, len(s)))) (!truthy(((if (truthy(.x <- Notation$is_letter(elem(m_chars(s), j)))) .x else eq(elem(m_chars(s), j), 95))))) else .x))) {
          .w("j", r_add(j, 1))
        }
        m_push(bits, Notation$sub_(s, k, j))
        .w("k", j)
      }
    }
    i <- 0
    while (truthy(lt(i, len(bits)))) {
      w <- elem(bits, i)
      after <- (if (truthy(lt(r_add(i, 1), len(bits)))) elem(bits, r_add(i, 1)) else "")
      then <- (if (truthy(lt(r_add(i, 2), len(bits)))) elem(bits, r_add(i, 2)) else "")
      named <- (if (truthy(.x <- Notation$is_letter(elem(m_chars(w), 0)))) .x else eq(elem(m_chars(w), 0), 95))
      if (truthy(m_contains(Notation$COUNTS, w))) {
        (flush)()
        m_push(out, Notation$counted(w))
      } else {
        if (truthy((if (truthy(.x <- m_contains(Notation$BARRED_UPRIGHT, w))) .x else m_contains(Notation$BARRED_LEANS, w)))) {
          (flush)()
          letter <- Piece$text_(w)
          m_push(out, Piece$wrap("bar", lst((if (truthy(m_contains(Notation$BARRED_LEANS, w))) Piece$wrap("var", lst(letter)) else letter))))
        } else {
          if (truthy((if (truthy(.x <- (if (truthy(.x <- eq(w, "@"))) (!truthy(m_empty(after))) else .x))) ((if (truthy(.x <- Notation$is_letter(elem(m_chars(after), 0)))) .x else eq(elem(m_chars(after), 0), 95))) else .x))) {
            (flush)()
            m_push(out, Piece$wrap("fn", lst(Piece$text_("@" %+% text_of(after) %+% ""))))
            .w("i", r_add(i, 1))
          } else {
            if (truthy((if (truthy(.x <- eq(w, "."))) eq(len(bits), 1) else .x))) {
              (flush)()
              m_push(out, Piece$wrap("muted", lst(Piece$text_("."))))
            } else {
              if (truthy((if (truthy(.x <- (if (truthy(.x <- ((if (truthy(.x <- eq(w, "l"))) .x else eq(w, "x"))))) eq(after, ".") else .x))) ((if (truthy(.x <- (if (truthy(.x <- m_empty(then))) .x else Notation$is_letter(elem(m_chars(then), 0))))) .x else eq(elem(m_chars(then), 0), 95))) else .x))) {
                (flush)()
                m_push(out, Piece$wrap("muted", lst(Piece$text_("" %+% text_of(w) %+% "."))))
                if (truthy(m_empty(then))) {
                  .w("i", r_add(i, 1))
                } else {
                  m_push(out, Notation$counted(then))
                  .w("i", r_add(i, 2))
                }
              } else {
                if (truthy(m_contains(Notation$FUNCTIONS, w))) {
                  (flush)()
                  m_push(out, Piece$wrap("fn", lst(Piece$text_(w))))
                } else {
                  if (truthy((if (truthy(.x <- named)) m_starts_with(after, "(") else .x))) {
                    (flush)()
                    m_push(out, Piece$wrap("fn", lst(Piece$text_(w))))
                  } else {
                    alone <- (if (truthy(.x <- eq(len(w), 1))) Notation$is_letter(elem(m_chars(w), 0)) else .x)
                    is_word <- (if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- alone)) (!truthy(m_empty(after))) else .x))) m_every(m_chars(after), function(ch = NULL, ...) {
                      return(blank(ch))
                      NULL
                    }) else .x))) (!truthy(m_empty(then))) else .x))) Notation$is_letter(elem(m_chars(then), 0)) else .x)
                    if (truthy((if (truthy(.x <- (if (truthy(.x <- alone)) ((if (truthy(.x <- eq(w, "l"))) .x else eq(w, "x"))) else .x))) (!truthy(is_word)) else .x))) {
                      (flush)()
                      m_push(out, Piece$wrap("muted", lst(Piece$text_(w))))
                    } else {
                      if (truthy((if (truthy(.x <- alone)) (!truthy(is_word)) else .x))) {
                        (flush)()
                        m_push(out, Piece$wrap("var", lst(Piece$text_(w))))
                      } else {
                        .w("buf", "" %+% text_of(buf) %+% "" %+% text_of(w) %+% "")
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
      .w("i", r_add(i, 1))
    }
    (flush)()
    return(out)
    NULL
  })
  statik(cl, "set", function(pieces = NULL, w = NULL, ...) {
    return(w$together(m_map(pieces, function(p = NULL, ...) {
      k <- p$kind
      if (truthy(eq(k, "text"))) {
        return(w$text(p$text))
      }
      if (truthy(eq(k, "words"))) {
        return(w$words(p$text))
      }
      if (truthy(eq(k, "ref"))) {
        return(w$ref(p$key))
      }
      if (truthy(eq(k, "frac"))) {
        return(w$frac(Notation$set(p$over, w), Notation$set(p$under, w)))
      }
      if (truthy(eq(k, "binom"))) {
        return(w$binom(Notation$set(p$over, w), Notation$set(p$under, w)))
      }
      if (truthy(m_contains(Notation$BIGS, k))) {
        return(w$big(k, Notation$set(p$lo, w), Notation$set(p$hi, w)))
      }
      if (truthy(eq(k, "scripted"))) {
        b <- p$base
        named <- (if (truthy(((if (truthy(.x <- (if (truthy(.x <- eq(b$kind, "fn"))) eq(len(b$of), 1) else .x))) eq(elem(b$of, 0)$kind, "text") else .x)))) elem(b$of, 0)$text else NULL)
        if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (!eq(named, NULL)))) m_contains(Notation$UNDERSET, named) else .x))) (!eq(p$lowered, NULL)) else .x))) eq(p$raised, NULL) else .x))) {
          return(w$underset(Notation$set(lst(b), w), Notation$set(p$lowered, w)))
        }
        if (truthy((if (truthy(.x <- m_contains(Notation$SHORT, b$kind))) (!truthy(((if (truthy(.x <- (!eq(p$raised, NULL)))) (!eq(p$lowered, NULL)) else .x)))) else .x))) {
          parts <- lst(Notation$set(lst(b), w))
          if (truthy((!eq(p$raised, NULL)))) {
            m_push(parts, w$wrap("sup", Notation$set(p$raised, w)))
          }
          if (truthy((!eq(p$lowered, NULL)))) {
            m_push(parts, w$wrap("sub", Notation$set(p$lowered, w)))
          }
          return(w$together(parts))
        }
        return(w$scripted(Notation$set(lst(b), w), (if (truthy(eq(p$raised, NULL))) NULL else Notation$set(p$raised, w)), (if (truthy(eq(p$lowered, NULL))) NULL else Notation$set(p$lowered, w))))
      }
      return(w$wrap(k, Notation$set(p$of, w)))
      NULL
    })))
    NULL
  })
  statik(cl, "html", function(src = NULL, ...) {
    return(Notation$set(Notation$parse(src), Setter$new()))
    NULL
  })
  statik(cl, "escaped", function(s = NULL, ...) {
    return(m_replace(m_replace(m_replace(s, "&", "&amp;"), "<", "&lt;"), ">", "&gt;"))
    NULL
  })
  statik(cl, "banned", function(line = NULL, ...) {
    if (truthy(m_some(m_chars(line), function(c = NULL, ...) {
      return((if (truthy(.x <- ge(c, 768))) le(c, 879) else .x))
      NULL
    }))) {
