    NULL
  })
})

Keyed <- ray_class("Keyed", Node, function(cl) {
  field(cl, "keys", function() lst())
  field(cl, "vals", function() Node$new())
  method(cl, "has", function(k = NULL, ...) {
    return((!eq(elem(self$vals, k), NULL)))
    NULL
  })
  method(cl, "get", function(k = NULL, ...) {
    return(elem(self$vals, k))
    NULL
  })
  method(cl, "set", function(k = NULL, v = NULL, ...) {
    if (truthy(eq(elem(self$vals, k), NULL))) {
      m_push(self$keys, k)
    }
    set_at(self$vals, k, v)
    NULL
  })
  getter(cl, "values", function() {
    return(m_map(self$keys, function(k = NULL, ...) {
      return(elem(self$vals, k))
      NULL
    }))
    NULL
  })
})

