  statik(cl, "factored", function(e = NULL, ...) {
    t <- Expr$simplify(e)
    if (truthy((if (truthy(.x <- (!eq(t$kind, "add")))) .x else lt(len(t$of), 2)))) {
      return(t)
    }
    parts <- m_map(t$of, function(x = NULL, ...) {
      m <- Keyed$new()
      bits <- (if (truthy(eq(x$kind, "mul"))) x$of else lst(x))
      .r <- for_each(bits, function(b) {
