            }
            if (truthy(gt(v, hi))) {
              .w("hi", v)
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          .w("ok", eq((le(lo, 0)), (le(hi, 0))))
          least <- elem(nums, 0)
          .r <- for_each(nums, function(v) {
            if (truthy(lt(m_abs(v), m_abs(least)))) {
              .w("least", v)
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          .w("k", Expr$num(least))
