    out <- Expr$mul(m_map(common, function(c = NULL, ...) {
      return(Expr$to_power(elem(c, 0), elem(c, 1)))
      NULL
    }))
    inv <- Expr$mul(m_map(common, function(c = NULL, ...) {
      return(Expr$to_power(elem(c, 0), Expr$gather(Expr$neg(elem(c, 1)))))
      NULL
    }))
    return(Expr$simplify(Expr$mul(lst(out, Expr$add(m_map(t$of, function(x = NULL, ...) {
      return(Expr$simplify(Expr$mul(lst(x, inv))))
      NULL
    }))))))
    NULL
  })
  statik(cl, "collected", function(e = NULL, ...) {
