          m_more <- (if (truthy(eq(more$kind, "add"))) len(more$of) else ((if (truthy(((if (truthy(.x <- eq(more$kind, "num"))) eq(more$value, 0) else .x)))) 0 else 1)))
          if (truthy(lt(m_less, n))) {
            m_push(elem(g, 1), Expr$num(1))
