      return(Expr$mul(lst(by, elem(g, 0))))
      NULL
    }), function(t = NULL, ...) {
      return((!truthy(((if (truthy(.x <- eq(t$kind, "num"))) eq(t$value, 0) else .x)))))
      NULL
    })
    if (truthy((!truthy(m_empty(loose))))) {
      m_push(out, Expr$gather(Expr$add(loose)))
