    if (truthy(eq(t$kind, "add"))) {
      return(Expr$simplify(Expr$add(m_map(t$of, function(x = NULL, ...) {
        return(Expr$deep_factored(x, r_add(depth, 1)))
        NULL
      }))))
    }
    return(t)
    NULL
  })
  statik(cl, "evaluate", function(e = NULL, at = NULL, ...) {
    go <- function(x = NULL, ...) {
      k <- x$kind
      if (truthy((if (truthy(.x <- eq(k, "field"))) .x else eq(k, "sym")))) {
        return(((if (truthy((!eq(elem(at, x$label), NULL)))) Expr$num(elem(at, x$label)) else x)))
      }
      if (truthy(eq(k, "add"))) {
        return(Expr$add(m_map(x$of, function(y = NULL, ...) {
          return((go)(y))
          NULL
        })))
      }
      if (truthy(eq(k, "mul"))) {
        return(Expr$mul(m_map(x$of, function(y = NULL, ...) {
          return((go)(y))
          NULL
        })))
      }
      if (truthy(eq(k, "pow"))) {
        return(Expr$to_power((go)(x$base), (go)(x$power)))
      }
      if (truthy(eq(k, "grad"))) {
        return(Expr$grad((go)(x$base)))
      }
      if (truthy(eq(k, "gammaInc"))) {
        a <- (go)(x$first_)
        b <- (go)(x$second_)
        return((if (truthy(((if (truthy(.x <- eq(a$kind, "num"))) eq(b$kind, "num") else .x)))) Expr$num(Expr$gamma_upper(a$value, b$value)) else Expr$gamma_inc(a, b)))
      }
      if (truthy(eq(k, "log"))) {
        return(Expr$log((go)(x$base)))
      }
      if (truthy(eq(k, "exp"))) {
        return(Expr$exp((go)(x$base)))
      }
      if (truthy(eq(k, "choose"))) {
        return(Expr$choose((go)(x$first_), (go)(x$second_)))
      }
      if (truthy(eq(k, "root"))) {
        v <- Expr$solve_root(x$base, x$bound, at)
        return((if (truthy(Expr$finite(v))) Expr$num(v) else Expr$root((go)(x$base), x$bound)))
      }
      if (truthy(eq(k, "limit"))) {
        v <- Expr$to_infinity(x$base, x$bound, at)
        return((if (truthy(Expr$finite(v))) Expr$num(v) else Expr$limit((go)(x$base), x$bound)))
      }
      if (truthy(eq(k, "call"))) {
        return(Expr$call(x$label, (go)(x$base)))
      }
      return(x)
      NULL
    }
    return(Expr$simplify((go)(e)))
    NULL
  })
  statik(cl, "name_of", function(symbol = NULL, ...) {
    i <- m_index_of(Expr$SYMBOLS, symbol)
    return((if (truthy(eq(i, NULL))) symbol else elem(Expr$NAMES, i)))
    NULL
  })
  statik(cl, "of_node", function(n = NULL, ...) {
    c <- n$construct
    if (truthy(eq(c, "number"))) {
      return(Expr$num(Algebra$number_of(n)))
    }
    if (truthy(eq(c, "member"))) {
      s <- Algebra$symbol_of(n)
      if (truthy((!eq(s, NULL)))) {
        return(Expr$field(Expr$name_of(s)))
      }
    }
    if (truthy(eq(c, "dynamic"))) {
      return(Expr$field(Expr$name_of(m_take(m_drop(n$name$source, 1), r_sub(len(n$name$source), 2)))))
    }
    if (truthy(eq(c, "paren"))) {
      return(Expr$of_node(n$inner))
    }
    if (truthy(eq(c, "unary"))) {
      if (truthy(eq(n$operator, "-"))) {
        return(Expr$neg(Expr$of_node(n$operand)))
      }
    }
    if (truthy(eq(c, "binary"))) {
      l <- Expr$of_node(n$left)
      r <- Expr$of_node(n$right)
      op <- n$operator
      if (truthy(eq(op, "+"))) {
        return(Expr$add(lst(l, r)))
      }
      if (truthy(eq(op, "-"))) {
        return(Expr$sub(l, r))
      }
      if (truthy(eq(op, "*"))) {
        return(Expr$mul(lst(l, r)))
      }
      if (truthy(eq(op, "/"))) {
        return(Expr$div(l, r))
      }
      if (truthy(eq(op, "^"))) {
        return(Expr$to_power(l, r))
      }
    }
    if (truthy(eq(c, "method"))) {
      if (truthy(eq(n$method, "root"))) {
        nm <- elem(n$arguments, 1)$value$source
        return(Expr$root(Expr$of_node(elem(n$arguments, 2)$value$body), Expr$name_of(m_take(m_drop(nm, 1), r_sub(len(nm), 2)))))
      }
      if (truthy(eq(n$method, "ln"))) {
        return(Expr$log(Expr$of_node(n$receiver)))
      }
      return(Expr$call(n$method, Expr$of_node((if (truthy(m_empty(n$arguments))) n$receiver else elem(n$arguments, 0)$value))))
    }
    return(Expr$field(n$source))
    NULL
  })
  statik(cl, "of_source", function(text = NULL, ...) {
    r <- ExprReader$new(text = text)
    return(r$addition)
    NULL
  })
})

ExprReader <- ray_class("ExprReader", Node, function(cl) {
  field(cl, "text", NULL)
  field(cl, "at", function() 0)
  getter(cl, "peek", function() {
    return((if (truthy(lt(self$at, len(self$text)))) elem(m_chars(self$text), self$at) else 0))
    NULL
  })
  getter(cl, "skip", function() {
    while (truthy(eq(self$peek, 32))) {
      self$at <- r_add(self$at, 1)
    }
    NULL
  })
  method(cl, "eat", function(n = NULL, ...) {
    got <- Notation$sub_(self$text, self$at, r_add(self$at, n))
    self$at <- r_add(self$at, n)
    return(got)
    NULL
  })
  method(cl, "starts", function(s = NULL, ...) {
    return(eq(Notation$sub_(self$text, self$at, r_add(self$at, len(s))), s))
    NULL
  })
  getter(cl, "addition", function() {
    left <- self$product
    self$skip
    while (truthy((if (truthy(.x <- eq(self$peek, 43))) .x else ((if (truthy(.x <- eq(self$peek, 45))) (!truthy(self$starts("->"))) else .x))))) {
      op <- self$eat(1)
      right <- self$product
      .w("left", (if (truthy(eq(op, "+"))) Expr$add(lst(left, right)) else Expr$sub(left, right)))
      self$skip
    }
    return(left)
    NULL
  })
  getter(cl, "product", function() {
    left <- self$power
    self$skip
    while (truthy((if (truthy(.x <- eq(self$peek, 42))) .x else eq(self$peek, 47)))) {
      op <- self$eat(1)
      right <- self$power
      .w("left", (if (truthy(eq(op, "*"))) Expr$mul(lst(left, right)) else Expr$div(left, right)))
      self$skip
    }
    return(left)
    NULL
  })
  getter(cl, "power", function() {
    base <- self$unary
    self$skip
    if (truthy(eq(self$peek, 94))) {
      self$eat(1)
      return(Expr$to_power(base, self$power))
    }
    return(base)
    NULL
  })
  getter(cl, "unary", function() {
    self$skip
    if (truthy(eq(self$peek, 45))) {
      self$eat(1)
      return(Expr$neg(self$unary))
    }
    return(self$postfix)
    NULL
  })
  getter(cl, "postfix", function() {
    e <- self$primary
    self$skip
    while (truthy((if (truthy(.x <- eq(self$peek, 46))) (!truthy(Notation$is_digit(Notation$char_at(self$text, r_add(self$at, 1))))) else .x))) {
      self$eat(1)
      name <- self$word
      .w("e", (if (truthy(eq(name, "ln"))) Expr$log(e) else Expr$call(name, e)))
    }
    return(e)
    NULL
  })
  getter(cl, "word", function() {
    k <- self$at
    while (truthy((if (truthy(.x <- lt(k, len(self$text)))) ((if (truthy(.x <- Notation$is_name(elem(m_chars(self$text), k)))) .x else gt(elem(m_chars(self$text), k), 127))) else .x))) {
      .w("k", r_add(k, 1))
    }
    return(self$eat(r_sub(k, self$at)))
    NULL
  })
  getter(cl, "number", function() {
    k <- self$at
    while (truthy((if (truthy(.x <- lt(k, len(self$text)))) ((if (truthy(.x <- Notation$is_digit(elem(m_chars(self$text), k)))) .x else eq(elem(m_chars(self$text), k), 46))) else .x))) {
      .w("k", r_add(k, 1))
    }
    return(Expr$num(number(self$eat(r_sub(k, self$at)))))
    NULL
  })
  getter(cl, "primary", function() {
    self$skip
    c <- self$peek
    if (truthy(eq(c, 40))) {
      self$eat(1)
      e <- self$addition
      self$skip
      self$eat(1)
      return(e)
    }
    if (truthy(Notation$is_digit(c))) {
      return(self$number)
    }
    if (truthy(eq(c, 34))) {
      self$eat(1)
      k <- self$at
      while (truthy((if (truthy(.x <- lt(k, len(self$text)))) (!eq(elem(m_chars(self$text), k), 34)) else .x))) {
        .w("k", r_add(k, 1))
      }
      name <- self$eat(r_sub(k, self$at))
      self$eat(1)
      return(Expr$field(Expr$name_of(name)))
    }
    if (truthy(self$starts("Solve.root("))) {
      self$eat(11)
      self$skip
      self$word
      self$skip
      self$eat(1)
      self$skip
      self$eat(1)
      k <- self$at
      while (truthy((if (truthy(.x <- lt(k, len(self$text)))) (!eq(elem(m_chars(self$text), k), 34)) else .x))) {
        .w("k", r_add(k, 1))
      }
      name <- self$eat(r_sub(k, self$at))
      self$eat(1)
      self$skip
      self$eat(1)
      self$skip
      self$eat(1)
      self$word
      self$eat(1)
      self$skip
      self$eat(2)
      body <- self$addition
      self$skip
      self$eat(1)
      return(Expr$root(body, Expr$name_of(name)))
    }
    name <- self$word
    if (truthy((if (truthy(.x <- eq(name, "s"))) eq(self$peek, 46) else .x))) {
      self$eat(1)
      return(Expr$field(Expr$name_of(self$word)))
    }
    if (truthy((if (truthy(.x <- eq(name, "s"))) eq(self$peek, 91) else .x))) {
      self$eat(2)
      k <- self$at
      while (truthy((if (truthy(.x <- lt(k, len(self$text)))) (!eq(elem(m_chars(self$text), k), 34)) else .x))) {
        .w("k", r_add(k, 1))
      }
      key <- self$eat(r_sub(k, self$at))
      self$eat(2)
      return(Expr$field(Expr$name_of(key)))
    }
    return(Expr$field(name))
    NULL
  })
})

Fact <- ray_class("Fact", Node, function(cl) {
  field(cl, "kind", NULL)
  field(cl, "of", NULL)
  field(cl, "to", function() NULL)
  getter(cl, "key", function() {
    return("" %+% text_of(self$kind) %+% "(" %+% text_of(self$of) %+% ")")
    NULL
  })
  getter(cl, "says", function() {
    if (truthy(eq(self$kind, "is"))) {
      return("" %+% text_of(self$of) %+% " = " %+% text_of(Expr$show(self$to)) %+% "")
    }
    if (truthy(eq(self$kind, "conserved"))) {
      return("" %+% text_of(self$of) %+% " is conserved on its way out")
    }
    if (truthy(eq(self$kind, "isotropic"))) {
      return("" %+% text_of(self$of) %+% " goes every way alike")
    }
    if (truthy(eq(self$kind, "grows"))) {
      return("" %+% text_of(self$of) %+% " grows as " %+% text_of(Expr$show(self$to)) %+% "")
    }
    if (truthy(eq(self$kind, "restored"))) {
      return("" %+% text_of(self$of) %+% " is pushed back at " %+% text_of(Expr$show(self$to)) %+% "")
    }
    return("" %+% text_of(self$of) %+% " > 0")
    NULL
  })
  statik(cl, "stands", function(of = NULL, to = NULL, ...) {
    return(Fact$new(kind = "is", of = of, to = to))
    NULL
  })
  statik(cl, "key_of", function(kind = NULL, of = NULL, ...) {
    return("" %+% text_of(kind) %+% "(" %+% text_of(of) %+% ")")
    NULL
  })
})

