Store <- ray_class("Store", Node, function(cl) {
  field(cl, "steps", function() Node$new())
  field(cl, "keys", function() lst())
  field(cl, "version", function() 0)
  field(cl, "round_", function() 0)
  method(cl, "has", function(kind = NULL, of = NULL, ...) {
    return((!eq(self$get(kind, of), NULL)))
    NULL
  })
  method(cl, "get", function(kind = NULL, of = NULL, ...) {
    k <- "" %+% text_of(kind) %+% "(" %+% text_of(of) %+% ")"
    return(elem(self$steps, k))
    NULL
  })
  method(cl, "fact", function(kind = NULL, of = NULL, ...) {
    st <- self$get(kind, of)
    return((if (truthy(eq(st, NULL))) NULL else st$fact))
    NULL
  })
  method(cl, "stands", function(of = NULL, ...) {
    st <- self$get("is", of)
    return((if (truthy(eq(st, NULL))) NULL else st$fact$to))
    NULL
  })
  method(cl, "all", function(kind = NULL, ...) {
    return(m_map(filt(m_map(self$keys, function(k = NULL, ...) {
      return(elem(self$steps, k))
      NULL
    }), function(st = NULL, ...) {
      return(eq(st$fact$kind, kind))
      NULL
    }), function(st = NULL, ...) {
      return(st$fact)
      NULL
    }))
    NULL
  })
  getter(cl, "nodes", function() {
    return(m_map(self$keys, function(k = NULL, ...) {
      return(elem(self$steps, k))
      NULL
    }))
    NULL
  })
  method(cl, "add", function(st = NULL, ...) {
    k <- st$fact$key
    if (truthy((!eq(elem(self$steps, k), NULL)))) {
      return(FALSE)
    }
    .set(st, "round_", self$round_)
    set_at(self$steps, k, st)
    m_push(self$keys, k)
    self$version <- r_add(self$version, 1)
    return(TRUE)
    NULL
  })
})

