Line <- ray_class("Line", Node, function(cl) {
  field(cl, "kind", NULL)
  field(cl, "via", NULL)
  field(cl, "line", NULL)
  field(cl, "working", NULL)
  field(cl, "because", NULL)
  field(cl, "id", function() "")
  field(cl, "upon", function() lst())
  field(cl, "rule", function() NULL)
  field(cl, "source", function() NULL)
  field(cl, "gates", function() lst())
  field(cl, "derivation", function() lst())
  getter(cl, "json", function() {
    sep <- ", "
    working <- m_join(m_map(self$working, function(w = NULL, ...) {
      return(quoted(w))
      NULL
    }), sep)
    upon <- m_join(m_map(self$upon, function(f = NULL, ...) {
      return(quoted(f))
      NULL
    }), sep)
    rule <- (if (truthy(eq(self$rule, NULL))) "" else ", \"rule\": " %+% text_of(quoted(self$source)) %+% ", \"gates\": [" %+% text_of(m_join(m_map(self$gates, function(g = NULL, ...) {
      return(quoted(g))
      NULL
    }), sep)) %+% "]")
    deriv <- (if (truthy(m_empty(self$derivation))) "" else ", \"derivation\": [" %+% text_of(m_join(m_map(self$derivation, function(d = NULL, ...) {
      return(d$json)
      NULL
    }), sep)) %+% "]")
    return("{\"id\": " %+% text_of(quoted(self$id)) %+% ", \"kind\": " %+% text_of(quoted(self$kind)) %+% ", \"via\": " %+% text_of(quoted(self$via)) %+% ", \"line\": " %+% text_of(quoted(self$line)) %+% ", \"working\": [" %+% text_of(working) %+% "], \"because\": " %+% text_of(quoted(self$because)) %+% ", \"from\": [" %+% text_of(upon) %+% "], \"measured\": []" %+% text_of(rule) %+% "" %+% text_of(deriv) %+% "}")
    NULL
  })
  getter(cl, "registry", function() {
    sep <- ", "
    working <- m_join(m_map(self$working, function(w = NULL, ...) {
      return(quoted(w))
      NULL
    }), sep)
    return("{\"kind\": " %+% text_of(quoted(self$kind)) %+% ", \"via\": " %+% text_of(quoted(self$via)) %+% ", \"line\": " %+% text_of(quoted(self$line)) %+% ", \"working\": [" %+% text_of(working) %+% "], \"because\": " %+% text_of(quoted(self$because)) %+% "}")
    NULL
  })
  getter(cl, "opens", function() {
    return((if (truthy(.x <- (!truthy(m_empty(self$derivation))))) .x else (!eq(self$rule, NULL))))
    NULL
  })
})

