    }), sep)
    parts <- m_join(m_map(self$parts, function(p = NULL, ...) {
      return("{\"part\": " %+% text_of(quoted(p$part)) %+% ", \"is\": " %+% text_of(quoted(p$stands)) %+% ", \"because\": " %+% text_of(quoted(p$because)) %+% "}")
      NULL
    }), sep)
