    }), sep)
    return("{\"theorem\": " %+% text_of(quoted(self$theorem)) %+% ", \"asks\": " %+% text_of(quoted(self$asks)) %+% ", \"about\": " %+% text_of(quoted(self$about)) %+% ", \"under\": " %+% text_of(self$under) %+% ", \"beneath\": [" %+% text_of(m_join(m_map(self$beneath, function(b = NULL, ...) {
      return(quoted(b))
      NULL
    }), sep)) %+% "], \"concluded\": " %+% text_of(Proved$v_NULL(self$concluded)) %+% ", \"leads\": " %+% text_of(Proved$v_NULL(self$leads)) %+% ", \"then\": " %+% text_of(Proved$v_NULL(self$then)) %+% ", \"also\": " %+% text_of(Proved$v_NULL(self$also)) %+% ", \"parts\": [" %+% text_of(parts) %+% "], \"standing_for\": [" %+% text_of(standing) %+% "], \"space\": " %+% text_of(Proved$v_NULL(self$space)) %+% ", \"standing\": " %+% text_of(self$standing) %+% ", \"missing\": [" %+% text_of(missing) %+% "], \"cites\": [" %+% text_of(cites) %+% "], \"terms\": [" %+% text_of(terms) %+% "], \"probes\": [], \"steps\": [" %+% text_of(steps) %+% "], \"glossary\": {}}")
    NULL
  })
  getter(cl, "signature", function() {
    sep <- ", "
    steps <- m_join(m_map(self$steps, function(l = NULL, ...) {
      return("[" %+% text_of(quoted(l$kind)) %+% ", " %+% text_of(quoted(l$via)) %+% ", " %+% text_of(quoted(l$line)) %+% "]")
      NULL
    }), sep)
    return("{\"concluded\":" %+% text_of(Proved$v_NULL(self$concluded)) %+% ",\"standing\":" %+% text_of(self$standing) %+% ",\"missing\":[" %+% text_of(m_join(m_map(self$missing, function(m = NULL, ...) {
      return(quoted(m))
      NULL
    }), sep)) %+% "],\"steps\":[" %+% text_of(steps) %+% "]}")
    NULL
  })
  getter(cl, "group", function() {
    return("{\n  \"theorem\": " %+% text_of(quoted(self$theorem)) %+% ",\n  \"theories\": [\n    {\n      \"theory\": " %+% text_of(quoted(self$theory)) %+% ",\n      \"results\": [\n        {\n          \"signature\": " %+% text_of(quoted(self$signature)) %+% ",\n          \"variants\": [" %+% text_of(self$json) %+% "]\n        }\n      ]\n    }\n  ]\n}\n")
    NULL
  })
  getter(cl, "registry", function() {
    sep <- ", "
    steps <- m_join(m_map(self$steps, function(l = NULL, ...) {
      return(l$registry)
      NULL
    }), sep)
    parts <- m_join(m_map(self$parts, function(p = NULL, ...) {
      return("{\"part\": " %+% text_of(quoted(p$part)) %+% ", \"is\": " %+% text_of(quoted(p$stands)) %+% ", \"because\": " %+% text_of(quoted(p$because)) %+% "}")
      NULL
    }), sep)
    standing <- m_join(m_map(self$standing_for, function(p = NULL, ...) {
      return("{\"name\": " %+% text_of(quoted(p$name)) %+% ", \"is\": " %+% text_of(quoted(p$stands)) %+% ", \"because\": " %+% text_of(quoted(p$because)) %+% "}")
      NULL
    }), sep)
    return("" %+% text_of(quoted(self$theorem)) %+% ": {\"theorem\": " %+% text_of(quoted(self$theorem)) %+% ", \"theory\": " %+% text_of(quoted(self$theory)) %+% ", \"asks\": " %+% text_of(quoted(self$asks)) %+% ", \"about\": " %+% text_of(quoted(self$about)) %+% ", \"concluded\": " %+% text_of(Proved$v_NULL(self$concluded)) %+% ", \"beneath\": [" %+% text_of(m_join(m_map(self$beneath, function(b = NULL, ...) {
      return(quoted(b))
      NULL
    }), sep)) %+% "], \"also\": " %+% text_of(Proved$v_NULL(self$also)) %+% ", \"leads\": " %+% text_of(Proved$v_NULL(self$leads)) %+% ", \"then\": " %+% text_of(Proved$v_NULL(self$then)) %+% ", \"space\": " %+% text_of(Proved$v_NULL(self$space)) %+% ", \"standing\": " %+% text_of(self$standing) %+% ", \"missing\": [" %+% text_of(m_join(m_map(self$missing, function(m = NULL, ...) {
      return(quoted(m))
      NULL
    }), sep)) %+% "], \"cites\": [" %+% text_of(m_join(m_map(self$cites, function(c = NULL, ...) {
      return(quoted(c$key))
      NULL
    }), sep)) %+% "], \"steps\": [" %+% text_of(steps) %+% "], \"standingFor\": [" %+% text_of(standing) %+% "], \"parts\": [" %+% text_of(parts) %+% "]}")
    NULL
  })
})

Proof <- ray_class("Proof", Node, function(cl) {
  field(cl, "theory", NULL)
  field(cl, "proved", NULL)
  method(cl, "theorem", function(id = NULL, ...) {
    return(m_first(filt(self$proved, function(p = NULL, ...) {
      return(eq(p$theorem, id))
      NULL
    })))
    NULL
  })
  method(cl, "has", function(id = NULL, ...) {
    return((!eq(self$theorem(id), NULL)))
    NULL
  })
  method(cl, "concluded", function(id = NULL, ...) {
    p <- self$theorem(id)
    return((if (truthy(eq(p, NULL))) NULL else p$concluded))
    NULL
  })
  method(cl, "standing", function(id = NULL, ...) {
    p <- self$theorem(id)
    return((if (truthy(eq(p, NULL))) FALSE else p$standing))
    NULL
  })
  getter(cl, "ids", function() {
    return(m_map(self$proved, function(p = NULL, ...) {
      return(p$theorem)
      NULL
    }))
    NULL
  })
  getter(cl, "json", function() {
    sep <- ", "
    items <- m_join(m_map(self$proved, function(p = NULL, ...) {
      return(p$registry)
      NULL
    }), sep)
    return("" %+% text_of(quoted(self$theory)) %+% ": {" %+% text_of(items) %+% "}")
    NULL
  })
})

TermInfo <- ray_class("TermInfo", Node, function(cl) {
  field(cl, "term", NULL)
  getter(cl, "rules", function() {
    return((if (truthy(((if (truthy(.x <- eq(self$term$rule, NULL))) .x else self$outside)))) lst() else lst(m_upper(self$term$rule$name))))
    NULL
  })
  getter(cl, "rule_id", function() {
    return((if (truthy(eq(self$term$rule, NULL))) NULL else self$term$rule$id))
    NULL
  })
  getter(cl, "rate", function() {
    return((if (truthy(eq(self$term$rate, NULL))) NULL else Expr$name_of(self$term$rate)))
    NULL
  })
  getter(cl, "degree", function() {
    return(self$term$degree)
    NULL
  })
  getter(cl, "facing", function() {
    return(ge(self$term$degree, 2))
    NULL
  })
  getter(cl, "outside", function() {
    return(self$term$outside)
    NULL
  })
  getter(cl, "settles", function() {
    return(self$term$settles)
    NULL
  })
  getter(cl, "carries", function() {
    return(self$term$doing$carries)
    NULL
  })
  getter(cl, "transport", function() {
    return(self$term$transport)
    NULL
  })
  getter(cl, "side", function() {
    return((if (truthy(((if (truthy(.x <- self$settles)) .x else self$transport)))) "left" else "right"))
    NULL
  })
  getter(cl, "share", function() {
    return((if (truthy(eq(self$term$doing$share$source, "1"))) NULL else Expr$of_source(self$term$doing$share$source)))
    NULL
  })
  getter(cl, "asked", function() {
    return((if (truthy(eq(self$term$doing$asked$source, "1"))) NULL else Expr$of_source(self$term$doing$asked$source)))
    NULL
  })
  getter(cl, "around", function() {
    return((if (truthy(eq(self$term$doing$around$source, "1"))) NULL else Expr$of_source(self$term$doing$around$source)))
    NULL
  })
  getter(cl, "ray_count", function() {
    return(Expr$of_source(self$term$doing$rays$source))
    NULL
  })
  getter(cl, "space_count", function() {
    return(Expr$of_source(self$term$doing$space$source))
    NULL
  })
  getter(cl, "fold_count", function() {
    return(Expr$of_source(self$term$doing$folds$source))
    NULL
  })
  getter(cl, "rays", function() {
    return(Expr$show(Expr$simplify(self$ray_count)))
    NULL
  })
  getter(cl, "space", function() {
    return(Expr$show(Expr$simplify(self$space_count)))
    NULL
  })
  getter(cl, "folds", function() {
    return(Expr$show(Expr$simplify(self$fold_count)))
    NULL
  })
  getter(cl, "net", function() {
    return(Expr$numeric(Expr$evaluate(self$ray_count, TermInfo$COUNTS), TermInfo$COUNTS))
    NULL
  })
  getter(cl, "space_net", function() {
    return(Expr$numeric(Expr$evaluate(self$space_count, TermInfo$COUNTS), TermInfo$COUNTS))
    NULL
  })
  getter(cl, "sign", function() {
    return((if (truthy(lt(self$net, 0))) neg(1) else 1))
    NULL
  })
  getter(cl, "over", function() {
    return((if (truthy(eq(self$term$rule, NULL))) "World" else ((if (truthy(eq(self$term$rule$over, "Vertex"))) "Local" else self$term$rule$over))))
    NULL
  })
  getter(cl, "says", function() {
    return((if (truthy(eq(self$term$rule, NULL))) "put in from outside" else self$term$rule$source))
    NULL
  })
  getter(cl, "draws", function() {
    return((!eq(self$term$doing$draws, NULL)))
    NULL
  })
  getter(cl, "grown", function() {
    return(self$term$doing$grown)
    NULL
  })
  getter(cl, "grew_count", function() {
    return(Expr$of_source(self$term$doing$grew$source))
    NULL
  })
  getter(cl, "grew_apart_count", function() {
    return((if (truthy(eq(self$term$doing$grew_apart, NULL))) Expr$num(0) else Expr$of_source(self$term$doing$grew_apart$source)))
    NULL
  })
  getter(cl, "held_count", function() {
    return(Expr$simplify(Expr$sub(self$space_count, self$grew_count)))
    NULL
  })
  getter(cl, "held", function() {
    return(Expr$show(Expr$simplify(self$held_count)))
    NULL
  })
  getter(cl, "grows", function() {
    return(Expr$show(Expr$simplify(self$grew_count)))
    NULL
  })
  getter(cl, "kernel", function() {
    return((!eq(self$term$leans, NULL)))
    NULL
  })
  getter(cl, "keeps", function() {
    return(Expr$pown(Expr$add(lst(Expr$num(1), Expr$field("n_{f}"))), neg(1)))
    NULL
  })
  getter(cl, "drifts", function() {
    return(Expr$grad(Expr$field("n_{f}")))
    NULL
  })
  static_getter(cl, "COUNTS", function() {
    s <- Node$new()
    .set(s, key_("DEG"), 8)
    return(s)
    NULL
  })
  getter(cl, "expr", function() {
    parts <- lst()
    if (truthy(self$outside)) {
      m_push(parts, Expr$field("l.\\bar{m}"))
      if (truthy((!eq(self$around, NULL)))) {
        m_push(parts, self$around)
      }
    } else {
      if (truthy((!eq(self$rate, NULL)))) {
        m_push(parts, Expr$field(self$rate))
      }
      if (truthy((!eq(self$share, NULL)))) {
        m_push(parts, self$share)
      }
      if (truthy(gt(self$degree, 0))) {
        m_push(parts, Expr$pown(Expr$field("n"), self$degree))
      }
    }
    return((if (truthy(m_empty(parts))) Expr$num(1) else Expr$mul(parts)))
    NULL
  })
  getter(cl, "gate", function() {
    s <- (if (truthy(self$outside)) self$around else self$share)
    if (truthy(eq(s, NULL))) {
      return("")
    }
    return((if (truthy(eq(Expr$simplify(s)$kind, "add"))) "\\paren{" %+% text_of(Expr$show(s)) %+% "}" else Expr$show(s)))
    NULL
  })
  getter(cl, "operator", function() {
    if (truthy(self$settles)) {
      return("\\partial_{t}")
    }
    if (truthy(self$transport)) {
      carry <- "\\hat{d}·\\nabla_{l}"
      return((if (truthy(self$kernel)) "" %+% text_of(carry) %+% " + \\paren{" %+% text_of(Expr$show(self$drifts)) %+% "}·\\nabla_{\\hat{d}}" else carry))
    }
    return(NULL)
    NULL
  })
  statik(cl, "powers", function(n = NULL, degree = NULL, ...) {
    return((if (truthy(eq(degree, 0))) "" else ((if (truthy(eq(degree, 1))) n else ((if (truthy(eq(degree, 2))) "" %+% text_of(n) %+% "\\tilde{" %+% text_of(n) %+% "}" else "" %+% text_of(n) %+% "^{" %+% text_of(degree) %+% "}"))))))
    NULL
  })
  getter(cl, "symbol", function() {
    population <- "n"
    if (truthy(self$outside)) {
      return("" %+% text_of(self$gate) %+% "l.\\bar{m}")
    }
    if (truthy(self$settles)) {
      return("\\partial_{t}" %+% text_of(population) %+% "")
    }
    if (truthy(self$transport)) {
      return("" %+% text_of(self$operator) %+% "" %+% text_of(population) %+% "")
    }
    rate <- or_else(self$rate, "")
    room <- self$gate
    pw <- TermInfo$powers(population, self$degree)
    gap <- (if (truthy(((if (truthy(.x <- (if (truthy(.x <- (!truthy(m_empty(rate))))) m_empty(room) else .x))) (!truthy(m_empty(pw))) else .x)))) " " else "")
    return("" %+% text_of(rate) %+% "" %+% text_of(room) %+% "" %+% text_of(gap) %+% "" %+% text_of(pw) %+% "")
    NULL
  })
})

Prover <- ray_class("Prover", Node, function(cl) {
  field(cl, "theory", NULL)
  static_field(cl, "PROOFS", function() Node$new())
  field(cl, "population_line", function() NULL)
  field(cl, "record_line", function() NULL)
  field(cl, "store", function() Store$new())
  getter(cl, "equation", function() {
    return(self$theory$equation)
    NULL
  })
  getter(cl, "infos", function() {
    return(m_map(self$equation$terms, function(t = NULL, ...) {
      return(TermInfo$new(term = t))
      NULL
    }))
    NULL
  })
  getter(cl, "acting", function() {
    return(filt(self$infos, function(t = NULL, ...) {
      return((if (truthy(.x <- (if (truthy(.x <- (!eq(t$side, "left")))) (!truthy(m_empty(t$rules))) else .x))) (!eq(t$rate, NULL)) else .x))
      NULL
    }))
    NULL
  })
  static_getter(cl, "rho", function() {
    return(Expr$field("\\rho"))
    NULL
  })
  statik(cl, "text", function(f = NULL, ...) {
    return((if (truthy(eq(f$to, NULL))) "-" else Expr$show(f$to)))
    NULL
  })
  statik(cl, "body_of", function(t = NULL, ...) {
    parts <- lst(Expr$field(t$rate))
    if (truthy((!eq(t$share, NULL)))) {
      m_push(parts, t$share)
    }
    if (truthy(gt(t$degree, 0))) {
      m_push(parts, Expr$pown(Prover$rho, t$degree))
    }
    return(Expr$simplify(Expr$mul(parts)))
    NULL
  })
  getter(cl, "premises", function() {
    out <- lst()
    equation <- self$equation
    infos <- self$infos
    acting <- self$acting
    a <- Expr$num(0)
    steps <- lst()
    .r <- for_each(acting, function(t) {
      body <- Prover$body_of(t)
      slope <- Expr$simplify(Expr$d(body, "\\rho"))
      signed <- Expr$simplify(Expr$mul(lst(Expr$num((if (truthy(eq(t$sign, neg(1)))) 1 else neg(1))), slope)))
      .w("a", Expr$simplify(Expr$add(lst(a, signed))))
      nm <- m_join(t$rules, ", ")
      how <- (if (truthy(eq(t$sign, neg(1)))) "subtracted" else "added")
      leaf <- Step$of(Fact$stands("how " %+% text_of(t$symbol) %+% " answers a change in the density", signed), "differentiating a term", lst(Fact$key_of("is", t$symbol)), "" %+% text_of(nm) %+% " contributes " %+% text_of(t$symbol) %+% ", which is its rate times what its gates let through times the density to the power its quantifier gives. How that answers a small change in the density is the DERIVATIVE - the product rule, on what the rule already said the term was. A term that shrinks as the density rises pushes a shortfall back, so the sign is turned about what the term itself carries", lst("" %+% text_of(t$symbol) %+% " = " %+% text_of(Expr$show(body)) %+% "", "d/d\\rho = " %+% text_of(Expr$show(slope)) %+% "", "the term is " %+% text_of(how) %+% ", so it restores by " %+% text_of(Expr$show(signed)) %+% ""))
      .set(leaf, "rule", elem(t$rules, 0))
      term <- self$from_rule(t)
      .set(leaf, "derivation", m_concat(term$nodes, lst(leaf)))
      m_push(steps, leaf)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    restored <- Step$of(Fact$new(kind = "restored", of = "\\rho", to = a), "and so the rate", m_map(steps, function(x = NULL, ...) {
      return(x$fact$key)
      NULL
    }), "every term that depends on the density answers a change in it, and they do not consult one another - so what the line does back to A CHANGE IN THE DENSITY is their sum", m_concat(m_map(rng(len(acting)), function(i = NULL, ...) {
      return("" %+% text_of(elem(acting, i)$symbol) %+% ": " %+% text_of(Expr$show(elem(steps, i)$fact$to)) %+% "")
      NULL
    }), lst("a = " %+% text_of(Expr$show(a)) %+% "")))
    .set(restored, "derivation", steps)
    m_push(out, restored)
    reaching <- filt(infos, function(t = NULL, ...) {
      return((if (truthy(.x <- (!truthy(m_empty(t$rules))))) t$outside else .x))
      NULL
    })
    if (truthy(m_empty(reaching))) {
      count <- len(filt(infos, function(t = NULL, ...) {
        return((!truthy(m_empty(t$rules))))
        NULL
      }))
      m_push(out, Step$of(Fact$new(kind = "conserved", of = "\\delta"), "every rule is a function of its own match", lst(), "a rule reads the refs its match handed over and nothing else, so two worlds that agree about a match agree after it - a difference between them can be moved and cannot be made or unmade. What a meeting takes from the disturbed world it leaves as a hole in the undisturbed one, and the difference is the same size. So as much of the shortfall crosses a far shell as a near one, which is what the dilution argument wants", lst("every one of the " %+% text_of(count) %+% " terms the line carries is a rule acting on the match it was handed", "none of them consults anything outside it, so agreement is carried and disagreement is only moved", "the DENSITY is pushed back at a = " %+% text_of(Expr$show(a)) %+% ", which is a different quantity")))
    }
    turning <- m_first(filt(infos, function(t = NULL, ...) {
      return(t$kernel)
      NULL
    }))
    if (truthy((!eq(turning, NULL)))) {
      g <- Expr$simplify(turning$keeps)
      tr <- Expr$simplify(Expr$mul(lst(Expr$field("\\sigma"), Expr$sub(Expr$num(1), turning$keeps))))
      via <- m_join(turning$rules, ", ")
      gs <- Step$of(Fact$stands("g", g), (if (truthy(m_empty(via))) "the turn" else via), lst(), "the rule's body chooses where a ray goes next, and what is left of a heading after one such choice is its cosine moment - one way straight on against the folded ones", lst("the choice is 1 way straight on against n_{f} folded", "g = " %+% text_of(Expr$show(g)) %+% ""))
      .set(gs, "rule", elem(turning$rules, 0))
      st <- Step$of(Fact$stands("\\sigma_{tr}", tr), "the kernel", lst(), "what removes a DIRECTION is not what removes a ray: a turn that sends it on nearly the way it was going has hardly removed it, so the transport cross section is sigma times what the turn does NOT keep", lst())
      .set(st, "derivation", lst(gs, Step$of(Fact$stands("\\sigma_{tr}", tr), "and so the transport cross section", lst(Fact$key_of("is", "g")), "what removes a RAY is not what removes a DIRECTION: a turn that sends it on nearly the way it was going has hardly removed it, so what attenuates a shadow is the rate times what the turn does NOT keep", lst("g = " %+% text_of(Expr$show(g)) %+% "", "\\sigma_{tr} = \\sigma(1-g) = " %+% text_of(Expr$show(tr)) %+% ""))))
      m_push(out, st)
      sw <- Step$of(Fact$stands("what swings a heading", turning$drifts), "the kernel", lst(), "the line's direction term is the kernel's first moment - which way a turn leans on average", lst())
      inner <- Step$of(Fact$stands("what swings a heading", turning$drifts), (if (truthy(m_empty(via))) "the turn" else via), lst(), "the same choice, read as a first moment rather than as a cosine: where the cosine says how much of a heading survives, this says which way what is left of it leans - and it leans toward where the folds are, since those are the ways the choice offers besides straight on", lst("the choice is 1 way straight on against n_{f} folded", "<d^> = " %+% text_of(Expr$show(Expr$simplify(turning$drifts))) %+% ""))
      .set(inner, "rule", elem(turning$rules, 0))
      .set(sw, "derivation", lst(inner))
      m_push(out, sw)
    }
    rates <- lst()
    .r <- for_each(infos, function(t) {
      if (truthy((if (truthy(.x <- (!eq(t$rate, NULL)))) (!truthy(m_contains(rates, t$rate))) else .x))) {
        m_push(rates, t$rate)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_each(rates, function(name) {
      m_push(out, Step$of(Fact$stands(name, Expr$num(1)), "the rewrite", lst(), "a rewrite fires on every match it has, once a tick - that is what a rule of this model is. So its rate is ONE per match per tick, and the name on it says which rewrite rather than how often: there is nothing here to choose or to fit", lst("" %+% text_of(name) %+% " = 1 per match per tick")))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_each(lst("rays", "space", "folds"), function(ledger) {
      parts <- lst()
      .r <- for_each(acting, function(t) {
        c <- (if (truthy(eq(ledger, "rays"))) t$ray_count else ((if (truthy(eq(ledger, "space"))) t$space_count else t$fold_count)))
        m_push(parts, Expr$simplify(Expr$mul(lst(Prover$body_of(t), c))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      if (!truthy(m_empty(parts))) {
        m_push(out, Step$of(Fact$stands("the " %+% text_of(ledger) %+% " line nets", Expr$simplify(Expr$add(parts))), "the line", lst(), "every term of the line does something to the " %+% text_of(ledger) %+% " ledger - its rate, times what its gates let through, times the count one firing puts in - and what the ledger does per point per tick is those added up. Nothing is left out and nothing is counted twice, which is the whole reason for reading it off the line rather than assembling it again wherever it is wanted", m_map(acting, function(t = NULL, ...) {
          c <- (if (truthy(eq(ledger, "rays"))) t$ray_count else ((if (truthy(eq(ledger, "space"))) t$space_count else t$fold_count)))
          return("" %+% text_of(m_join(t$rules, g_sep2())) %+% ": " %+% text_of(t$symbol) %+% " into " %+% text_of(ledger) %+% " " %+% text_of(Expr$show(c)) %+% "")
          NULL
        })))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    meetings <- filt(infos, function(t = NULL, ...) {
      return((if (truthy(.x <- (if (truthy(.x <- (!truthy(t$outside)))) (!eq(t$term$rule, NULL)) else .x))) eq(t$term$rule$over, "Edge") else .x))
      NULL
    })
    if (!truthy(m_empty(meetings))) {
      named <- m_first(m_first(meetings)$rules)
      grown <- Expr$simplify(Expr$add(m_map(meetings, function(t = NULL, ...) {
        return(t$grew_apart_count)
        NULL
      })))
      m_push(out, Step$of(Fact$stands("what bodies' rays grow where they meet", grown), named, lst(), "" %+% text_of(named) %+% " read on two bodies' rays: each still leaves the point behind it where the way behind is dark, and behind a body's ray - lit by a source, not by CREATE, and met in the vacuum's dark half - nothing stands, so both gates are open", lst("behind a vacuum ray: the ray CREATE lit with it, so nothing is grown", "behind a body's ray in the dark half: nothing, so a point is grown", "grown a meeting = " %+% text_of(Expr$show(grown)) %+% "")))
      rho_ <- Prover$rho
      m_push(out, Step$of(Fact$stands("\\bar{n}", Expr$num(0)), "the world", lst(), "how much of a way carries some body's ray, on the world's mean - a fact about what the world holds, not about its rules, so it is put in; in the settled vacuum, with no body in it, it is nought", lst("\\bar{n} = 0 in the empty vacuum, an input where a world is asked about")))
      eps <- Expr$simplify(Expr$mul(lst(Expr$num(2), Expr$field("\\sigma"), Expr$field("F"), Expr$sub(Expr$num(1), rho_), Expr$pown(rho_, 2))))
      m_push(out, Step$of(Fact$stands("\\varepsilon", eps), "the vacuum", lst(), "what the empty vacuum grows on its own, per point per tick: a vacuum ray meeting with the way behind it not lit in the same event. Not yet derived from the rules - put in, at the rate the meetings were read to grow at before", lst("\\varepsilon = " %+% text_of(Expr$show(eps)) %+% ", a placeholder until derived")))
      matter <- Expr$simplify(Expr$mul(lst(Expr$field("\\sigma"), Expr$field("F"), Expr$pown(Expr$field("\\bar{n}"), 2), grown)))
      m_push(out, Step$of(Fact$stands("the world's matter grows", matter), named, lst(Fact$key_of("is", "what bodies' rays grow where they meet"), Fact$key_of("is", "\\bar{n}")), "two bodies' rays meet as any two rays do - at the rate, facing, each end carrying - and each such meeting grows what the rule read on bodies' rays says: per point per tick, that is how much the world grows", lst("\\sigma F \\bar{n}^{2}: two bodies' rays facing on a way", "times " %+% text_of(Expr$show(grown)) %+% " grown a meeting", "= " %+% text_of(Expr$show(matter)) %+% "")))
    }
    .r <- for_each(acting, function(t) {
      body <- Prover$body_of(t)
      which <- (if (truthy(lt(t$sign, 0))) "taken" else "made")
      nm <- m_join(t$rules, ", ")
      verb <- (if (truthy(lt(t$sign, 0))) "takes" else "makes")
      if (truthy((!eq(t$rays, "0")))) {
        made <- Step$of(Fact$stands("what is " %+% text_of(which) %+% "", body), elem(t$rules, 0), lst(), "" %+% text_of(nm) %+% " " %+% text_of(verb) %+% " at " %+% text_of(Expr$show(body)) %+% " - its rate, times what its gates let through, times the density to the power its quantifier gives", lst())
        .set(made, "rule", elem(t$rules, 0))
        m_push(out, made)
      }
      if (truthy((if (truthy(.x <- (if (truthy(.x <- eq(t$rays, "0"))) gt(t$space_net, 0) else .x))) t$carries else .x))) {
        w <- Step$of(Fact$stands("what the waiting makes", body), elem(t$rules, 0), lst(), "" %+% text_of(nm) %+% " hands the ray to itself and grows the world - no ray made, destroyed or moved, and a point of space where there was none. That is a carrier standing still to make the room it could not step into, and the rate it does so at is " %+% text_of(Expr$show(body)) %+% "", lst("no rays, " %+% text_of(Expr$show(t$space_count)) %+% " of space", "the waiting makes " %+% text_of(Expr$show(body)) %+% ""))
        .set(w, "rule", elem(t$rules, 0))
        m_push(out, w)
      }
      .r <- for_each(filt(lst(lst("rays", t$ray_count), lst("space", t$space_count), lst("folds", t$fold_count)), function(v__ = NULL, ...) {
        return((!eq(t$rays, "0")))
        NULL
      }), function(pair) {
        ledger <- elem(pair, 0)
        per <- elem(pair, 1)
        c <- Step$of(Fact$stands("the " %+% text_of(ledger) %+% " count of what is " %+% text_of(which) %+% "", per), elem(t$rules, 0), lst(), "" %+% text_of(nm) %+% " fires at " %+% text_of(Expr$show(body)) %+% ", and ONE firing of it puts " %+% text_of(Expr$show(per)) %+% " into the " %+% text_of(ledger) %+% " ledger - counted off the body, not written down. The two ledgers get different counts from the same firing, which is why they do not settle at the same density", lst("fires at " %+% text_of(Expr$show(body)) %+% "", "" %+% text_of(ledger) %+% " per firing: " %+% text_of(Expr$show(per)) %+% ""))
        .set(c, "rule", elem(t$rules, 0))
        m_push(out, c)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    maker <- m_first(filt(acting, function(t = NULL, ...) {
      return(gt(t$sign, 0))
      NULL
    }))
    if (truthy((!eq(maker, NULL)))) {
      parts <- lst(Expr$field(maker$rate))
      if (truthy((!eq(maker$share, NULL)))) {
        m_push(parts, maker$share)
      }
      s <- Step$of(Fact$stands("S", Expr$simplify(Expr$mul(parts))), elem(maker$rules, 0), lst(), "" %+% text_of(m_join(maker$rules, g_sep2())) %+% " fires because a point is neutral, and matter is not - so what a body puts into the medium is exactly the making that did not happen where it sits. Its strength is that term, and is not a quantity of its own", lst())
      .set(s, "rule", elem(maker$rules, 0))
      m_push(out, s)
    }
    lit <- m_first(filt(acting, function(t = NULL, ...) {
      return((if (truthy(.x <- gt(t$sign, 0))) (!eq(t$rays, "0")) else .x))
      NULL
    }))
    if (truthy((!eq(lit, NULL)))) {
      w <- Step$of(Fact$stands("the ways out of a point", Expr$field(lit$rays)), elem(lit$rules, 0), lst(), "" %+% text_of(m_join(lit$rules, g_sep2())) %+% " lights every exit a point has, so the count its body ran over is how many ways out there are - " %+% text_of(lit$rays) %+% ". A shortfall is ways out that are missing, so that count is also its ceiling", lst("the body lit " %+% text_of(lit$rays) %+% " exits", "so a point has " %+% text_of(lit$rays) %+% " ways out"))
      .set(w, "rule", elem(lit$rules, 0))
      m_push(out, w)
    }
    source <- m_first(filt(infos, function(t = NULL, ...) {
      return(t$outside)
      NULL
    }))
    if (truthy((!eq(source, NULL)))) {
      chosen <- lst(Expr$field("\\bar{m}_{x}"), Expr$field("l.DEG"))
      if (truthy((!eq(source$asked, NULL)))) {
        m_push(chosen, source$asked)
      }
      mass <- Expr$call("l.choose", Expr$simplify(Expr$mul(chosen)))
      m_push(out, Step$of(Fact$stands("l.\\bar{m}", mass), "put in from outside", lst(), "the line is written at a local, l, and what a source puts in there is its mass - a choice over that local's ways out: which of its l.DEG exits it lights, at \\bar{m}_{x} apiece, on the ticks its own rule leaves it. The gate the rule asked of the source is inside the choice because it is a statement about which exits, and the line carries nothing of the source but this", lst("the term is " %+% text_of(source$symbol) %+% "", "l.\\bar{m} = " %+% text_of(Expr$show(mass)) %+% "")))
      parts <- lst(mass)
      if (truthy((!eq(source$around, NULL)))) {
        m_push(parts, source$around)
      }
      sigma <- Expr$simplify(Expr$mul(parts))
      m_push(out, Step$of(Fact$stands("what a body puts out", sigma), "put in from outside", lst(), "what a body puts out is the term no rewrite puts there, scaled by what its gates let through - and a body going somewhere has spent that share of its ticks moving rather than shining, which is the whole of why a moving source is shifted. AND IT IS NAMED \\bar{m}_{x} BECAUSE THAT IS ITS NAME - how often per tick a source activates one direction, a fraction of \\bar{c} whose period is 1/\\bar{m}_{x}. Calling the same number \\Sigma_{0} here made the medium's ledger and the source's own rate look like two quantities, and every law that touched both then carried the seam between them", lst("the term is " %+% text_of(source$symbol) %+% "")))
      m_push(out, Step$of(Fact$new(kind = "conserved", of = "what a body puts out"), "the kernel", lst(), "what a source puts out survives its own transport for the same reason a shortfall does - a turn that keeps the heading loses none of it", lst()))
      m_push(out, Step$of(Fact$new(kind = "isotropic", of = "what a body puts out"), "put in from outside", lst(), "a body lights its exits alike, so what leaves it goes every way alike", lst()))
      feels <- Step$of(Fact$stands("what a body feels", Expr$field("\\sum\\hat{d}")), "EMISSION", lst(), "the rule adds the ray's own exit to the body's momentum, once per ray taken - so what a body feels is the vector sum of the directions that arrived at it, and a count of them would be a different quantity that is not what any rule computes", lst("each absorbed ray adds its exit", "force = \\sum \\hat{d} over what arrives"))
      .set(feels, "rule", "EMISSION")
      m_push(out, feels)
    }
    carrying <- filt(infos, function(t = NULL, ...) {
      return(t$transport)
      NULL
    })
    moving <- m_first(carrying)
    if (truthy((!eq(moving, NULL)))) {
      if (truthy((!eq(moving$share, NULL)))) {
        advancing <- Expr$simplify(Expr$add(m_map(filt(carrying, function(t = NULL, ...) {
          return((!eq(t$share, NULL)))
          NULL
        }), function(t = NULL, ...) {
          return(t$share)
          NULL
        })))
        st <- Step$of(Fact$stands("what share of a step advances", advancing), elem(moving$rules, 0), lst(), "the streaming term is gated: a ray hands over only where the way it drew leads somewhere, and where it does not it makes the room and waits instead. That gate is on the transport, so it is on the speed - and its complement is on the waiting, which is the other arm of the same either and the only other thing in these rules that makes space. One share, both lines", lst())
        .set(st, "rule", elem(moving$rules, 0))
        m_push(out, st)
      }
      c <- Step$of(Fact$stands("\\bar{c}", Expr$num(1)), elem(moving$rules, 0), lst(), "every active ray goes ONE CELL along its own exit in one tick, which is what the streaming term says - so a step is one cell, and that is the only length the lattice has to measure anything else against", lst())
      .set(c, "rule", elem(moving$rules, 0))
      m_push(out, c)
    }
    m_push(out, Step$of(Fact$stands("\\omega", Expr$num(1)), "a way always leads somewhere", lst(), "`outward` finds the point across the way, and where that point has been folded it follows it through to the hub it was folded into - so a way that led somewhere still does, hub or point. It comes back with nothing only where there is no point across the way at all, which is the edge of a finite world. The vacuum the line is written in is infinite: every way has a point across it, and the share of ways with room ahead is all of them", lst("outward(d): the point across d; folded, the hub it is in; None only across the world's edge", "an infinite vacuum has no edge", "\\omega = 1")))
    m_push(out, Step$of(Fact$new(kind = "isotropic", of = "\\delta"), "the lattice", lst(), "the tiling has no preferred direction, so what spreads through it goes every way alike", lst()))
    return(out)
    NULL
  })
  method(cl, "from_rule", function(t = NULL, ...) {
    s <- Store$new()
    name <- elem(t$rules, 0)
    body <- t$says
    pieces <- lst()
    if (truthy((!eq(t$rays, "0")))) {
      m_push(pieces, "" %+% text_of(t$rays) %+% " rays")
    }
    if (truthy((!eq(t$space, "0")))) {
      m_push(pieces, "" %+% text_of(t$space) %+% " points of space")
    }
    if (truthy(t$carries)) {
      m_push(pieces, "carries the population")
    }
    if (truthy(t$settles)) {
      m_push(pieces, "settles the tick")
    }
    both <- (if (truthy(m_empty(pieces))) "nothing to either ledger" else m_join(pieces, ", "))
    top <- "what the body does"
    b <- Step$of(Fact$stands(top, t$ray_count), "the body", lst(), "" %+% text_of(body) %+% " - " %+% text_of(both) %+% ". The reading follows the body down through the methods it calls, and the ledgers it moves are counted off the assignments it makes", lst("rays: " %+% text_of(t$rays) %+% "", "space: " %+% text_of(t$space) %+% "", "folds: " %+% text_of(t$folds) %+% ""))
    .set(b, "rule", name)
    s$add(b)
    degree_of <- (if (truthy(eq(t$degree, 0))) "no power of the density" else ((if (truthy(eq(t$degree, 1))) "the density once" else "the density to the power " %+% text_of(t$degree) %+% "")))
    facing <- (if (truthy(t$facing)) " - and the two are across an edge, so the rate goes against the oncoming current, which is the facing factor F" else "")
    q <- Step$of(Fact$stands("what " %+% text_of(name) %+% " is about", Expr$num(t$degree)), "the quantifier", lst(), "the rule is quantified over " %+% text_of(t$degree) %+% " population-bearing refs, so its term carries " %+% text_of(degree_of) %+% "" %+% text_of(facing) %+% "", lst())
    .set(q, "rule", name)
    s$add(q)
    gates <- self$gates_of(t)
    .r <- for_each(gates, function(g) {
      gs <- Step$of(Fact$stands("what " %+% text_of(elem(g, 0)) %+% " lets through", elem(g, 1)), "a gate", lst(), "the rule fires only where " %+% text_of(elem(g, 0)) %+% ", so whatever it does it does on that share of its matches and the term carries it", lst())
      .set(gs, "rule", name)
      s$add(gs)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    shares <- m_map(gates, function(g = NULL, ...) {
      return(elem(g, 1))
      NULL
    })
    rate <- or_else(t$rate, "nothing")
    term <- Step$of(Fact$stands(t$symbol, Expr$simplify(Expr$mul((if (truthy(m_empty(shares))) lst(Expr$num(1)) else shares)))), "and so the term", m_concat(lst(Fact$key_of("is", top), Fact$key_of("is", "what " %+% text_of(name) %+% " is about")), m_map(gates, function(g = NULL, ...) {
      return(Fact$key_of("is", "what " %+% text_of(elem(g, 0)) %+% " lets through"))
      NULL
    })), "the rate it fires at is called " %+% text_of(rate) %+% ", and it fires on the share its gates let through, once per thing it is quantified over. Multiplied out, that is the term", m_concat(m_concat(lst((if (truthy(eq(t$rate, NULL))) "no rate - it neither makes nor takes" else "rate: " %+% text_of(t$rate) %+% "")), m_map(shares, function(x = NULL, ...) {
      return("share: " %+% text_of(Expr$show(x)) %+% "")
      NULL
    })), lst("degree: " %+% text_of(degree_of) %+% "", "term: " %+% text_of(t$symbol) %+% "")))
    .set(term, "rule", name)
    s$add(term)
    return(s)
    NULL
  })
  method(cl, "gates_of", function(t = NULL, ...) {
    if (truthy(eq(t$share, NULL))) {
      return(lst())
    }
    where <- (if (truthy((if (truthy(.x <- eq(t$term$rule, NULL))) .x else eq(t$term$rule$where, NULL)))) "the match holds" else t$term$rule$where$source)
    return(lst(lst(where, t$share)))
    NULL
  })
  statik(cl, "saturate", function(s = NULL, rules = NULL, cap = NULL, ...) {
    if (truthy(eq(cap, NULL))) {
      .w("cap", 40)
    }
    idle <- Node$new()
    round <- 1
    while (truthy(le(round, cap))) {
      .set(s, "round_", round)
      grew <- 0
      .r <- for_range(len(rules), function(i) {
        rule <- elem(rules, i)
        if (truthy((!eq(elem(idle, i), s$version)))) {
          before <- s$version
          any <- FALSE
          .r <- for_each(rule$fire(s), function(st) {
            if (truthy(s$add(st))) {
              .w("grew", r_add(grew, 1))
              .w("any", TRUE)
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          if (truthy((!truthy(any)))) {
            set_at(idle, i, before)
          }
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      if (truthy(eq(grew, 0))) {
        return(NULL)
      }
      .w("round", r_add(round, 1))
    }
    return((fail)("the rules are still producing facts - something in them feeds itself"))
    NULL
  })
  getter(cl, "model_step", function() {
    infos <- self$infos
    right <- filt(infos, function(t = NULL, ...) {
      return((if (truthy(.x <- eq(t$side, "right"))) ((if (truthy(.x <- m_empty(t$rules))) .x else (!eq(t$rays, "0")))) else .x))
      NULL
    })
    .w("right", m_concat(filt(right, function(t = NULL, ...) {
      return((!truthy(m_empty(t$rules))))
      NULL
    }), filt(right, function(t = NULL, ...) {
      return(m_empty(t$rules))
      NULL
    })))
    rhs <- Expr$add(m_map(right, function(t = NULL, ...) {
      return(Expr$mul(lst(t$ray_count, t$expr)))
      NULL
    }))
    st <- Step$of(Fact$stands("the continuous model", rhs), "the reading", lst(), "the rules, read as a line: every rule of the theory is a term, the reading having run each rule's program on a symbolic match and counted what it does to the population - what it makes, what it takes, what it carries, what a body puts in - so the line is what the rules come to as a crowd rather than a description of them. Everything a theorem of this theory stands on is a term of this line or a reading of one, so every premise below is read off it, and every derivation passes through it", lst(self$line_text, self$space_text))
    .set(st, "derivation", self$line_steps)
    return(st)
    NULL
  })
  statik(cl, "not_the_lines", function(st = NULL, ...) {
    return((if (truthy(.x <- eq(st$fact$of, "what a body feels"))) .x else eq(st$via, "the lattice")))
    NULL
  })
  getter(cl, "closure", function() {
    model <- self$model_step
    self$store$add(model)
    infos <- self$infos
    .r <- for_each(self$premises, function(st) {
      if (truthy((if (truthy(.x <- m_empty(st$upon))) (!truthy(Prover$not_the_lines(st))) else .x))) {
        term <- (if (truthy(eq(st$rule, NULL))) NULL else m_first(filt(infos, function(t = NULL, ...) {
          return((if (truthy(.x <- (!truthy(m_empty(t$rules))))) eq(elem(t$rules, 0), st$rule) else .x))
          NULL
        })))
        if (truthy((!eq(term, NULL)))) {
          sign <- (if (truthy(lt(term$sign, 0))) "-" else "+")
          share <- (if (truthy(eq(term$share, NULL))) "1" else Expr$show(term$share))
          rate <- or_else(term$rate, "1")
          how <- "the term " %+% text_of(sign) %+% " " %+% text_of(term$symbol) %+% " of the continuous model: " %+% text_of(term$rays) %+% " rays a firing, at rate " %+% text_of(rate) %+% ", on the share " %+% text_of(share) %+% " of the matches, of degree " %+% text_of(term$degree) %+% " in the density"
          .set(st, "working", m_concat(lst("read off " %+% text_of(how) %+% ""), st$working))
          .set(st, "because", "READ OFF THE CONTINUOUS MODEL - " %+% text_of(how) %+% "; what this fact takes from it is below. " %+% text_of(st$because) %+% "")
        } else {
          .set(st, "working", m_concat(lst("read off the continuous model: " %+% text_of(st$fact$of) %+% ", which stands on every term of it alike"), st$working))
          .set(st, "because", "READ OFF THE CONTINUOUS MODEL - not one term of it but all of them, since this is about how the line is made. " %+% text_of(st$because) %+% "")
        }
        .set(st, "upon", lst(model$fact$key))
        .set(st, "via", "read off the continuous model")
        .set(st, "rule", NULL)
        .set(st, "derivation", lst())
      }
      self$store$add(st)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    Prover$saturate(self$store, Inferences$RULES)
    return(self$store)
    NULL
  })
  method(cl, "missing", function(s = NULL, ...) {
    out <- lst()
    if (truthy(m_empty(s$all("conserved")))) {
      m_push(out, "nothing says the shortfall survives its own transport")
    }
    if (truthy((!truthy(m_some(s$all("is"), function(f = NULL, ...) {
      return(eq(f$of, "N"))
      NULL
    }))))) {
      m_push(out, "nothing in the line swings a heading, so there is no index")
    }
    return(out)
    NULL
  })
  statik(cl, "behind", function(s = NULL, about = NULL, ...) {
    out <- lst()
    seen <- Node$new()
    walk <- function(k = NULL, ...) {
      if (!truthy(eq(elem(seen, k), TRUE))) {
        st <- elem(s$steps, k)
        if (!truthy(eq(st, NULL))) {
          set_at(seen, k, TRUE)
          .r <- for_each(st$upon, function(f) {
            (walk)(f)
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          m_push(out, st)
        }
      }
      NULL
    }
    if (truthy(m_empty(about))) {
      return(s$nodes)
    }
    .r <- for_each(s$keys, function(k) {
      if (truthy(eq(elem(s$steps, k)$fact$of, about))) {
        (walk)(k)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  getter(cl, "line_steps", function() {
    out <- lst()
    infos <- self$infos
    .r <- for_each(infos, function(t) {
      name <- (if (truthy(m_empty(t$rules))) NULL else elem(t$rules, 0))
      rays <- t$rays
      does <- (if (truthy(eq(rays, "0"))) "moves the population without making or taking any" else "comes to " %+% text_of(rays) %+% " rays and " %+% text_of(t$space) %+% " points of space")
      power <- (if (truthy(eq(t$degree, 0))) "carry no power of the density" else "of degree " %+% text_of(t$degree) %+% " in the density")
      edge <- (if (truthy(t$facing)) " across an edge, which is the facing factor" else "")
      edge2 <- (if (truthy(t$facing)) ", across an edge" else "")
      sign <- (if (truthy(lt(t$sign, 0))) "-" else "+")
      why <- (if (truthy(m_empty(t$rules))) "no rewrite of the model puts it there - it is what is put into the box from outside, and the only place anything about a particular problem can be written" else "" %+% text_of(m_join(t$rules, g_sep2())) %+% " contributes it: its body " %+% text_of(does) %+% ", its quantifier makes it " %+% text_of(power) %+% "" %+% text_of(edge) %+% ", and its gates let through what they let through")
      st <- Step$of(Fact$stands(t$symbol, Expr$simplify(Expr$mul(lst(Expr$num(t$sign), Expr$sym((if (truthy(eq(rays, "0"))) "carried" else rays)))))), or_else(name, "put in from outside"), lst(), why, lst("rays: " %+% text_of(rays) %+% "", "space: " %+% text_of(t$space) %+% "", "degree: " %+% text_of(t$degree) %+% "" %+% text_of(edge2) %+% "", "term: " %+% text_of(sign) %+% " " %+% text_of(t$symbol) %+% ""))
      .set(st, "rule", name)
      .set(st, "derivation", (if (truthy(eq(name, NULL))) lst() else self$from_rule(t)$nodes))
      m_push(out, st)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    rhs <- filt(infos, function(t = NULL, ...) {
      return(eq(t$side, "right"))
      NULL
    })
    lhs <- m_join(m_map(filt(infos, function(t = NULL, ...) {
      return(eq(t$side, "left"))
      NULL
    }), function(t = NULL, ...) {
      return(or_else(t$operator, t$symbol))
      NULL
    }), " + ")
    equation <- self$equation
    m_push(out, Step$of(Fact$stands("" %+% text_of(lhs) %+% "n", Expr$simplify(Expr$add(m_map(rhs, function(t = NULL, ...) {
      return(Expr$mul(lst(Expr$num(t$sign), Expr$sym(t$symbol))))
      NULL
    })))), "and the terms add", m_map(infos, function(t = NULL, ...) {
      return(Fact$key_of("is", t$symbol))
      NULL
    }), "the rules do not consult one another - each fires on its own matches once a tick - so what they do to the population adds, and the line is what they come to rather than a description of them. A theory with a rule taken out writes one term fewer here without anything else changing", m_concat(m_map(infos, function(t = NULL, ...) {
      sign <- (if (truthy(lt(t$sign, 0))) "-" else "+")
      by <- (if (truthy(m_empty(t$rules))) "not a rule" else m_join(t$rules, g_sep2()))
      return("" %+% text_of(sign) %+% " " %+% text_of(t$symbol) %+% "   (" %+% text_of(by) %+% ")")
      NULL
    }), lst(self$line_text, self$space_text))))
    return(out)
    NULL
  })
  getter(cl, "line_text", function() {
    infos <- self$infos
    left <- filt(infos, function(t = NULL, ...) {
      return(eq(t$side, "left"))
      NULL
    })
    .w("left", m_concat(filt(left, function(t = NULL, ...) {
      return(eq(t$operator, "\\partial_{t}"))
      NULL
    }), filt(left, function(t = NULL, ...) {
      return((!eq(t$operator, "\\partial_{t}")))
      NULL
    })))
    right <- filt(infos, function(t = NULL, ...) {
      return((if (truthy(.x <- eq(t$side, "right"))) ((if (truthy(.x <- m_empty(t$rules))) .x else (!eq(t$rays, "0")))) else .x))
      NULL
    })
    .w("right", m_concat(filt(right, function(t = NULL, ...) {
      return((!truthy(m_empty(t$rules))))
      NULL
    }), filt(right, function(t = NULL, ...) {
      return(m_empty(t$rules))
      NULL
    })))
    lhs <- (if (truthy(m_empty(left))) "n" else "(" %+% text_of(m_join(m_map(left, function(t = NULL, ...) {
      return(or_else(t$operator, t$symbol))
      NULL
    }), g_plus())) %+% ")n")
    rhs <- ""
    .r <- for_range(len(right), function(i) {
      t <- elem(right, i)
      piece <- (if (truthy(eq(i, 0))) ((if (truthy(eq(t$sign, neg(1)))) "-" else "")) else ((if (truthy(eq(t$sign, neg(1)))) " - " else " + ")))
      .w("rhs", "" %+% text_of(rhs) %+% "" %+% text_of(piece) %+% "" %+% text_of(t$symbol) %+% "")
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    if (truthy(m_empty(right))) {
      .w("rhs", "0")
    }
    return("" %+% text_of(lhs) %+% " = " %+% text_of(rhs) %+% "")
    NULL
  })
  static_getter(cl, "POPULATION", function() {
    return(Expr$field("\\rho"))
    NULL
  })
  getter(cl, "isotropic_population", function() {
    return(Step$of(Fact$stands("n", Prover$POPULATION), "the density is the share of ways lit", lst(), "\\rho is not a second population: it is the lit ways of a point over all DEG of them, each way's count clamped to one before it is counted and the whole averaged over the headings - which is what the field computes at every cell. The line's n is the count on one heading. So the two are one name on two conditions. ISOTROPIC: the rules light every exit of a point alike and turn a heading by a record that is the same from every side, so nothing picks a heading out and the average over the headings is the count on any one. DILUTE: a way holds at most one ray, so clamping it to one changes nothing. Both hold in the vacuum the line is about; where a way carries more than one ray, \\rho saturates at one while n keeps counting, and the meeting term the reading writes as n^{2} is the field's \\rho^{2} - one pair per edge per tick. Read per point rather than per heading, n would be the rays over all the ways and the same statement is \\rho = n/DEG, the lattice's count of ways being exactly the factor that stands in l.choose and in front of the creation term", lst("\\rho = \\langle \\min(1, n_{d}) \\rangle_{d} - the lit ways over all DEG of them", "isotropic: every heading alike, so \\langle n_{d} \\rangle_{d} = n", "dilute: at most one ray a way, so \\min(1, n) = n", "so \\rho = n on a heading, and \\rho = n/DEG per point")))
    NULL
  })
