  method(cl, "line_filled", function(s = NULL, ...) {
    fill <- Prover$settled(s)
    infos <- self$infos
    right <- filt(infos, function(t = NULL, ...) {
      return((if (truthy(.x <- eq(t$side, "right"))) ((if (truthy(.x <- m_empty(t$rules))) .x else (!eq(t$rays, "0")))) else .x))
      NULL
    })
    .w("right", m_concat(filt(right, function(t = NULL, ...) {
      return((!truthy(m_empty(t$rules))))
      NULL
    }), filt(right, function(t = NULL, ...) {
      return(m_empty(t$rules))
      NULL
    })))
    used <- Prover$constants_in(s, fill, right)
    rhs <- Expr$add(m_map(right, function(t = NULL, ...) {
      return(Prover$neat(Expr$mul(lst(t$ray_count, self$filled_term(t, fill)))))
      NULL
    }))
    lhs <- self$operators_on(Expr$show(Prover$POPULATION))
    return(Step$of(Fact$stands(lhs, rhs), "with every factor written in", m_concat(m_map(used, function(n = NULL, ...) {
      return(Fact$key_of("is", n))
      NULL
    }), lst(Fact$key_of("is", "n"))), "a name that has a law of its own is not a primitive - it is what that law shows it to be, so it stands in for itself. The constants the rules fix - a rate, which is one per match per tick, the facing factor, which is what isotropy leaves - are filled in here and nowhere earlier, so the line above is what the rules say and this is what it comes to", m_concat(m_map(used, function(n = NULL, ...) {
      return("" %+% text_of(n) %+% " = " %+% text_of(Expr$show(Expr$num(elem(fill, n)))) %+% "")
      NULL
    }), lst("" %+% text_of(lhs) %+% " = " %+% text_of(Expr$show(rhs)) %+% ""))))
    NULL
  })
  statik(cl, "constants_in", function(s = NULL, fill = NULL, terms = NULL, ...) {
    used <- lst()
    .r <- for_each(s$all("is"), function(f) {
      if (!truthy((if (truthy(.x <- eq(elem(fill, f$of), NULL))) .x else m_contains(used, f$of)))) {
        if (truthy(m_some(terms, function(t = NULL, ...) {
          return(Expr$mentions(t$expr, f$of))
          NULL
        }))) {
          m_push(used, f$of)
        }
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(used)
    NULL
  })
  method(cl, "ledger_filled", function(s = NULL, ledger = NULL, ...) {
    fill <- Prover$settled(s)
    moving <- filt(self$infos, function(t = NULL, ...) {
      return(((if (truthy(eq(ledger, "space"))) (!eq(t$held, "0")) else (!eq(t$folds, "0")))))
      NULL
    })
    used <- Prover$constants_in(s, fill, moving)
    counted <- function(t = NULL, ...) {
      return((if (truthy(eq(ledger, "space"))) Expr$neg(t$held_count) else t$fold_count))
      NULL
    }
    rhs <- (if (truthy(m_empty(moving))) Expr$num(0) else Expr$add(m_map(moving, function(t = NULL, ...) {
      return(Prover$neat(Expr$mul(lst((counted)(t), self$filled_term(t, fill)))))
      NULL
    })))
    lhs <- (if (truthy(eq(ledger, "space"))) "\\partial_{t}s" else "\\partial_{t}n_{f}")
    what <- (if (truthy(eq(ledger, "space"))) "a point held at the local - the world's count read from the hub's side, so a swallow is one more here and a hand-back one fewer, and a point the world grows is a new local rather than one held here" else "a fold of the record")
    return(Step$of(Fact$stands(lhs, rhs), "with every factor written in", m_concat(m_map(used, function(n = NULL, ...) {
      return(Fact$key_of("is", n))
      NULL
    }), lst(Fact$key_of("is", "n"))), "the same rules, read on another ledger: every term that makes or takes " %+% text_of(what) %+% " does so at its own rate, through its own gates, and the count one firing moves is written on it. The constants are the same facts as on the population's line, filled in here the same way", m_concat(m_map(used, function(n = NULL, ...) {
      return("" %+% text_of(n) %+% " = " %+% text_of(Expr$show(Expr$num(elem(fill, n)))) %+% "")
      NULL
    }), lst("" %+% text_of(lhs) %+% " = " %+% text_of(Expr$show(rhs)) %+% ""))))
    NULL
  })
  method(cl, "growth_filled", function(s = NULL, ...) {
