      return(Fact$key_of("is", n))
      NULL
    }), lst(Fact$key_of("is", "n"))), "a firing that makes a point no local held - behind a ray at a meeting, ahead of a ray with nowhere to step - grows the world by it, at its own rate, through its own gates, the count written on it. This is the room the world gains per local per tick: what it expands by", m_concat(m_map(used, function(n = NULL, ...) {
      return("" %+% text_of(n) %+% " = " %+% text_of(Expr$show(Expr$num(elem(fill, n)))) %+% "")
      NULL
    }), lst("" %+% text_of(lhs) %+% " = " %+% text_of(Expr$show(rhs)) %+% ""))))
    NULL
  })
  method(cl, "ledgers_are_one", function(s = NULL, folds = NULL, space = NULL, ...) {
    together <- Expr$collected(Expr$gather(Expr$expand(Expr$sub(space$fact$to, folds$fact$to))))
    lhs <- "\\partial_{t}s - \\partial_{t}n_{f}"
    return(Step$of(Fact$stands(lhs, together), "the record is the space held", lst(folds$fact$key, space$fact$key), "the same firings move both ledgers, and nothing is handed back by decree. ANNIHILATION folds a point into the hub and writes one fold on the way it came by: one held, one written. CREATION lights every exit and unfolds - and unfolding is gated twice on the same record: a fold comes off a way only `if folds[d] > 0`, and a point comes back only `if held.last != None`, and a hub holds one point per fold it wrote. Read as the shares they are, the ways that lose a fold number n_{f} in expectation and so do the points that come back: the hand-back is what the gates come to on aggregate, not a line in the rule. So the space a local holds and the record it keeps move together, tick for tick, and their difference does not move at all. Integrated, s - n_{f} is a constant, and it is one: a local holds itself and one point per fold. THAT IS WHERE THE POPULATION'S LINE STANDS ON THE SPACE: it never names s, but its transport leans on \\nabla n_{f} and keeps 1/(1 + n_{f}) of a heading, and its room ahead \\omega is the share of ways whose far point is still there - both are the space, read through the record", lst("\\partial_{t}n_{f} = " %+% text_of(Expr$show(folds$fact$to)) %+% "", "\\partial_{t}s = " %+% text_of(Expr$show(space$fact$to)) %+% "", "" %+% text_of(lhs) %+% " = " %+% text_of(Expr$show(together)) %+% "", "a meeting: one point held, one fold written", "a creation: `if folds[d] > 0` on each of DEG ways is n_{f} folds off; `if held.last != None` is n_{f} points back - the same record, twice", "so s - n_{f} does not move: s = 1 + n_{f}, a local holds itself and one point per fold", "the population's transport, \\paren{\\nabla n_{f}}·\\nabla_{\\hat{d}} with 1/(1+n_{f}) kept, is steered by that record")))
    NULL
  })
  getter(cl, "fold_weight", function() {
    meet <- m_first(filt(self$infos, function(t = NULL, ...) {
      return((if (truthy(.x <- (if (truthy(.x <- eq(t$degree, 2))) (!truthy(m_empty(t$rules))) else .x))) (!eq(t$folds, "0")) else .x))
      NULL
    }))
    if (truthy(eq(meet, NULL))) {
      return(Expr$num(1))
    }
    return(Expr$simplify(Expr$neg(Expr$div(meet$ray_count, meet$fold_count))))
    NULL
  })
  method(cl, "general", function(filled = NULL, folds = NULL, ...) {
    k <- self$fold_weight
    weighed_terms <- m_map(((if (truthy(eq(folds$fact$to$kind, "add"))) folds$fact$to$of else lst(folds$fact$to))), function(t = NULL, ...) {
      return(Prover$neat(Expr$mul(lst(k, t))))
      NULL
    })
    rhs <- Expr$collected(Expr$add(lst(filled$fact$to, Expr$add(weighed_terms))))
    rho <- Expr$show(Prover$POPULATION)
    ops <- m_join(m_map(filt(self$infos, function(t = NULL, ...) {
      return((if (truthy(.x <- eq(t$side, "left"))) (!eq(t$operator, "\\partial_{t}")) else .x))
      NULL
    }), function(t = NULL, ...) {
      return(or_else(t$operator, t$symbol))
      NULL
    }), g_plus())
    weighed <- (if (truthy(((if (truthy(.x <- eq(k$kind, "num"))) eq(k$value, 1) else .x)))) "n_{f}" else "" %+% text_of(Expr$show(k)) %+% "·n_{f}")
    lhs <- (if (truthy(m_empty(ops))) "\\partial_{t}\\paren{" %+% text_of(rho) %+% " + " %+% text_of(weighed) %+% "}" else "\\partial_{t}\\paren{" %+% text_of(rho) %+% " + " %+% text_of(weighed) %+% "} + \\paren{" %+% text_of(ops) %+% "}" %+% text_of(rho) %+% "")
    return(Step$of(Fact$stands(lhs, rhs), "the population's line and the record's added", lst(filled$fact$key, folds$fact$key), "ANNIHILATION takes rays and writes a fold - " %+% text_of(Expr$show(k)) %+% " rays a fold, which is the weight the record carries against the population; CREATION takes a fold off and lights every exit. So the vacuum's taking stands on the population's line and, weighed so, on the record's with the opposite sign, and adding the two cancels it exactly - the same count written twice. What is left moves rays-plus-record: the transport carries the rays, a body puts its mass in, and CREATION at a point that held fewer folds than it lights exits makes rays with nothing consumed - which on an expanding world is where the space grows. That last term is kept as it is: at a small scale the record differs from place to place and the sum is not conserved. It is the one term a settled aggregate loses", lst("" %+% text_of(filled$fact$of) %+% " = " %+% text_of(Expr$show(filled$fact$to)) %+% "", "" %+% text_of(folds$fact$of) %+% " = " %+% text_of(Expr$show(folds$fact$to)) %+% "", "a meeting: " %+% text_of(Expr$show(k)) %+% " rays in, one fold out - so the record counts " %+% text_of(Expr$show(k)) %+% " to one", "added: the taking cancels, the making does not - a creation lights every exit whether or not it held a fold", "" %+% text_of(lhs) %+% " = " %+% text_of(Expr$show(rhs)) %+% "")))
    NULL
  })
  method(cl, "aggregate", function(general_ = NULL, one = NULL, s = NULL, ...) {
    inf <- s$fact("is", "\\rho_{\\infty}")
    if (truthy(eq(inf, NULL))) {
      return(NULL)
    }
    rho <- Prover$POPULATION
    terms <- (if (truthy(eq(one$fact$to$kind, "add"))) one$fact$to$of else lst(one$fact$to))
    balance <- Expr$gather(Expr$add(filt(terms, function(t = NULL, ...) {
      return((!truthy(Expr$mentions(t, "l.\\bar{m}"))))
      NULL
    })))
    kept <- Expr$collected(Expr$add(filt(terms, function(t = NULL, ...) {
      return(Expr$mentions(t, "l.\\bar{m}"))
      NULL
    })))
    fill <- Prover$settled(s)
    flat <- function(x = NULL, ...) {
      return(Expr$show(Expr$gather(Expr$expand(Expr$evaluate(x, fill)))))
      NULL
    }
    same <- (if (truthy(.x <- eq(inf$to$kind, "root"))) ((if (truthy(.x <- eq((flat)(balance), (flat)(inf$to$base)))) .x else eq((flat)(balance), (flat)(Expr$neg(inf$to$base))))) else .x)
    if (!truthy(same)) {
      env <- Model$copy(fill)
      .set(env, key_("DEG"), 8)
      at <- Expr$numeric(Expr$evaluate(inf$to, env), env)
      .set(env, key_("\\rho"), at)
      v <- Expr$numeric(Expr$evaluate(balance, env), env)
      if (truthy((if (truthy(.x <- (if (truthy(.x <- (!truthy(Expr$finite(at))))) .x else (!truthy(Expr$finite(v)))))) .x else gt(m_abs(v), 0.000001)))) {
        return(NULL)
      }
    }
    return(Step$of(Fact$stands(general_$fact$of, kept), "the vacuum settled", lst(general_$fact$key, one$fact$key, inf$key), "with the record written as the density, everything on the right that is not a body's mass is the vacuum's own making against its own taking - the balance that fixes \\rho_{\\infty}, and nought exactly there. The continuous aggregate is the settled vacuum: at that density the growth the general line kept has gone, the record is the settled one, and what is left is CONSERVED up to what carries it and what the bodies put in. The record's gradient stays on the left because that is what bends a heading; every place the record departs from the settled one is the small-scale dynamics the general line keeps", lst("the vacuum's balance: " %+% text_of(Expr$show(balance)) %+% "", "\\rho_{\\infty} = " %+% text_of(Expr$show(inf$to)) %+% ": the same balance, at nought", "" %+% text_of(general_$fact$of) %+% " = " %+% text_of(Expr$show(kept)) %+% "")))
    NULL
  })
  method(cl, "settled_record", function(folds = NULL, ...) {
    parts <- m_split(Expr, folds$fact$to, "n_{f}")
    if (truthy(eq(parts, NULL))) {
      return(NULL)
    }
    top <- Prover$tidy(Expr$neg(elem(parts, 1)))
    bottom <- Prover$tidy(elem(parts, 0))
    if (truthy(m_starts_with(Expr$show(top), "-"))) {
      .w("top", Prover$tidy(Expr$neg(top)))
      .w("bottom", Expr$flip(bottom))
    }
    nf <- Expr$div(top, bottom)
    st <- Step$of(Fact$stands("n_{f}", nf), "the record settled against the density", lst(folds$fact$key), "the record's line is linear in the record: folds are written at the meeting rate and taken off at the creation rate times how many there are to take. On the continuous aggregate the record has stopped moving against the density - what a meeting writes a creation takes off - so its line is at nought and the record is a function of the density alone. That is the aggregate: not that the record is conserved, but that it has settled, and every place where it has not is the small-scale dynamics the line above keeps", lst("" %+% text_of(folds$fact$of) %+% " = " %+% text_of(Expr$show(folds$fact$to)) %+% " = 0", "n_{f} = " %+% text_of(Expr$show(nf)) %+% ""))
    .set(st, "parts_", lst(top, bottom))
    return(st)
    NULL
  })
  method(cl, "single", function(general_ = NULL, settled = NULL, folds = NULL, s = NULL, ...) {
    rho <- Prover$POPULATION
    nf <- settled$fact$to
    slope <- Expr$quotient_d(elem(settled$parts_, 0), elem(settled$parts_, 1), Expr$show(rho))
    rhs <- Expr$collected(Expr$reduced(Prover$tidy(Expr$replace(general_$fact$to, "n_{f}", nf))))
    carry <- "\\hat{d}·\\nabla_{l}"
    drift <- "\\paren{" %+% text_of(Expr$show(slope)) %+% "}·\\paren{\\nabla " %+% text_of(Expr$show(rho)) %+% "}·\\nabla_{\\hat{d}}"
    lhs <- "\\partial_{t}" %+% text_of(Expr$show(rho)) %+% " + \\paren{" %+% text_of(carry) %+% " + " %+% text_of(drift) %+% "}" %+% text_of(Expr$show(rho)) %+% ""
    inf <- s$fact("is", "\\rho_{\\infty}")
    upon <- lst(general_$fact$key, settled$fact$key)
    if (truthy((!eq(inf, NULL)))) {
      m_push(upon, inf$key)
    }
    return(Step$of(Fact$stands(lhs, rhs), "the record written as the density", upon, "with the record settled it is a function of the density, so \\partial_{t}n_{f} is nought and \\nabla n_{f} is the record's slope times \\nabla\\rho - the chain rule, on the line above. Every n_{f} on the right is the same function. What is left is one equation in the density alone, and the term the growth left behind is the vacuum's own restoring term: the making against the taking, which is nought exactly where the vacuum has settled, \\rho = \\rho_{\\infty}, and pushes back everywhere else. Near a body the record is steep and that slope is what bends a heading; far from everything it is flat and the line is a ray carried at \\bar{c}, sourced by the masses", m_concat(lst("n_{f} = " %+% text_of(Expr$show(nf)) %+% "", "\\nabla n_{f} = " %+% text_of(Expr$show(slope)) %+% "·\\nabla\\rho", "" %+% text_of(lhs) %+% " = " %+% text_of(Expr$show(rhs)) %+% ""), (if (truthy(eq(inf, NULL))) lst() else lst("the making against the taking is nought at \\rho_{\\infty} = " %+% text_of(Expr$show(inf$to)) %+% "")))))
    NULL
  })
  statik(cl, "reach", function(r = NULL, ...) {
