  method(cl, "forgotten", function(s = NULL, each = NULL, settled = NULL, ...) {
    rho_inf <- Expr$field("\\rho_{\\infty}")
    nf <- Expr$swap(settled$fact$to, Expr$to_power(Prover$POPULATION, Expr$num(2)), Expr$mul(lst(Expr$field("DEG"), Expr$sub(Expr$num(1), Prover$POPULATION))))
    .w("nf", Prover$tidy(nf))
    reach <- s$fact("is", "l.reach\\paren{\\bar{R}}")
    at <- (if (truthy(eq(reach, NULL))) Prover$reach("\\bar{R}") else Prover$neat(Expr$evaluate(reach$to, Prover$settled(s))))
    term <- Expr$mul(lst(Prover$reach("x.\\bar{R}"), Expr$field("x.\\bar{m}")))
