  method(cl, "felt", function(s = NULL, known = NULL, settled = NULL, ...) {
    nf <- Expr$swap(settled$fact$to, Expr$to_power(Prover$POPULATION, Expr$num(2)), Expr$mul(lst(Expr$field("DEG"), Expr$sub(Expr$num(1), Prover$POPULATION))))
    .w("nf", Prover$tidy(nf))
    k <- self$fold_weight
    base <- Prover$neat(Expr$add(lst(Expr$field("\\rho_{\\infty}"), Expr$mul(lst(k, nf)))))
    fill <- Prover$settled(s)
    c <- (if (truthy(eq(mem(fill, key_("\\bar{c}")), NULL))) Expr$field("\\bar{c}") else Expr$num(mem(fill, key_("\\bar{c}"))))
    term <- Prover$neat(Expr$mul(lst(Expr$field("x.\\bar{m}"), Expr$pown(Expr$mul(lst(Expr$field("l.shell\\paren{x.\\bar{R}}"), c)), neg(1)))))
    rhs <- Expr$add(lst(base, Expr$call("\\sum_{x = x_{@t}}", term)))
    weighed <- (if (truthy(((if (truthy(.x <- eq(k$kind, "num"))) eq(k$value, 1) else .x)))) "n_{f}" else "" %+% text_of(Expr$show(k)) %+% "·n_{f}")
    return(Step$of(Fact$stands("\\paren{\\rho + " %+% text_of(weighed) %+% "}_{l}\\paren{t}", rhs), "what a local feels from every body", lst(known$fact$key, settled$fact$key), "the near field is the rays alone, and they are gone in a free path - into the record. But rays and record together the vacuum never loses: a meeting turns " %+% text_of(Expr$show(k)) %+% " rays into a fold, a creation turns a fold back into rays, and the conserved line says so. So what a body puts out is all still there, spread over the space it went into - and from a steady body xt only spreads: what crosses the shell at any distance in a tick is what the body put out, so per site it is the body's mass over that shell, and it dwells one over \\bar{c} there. From every body xt is the sum, each from its own distance - its own walk, on whatever lattice, folded as it may be. That is the force felt at a local: the record it holds above the settled one is what bends every heading through it, and this is where that record came from", lst("rays plus record is conserved: what a body puts out is never lost to the vacuum, only spread", "what crosses the shell at x.\\bar{R} in a tick is what the body put out x.\\bar{R} ticks ago: per site, that over l.shell\\paren{x.\\bar{R}}, dwelling 1/\\bar{c}", "the settled vacuum underneath it: " %+% text_of(Expr$show(base)) %+% "", "no l.reach here - that is the rays alone, and is the mass law's own near field", "\\paren{\\rho + " %+% text_of(weighed) %+% "}_{l}\\paren{t} = " %+% text_of(Expr$show(rhs)) %+% "")))
    NULL
  })
  method(cl, "one_body", function(s = NULL, field_ = NULL, ...) {
