  method(cl, "balance", function(rec = NULL, s = NULL, ...) {
    inf <- s$fact("is", "\\rho_{\\infty}")
    if (truthy(eq(inf, NULL))) {
      return(NULL)
    }
    rho <- Expr$field("\\rho_{l}")
    inf_ <- Expr$field("\\rho_{\\infty}")
    got <- Expr$mul(lst(Expr$sub(inf_, rho), Expr$add(lst(rho, inf_, Expr$field("DEG")))))
    raw <- Expr$sub(Expr$mul(lst(Expr$field("DEG"), Expr$sub(Expr$num(1), rho))), Expr$to_power(rho, Expr$num(2)))
    diff <- Expr$simplify(Expr$expand(Expr$sub(got, raw)))
    .w("diff", Expr$gather(Expr$expand(Expr$swap(diff, Expr$to_power(inf_, Expr$num(2)), Expr$mul(lst(Expr$field("DEG"), Expr$sub(Expr$num(1), inf_)))))))
    exact <- (if (truthy(.x <- eq(diff$kind, "num"))) eq(diff$value, 0) else .x)
    check <- (if (truthy(exact)) " - checked exact" else "")
    return(Step$of(Fact$stands("l.balance", got), "where the making pays for the taking", lst(rec$fact$key, inf$key), "the vacuum's balance at the local: the making, creation lighting every dark exit of a point, less the taking, the meetings. It is a quadratic in the density, and the settled density is its root - that is what vacuum.occupancy says rho_infty is - so it factors: how far the density here is from settled, times the rate the vacuum pulls it back at, which is the density plus the settled one plus the ways a point has to relight. Positive below the settled density, negative above it: a restoring term. It stands on the population's line as what the vacuum does to the rays, and on the record's with the opposite sign, as what the meetings write above what creation clears - one quantity in both, and its cancelling between them is the conservation of rays plus record", lst("DEG\\paren{1 - \\rho_{l}} - \\rho_{l}^{2} = " %+% text_of(Expr$show(got)) %+% ", since \\rho_{\\infty}^{2} = DEG\\paren{1 - \\rho_{\\infty}}" %+% text_of(check) %+% "", "l.balance = " %+% text_of(Expr$show(got)) %+% "", "nought where the vacuum has settled; a pull back toward \\rho_{\\infty} elsewhere")))
    NULL
  })
