  method(cl, "one_line", function(rec = NULL, given = NULL, ...) {
    if (truthy(eq(given, NULL))) {
      .w("given", NULL)
    }
    lhs <- "\\Delta_{\\hat{d}}\\rho_{l} + a·\\nabla S_{l}"
    rhs <- Expr$add(lst(Expr$field("l.balance"), Expr$field("l.\\bar{m}")))
    return(Step$of(Fact$stands(lhs, rhs), "one line for every mass", lst(rec$fact$key), "the population's own line, with its names: STREAMING, the density followed along its heading - what the ray finds one step on; plus BENDING, the record's slope along the lean - how the record every mass left here turns the heading; equals the vacuum's BALANCE, the making less the taking, which pulls the density back toward the settled one; plus the mass standing here. The balance is kept on the line and not cancelled against the record, because every theorem of this theory stands on it: the settled density is its root, the free path is one over its taking, the mass law is the source through the taking over a body's depth, the screening is the taking along the way - and the transport's turn is the lean. So this is the line the theorems follow from, one step of indirection from the rules: the rules' own terms, with the constants filled in and the record given its name. Adding the record's own line to it cancels the balance and gives the conserved line, rays plus record, which is a consequence and is kept as one. TO FILL IT IN: l.\\bar{m} as a field over the locals and the ticks - where each body stands at each tick and what it lights then - and S from the record's line, or, far from every body, from the sum over the locals", lst("" %+% text_of(lhs) %+% " = " %+% text_of(Expr$show(rhs)) %+% "", "streaming + bending = the balance + the mass here", "the theorems' roots: the making and the taking (the balance), the source (emission), the transport and its turn (movement, the kernel) - all on this line", "the conserved line, rays plus record, is this plus the record's own line - a consequence")))
    NULL
  })
  method(cl, "settled_line", function(line = NULL, bal = NULL, ...) {
    lhs <- "\\Delta_{\\hat{d}}\\rho_{l} + a·\\nabla S_{l} \\aside{at} \\rho_{\\infty}"
    return(Step$of(Fact$stands(lhs, Expr$field("l.\\bar{m}")), "the vacuum settled", lst(line$fact$key, bal$fact$key), "where the vacuum has settled, the density is the settled one and the balance is nought: the making pays for the taking exactly, and what the vacuum does to the rays on its own is gone from the line. That is the far field - beyond a free path of every body, where the density along every path is \\rho_{\\infty} - and it is the assumption that the near-field terms do not matter, made once and named. What is left is streaming plus bending equals the mass standing here: the rays are carried, the record every mass left here turns them, and only a body adds anything. The record's line loses its imbalance the same way and relaxes to the settled record at the creation rate", lst("l.balance = 0 at \\rho_{l} = \\rho_{\\infty}", "" %+% text_of(lhs) %+% " = l.\\bar{m}", "and the record: \\Delta_{t}S_{l} \\aside{at} \\rho_{\\infty} = \\paren{DEG - S_{l}}\\paren{1 - \\rho_{\\infty}}")))
    NULL
  })
  method(cl, "settled_S", function(line = NULL, bal = NULL, ...) {
    rhs <- Expr$mul(lst(Expr$sub(Expr$field("DEG"), Expr$field("S_{l}")), Expr$sub(Expr$num(1), Expr$field("\\rho_{\\infty}"))))
    return(Step$of(Fact$stands("\\Delta_{t}S_{l} \\aside{at} \\rho_{\\infty}", rhs), "the vacuum settled", lst(line$fact$key, bal$fact$key), "the record's line at the settled density: the imbalance is nought, and creation clears whatever record stands above the settled one, DEG, at its own rate - so the record relaxes to DEG where nothing is sent, and far from every body what stands above DEG is the sum over the locals of what the masses sent", lst("\\Delta_{t}S_{l} \\aside{at} \\rho_{\\infty} = " %+% text_of(Expr$show(rhs)) %+% "")))
    NULL
  })
  method(cl, "bent_line", function(quiet = NULL, lean_ = NULL, s = NULL, ...) {
    bend <- Expr$mul(lst(Expr$field("\\partial_{\\hat{d}}\\rho_{l}"), Expr$field("g")))
    return(Step$of(Fact$stands("a·\\nabla S_{l}", bend), "the bending, read as the pull", lst(quiet$fact$key, lean_$fact$key), "the bending term of the settled line is the lean times the record's slope. The lean is half the density's difference across the headings (vacuum.lean), and the record's slope is what a body is carried along: TRANSPORT leans a body on the folds of the points across each way, so what a body feels, g, is the record's gradient - and the record in rays' worth is twice the folds, so g = \\frac{1}{2}\\nabla S_{l}. Put the two in and the bending is the density's difference across the headings times the pull: g stands on the line's own left side, and that is where the recursion is read from", lst("a = \\frac{1}{2}\\partial_{\\hat{d}}\\rho_{l} (vacuum.lean)", "S_{l} = 2n_{f,l}, and TRANSPORT carries a body along \\nabla n_{f}: g = \\frac{1}{2}\\nabla S_{l}", "a·\\nabla S_{l} = \\frac{1}{2}\\partial_{\\hat{d}}\\rho_{l}·2g = " %+% text_of(Expr$show(bend)) %+% "")))
    NULL
  })
  method(cl, "bent_far", function(bent = NULL, known = NULL, quiet = NULL, ...) {
    screened <- Expr$call("\\sum_{x = x_{@t}}", Expr$mul(lst(Expr$field("x.\\bar{m}"), Prover$reach("x.\\bar{R}"))))
    got <- Expr$div(Expr$field("g_{N}"), Expr$sub(Expr$num(1), screened))
    return(Step$of(Fact$stands("g \\aside{bent}", got), "the far field, bent", lst(bent$fact$key, known$fact$key, quiet$fact$key), "what streams into a local along a heading is the mass there less what the record bends off it: \\Delta_{\\hat{d}}\\rho_{l} = l.\\bar{m} - \\partial_{\\hat{d}}\\rho_{l}·g. The difference across the headings is the rays alone, since the vacuum's own rays are alike on every heading and the record sits on the point, not on a heading: it is what the bodies' rays put there, \\rho_{l} - \\rho_{\\infty} = \\sum x.\\bar{m}·l.reach\\paren{x.\\bar{R}} (ignorant of what came before). So what a body feels is what arrives, g_{N}, plus that difference times g - and solved for g it is g_{N} over one less the rays' own screened sum. THE ENHANCEMENT IS ON g_{N} AND IT IS SCREENED: l.reach dies in a free path, so beyond one the bending gives the arrival back unchanged. This reading puts no a_{0}/g on the line; whatever the recursion of the force law is, it is not this term far from a body", lst("\\Delta_{\\hat{d}}\\rho_{l} = l.\\bar{m} - a·\\nabla S_{l} = l.\\bar{m} - \\partial_{\\hat{d}}\\rho_{l}·g", "\\partial_{\\hat{d}}\\rho_{l}: the rays alone - " %+% text_of(Expr$show(screened)) %+% "", "g = g_{N} + \\partial_{\\hat{d}}\\rho_{l}·g", "g \\aside{bent} = " %+% text_of(Expr$show(got)) %+% "", "l.reach\\paren{\\bar{R}} -> 0 past a free path: g -> g_{N}")))
    NULL
  })
  method(cl, "record_here", function(big_s = NULL, bal = NULL, ...) {
    parts <- m_split(Expr, big_s$fact$to, "S_{l}")
    if (truthy(eq(parts, NULL))) {
      return(NULL)
    }
    here <- Prover$neat(Expr$div(Expr$neg(elem(parts, 1)), elem(parts, 0)))
    written <- Prover$neat(Expr$replace(here, "l.balance", bal$fact$to))
    st <- Step$of(Fact$stands("S_{l} \\aside{standing}", written), "the record standing against the density here", lst(big_s$fact$key, bal$fact$key), "the record's line at a standstill, \\Delta_{t}S_{l} = 0, is linear in the record: the meetings write it and creation clears what stands above DEG at the share of dark ways here, 1 - \\rho_{l}. Solved for S_{l} it is DEG less the balance over that share - and the balance is how far the density here is from settled times the rate the vacuum pulls it back. Where a body's rays raise the density the balance is negative and the clearing is slow, so the record stands ABOVE DEG by that quotient. Nothing in it is at \\rho_{\\infty}: this is the record where the density is what it is", lst("\\Delta_{t}S_{l} = 0: " %+% text_of(Expr$show(big_s$fact$to)) %+% " = 0", "S_{l} = " %+% text_of(Expr$show(here)) %+% "", "l.balance = " %+% text_of(Expr$show(bal$fact$to)) %+% "", "S_{l} = " %+% text_of(Expr$show(written)) %+% ""))
    .set(st, "parts_", lst(written))
