    NULL
  })
  method(cl, "record_slope", function(here = NULL, s = NULL, ...) {
    inf <- s$fact("is", "\\rho_{\\infty}")
    if (truthy((if (truthy(.x <- eq(inf, NULL))) .x else m_empty(here$parts_)))) {
      return(NULL)
    }
    rho <- "\\rho_{l}"
    dS <- Prover$neat(Expr$d(elem(here$parts_, 0), rho))
    at <- Expr$replace(dS, rho, Expr$field("\\rho_{\\infty}"))
    .w("at", Prover$tidy(Expr$swap(Expr$expand(at), Expr$to_power(Expr$field("\\rho_{\\infty}"), Expr$num(2)), Expr$mul(lst(Expr$field("DEG"), Expr$sub(Expr$num(1), Expr$field("\\rho_{\\infty}")))))))
    .w("at", Prover$tidy(Expr$reduced(Expr$expand(Expr$reduced(at)))))
    Q <- Prover$tidy(Expr$reduced(Expr$mul(lst(Expr$num(0.5), at))))
    got <- Expr$mul(lst(Q, Expr$field("\\nabla\\rho_{l}")))
    return(Step$of(Fact$stands("g \\aside{at} \\rho_{\\infty}", got), "the pull off the record standing here", lst(here$fact$key, inf$key), "what a body feels is the record's slope, g = \\frac{1}{2}\\nabla S_{l}, and the record standing here is a function of the density here alone - so its slope is its slope in the density times the density's slope, by the chain rule. Read where the vacuum has settled, the slope in the density is a number of the lattice: the record answers a rise in the density by \\frac{2\\rho_{\\infty} + DEG}{1 - \\rho_{\\infty}}, and it is large because the clearing share 1 - \\rho_{\\infty} is small. THAT FACTOR IS WHERE DEG STANDS IN THE FAR FIELD: not in the shape of the curve, which the density's slope sets, but in how much record a given density buys. It is not a_{0}/g either - the density's slope is what the bodies' rays make at the local, screened, so this reading amplifies the near field rather than the arrival at a distance", lst("g = \\frac{1}{2}\\nabla S_{l} = \\frac{1}{2}\\frac{\\partial S_{l}}{\\partial \\rho_{l}}·\\nabla\\rho_{l}", "\\frac{\\partial S_{l}}{\\partial \\rho_{l}} = " %+% text_of(Expr$show(dS)) %+% "", "at \\rho_{\\infty}, with \\rho_{\\infty}^{2} = DEG\\paren{1 - \\rho_{\\infty}}: " %+% text_of(Expr$show(at)) %+% "", "g \\aside{at} \\rho_{\\infty} = " %+% text_of(Expr$show(got)) %+% "")))
    NULL
  })
  getter(cl, "space_text", function() {
