      by <- (if (truthy(eq(mag, "1"))) t$symbol else "" %+% text_of(mag) %+% "·" %+% text_of(t$symbol) %+% "")
      head <- (if (truthy(eq(i, 0))) ((if (truthy(minus)) "-" else "")) else ((if (truthy(minus)) " - " else " + ")))
      .w("out", "" %+% text_of(out) %+% "" %+% text_of(head) %+% "" %+% text_of(by) %+% "")
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return("\\partial_{t}s = " %+% text_of(out) %+% "")
    NULL
  })
