  statik(cl, "annotate", function(e = NULL, s = NULL, at = NULL, of = NULL, ...) {
    known <- Prover$names_known(s, at)
    out <- lst()
    seen <- Node$new()
    whole <- Expr$show(Expr$simplify(e))
    look <- function(x = NULL, depth = NULL, ...) {
      k <- Expr$show(Expr$simplify(x))
      hit <- known$get(k)
      if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (!eq(hit, NULL)))) eq(elem(seen, k), NULL) else .x))) (!eq(k, whole)) else .x))) (!eq(elem(hit, 0), of)) else .x))) (!eq(elem(hit, 0), "F_{g}")) else .x))) (!truthy(m_starts_with(elem(hit, 0), "F_{g} "))) else .x))) {
        set_at(seen, k, TRUE)
        return(m_push(out, Part$new(part = k, stands = elem(hit, 0), because = elem(hit, 1))))
      } else {
        if (truthy(le(depth, 5))) {
          if (truthy((if (truthy(.x <- eq(x$kind, "mul"))) .x else eq(x$kind, "add")))) {
            .r <- for_each(x$of, function(y) {
              (look)(y, r_add(depth, 1))
              CONTINUE
            })
            if (!is.null(.r)) return(.r[[1]])
          } else {
            if (truthy(eq(x$kind, "pow"))) {
              return((look)(x$base, r_add(depth, 1)))
            }
          }
        }
      }
      NULL
    }
    (look)(Expr$simplify(e), 0)
    return(out)
    NULL
  })
  statik(cl, "standing_for", function(e = NULL, s = NULL, of = NULL, ...) {
    facts <- Prover$by_name(s)
    known <- Prover$names_known(s, "R")
    cite <- function(x = NULL, v_self = NULL, d = NULL, ...) {
      if (truthy(gt(d, 0))) {
        k <- Expr$show(Expr$simplify(x))
        hit <- known$get(k)
        if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (!eq(hit, NULL)))) (!eq(elem(hit, 0), v_self)) else .x))) (!truthy(Prover$in_r(elem(hit, 0)))) else .x))) gt(len(k), ((if (truthy(gt(r_add(len(elem(hit, 0)), 8), 24))) r_add(len(elem(hit, 0)), 8) else 24))) else .x))) {
          return(Expr$field("\\text{" %+% text_of(elem(hit, 0)) %+% "}"))
        }
      }
      if (truthy(gt(d, 2))) {
        return(x)
      }
      if (truthy(eq(x$kind, "add"))) {
        return(Expr$add(m_map(x$of, function(y = NULL, ...) {
          return((cite)(y, v_self, r_add(d, 1)))
          NULL
        })))
      }
      if (truthy(eq(x$kind, "mul"))) {
        return(Expr$mul(m_map(x$of, function(y = NULL, ...) {
          return((cite)(y, v_self, r_add(d, 1)))
          NULL
        })))
      }
      return(x)
      NULL
    }
    out <- lst()
    done <- Node$new()
    if (truthy((!truthy(m_empty(of))))) {
      set_at(done, of, TRUE)
    }
    front <- lst(Expr$simplify(e))
    round <- 0
    while (truthy((if (truthy(.x <- lt(round, 6))) (!truthy(m_empty(front))) else .x))) {
      found <- lst()
      walk <- function(x = NULL, ...) {
        k <- x$kind
        if (truthy((if (truthy(.x <- eq(k, "sym"))) .x else eq(k, "field")))) {
          return(m_push(found, x$label))
        } else {
          if (truthy((if (truthy(.x <- eq(k, "add"))) .x else eq(k, "mul")))) {
            .r <- for_each(x$of, function(y) {
              (walk)(y)
              CONTINUE
            })
            if (!is.null(.r)) return(.r[[1]])
          } else {
            if (truthy(eq(k, "pow"))) {
              (walk)(x$base)
              return((walk)(x$power))
            } else {
              if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- eq(k, "grad"))) .x else eq(k, "log")))) .x else eq(k, "exp")))) .x else eq(k, "root")))) {
                return((walk)(x$base))
              } else {
                if (truthy((if (truthy(.x <- eq(k, "choose"))) .x else eq(k, "gammaInc")))) {
                  (walk)(x$first_)
                  return((walk)(x$second_))
                }
              }
            }
          }
        }
        NULL
      }
      .r <- for_each(front, function(x) {
        (walk)(x)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      v_next <- lst()
      .r <- for_each(found, function(name) {
        if (!truthy(eq(elem(done, name), TRUE))) {
          set_at(done, name, TRUE)
          f <- facts$get(Prover$plain(name))
          if (!truthy(eq(f, NULL))) {
            to <- Expr$simplify(elem(f, 0))
            if (!truthy(eq(Expr$show(to), name))) {
              cited <- (cite)(to, Prover$plain(name), 0)
              m_push(out, Standing$new(name = Prover$plain(name), stands = Expr$show(cited), because = elem(f, 1)))
              m_push(v_next, cited)
            }
          }
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .w("front", v_next)
      .w("round", r_add(round, 1))
    }
    return(out)
    NULL
  })
