    back <- (if (truthy(eq(agg, NULL))) NULL else self$remembered(s, agg))
    each <- (if (truthy(eq(back, NULL))) NULL else self$from_each(s, back))
    known <- (if (truthy(eq(each, NULL))) NULL else self$forgotten(s, each, settled))
    pull <- (if (truthy(eq(known, NULL))) NULL else self$felt(s, known, settled))
    one_ <- (if (truthy(eq(pull, NULL))) NULL else self$one_body(s, pull))
    rec <- (if (truthy(eq(pull, NULL))) NULL else self$record_of_all(known, pull, settled))
    locals <- (if (truthy(eq(rec, NULL))) NULL else self$every_local(rec, settled))
    at_ <- (if (truthy(eq(locals, NULL))) NULL else self$at_time(locals))
    follow <- (if (truthy(eq(locals, NULL))) NULL else self$following(locals))
    lean_ <- (if (truthy(eq(locals, NULL))) NULL else self$lean(locals))
    bal <- (if (truthy(eq(locals, NULL))) NULL else self$balance(locals, s))
    worth <- (if (truthy(eq(bal, NULL))) NULL else self$record_worth(locals, folded))
    big_s <- (if (truthy(eq(bal, NULL))) NULL else self$record_S(locals, folded))
    far <- (if (truthy(eq(bal, NULL))) NULL else self$record_sum(locals))
    whole_line <- (if (truthy(eq(bal, NULL))) NULL else self$one_line(locals, filled))
    quiet <- (if (truthy(eq(whole_line, NULL))) NULL else self$settled_line(whole_line, bal))
    quiet_s <- (if (truthy(eq(whole_line, NULL))) NULL else self$settled_S(whole_line, bal))
    bent <- (if (truthy(((if (truthy(.x <- eq(quiet, NULL))) .x else eq(lean_, NULL))))) NULL else self$bent_line(quiet, lean_, s))
    bent_far <- (if (truthy(((if (truthy(.x <- eq(bent, NULL))) .x else eq(known, NULL))))) NULL else self$bent_far(bent, known, quiet))
    here <- (if (truthy(((if (truthy(.x <- eq(big_s, NULL))) .x else eq(bal, NULL))))) NULL else self$record_here(big_s, bal))
    slope <- (if (truthy(eq(here, NULL))) NULL else self$record_slope(here, s))
    solved <- filt(lst(back, each, known, pull, one_, rec, locals, at_, follow, lean_, bal, worth, big_s, far, whole_line, quiet, quiet_s, bent, bent_far, here, slope), function(x = NULL, ...) {
      return((!eq(x, NULL)))
      NULL
    })
    chain <- m_concat(m_concat(m_concat(m_concat(line, lst(self$isotropic_population, filled, spaced, folded, one, whole)), (if (truthy(eq(settled, NULL))) lst() else lst(settled, short))), (if (truthy(eq(agg, NULL))) lst() else lst(agg))), solved)
    named <- Keyed$new()
    .r <- for_each(filt(lst(at_, follow, lean_, bal, worth, big_s, far, quiet, quiet_s, bent, bent_far, here, slope), function(x = NULL, ...) {
      return((!eq(x, NULL)))
      NULL
    }), function(st) {
      named$set(st$fact$of, st)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    proved <- m_map(self$theory$theorems, function(t = NULL, ...) {
      q <- t$asked
      p <- Proved$new(theorem = t$id, theory = self$theory$name, asks = q$asks, about = q$about)
      hit <- (if (truthy(m_empty(q$about))) NULL else named$get(q$about))
      root <- elem(s$steps, Fact$key_of("is", "the continuous model"))
      steps <- (if (truthy(m_empty(q$about))) chain else ((if (truthy((!eq(hit, NULL)))) ((if (truthy(eq(root, NULL))) lst(hit) else lst(root, hit))) else Prover$behind(s, q$about))))
      end <- (if (truthy(m_empty(q$about))) NULL else m_last(steps))
      .set(p, "steps", m_map(steps, function(st = NULL, ...) {
        return(self$line_of(st))
        NULL
      }))
      if (truthy(m_empty(q$about))) {
        .set(p, "concluded", Prover$headline((or_else(or_else(or_else(whole_line, agg), short), whole))$fact, NULL))
        .set(p, "standing", TRUE)
      } else {
        if (truthy((if (truthy(.x <- (!eq(end, NULL)))) (!eq(end$fact$of, q$about)) else .x))) {
          .w("end", NULL)
        }
        if (truthy(eq(end, NULL))) {
          .set(p, "missing", missing)
        } else {
          chained <- ""
          if (truthy((!eq(q$chain, NULL)))) {
            walk <- Prover$behind(s, q$chain)
            at <- m_last(walk)
            .w("chained", (if (truthy(((if (truthy(.x <- (if (truthy(.x <- (!eq(at, NULL)))) eq(at$fact$kind, "is") else .x))) eq(at$fact$of, q$chain) else .x)))) " = " %+% text_of(Expr$show(Expr$deep_factored(Expr$evaluate(at$fact$to, fill)))) %+% "" else ""))
          }
          .set(p, "concluded", (if (truthy((!eq(hit, NULL)))) Prover$headline(end$fact, NULL) else "" %+% text_of(Prover$headline(end$fact, fill)) %+% "" %+% text_of(chained) %+% ""))
          .set(p, "standing", TRUE)
          if (truthy(eq(end$fact$kind, "is"))) {
            .set(p, "parts", Prover$annotate(end$fact$to, s, "R", q$about))
            .set(p, "standing_for", Prover$standing_for(end$fact$to, s, q$about))
          }
        }
      }
      .set(p, "leads", q$leads)
      .set(p, "then", q$then)
      if (truthy((!eq(q$also, NULL)))) {
        hitA <- named$get(q$also)
        walk <- (if (truthy((!eq(hitA, NULL)))) lst(hitA) else Prover$behind(s, q$also))
        at <- m_last(walk)
        .set(p, "also", (if (truthy(((if (truthy(.x <- (!eq(at, NULL)))) eq(at$fact$of, q$also) else .x)))) ((if (truthy((!eq(hitA, NULL)))) Prover$headline(at$fact, NULL) else Prover$headline(at$fact, fill))) else NULL))
      }
      .set(p, "terms", m_map(self$infos, function(t = NULL, ...) {
        return(TermRecord$new(symbol = t$symbol, sign = t$sign, degree = t$degree, facing = t$facing, rays = t$rays, space = t$space, rules = t$rules, says = t$says))
        NULL
      }))
      return(p)
      NULL
    })
    return(Proof$new(theory = self$theory$name, proved = proved))
    NULL
  })
  method(cl, "chain", function(s = NULL, ...) {
    out <- Keyed$new()
    filled <- self$line_filled(s)
    spaced <- self$ledger_filled(s, "space")
    folded <- self$ledger_filled(s, "folds")
    one <- self$ledgers_are_one(s, folded, spaced)
    whole <- self$general(filled, folded)
    settled <- self$settled_record(folded)
    short <- (if (truthy(eq(settled, NULL))) NULL else self$single(whole, settled, folded, s))
    agg <- (if (truthy(eq(short, NULL))) NULL else self$aggregate(whole, short, s))
    back <- (if (truthy(eq(agg, NULL))) NULL else self$remembered(s, agg))
    each <- (if (truthy(eq(back, NULL))) NULL else self$from_each(s, back))
    known <- (if (truthy(eq(each, NULL))) NULL else self$forgotten(s, each, settled))
    pull <- (if (truthy(eq(known, NULL))) NULL else self$felt(s, known, settled))
    rec <- (if (truthy(eq(pull, NULL))) NULL else self$record_of_all(known, pull, settled))
    whole_line <- (if (truthy(eq(rec, NULL))) NULL else self$one_line(rec))
    grown <- self$growth_filled(s)
    roles <- lst("population", "space", "folds", "one", "general", "settled", "single", "aggregate", "remembered", "each", "known", "felt", "record", "line", "growth")
    steps <- lst(filled, spaced, folded, one, whole, settled, short, agg, back, each, known, pull, rec, whole_line, grown)
    .r <- for_range(len(roles), function(i) {
      if (truthy((!eq(elem(steps, i), NULL)))) {
        out$set(elem(roles, i), elem(steps, i))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
})

