      return(e)
    }
    inner <- Expr$simplify(Expr$add(lst(Expr$num(1), Expr$mul(lst(Expr$sub(X, sq), Expr$pown(sq, neg(1)))))))
    got <- Expr$simplify(Expr$mul(lst(A, Expr$add(lst(Expr$num(1), Expr$pown(inner, 0.5))))))
    return((if (truthy(le(len(Expr$show(got)), len(Expr$show(e))))) got else e))
    NULL
  })
  statik(cl, "clear_root", function(e = NULL, ...) {
    if (truthy((if (truthy(.x <- (!eq(e$kind, "add")))) .x else (!eq(len(e$of), 2))))) {
      return(e)
    }
    i <- NULL
    .r <- for_range(2, function(k) {
      if (truthy((if (truthy(.x <- (if (truthy(.x <- eq(i, NULL))) eq(elem(e$of, k)$kind, "pow") else .x))) eq(elem(e$of, k)$by_num, 0.5) else .x))) {
        .w("i", k)
