    if (truthy(eq(Expr$show(under), "0"))) {
      return(e)
    }
    return(Expr$simplify(Expr$mul(lst(over, Expr$pown(under, neg(1))))))
    NULL
  })
  statik(cl, "everywhere", function(f = NULL, e = NULL, ...) {
