        return((go)(y))
        NULL
      })) else ((if (truthy(eq(k, "pow"))) Expr$to_power((go)(x$base), (go)(x$power)) else ((if (truthy(eq(k, "root"))) Expr$root((go)(x$base), x$bound) else x)))))))
