  static_getter(cl, "spreading", function() {
    return(Inference$new(name = "spreading", because = "count what crosses a shell in a tick: the sites on it, times what is at each, times how many of those step outward - and MOVEMENT neither makes nor destroys, so that count is the same at every distance", fire = function(s = NULL, ...) {
      out <- lst()
      v <- s$stands("v")
      if (truthy(eq(v, NULL))) {
        return(lst())
      }
      .r <- for_each(s$all("conserved"), function(c) {
        if (truthy(s$has("isotropic", c$of))) {
          shell <- s$fact("grows", "shell")
          if (truthy((if (truthy(.x <- (!eq(shell, NULL)))) (!truthy(s$has("is", "" %+% text_of(c$of) %+% " per site"))) else .x))) {
            flux <- Expr$simplify(Expr$mul(lst(Expr$sym(c$of), Expr$pown(shell$to, neg(1)))))
            per <- Expr$simplify(Expr$mul(lst(flux, Expr$pown(v, neg(1)))))
            m_push(out, Inferences$step("" %+% text_of(c$of) %+% " per site", per, "spreading", lst(c$key, Fact$key_of("isotropic", c$of), shell$key), "count what crosses a shell in one tick - the sites on it, times what is at each, times the share of a step that went outward - and MOVEMENT neither makes nor destroys, so that count is carried outward unchanged. So what CROSSES one site is the whole of it over the number of sites there are at that distance. What IS at one site is that again over how fast a share gets across, and how fast a share gets across is not a constant: a carrier with nowhere to step makes the room instead and does not move, so it dwells longer exactly where the medium is thin. Solving the conservation with that speed in it is one quadratic with one root that is not negative - the old line where the medium is dense, and a square root where it is not", lst("what crosses one site: " %+% text_of(c$of) %+% "/shell = " %+% text_of(Expr$show(flux)) %+% "", "and it dwells 1/v there, with v = " %+% text_of(Expr$show(v)) %+% " off turns's own draw", "" %+% text_of(c$of) %+% " per site = " %+% text_of(Expr$show(per)) %+% "")))
