  })
  static_getter(cl, "ehrhart", function() {
    return(Inference$new(name = "how many places are r steps out", because = "`exits` is the ways out of a point and there are DEG of them, so the places reached in r steps are counted by walking those exits r times - and what that count comes to is fixed by how many independent ways out there are, which is what D names", fire = function(s = NULL, ...) {
      if (truthy(s$has("grows", "shell"))) {
        return(lst())
      }
      return(lst(Step$of(Fact$new(kind = "grows", of = "shell", to = Expr$to_power(Expr$sym("r"), Expr$sub(Inferences$D, Expr$num(1)))), "how many places are r steps out", lst(), "the rules give a point, DEG ways out of it, and where each one leads - and nothing else about where anything is. So how far is how many steps were taken, and how many places are that far out is a count of walks. D is how many of those ways are independent, so within r steps there are r choices along each of D and the places within r go as r^{D}; the places at exactly r are the difference between two of those, which is r^{D-1}. Every step is whole and every place counted once, so this is the count itself and not an approximation to one", lst("exits(p): the ways out of a point, DEG of them", "steps: where one exit leads - and that is all the rules say about where anything is", "D of those ways are independent, so places within r steps ∝ r^{D}", "shell(r) = ball(r) - ball(r-1) ∝ r^{D-1}"))))
      NULL
    }))
    NULL
  })
  static_getter(cl, "screening", function() {
    return(Inference$new(name = "what is pushed back is screened", because = "a carrier is destroyed when it meets something, so what survives r steps is what survived one, r times over - a factor per step, which is a power and not an exponential", fire = function(s = NULL, ...) {
      out <- lst()
      .r <- for_each(s$all("conserved"), function(c) {
        per <- s$fact("is", "" %+% text_of(c$of) %+% " per site")
        if (truthy((if (truthy(.x <- (if (truthy(.x <- (!eq(per, NULL)))) (!truthy(s$has("restored", c$of))) else .x))) (!truthy(s$has("is", "" %+% text_of(c$of) %+% " screened"))) else .x))) {
          m_push(out, Inferences$step("" %+% text_of(c$of) %+% " screened", per$to, "what is pushed back is screened", lst(c$key, per$key), "nothing in the line pushes " %+% text_of(c$of) %+% " back, so the chance of surviving one step is one and the chance of surviving r of them is one. What is left at r is what spread there, and the dilution is the whole of the law", lst("nothing restores " %+% text_of(c$of) %+% ", so survives(r) = 1", "" %+% text_of(c$of) %+% " = " %+% text_of(Expr$show(per$to)) %+% "")))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .r <- for_each(s$all("restored"), function(rst) {
