        if (truthy((!eq(per, NULL)))) {
          a <- Expr$simplify(rst$to)
          if (!truthy((if (truthy(.x <- eq(a$kind, "num"))) eq(a$value, 0) else .x))) {
            L <- Expr$simplify(Expr$pown(Expr$mul(lst(a, Expr$sym("\\sigma_{tr}"))), neg(0.5)))
            damped <- Expr$simplify(Expr$mul(lst(per$to, Expr$to_power(Expr$sub(Expr$num(1), Expr$pown(Expr$sym("L"), neg(1))), Expr$sym("r")))))
            m_push(out, Inferences$step("L", L, "what is pushed back is screened", lst(rst$key, per$key), "what spreads is damped as well as diluted, and the range is where the two balance - one over the root of how hard it is pushed back times how fast it forgets which way it was going", lst("a = " %+% text_of(Expr$show(a)) %+% "", "L = " %+% text_of(Expr$show(L)) %+% "")))
            m_push(out, Inferences$step("" %+% text_of(rst$of) %+% " screened", damped, "what is pushed back is screened", lst(rst$key, per$key), "" %+% text_of(rst$of) %+% " is pushed back at " %+% text_of(Expr$show(a)) %+% ", so what spreads is damped as well as diluted - and the range is where the two balance. WHAT SURVIVES IS A POWER: a carrier takes whole steps and on each one it is either destroyed or it is not, so surviving r steps is surviving one, r times over. An exponential is that in the limit where no single step can matter, which is a continuum this lattice has not got", lst("\\nabla^{2}\\delta = " %+% text_of(Expr$show(a)) %+% "·\\sigma_{tr}·\\delta", "what spreads: " %+% text_of(Expr$show(per$to)) %+% "", "a carrier survives one step with 1 - 1/L, and r steps with that r times over", "damped: " %+% text_of(Expr$show(damped)) %+% "", "L = " %+% text_of(Expr$show(L)) %+% "")))
          }
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      return(out)
      NULL
    }))
    NULL
  })
  static_getter(cl, "refracting", function() {
    return(Inference$new(name = "what a place stands for, counted off what a fold does", because = "a fold joins what was behind each of the two points onto the other, so what a place stands for includes what the places it swallowed stood for - and that is a chain, not a tally", fire = function(s = NULL, ...) {
      out <- lst()
      f <- s$fact("is", "what swings a heading")
      if (truthy((if (truthy(.x <- eq(f, NULL))) .x else s$has("is", "N")))) {
        return(lst())
      }
      raw <- Expr$integrate(f$to, "n_{f}")
      if (truthy(eq(raw, NULL))) {
        return(lst())
      }
