  static_getter(cl, "room_balance", function() {
    return(Inference$new(name = "a way leads somewhere only if the point it leads to is still there", because = "a meeting folds two points into one, so the way that led to the second leads nowhere - and the share of ways that are clear is the share of the record that is empty", fire = function(s = NULL, ...) {
