      tkF <- s$fact("is", "the folds count of what is taken")
      if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- eq(mkC, NULL))) .x else eq(tkC, NULL)))) .x else eq(mkF, NULL)))) .x else eq(tkF, NULL)))) .x else s$has("is", "\\omega")))) {
        return(lst())
      }
      zero <- function(e = NULL, ...) {
        v <- Expr$simplify(e)
        return((if (truthy(.x <- eq(v$kind, "num"))) eq(v$value, 0) else .x))
        NULL
      }
