      held <- Expr$simplify(Expr$mul(lst(tkF$to, mkC$to, Expr$pown(Expr$mul(lst(mkF$to, tkC$to)), neg(1)))))
      got <- Expr$simplify(Expr$sub(Expr$num(1), held))
