  static_getter(cl, "arrangement", function() {
    return(Inference$new(name = "the same mass, gathered or scattered", because = "what a body sends is a face times what gets out through it, and that factor saturates for one big body and goes linear for many small ones", fire = function(s = NULL, ...) {
