      return(lst(Inferences$step("what a gathered mass sends", gathered, via, lst(puts$key), "all of it in one place is many mean free paths deep behind its own face, so what gets out through that face is all of it - the factor saturates and what is sent is set by the FACE. Mass added behind it is shadowed by its own skin and sends nothing", lst("\\paren{1-\\sigma\\rho}^{m/A} -> 0 as m/A grows", "what is sent -> " %+% text_of(Expr$show(gathered)) %+% "", "and that does not mention m at all - the inside is hidden")), Inferences$step("what a scattered mass sends", scattered, via, lst(puts$key), "cut into stars, each is thin: 1 - \\paren{1-\\sigma\\rho}^{x} is -x\\log\\paren{1-\\sigma\\rho} for small x, so a star sends its own MASS by that log and its face cancels. Arrivals add, so M/m_{*} of them send M by the same log - LINEAR IN THE TOTAL, with the star's mass and face both gone from the answer. How finely it is cut does not change it, which is the only way a sum over bodies can mean anything", lst("1 - \\paren{1-\\sigma\\rho}^{x} = -x\\log\\paren{1-\\sigma\\rho} + O\\paren{x^{2}}", "one star: A_{*}\\cdot\\frac{m_{*}}{A_{*}}\\cdot-\\log\\paren{1-\\sigma\\rho} = m_{*}\\cdot-\\log\\paren{1-\\sigma\\rho}", "M/m_{*} of them: " %+% text_of(Expr$show(scattered)) %+% ""))))
      NULL
    }))
    NULL
  })
  static_getter(cl, "curves_of_each", function() {
    return(Inference$new(name = "the curve each arrangement has", because = "what arrives is what is sent diluted over the shell, so each arrangement has its own arrival and its own curve", fire = function(s = NULL, ...) {
      v2 <- s$fact("is", "v^{2}")
      one2 <- s$fact("is", "v^{2} as one equation")
      gN <- s$fact("is", "g_{N}")
      puts <- s$fact("is", "what a body puts into the medium")
      one <- s$fact("is", "what a gathered mass sends")
      scattered <- s$fact("is", "what a scattered mass sends")
      if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- eq(v2, NULL))) .x else eq(gN, NULL)))) .x else eq(puts, NULL)))) .x else eq(one, NULL)))) .x else eq(scattered, NULL)))) .x else s$has("is", "v^{2} with the mass gathered")))) {
        return(lst())
      }
      thick <- Inferences$thick
      arrival <- function(by = NULL, ...) {
        return(Expr$simplify(Expr$swap(gN$to, thick, by)))
        NULL
      }
      curve <- function(by = NULL, ...) {
        return(Expr$simplify(Expr$swap(v2$to, Expr$field("g_{N}"), (arrival)(by))))
        NULL
      }
      told <- s$fact("is", "g_{N} in bodies and transport")
      front <- (if (truthy(((if (truthy(.x <- (!eq(told, NULL)))) eq(told$to$kind, "mul") else .x)))) elem(told$to$of, 0) else NULL)
      as_mass <- function(mark = NULL, ...) {
        if (truthy((if (truthy(.x <- eq(told, NULL))) .x else eq(front, NULL)))) {
          return(NULL)
        }
        return(Expr$simplify(Expr$swap(told$to, front, Expr$field(Expr$show(Expr$simplify(Expr$div(Expr$mul(lst(Expr$field("\\bar{m}_{" %+% text_of(mark) %+% "}"), Expr$field("\\bar{m}'"))), Expr$to_power(Inferences$rbar, Expr$sub(Inferences$D, Expr$num(1))))))))))
        NULL
      }
      deep <- Expr$num(0)
      thin <- Inferences$thin
      via <- "the curve each arrangement has"
      out <- lst(Inferences$step("what arrives with the mass gathered", (arrival)(deep), via, lst(gN$key, one$key), "what arrives is what is sent over the room of a shell, and gathered the sending is set by the face - so the arrival does not grow with the mass behind it", lst("g_{N} with what is sent replaced by " %+% text_of(Expr$show(one$to)) %+% "")), Inferences$step("what arrives with the mass scattered", (arrival)(thin), via, lst(gN$key, scattered$key), "and scattered the sending is the total mass by the log, so the arrival grows with all of it - every star radiates its whole self, none of it shadowed", lst("g_{N} with what is sent replaced by " %+% text_of(Expr$show(scattered$to)) %+% "")))
      .r <- for_each(lst(lst("gathered", "\\bullet", one), lst("scattered", "\\star", scattered)), function(trio) {
        which <- elem(trio, 0)
        mark <- elem(trio, 1)
        sends <- elem(trio, 2)
        g <- (as_mass)(mark)
        if (!truthy(eq(g, NULL))) {
          m_push(out, Inferences$step("what arrives with the mass " %+% text_of(which) %+% " in bodies and transport", g, via, lst(sends$key, gN$key), "the arrival at the " %+% text_of(which) %+% " mass, in the names the arrival was told apart into - the same separation and the same two transports, and the arrangement in the mass alone, which is the only thing it changes", lst("\\bar{m}_{" %+% text_of(mark) %+% "} = " %+% text_of(Expr$show(sends$to)) %+% "", "and the rest is unchanged")))
          if (truthy((!eq(one2, NULL)))) {
            m_push(out, Inferences$step("v^{2} with the mass " %+% text_of(which) %+% " as one equation in bodies and transport", Expr$simplify(Expr$swap(one2$to, Expr$field("g_{N}"), g)), via, lst(v2$key, sends$key), "the circle read at that arrival, against the equation the rules give rather than against its solution - so the arrival is written once", lst("v^{2} = R·g, and g = (that arrival)·(1 + a_{0}/g)")))
          }
          m_push(out, Inferences$step("v^{2} with the mass " %+% text_of(which) %+% " in bodies and transport", Expr$simplify(Expr$swap(v2$to, Expr$field("g_{N}"), g)), via, lst(v2$key, sends$key), "and the same curve solved for the speed rather than left as an equation in it - the arrangement is still in the mass alone", lst("v^{2} = R·F_{g} at that arrival")))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .r <- for_each(lst(lst("gathered", deep, one), lst("scattered", thin, scattered)), function(trio) {
        which <- elem(trio, 0)
        by <- elem(trio, 1)
        if (truthy((!eq(one2, NULL)))) {
          e <- Expr$simplify(Expr$swap(one2$to, Expr$field("g_{N}"), Expr$deep_factored((arrival)(by))))
          m_push(out, Inferences$step("v^{2} with the mass " %+% text_of(which) %+% " as one equation", e, via, lst(v2$key, elem(trio, 2)$key), "the circle read at the " %+% text_of(which) %+% " arrival, against the equation the rules give rather than against its solution - so the arrival is written once", lst("v^{2} = R·g, and g = (that arrival)·(1 + a_{0}/g)")))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      m_push(out, Inferences$step("v^{2} with the mass gathered", (curve)(deep), via, lst(v2$key, one$key), "the circle's law read at the gathered arrival - one source, the whole of it presenting its own face, which is what a galaxy taken as a single point comes to", lst("v^{2} = R·F_{g} at the gathered arrival")))
      m_push(out, Inferences$step("v^{2} with the mass scattered", (curve)(thin), via, lst(v2$key, scattered$key), "and read at the scattered arrival - a star apiece, each thin enough to send all of itself, which is what a galaxy taken as its stars comes to", lst("v^{2} = R·F_{g} at the scattered arrival")))
      return(out)
      NULL
    }))
    NULL
  })
