  statik(cl, "writing_out", function(of = NULL, ...) {
    return(Inference$new(name = "with every factor written in", because = "a name that has a law of its own is not a primitive - it is what that law shows it to be, so it stands in for itself", fire = function(s = NULL, ...) {
      F <- s$fact("is", of)
      if (truthy((if (truthy(.x <- eq(F, NULL))) .x else s$has("is", "" %+% text_of(of) %+% " in full")))) {
        return(lst())
      }
      about <- function(e = NULL, ...) {
        return(m_some(lst("R", "m", "A", "\\beta", "\\bar{m}_{x}"), function(n = NULL, ...) {
          return(Expr$mentions(e, n))
          NULL
        }))
        NULL
      }
      laws <- Keyed$new()
      .r <- for_each(s$nodes, function(n) {
        f <- n$fact
        if (truthy((if (truthy(.x <- (if (truthy(.x <- eq(f$kind, "is"))) (!truthy(Prover$in_r(f$of))) else .x))) ((if (truthy(.x <- (if (truthy(.x <- m_empty(n$upon))) .x else eq(Expr$simplify(f$to)$kind, "num")))) .x else (about)(f$to))) else .x))) {
          if (truthy((!truthy(laws$has(f$of))))) {
            laws$set(f$of, f$to)
          }
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      set_at(laws$vals, of, NULL)
      told <- s$fact("is", "g_{N} in bodies and transport")
      if (truthy((!eq(told, NULL)))) {
        laws$set("g_{N}", told$to)
      }
      .set(laws$vals, key_("T_{vac}"), NULL)
      .set(laws$vals, key_("T_{met}"), NULL)
      steps <- lst("" %+% text_of(of) %+% " = " %+% text_of(Expr$show(F$to)) %+% "")
      seen <- Node$new()
      written <- function(start = NULL, ...) {
        e <- start
        i <- 0
        stop <- FALSE
        while (truthy((if (truthy(.x <- lt(i, 24))) (!truthy(stop)) else .x))) {
          was <- Expr$show(e)
          .r <- for_each(laws$keys, function(name) {
            law <- elem(laws$vals, name)
            if (!truthy((if (truthy(.x <- (if (truthy(.x <- eq(law, NULL))) .x else (!truthy(Expr$mentions(e, name)))))) .x else Expr$mentions(law, name)))) {
              put <- Expr$deep_factored(law)
              .w("e", Expr$simplify(Expr$replace(e, name, put)))
              if (truthy(eq(elem(seen, name), NULL))) {
                set_at(seen, name, TRUE)
                m_push(steps, "" %+% text_of(name) %+% " = " %+% text_of(Expr$show(put)) %+% "")
              }
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          .w("stop", eq(Expr$show(e), was))
          .w("i", r_add(i, 1))
        }
        return(Inferences$folded(Expr$deep_factored(e)))
        NULL
      }
      a <- (written)(Inferences$folded(F$to))
      b <- (written)(Inferences$cleared(F$to))
      e <- (if (truthy(lt(len(Expr$show(b)), len(Expr$show(a))))) b else a)
      m_push(steps, "" %+% text_of(of) %+% " = " %+% text_of(Expr$show(e)) %+% "")
      return(lst(Inferences$step("" %+% text_of(of) %+% " in full", e, "with every factor written in", lst(F$key), "what is read straight off a rewrite is written in, because a reader could not have known it; what has a theorem of its own KEEPS ITS NAME and is cited, because writing it in would replace a proof with its answer. What is left standing is the rules' own rates, the counts of the tiling, the two bodies, and the handful of quantities that have pages of their own", steps)))
      NULL
    }))
    NULL
  })
