      return(m_map(lst("", "'"), function(b = NULL, ...) {
        return(Inferences$step("\\mathcal{D}" %+% text_of(b) %+% "", Inferences$doppler_is(b), "what motion does to what a body sends", lst(took$key), "ONE MOTION, TWO EFFECTS, AND ONLY ONE OF THEM IS HERE. `EMISSION` is gated on `spare = not(moving)`, so a tick spent crossing a cell is a tick not spent shining and a body emits on 1 - \\beta of its ticks - THE SAME IN EVERY DIRECTION, so that is how much the body sends and it is already in the mass, inside the source's own choice, `l.choose\\paren{\\bar{m}_{x·l.DEG·\\paren{1 - \\beta}}}`. WHAT IS DIRECTIONAL IS THE OTHER HALF: `MOVEMENT` gives one cell a tick, so a distance IS a time, and between two emissions a tick apart the body has closed \\beta\\cdot\\hat{d} of the way to wherever the ray is going - they land that much closer together and what arrives per tick is the reciprocal. IT IS THE CLASSICAL DOPPLER FACTOR and nothing about waves or observers went into it. A body blocks the vacuum's making whether it moves or not, so this is on the meeting term and nowhere else", lst("EMISSION is gated on not(moving), so it shines on 1 - \\beta" %+% text_of(b) %+% " of its ticks", "that is the same every way, so it is in \\bar{m}" %+% text_of(b) %+% " and not here", "one cell a tick, so \\bar{r} cells is \\bar{r} ticks", "two rays a tick apart land 1 - \\beta" %+% text_of(b) %+% "\\cdot\\hat{d} ticks apart", "\\mathcal{D}" %+% text_of(b) %+% " = " %+% text_of(Expr$show(Inferences$doppler_is(b))) %+% "")))
        NULL
      }))
      NULL
    }))
    NULL
  })
  static_getter(cl, "crossing", function() {
    return(Inference$new(name = "two bodies make meetings neither makes alone", because = "the meeting term is quadratic, so a population that is the sum of two has a cross piece - and that piece is meetings between one body's radiation and the other's", fire = function(s = NULL, ...) {
      per <- s$fact("is", "what a body puts out per site")
      took <- s$fact("is", "what is taken")
      c <- s$fact("is", "\\bar{c}")
      if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- eq(per, NULL))) .x else eq(took, NULL)))) .x else eq(c, NULL)))) .x else s$has("is", "met(R)")))) {
        return(lst())
      }
      rate <- Expr$simplify(Expr$mul(lst(Expr$field("\\sigma"), Expr$field("F"))))
      met <- Expr$simplify(Expr$mul(lst(Expr$num(2), rate, Expr$to_power(Inferences$rbar, Expr$neg(Expr$sub(Inferences$D, Expr$num(1)))), Expr$to_power(Expr$field("\\bar{c}"), Expr$neg(Expr$sub(Inferences$D, Expr$num(2)))), Inferences$doppler(""), Inferences$doppler("'"))))
      return(lst(Inferences$step("met(R)", met, "two bodies make meetings neither makes alone", lst(per$key, took$key, c$key), "the cross piece of the quadratic is one body's radiation meeting the other's, summed along the line between them. Each body's thins as the shell grows, so the product is large only near one of them - and how near is bounded by a step, which is the only length the lattice has. Two ends, each contributing the far density times the near sum cut off at one step. AND EACH END CARRIES A DOPPLER FACTOR, which is not put in: one cell a tick makes a distance a time, a body crosses \\beta of a cell a tick, so two rays sent a tick apart land 1 - \\beta\\cdot\\hat{d} ticks apart and what arrives per tick is the reciprocal. That is the classical factor, derived from the two rules and directional because only the motion ALONG the line changes when a ray gets there", lst("n_{A}+n_{B} squared has a cross piece 2n_{A}n_{B}", "each thins as " %+% text_of(Expr$show(per$to)) %+% "", "\\sum_{l} n_{A}n_{B} is largest at either end, cut off at \\bar{c}", "" %+% text_of(Expr$show(c$to)) %+% " means \\bar{r} cells is \\bar{r} ticks, and a body crosses \\beta of a cell a tick", "two rays a tick apart land 1 - \\beta\\cdot\\hat{d} ticks apart, so what arrives per tick goes as the reciprocal - one factor per body", "met(R) = " %+% text_of(Expr$show(met)) %+% ""))))
      NULL
    }))
    NULL
  })
  static_getter(cl, "unbiased", function() {
    return(Inference$new(name = "isotropy leaves no mean heading", because = "a medium that goes every way alike has no preferred direction, so the dot product of a heading with its mean averages to nothing", fire = function(s = NULL, ...) {
