        return(lst())
      }
      return(lst(Inferences$step("F", Expr$div(Expr$num(1), Expr$num(2)), "isotropy leaves no mean heading", lst(m_first(iso)$key), "the facing factor is (1 - d^·j^)/2 and j^ is what the opposing population is doing on average. Alike in every direction, that is nothing - so a meeting in an undisturbed vacuum carries exactly a half, and the two limits it interpolates are one head-on and nought co-moving", lst("F = (1 - d^·j^)/2", "j^ = 0 where nothing is biased", "F = 1/2"))))
      NULL
    }))
    NULL
  })
  static_getter(cl, "near_field", function() {
    return(Inference$new(name = "the rest of the integral, which is a logarithm", because = "scaled by the separation the integral is a pure number, and expanding it about either end gives a series whose middle term is a simple pole - which integrates to a log of the two lengths there are", fire = function(s = NULL, ...) {
      met <- s$fact("is", "met(R)")
      c <- s$fact("is", "\\bar{c}")
      shell <- s$fact("grows", "shell")
      if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- eq(met, NULL))) .x else eq(c, NULL)))) .x else eq(shell, NULL)))) .x else s$has("is", "met(R) in full")))) {
        return(lst())
      }
      a <- (if (truthy(((if (truthy(.x <- eq(shell$to$kind, "pow"))) (!eq(shell$to$power$kind, "num")) else .x)))) shell$to$power else Expr$sub(Inferences$D, Expr$num(1)))
      weight <- Expr$mul(lst(Expr$num(2), Expr$choose(Expr$simplify(Expr$mul(lst(Expr$num(2), Expr$sub(a, Expr$num(1))))), Expr$simplify(Expr$sub(a, Expr$num(1))))))
      near <- Expr$simplify(Expr$mul(lst(weight, Expr$to_power(Inferences$rbar, Expr$simplify(Expr$sub(Expr$num(1), Expr$mul(lst(Expr$num(2), a))))), Expr$log(Expr$mul(lst(Inferences$rbar, Expr$pown(Expr$field("\\bar{c}"), neg(1))))))))
      full <- Expr$simplify(Expr$add(lst(met$to, Expr$mul(lst(near, Inferences$doppler(""), Inferences$doppler("'"))))))
      return(lst(Inferences$step("met(R) in full", full, "the rest of the integral, which is a logarithm", lst(met$key, c$key, shell$key), "the leading term is the two ends of the line, where the product of the two thinning populations is largest. The rest of the line contributes as well, and one term of the series about either end is a simple pole - which integrates to a logarithm of the separation against a step rather than to a power. It falls off one power faster than the leading term, so it is a correction that matters close in and vanishes far out, which is what a near field IS", lst("s = Ru turns \\int \\frac{ds}{s^{a}(R-s)^{a}} into R^{1-2a}\\int \\frac{du}{u^{a}(1-u)^{a}},\\quad a = " %+% text_of(Expr$show(Expr$simplify(a))) %+% "", "(1-u)^{-a} = \\sum_{k}\\binom{a+k-1}{k}u^{k}", "so the integrand is \\sum_{k}\\binom{a+k-1}{k}u^{k-a} - a power at every k except k = a-1, which is u^{-1}", "\\int u^{-1}du = \\ln u, taken between \\bar{c}/R and 1 - \\bar{c}/R", "two ends, so " %+% text_of(Expr$show(near)) %+% "", "met(R) = " %+% text_of(Expr$show(full)) %+% ""))))
      NULL
    }))
    NULL
  })
  static_getter(cl, "in_motion", function() {
    return(Inference$new(name = "what one action a tick does to a moving body", because = "a body that spends a tick crossing a cell does not spend it shining, so what it puts out carries the share of its ticks it had left", fire = function(s = NULL, ...) {
      F <- s$fact("is", "F_{g}")
      sig <- s$fact("is", "what a body puts out")
