        return(lst())
      }
      return(lst(Inferences$step("how motion moves it", Expr$simplify(Expr$pown(Expr$sub(Expr$num(1), Expr$field("\\beta")), 2)), "what one action a tick does to a moving body", lst(F$key, sig$key), "the meetings channel is one body's radiation meeting the other's, so it needs both to be shining and carries the share twice. The vacuum's channel needs neither to emit anything - an inert body suppresses the expansion just by sitting there - so it carries none of it. Gravity between things in motion is therefore weaker, and weaker in ONE of its two channels, which is a thing that could be looked for", lst("what a body puts out: " %+% text_of(Expr$show(sig$to)) %+% "", "the meetings channel needs both: (1-\\beta)^{2}", "the vacuum's channel needs neither: 1"))))
      NULL
    }))
    NULL
  })
  static_getter(cl, "in_three", function() {
    return(Inference$new(name = "and the same law in three dimensions", because = "the dimension is a symbol so that one line serves every lattice; filling it in is the last step rather than the first, and it is done where it can be seen", fire = function(s = NULL, ...) {
      F <- s$fact("is", "F_{g} in full")
      gN <- s$fact("is", "g_{N}")
      if (truthy((if (truthy(.x <- eq(F, NULL))) .x else s$has("is", "F_{g} at D = 3")))) {
        return(lst())
      }
      at3 <- Node$new()
      .set(at3, key_("D"), 3)
      inner <- (if (truthy(eq(gN, NULL))) NULL else Expr$deep_factored(Expr$evaluate(gN$to, at3)))
      got <- Inferences$folded(Expr$deep_factored(Expr$evaluate(F$to, at3)))
      one <- s$fact("is", "F_{g} as one equation in full")
      via <- "and the same law in three dimensions"
      out <- lst()
      if (truthy((if (truthy(.x <- (!eq(one, NULL)))) (!truthy(s$has("is", "F_{g} at D = 3 as one equation"))) else .x))) {
        m_push(out, Inferences$step("F_{g} at D = 3 as one equation", Expr$deep_factored(Expr$evaluate(one$to, at3)), via, lst(one$key), "the same equation with the dimension put in - what is felt is what arrives, enhanced by the mismatch measured against itself, and in three dimensions what arrives falls off as the square", lst("" %+% text_of(Expr$show(one$to)) %+% "", "D = 3")))
      }
      working <- lst("F_{g} = " %+% text_of(Expr$show(F$to)) %+% "", "D = 3", "F_{g} = " %+% text_of(Expr$show(got)) %+% "")
      if (truthy((!eq(inner, NULL)))) {
        .w("working", m_concat(working, lst("and what it cites, in three dimensions:", "g_{N} = " %+% text_of(Expr$show(inner)) %+% "")))
      }
      m_push(out, Inferences$step("F_{g} at D = 3", got, via, lst(F$key), "three dimensions is where the exponents become numbers: the room a shell has goes as the square, so the leading term is an inverse square, and the near-field correction dies as one over the separation against it. Nothing above was fitted to this - it is the same line with the dimension put in", working))
      return(out)
      NULL
    }))
    NULL
  })
  static_getter(cl, "can_it_push", function() {
    return(Inference$new(name = "whether any of it can turn negative", because = "a factor can only change the sign of a law if something can make it negative, and what a share of ticks can be is bounded by what a share is", fire = function(s = NULL, ...) {
      F <- s$fact("is", "F_{g} in full")
