      }
      return(lst(Inferences$step("the sign of the force", Expr$num(1), "whether any of it can turn negative", lst(F$key, motion$key), "every factor of the assembled law is a rate, a count, a square, or an exponential, and none of those is ever below nothing. In particular the one thing motion contributes is a SHARE OF TICKS - how often a body spent its action crossing a cell rather than shining - which lies between nothing and all, so `(1-\\beta)` is never negative and its square is never negative. THE RULE THAT PRODUCES IT ASKS WHETHER A BODY STEPPED, AND A STEP IS A STEP WHICHEVER WAY IT WENT: nothing in it distinguishes toward from away. So the force is attractive always, and a body moving off is pulled LESS rather than pushed - which is a thing that could be looked for, and a thing this theory would be wrong about if a repulsion were ever seen", lst("motion contributes " %+% text_of(Expr$show(motion$to)) %+% "", "\\beta is a share of ticks, so 0 <= \\beta <= 1", "(1-\\beta)^{2} >= 0, with no direction in it", "and every other factor is a rate, a count or an exponential", "so F_{g} > 0 always - it weakens with motion and never reverses"))))
      NULL
    }))
    NULL
  })
  static_getter(cl, "receding", function() {
    return(Inference$new(name = "space is made between them, and there is more of it the further apart they are", because = "every neutral point between two bodies makes space, so the room between them grows at the net rate times how many points there are - which is how far apart they are", fire = function(s = NULL, ...) {
      line <- s$fact("is", "the space line nets")
      eps <- s$fact("is", "\\varepsilon")
      mat <- s$fact("is", "the world's matter grows")
      if (truthy((if (truthy(.x <- eq(line, NULL))) .x else s$has("is", "recession")))) {
        return(lst())
      }
      net <- line$to
      .w("net", (if (truthy(eq(mat, NULL))) net else Expr$add(lst(net, mat$to))))
      .w("net", (if (truthy(eq(eps, NULL))) net else Expr$add(lst(net, eps$to))))
      rec <- Expr$simplify(Expr$mul(lst(net, Inferences$rbar)))
      return(lst(Inferences$step("recession", rec, "space is made between them, and there is more of it the further apart they are", lst(line$key), "the space line says every neutral point makes space at the net of what the splitting makes and the meetings take. Between two bodies there are as many such points as there is distance, so the room between them grows at that rate times that distance - nothing is pushing them and they are carried apart anyway, faster the further apart they already are", lst("\\partial_{t}s = " %+% text_of(Expr$show(net)) %+% ", every term of the space line", "points between two bodies R apart: R of them", "recession = " %+% text_of(Expr$show(rec)) %+% ""))))
      NULL
    }))
    NULL
  })
  static_getter(cl, "shortfall", function() {
    return(Inference$new(name = "and a body makes less of it, so they are carried apart more slowly", because = "every point between them is making less by however much of the body's shortfall has reached it, so the reduction is that shortfall summed along the line", fire = function(s = NULL, ...) {
      rec <- s$fact("is", "recession")
      per <- or_else(s$fact("is", "\\delta screened"), s$fact("is", "\\delta per site"))
      puts <- s$fact("is", "what a body puts into the medium")
      if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- eq(rec, NULL))) .x else eq(per, NULL)))) .x else eq(puts, NULL)))) .x else s$has("is", "the deficit in recession")))) {
        return(lst())
      }
      profile <- Expr$replace(per$to, "\\delta", puts$to)
      far <- Expr$leading(profile, "r")
      F <- or_else(Expr$integrate(profile, "r"), Expr$integrate(far, "r"))
      if (truthy(eq(F, NULL))) {
        return(lst())
      }
      totalled <- Expr$simplify(Expr$neg(Expr$replace(F, "r", Inferences$rbar)))
      return(lst(Inferences$step("the deficit in recession", totalled, "and a body makes less of it, so they are carried apart more slowly", lst(rec$key, per$key, puts$key), "the room between two bodies grows at the making rate times how many points there are, and a body has reduced that rate at every one of them. Summed along the line - integrated by the algebra over whatever profile the transport gave, not over a power assumed in advance - that is the deficit in how fast they are carried apart, and it is what an attraction IS in a model whose gravity is an expansion that did not happen", lst("recession = " %+% text_of(Expr$show(rec$to)) %+% "", "the shortfall at each point is the body's own, carried: " %+% text_of(Expr$show(profile)) %+% "", "far out that comes to " %+% text_of(Expr$show(far)) %+% "", "\\int of that dr = " %+% text_of(Expr$show(F)) %+% "", "the deficit in recession = " %+% text_of(Expr$show(totalled)) %+% ""))))
      NULL
    }))
    NULL
  })
  static_getter(cl, "waiting", function() {
    return(Inference$new(name = "how fast a carrier goes, which is the share of its step that was straight", because = "`turns` draws one way straight on against the ways each direction was folded, so what carries a ray outward is the share of the draw that did not turn it", fire = function(s = NULL, ...) {
      nf <- s$fact("is", "n_{f}")
      c <- s$fact("is", "\\bar{c}")
      if (truthy((if (truthy(.x <- (if (truthy(.x <- eq(nf, NULL))) .x else eq(c, NULL)))) .x else s$has("is", "v")))) {
        return(lst())
      }
      gate <- s$fact("is", "what share of a step advances")
      parts <- lst(c$to)
      if (truthy((!eq(gate, NULL)))) {
        m_push(parts, gate$to)
      }
      m_push(parts, Expr$pown(Expr$add(lst(Expr$num(1), Expr$field("n_{f}"))), neg(1)))
      got <- Expr$simplify(Expr$mul(parts))
      return(lst(Inferences$step("v", got, "how fast a carrier goes, which is the share of its step that was straight", lst(nf$key, c$key), "MOVEMENT does not simply move a ray one cell: it draws where the ray goes, one way straight on against the ways each direction was folded. A place that has swallowed n_{f} folds sends it straight with 1/(1 + n_{f}) and turns it otherwise, so what advances it OUTWARD is that share. It is statistical and it is local, and it applies wherever the vacuum has met itself - which is everywhere, unlike the waiting, which happens only where there is no cell at all and so only at the frontier", lst("turns: 1 way straight on against folds[d] ways out along d", "so a ray keeps its heading with 1/(1 + n_{f})", "v = \\bar{c}/(1 + n_{f}) = " %+% text_of(Expr$show(got)) %+% "", "n_{f} small: v -> one cell a tick, and the carrier streams", "n_{f} large: v -> \\bar{c}/n_{f}, and it does not"))))
      NULL
    }))
    NULL
  })
  static_getter(cl, "transporting", function() {
    return(Inference$new(name = "what crosses a shell is the room times what is at each site times how fast it goes", because = "a flux is how much crosses per tick - the sites there are, times what is at each, times how fast it moves through - and conserved, that fixes the density", fire = function(s = NULL, ...) {
      shell <- s$fact("grows", "shell")
      v <- s$fact("is", "v")
      nf <- s$fact("is", "n_{f}")
      if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- eq(shell, NULL))) .x else eq(v, NULL)))) .x else eq(nf, NULL)))) .x else s$has("is", "n")))) {
        return(lst())
      }
      got <- Expr$simplify(Expr$mul(lst(Expr$sym("\\Phi"), Expr$pown(shell$to, neg(1)), Expr$pown(v$to, neg(1)))))
      return(lst(Inferences$step("n", got, "what crosses a shell is the room times what is at each site times how fast it goes", lst(shell$key, v$key, nf$key), "count what crosses a shell in a tick - the sites on it, what is at each, and the share of a step that went outward - and MOVEMENT neither makes nor destroys, so that count is carried. Solved for what is AT a site it is the flux over the room over the speed, and the speed is the share of the draw that did not turn. THE FOLD RECORD IS WHAT MAKES THIS MORE THAN A DILUTION: it grows with how far a ray has come, so 1 + n_{f} rises outward and the density falls more slowly than the room alone would have it. Close in that is nothing and this is an inverse square; far out it is not", lst("\\Phi = shell·n·v", "v = " %+% text_of(Expr$show(v$to)) %+% "", "n = \\Phi/(shell·v) = " %+% text_of(Expr$show(got)) %+% "", "n_{f} = " %+% text_of(Expr$show(nf$to)) %+% ", which grows with how far a ray has come"))))
      NULL
    }))
    NULL
  })
})

Aggregate <- ray_class("Aggregate", Node, function(cl) {
  field(cl, "theory", NULL)
  static_field(cl, "CACHE", function() Node$new())
  static_field(cl, "ROUNDS", function() 4)
  static_field(cl, "FOLDS_NAMES", function() lst("\\rho", "n_{f}"))
  field(cl, "D", function() 2)
  field(cl, "DEG", function() 8)
  statik(cl, "of", function(theory = NULL, DEG = NULL, D = NULL, ...) {
    if (truthy(eq(DEG, NULL))) {
      .w("DEG", NULL)
    }
    if (truthy(eq(D, NULL))) {
      .w("D", NULL)
    }
    deg <- or_else(DEG, theory$lattice$DEG)
    dim <- or_else(D, theory$lattice$D)
    key <- "" %+% text_of(theory$name) %+% "/" %+% text_of(dim) %+% "/" %+% text_of(deg) %+% ""
    if (truthy(eq(elem(Aggregate$CACHE, key), NULL))) {
      set_at(Aggregate$CACHE, key, Aggregate$new(theory = theory, DEG = deg, D = dim))
    }
    return(elem(Aggregate$CACHE, key))
    NULL
  })
  field(cl, "prover", function() Prover$new(theory = self$theory))
  field(cl, "store", function() self$prover$closure)
  field(cl, "chain", function() self$prover$chain(self$store))
  field(cl, "NEAR", function() 0.5)
  getter(cl, "env", function() {
    e <- Node$new()
    .r <- for_each(self$store$all("is"), function(f) {
      v <- Expr$simplify(f$to)
      if (truthy(eq(v$kind, "num"))) {
        set_at(e, f$of, v$value)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .set(e, key_("D"), self$D)
    .set(e, key_("DEG"), self$DEG)
    .set(e, key_("l.DEG"), self$DEG)
    .set(e, key_("\\bar{c}"), 1)
    return(e)
    NULL
  })
  statik(cl, "numeric_of", function(e = NULL, at = NULL, ...) {
    return(Expr$numeric(Expr$evaluate(e, at), at))
    NULL
  })
  method(cl, "fact_at", function(name = NULL, at = NULL, ...) {
    f <- self$store$fact("is", name)
    if (truthy(eq(f, NULL))) {
      return(NaN)
    }
    return(Aggregate$numeric_of(f$to, at))
    NULL
  })
  method(cl, "step", function(role = NULL, ...) {
    return(self$chain$get(role))
    NULL
  })
  method(cl, "says", function(role = NULL, ...) {
    st <- self$step(role)
    return((if (truthy(eq(st, NULL))) "-" else "" %+% text_of(st$fact$of) %+% " = " %+% text_of(Expr$show(st$fact$to)) %+% ""))
    NULL
  })
  getter(cl, "rho_inf", function() {
    return(self$fact_at("\\rho_{\\infty}", self$env))
    NULL
  })
  getter(cl, "settled_env", function() {
    e <- self$env
    .set(e, key_("\\rho"), self$rho_inf)
    .set(e, key_("\\rho_{\\infty}"), self$rho_inf)
    return(e)
    NULL
  })
  getter(cl, "nf_inf", function() {
    st <- self$step("settled")
    if (truthy(eq(st, NULL))) {
      return(NaN)
    }
    return(Aggregate$numeric_of(st$fact$to, self$settled_env))
    NULL
  })
  field(cl, "base", function() self$settled_env)
  getter(cl, "fold_weight", function() {
    return(Aggregate$numeric_of(self$prover$fold_weight, self$env))
    NULL
  })
  method(cl, "shell_at", function(R = NULL, ...) {
    e <- self$base
    .set(e, key_("\\bar{R}"), (if (truthy(lt(R, self$NEAR))) self$NEAR else R))
    got <- self$fact_at("l.shell\\paren{\\bar{R}}", e)
    .set(e, key_("\\bar{R}"), NULL)
    return(got)
    NULL
  })
  method(cl, "ball_at", function(R = NULL, ...) {
    e <- self$base
    .set(e, key_("\\bar{R}"), (if (truthy(lt(R, self$NEAR))) self$NEAR else R))
    got <- self$fact_at("l.ball\\paren{\\bar{R}}.count", e)
    .set(e, key_("\\bar{R}"), NULL)
    return(got)
    NULL
  })
  method(cl, "skin_at", function(face = NULL, ...) {
    at_one <- r_sub(1, self$reach_at(self$NEAR))
    got <- r_sub(1, self$reach_at((if (truthy(lt(face, self$NEAR))) self$NEAR else face)))
    return((if (truthy(gt(at_one, 0))) r_div(got, at_one) else 1))
    NULL
  })
  method(cl, "held_over_sent", function(face = NULL, beta = NULL, ...) {
    lets <- r_mul(self$skin_at(face), (r_sub(1, beta)))
    return((if (truthy(gt(lets, 0))) r_div(self$ball_at(face), (r_mul(self$ball_at(self$NEAR), lets))) else NaN))
    NULL
  })
  field(cl, "FACES", function() lst(1, 1.5, 2, 3, 4, 6, 8, 12, 16, 24, 32))
  field(cl, "BETAS", function() lst(0, 0.225, 0.45, 0.675, 0.9))
  getter(cl, "carries", function() {
    most <- 0
    .r <- for_each(self$FACES, function(face) {
      .r <- for_each(self$BETAS, function(beta) {
        q <- Fmt$log10(self$held_over_sent(face, beta))
        if (truthy((if (truthy(.x <- Fmt$finite(q))) gt(q, most) else .x))) {
          .w("most", q)
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(most)
    NULL
  })
  method(cl, "reach_at", function(R = NULL, ...) {
    e <- self$base
    .set(e, key_("\\bar{R}"), (if (truthy(lt(R, 0))) 0 else R))
    got <- self$fact_at("l.reach\\paren{\\bar{R}}", e)
    .set(e, key_("\\bar{R}"), NULL)
    return(got)
    NULL
  })
  field(cl, "STEP", function() 0.01)
  field(cl, "FAR", function() 400)
  field(cl, "shells", function() m_map(rng(r_add(m_round((r_div(self$FAR, self$STEP))), 1)), function(i = NULL, ...) {
    return(self$shell_at(r_mul(i, self$STEP)))
    NULL
  }))
  field(cl, "reaches", function() m_map(rng(r_add(m_round((r_div(self$FAR, self$STEP))), 1)), function(i = NULL, ...) {
    return(self$reach_at(r_mul(i, self$STEP)))
    NULL
  }))
  method(cl, "tabled", function(table = NULL, R = NULL, ...) {
    u <- r_div(R, self$STEP)
    i <- m_floor(u)
    if (truthy(ge(i, r_sub(len(table), 1)))) {
      return(elem(table, r_sub(len(table), 1)))
    }
    if (truthy(lt(i, 0))) {
      return(elem(table, 0))
    }
    f <- r_sub(u, i)
    return(r_add(r_mul(elem(table, i), (r_sub(1, f))), r_mul(elem(table, r_add(i, 1)), f)))
    NULL
  })
  method(cl, "shell", function(R = NULL, ...) {
    return((if (truthy(gt(R, self$FAR))) self$shell_at(R) else self$tabled(self$shells, R)))
    NULL
  })
  method(cl, "reach", function(R = NULL, ...) {
    return((if (truthy(gt(R, self$FAR))) self$reach_at(R) else self$tabled(self$reaches, R)))
    NULL
  })
  method(cl, "record_at", function(masses = NULL, xs = NULL, ys = NULL, x = NULL, y = NULL, skip = NULL, ...) {
    return(self$record_of(masses, m_map(rng(len(masses)), function(i = NULL, ...) {
      return(Fmt$hypot(r_sub(elem(xs, i), x), r_sub(elem(ys, i), y)))
      NULL
    }), skip))
    NULL
  })
  method(cl, "record_of", function(masses = NULL, Rs = NULL, skip = NULL, ...) {
    st <- self$step("record")
    if (truthy(eq(st, NULL))) {
      return(NaN)
    }
    return(self$value(st$fact$to, self$base, masses, Rs, skip))
    NULL
  })
  method(cl, "value", function(e = NULL, at = NULL, masses = NULL, Rs = NULL, skip = NULL, ...) {
    k <- e$kind
    if (truthy((if (truthy(.x <- eq(k, "call"))) m_starts_with(e$label, "\\sum") else .x))) {
      total <- 0
      names <- self$per_body
      kinds <- self$per_body_kinds
      .r <- for_range(len(masses), function(i) {
        if (!truthy(eq(i, skip))) {
          R <- elem(Rs, i)
          .r <- for_range(len(names), function(j) {
            set_at(at, elem(names, j), self$per_body_value(elem(kinds, j), elem(masses, i), R))
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          .w("total", r_add(total, self$value(e$base, at, masses, Rs, skip)))
          .r <- for_each(names, function(nm) {
            set_at(at, nm, NULL)
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      return(total)
    }
    if (truthy(eq(k, "num"))) {
      return(e$value)
    }
    if (truthy((if (truthy(.x <- eq(k, "sym"))) .x else eq(k, "field")))) {
      v <- elem(at, e$label)
      return((if (truthy(eq(v, NULL))) NaN else v))
    }
    if (truthy(eq(k, "add"))) {
      total <- 0
      .r <- for_each(e$of, function(p) {
        .w("total", r_add(total, self$value(p, at, masses, Rs, skip)))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      return(total)
    }
    if (truthy(eq(k, "mul"))) {
      prod <- 1
      .r <- for_each(e$of, function(p) {
        .w("prod", r_mul(prod, self$value(p, at, masses, Rs, skip)))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      return(prod)
    }
    if (truthy(eq(k, "pow"))) {
      return(r_pow(self$value(e$base, at, masses, Rs, skip), self$value(e$power, at, masses, Rs, skip)))
    }
    if (truthy(eq(k, "log"))) {
      return(m_ln(self$value(e$base, at, masses, Rs, skip)))
    }
    if (truthy(eq(k, "exp"))) {
      return(m_exp(self$value(e$base, at, masses, Rs, skip)))
    }
    return(Aggregate$numeric_of(e, at))
    NULL
  })
  method(cl, "lean_at", function(masses = NULL, xs = NULL, ys = NULL, x = NULL, y = NULL, skip = NULL, ...) {
    h <- 0.25
    gx <- r_div((r_sub(self$record_at(masses, xs, ys, r_add(x, h), y, skip), self$record_at(masses, xs, ys, r_sub(x, h), y, skip))), (r_mul(2, h)))
    gy <- r_div((r_sub(self$record_at(masses, xs, ys, x, r_add(y, h), skip), self$record_at(masses, xs, ys, x, r_sub(y, h), skip))), (r_mul(2, h)))
    return(lst(gx, gy))
    NULL
  })
  method(cl, "read_at", function(hx = NULL, hy = NULL, x = NULL, y = NULL, ...) {
    last <- r_sub(len(hx), 1)
    R <- Fmt$hypot(r_sub(elem(hx, last), x), r_sub(elem(hy, last), y))
    px <- elem(hx, last)
    py <- elem(hy, last)
    .r <- for_range(Aggregate$ROUNDS, function(r) {
      back <- m_round(R)
      if (truthy(gt(back, last))) {
        .w("back", last)
      }
      at <- r_sub(last, back)
      vx <- (if (truthy(gt(at, 0))) r_sub(elem(hx, at), elem(hx, r_sub(at, 1))) else 0)
      vy <- (if (truthy(gt(at, 0))) r_sub(elem(hy, at), elem(hy, r_sub(at, 1))) else 0)
      .w("px", r_add(elem(hx, at), r_mul(vx, back)))
      .w("py", r_add(elem(hy, at), r_mul(vy, back)))
      .w("R", Fmt$hypot(r_sub(px, x), r_sub(py, y)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(lst(px, py, R))
    NULL
  })
  method(cl, "retarded", function(hx = NULL, hy = NULL, x = NULL, y = NULL, ...) {
    return(elem(self$read_at(hx, hy, x, y), 2))
    NULL
  })
  method(cl, "record_history", function(masses = NULL, hx = NULL, hy = NULL, x = NULL, y = NULL, skip = NULL, ...) {
    return(self$record_of(masses, m_map(rng(len(masses)), function(i = NULL, ...) {
      return(self$retarded(elem(hx, i), elem(hy, i), x, y))
      NULL
    }), skip))
    NULL
  })
  method(cl, "lean_history", function(masses = NULL, hx = NULL, hy = NULL, x = NULL, y = NULL, skip = NULL, ...) {
    h <- 0.25
    gx <- r_div((r_sub(self$record_history(masses, hx, hy, r_add(x, h), y, skip), self$record_history(masses, hx, hy, r_sub(x, h), y, skip))), (r_mul(2, h)))
    gy <- r_div((r_sub(self$record_history(masses, hx, hy, x, r_add(y, h), skip), self$record_history(masses, hx, hy, x, r_sub(y, h), skip))), (r_mul(2, h)))
    return(lst(gx, gy))
    NULL
  })
  method(cl, "pull", function(m = NULL, R = NULL, ...) {
    g <- self$lean_at(lst(m), lst(0), lst(0), R, 0, neg(1))
    return(r_sub(0, elem(g, 0)))
    NULL
  })
  field(cl, "pulls", function() m_map(rng(r_add(m_round((r_div(self$FAR, self$STEP))), 1)), function(i = NULL, ...) {
    return(self$pull(1, r_mul(i, self$STEP)))
    NULL
  }))
  field(cl, "linear", function() lt(m_abs((r_sub(self$pull(2, 5), r_mul(2, self$pull(1, 5))))), r_mul(0.000000001, (r_add(m_abs(self$pull(1, 5)), 0.000000000001)))))
  method(cl, "quick", function(m = NULL, R = NULL, ...) {
    if (truthy((!truthy(self$linear)))) {
      (fail)("the record is not linear in a body's mass under this derivation: the tabled pull cannot stand in for it")
    }
    return((if (truthy(gt(R, self$FAR))) self$pull(m, R) else r_mul(m, self$tabled(self$pulls, R))))
    NULL
  })
  method(cl, "circling", function(m = NULL, R = NULL, rho = NULL, ...) {
    a <- self$pull(m, R)
    return((if (truthy(gt(a, 0))) m_sqrt((r_mul(a, rho))) else NaN))
    NULL
  })
  method(cl, "profile", function(radii = NULL, ...) {
    return(m_map(radii, function(R = NULL, ...) {
      return(self$pull(1, R))
      NULL
    }))
    NULL
  })
  method(cl, "well", function(m = NULL, R = NULL, ...) {
    step <- 0.05
    total <- 0
    r <- R
    while (truthy(lt(r, self$FAR))) {
      .w("total", r_add(total, r_div(r_mul(step, (r_add(self$quick(m, r), self$quick(m, r_add(r, step))))), 2)))
      .w("r", r_add(r, step))
    }
    return(r_sub(0, total))
    NULL
  })
  method(cl, "arriving", function(m = NULL, R_far = NULL, R_near = NULL, twins = NULL, ...) {
    both <- (if (truthy(twins)) 2 else 1)
    drop <- r_mul(both, (r_sub(self$well(m, R_far), self$well(m, R_near))))
    ratio <- r_sub(r_pow((r_div(R_far, R_near)), 2), 1)
    if (truthy((if (truthy(.x <- (!truthy((gt(drop, 0)))))) .x else (!truthy((gt(ratio, 0))))))) {
      return(NaN)
    }
    v_rel <- m_sqrt((r_div(r_mul(2, drop), ratio)))
    return((if (truthy(twins)) r_div(v_rel, 2) else v_rel))
    NULL
  })
  method(cl, "step_bodies", function(ms = NULL, hx = NULL, hy = NULL, vx = NULL, vy = NULL, moving = NULL, ...) {
    n <- len(ms)
    xs <- m_map(hx, function(h = NULL, ...) {
      return(m_last(h))
      NULL
    })
    ys <- m_map(hy, function(h = NULL, ...) {
      return(m_last(h))
      NULL
    })
    .r <- for_range(n, function(i) {
      if (truthy(elem(moving, i))) {
        ax <- 0
        ay <- 0
        .r <- for_range(n, function(j) {
          if (truthy((!eq(j, i)))) {
            got <- self$read_at(elem(hx, j), elem(hy, j), elem(xs, i), elem(ys, i))
            R <- elem(got, 2)
            dx <- r_sub(elem(got, 0), elem(xs, i))
            dy <- r_sub(elem(got, 1), elem(ys, i))
            there <- Fmt$hypot(dx, dy)
            if (truthy(gt(there, 0))) {
              a <- self$quick(elem(ms, j), R)
              .w("ax", r_add(ax, r_div(r_mul(a, dx), there)))
              .w("ay", r_add(ay, r_div(r_mul(a, dy), there)))
            }
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        set_at(vx, i, r_add(elem(vx, i), ax))
        set_at(vy, i, r_add(elem(vy, i), ay))
        speed <- Fmt$hypot(elem(vx, i), elem(vy, i))
        if (truthy(gt(speed, 1))) {
          set_at(vx, i, r_div(elem(vx, i), speed))
          set_at(vy, i, r_div(elem(vy, i), speed))
        }
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_range(n, function(i) {
      m_push(elem(hx, i), r_add(elem(xs, i), ((if (truthy(elem(moving, i))) elem(vx, i) else 0))))
      m_push(elem(hy, i), r_add(elem(ys, i), ((if (truthy(elem(moving, i))) elem(vy, i) else 0))))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  method(cl, "nearest", function(ms = NULL, fars = NULL, speeds = NULL, k = NULL, held = NULL, limit = NULL, ...) {
    n <- len(ms)
    hx <- m_map(fars, function(f = NULL, ...) {
      return(lst(f))
      NULL
    })
    hy <- m_map(fars, function(f = NULL, ...) {
      return(lst(0))
      NULL
    })
    vx <- m_map(fars, function(f = NULL, ...) {
      return(0)
      NULL
    })
    vy <- m_map(speeds, function(v = NULL, ...) {
      return(r_sub(0, v))
      NULL
    })
    moving <- m_map(rng(n), function(i = NULL, ...) {
      return((if (truthy(.x <- gt(i, 0))) .x else (!truthy(held))))
      NULL
    })
    set_at(vy, 0, (if (truthy(held)) 0 else elem(speeds, 1)))
    least <- Fmt$hypot(r_sub(m_last(elem(hx, k)), m_last(elem(hx, 0))), r_sub(m_last(elem(hy, k)), m_last(elem(hy, 0))))
    was <- least
    t <- 0
    turned <- FALSE
    while (truthy((if (truthy(.x <- lt(t, limit))) (!truthy(turned)) else .x))) {
      self$step_bodies(ms, hx, hy, vx, vy, moving)
      d <- Fmt$hypot(r_sub(m_last(elem(hx, k)), m_last(elem(hx, 0))), r_sub(m_last(elem(hy, k)), m_last(elem(hy, 0))))
      if (truthy(lt(d, least))) {
        .w("least", d)
      }
      if (truthy((if (truthy(.x <- gt(d, was))) lt(d, r_add(r_mul(0.75, elem(fars, k)), r_mul(0.25, least))) else .x))) {
        .w("turned", TRUE)
      }
      .w("was", d)
      .w("t", r_add(t, 1))
    }
    return(least)
    NULL
  })
  method(cl, "launches", function(ms = NULL, fars = NULL, nears = NULL, held = NULL, rounds = NULL, ...) {
    n <- len(ms)
    speeds <- m_map(rng(n), function(k = NULL, ...) {
      return((if (truthy(eq(k, 0))) 0 else self$arriving(elem(ms, 0), elem(fars, k), elem(nears, k), (!truthy(held)))))
      NULL
    })
    .r <- for_range(n, function(k) {
      if (truthy((!truthy(Fmt$finite(elem(speeds, k)))))) {
        set_at(speeds, k, 0)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_range(rounds, function(r) {
      .r <- for_range(n, function(k) {
        if (truthy(gt(k, 0))) {
          lo <- r_mul(elem(speeds, k), 0.5)
          hi <- r_mul(elem(speeds, k), 1.5)
          if (truthy(gt(hi, 1))) {
            .w("hi", 1)
          }
          limit <- m_round((r_div(r_mul(20, elem(fars, k)), ((if (truthy(gt(elem(speeds, k), 0.001))) elem(speeds, k) else 0.001)))))
          if (truthy(gt(limit, 40000))) {
            .w("limit", 40000)
          }
          .r <- for_range(14, function(b) {
            mid <- r_div((r_add(lo, hi)), 2)
            set_at(speeds, k, mid)
            got <- self$nearest(ms, fars, speeds, k, held, limit)
            if (truthy(lt(got, elem(nears, k)))) {
              .w("lo", mid)
            } else {
              .w("hi", mid)
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          set_at(speeds, k, r_div((r_add(lo, hi)), 2))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(speeds)
    NULL
  })
  statik(cl, "kind_of", function(name = NULL, ...) {
    if (truthy(m_starts_with(name, "l.shell"))) {
      return("shell")
    }
    if (truthy(m_starts_with(name, "l.reach"))) {
      return("reach")
    }
    if (truthy(m_contains(name, "\\bar{m}"))) {
      return("mass")
    }
    if (truthy(m_contains(name, "\\bar{R}"))) {
      return("distance")
    }
    return("constant")
    NULL
  })
  getter(cl, "per_body", function() {
    return(filt(Model$unbound(self$summand), function(n = NULL, ...) {
      return((!eq(Aggregate$kind_of(n), "constant")))
      NULL
    }))
    NULL
  })
  getter(cl, "per_body_kinds", function() {
    return(m_map(self$per_body, function(n = NULL, ...) {
      return(Aggregate$kind_of(n))
      NULL
    }))
    NULL
  })
  method(cl, "per_body_value", function(kind = NULL, m = NULL, R = NULL, ...) {
    if (truthy(eq(kind, "mass"))) {
      return(m)
    }
    if (truthy(eq(kind, "distance"))) {
      return(R)
    }
    if (truthy(eq(kind, "shell"))) {
      return(self$shell(R))
    }
    return(self$reach(R))
    NULL
  })
  statik(cl, "summing", function(e = NULL, ...) {
    k <- e$kind
    if (truthy((if (truthy(.x <- eq(k, "call"))) m_starts_with(e$label, "\\sum") else .x))) {
      return(e)
    }
    if (truthy((if (truthy(.x <- eq(k, "add"))) .x else eq(k, "mul")))) {
      found <- NULL
      .r <- for_each(e$of, function(x) {
        if (truthy(eq(found, NULL))) {
          .w("found", Aggregate$summing(x))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      return(found)
    }
    if (truthy(eq(k, "pow"))) {
      return(or_else(Aggregate$summing(e$base), Aggregate$summing(e$power)))
    }
    if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- eq(k, "log"))) .x else eq(k, "exp")))) .x else eq(k, "call")))) .x else eq(k, "grad")))) {
      return(Aggregate$summing(e$base))
    }
    return(NULL)
    NULL
  })
  getter(cl, "record_expr", function() {
    st <- self$step("record")
    return((if (truthy(eq(st, NULL))) Expr$num(0) else st$fact$to))
    NULL
  })
  getter(cl, "summand", function() {
    sum <- Aggregate$summing(self$record_expr)
    return((if (truthy(eq(sum, NULL))) Expr$num(0) else sum$base))
    NULL
  })
  getter(cl, "outer", function() {
    sum <- Aggregate$summing(self$record_expr)
    return((if (truthy(eq(sum, NULL))) self$record_expr else Expr$swap(self$record_expr, sum, Expr$field("SUM"))))
    NULL
  })
  getter(cl, "shell_expr", function() {
    f <- self$store$fact("is", "l.shell\\paren{\\bar{R}}")
    return((if (truthy(eq(f, NULL))) Expr$num(1) else f$to))
    NULL
  })
  getter(cl, "reach_expr", function() {
    f <- self$store$fact("is", "l.reach\\paren{\\bar{R}}")
    return((if (truthy(eq(f, NULL))) Expr$num(0) else f$to))
    NULL
  })
  getter(cl, "names", function() {
    out <- m_map(self$per_body, function(n = NULL, ...) {
      return(n)
      NULL
    })
    m_push(out, "SUM")
    .r <- for_each(lst(self$outer, self$summand, self$shell_expr, self$reach_expr), function(e) {
      .r <- for_each(Model$unbound(e), function(n) {
        if (truthy((if (truthy(.x <- (if (truthy(.x <- (!truthy(m_contains(out, n))))) (!eq(n, "\\bar{R}")) else .x))) (!truthy(m_ends_with(n, "\\paren{...}"))) else .x))) {
          m_push(out, n)
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  getter(cl, "constants", function() {
    return(m_map(self$names, function(n = NULL, ...) {
      v <- (if (truthy(((if (truthy(.x <- eq(n, "SUM"))) .x else (!eq(Aggregate$kind_of(n), "constant")))))) 0 else elem(self$base, n))
      if (truthy(eq(v, NULL))) {
        (fail)("the record stands on " %+% text_of(n) %+% ", which the settled vacuum does not bind - bind it in Aggregate.env or fix the derivation")
      }
      return(v)
      NULL
    }))
    NULL
  })
  getter(cl, "bindings", function() {
    names <- self$names
    return(m_map(self$per_body, function(n = NULL, ...) {
      return("" %+% text_of(m_index_of(names, n)) %+% ":" %+% text_of(Aggregate$kind_of(n)) %+% "")
      NULL
    }))
    NULL
  })
  getter(cl, "folds_expr", function() {
    st <- self$step("folds")
    return((if (truthy(eq(st, NULL))) Expr$num(0) else st$fact$to))
    NULL
  })
  method(cl, "folds_rate", function(rho = NULL, nf = NULL, ...) {
    at <- self$base
    was_rho <- mem(at, key_("\\rho"))
    .set(at, key_("\\rho"), rho)
    .set(at, key_("n_{f}"), nf)
    got <- Expr$numeric(self$folds_expr, at)
    .set(at, key_("\\rho"), was_rho)
    .set(at, key_("n_{f}"), NULL)
    return(got)
    NULL
  })
  getter(cl, "wgsl", function() {
    stray <- filt(Model$unbound(self$folds_expr), function(n = NULL, ...) {
      return((!truthy(m_contains(Aggregate$FOLDS_NAMES, n))))
      NULL
    })
    if (truthy((!truthy(m_empty(stray))))) {
      (fail)("the record's line stands on " %+% text_of(stray$join) %+% "", ")}, which a cell does not hold - fill the derivation's constants in")
    }
    folds_code <- Shaded$wgsl(self$folds_expr, Aggregate$FOLDS_NAMES, NULL)
    names <- self$names
    NV <- len(names)
    rb <- "\\bar{R}"
    shell_code <- Shaded$wgsl(self$shell_expr, names, rb)
    reach_code <- Shaded$wgsl(self$reach_expr, names, rb)
    summand_code <- Shaded$wgsl(self$summand, names, NULL)
    outer_code <- Shaded$wgsl(self$outer, names, NULL)
    nl <- from_codepoints(lst(10))
    return(m_join(lst("var<private> e: array<f32, " %+% text_of(NV) %+% ">;", "fn shell_at(x: f32) -> f32 { return " %+% text_of(shell_code) %+% "; }", "fn reach_at(x: f32) -> f32 { return " %+% text_of(reach_code) %+% "; }", "fn summand() -> f32 { return " %+% text_of(summand_code) %+% "; }", "fn record_of() -> f32 { return " %+% text_of(outer_code) %+% "; }", "fn folds_rate(rho: f32, nf: f32) -> f32 { e[0] = rho; e[1] = nf; return " %+% text_of(folds_code) %+% "; }"), nl))
    NULL
  })
})

Medium <- ray_class("Medium", Node, function(cl) {
  field(cl, "theory", NULL)
  field(cl, "N", NULL)
  field(cl, "A", NULL)
  field(cl, "K", NULL)
  static_field(cl, "GATHER", function() 96)
  static_field(cl, "SLOTS", function() 4)
  static_field(cl, "NEAR_CELLS", function() 5)
  field(cl, "DEG", function() self$theory$lattice$DEG)
  field(cl, "D", function() self$theory$lattice$D)
  field(cl, "tags", function() 1)
  field(cl, "aggregate", function() Aggregate$of(self$theory, self$DEG, self$D))
  getter(cl, "cells", function() {
    return(r_mul(self$N, self$N))
    NULL
  })
  field(cl, "apart", function() FALSE)
  getter(cl, "planes", function() {
    return((if (truthy((if (truthy(.x <- self$apart)) .x else self$local_rays))) r_add(len(self$holes), 1) else ((if (truthy(lt(self$tags, 1))) 1 else self$tags))))
    NULL
  })
  field(cl, "ticks", function() 0)
  getter(cl, "t", function() {
    return(self$ticks)
    NULL
  })
  getter(cl, "lit", function() {
    return(eq(r_mod(self$ticks, 2), 0))
    NULL
  })
  field(cl, "rho_inf", function() self$aggregate$rho_inf)
  field(cl, "nf_inf", function() self$aggregate$nf_inf)
  getter(cl, "rungs", function() {
    return(r_add(m_floor((r_div(self$N, self$K))), 3))
    NULL
  })
  field(cl, "beam", function() m_map(rng(self$planes), function(z = NULL, ...) {
    return(filled(self$rungs, 0))
    NULL
  }))
  method(cl, "sent_at", function(z = NULL, r = NULL, ...) {
    rr <- (if (truthy(lt(r, 0))) 0 else r)
    i <- m_floor(rr)
    if (truthy(ge(r_add(i, 1), self$rungs))) {
      return(0)
    }
    near <- self$face_of(self$body_of(z))
    f <- r_sub(rr, i)
    over <- r_sub(self$D, 1)
    here <- r_pow(Fmt$max(near, rr), over)
    was <- r_mul(elem(elem(self$beam, z), i), (r_pow(Fmt$max(near, i), over)))
    v_next <- r_mul(elem(elem(self$beam, z), r_add(i, 1)), (r_pow(Fmt$max(near, r_add(i, 1)), over)))
    return((if (truthy(gt(here, 0))) r_div((r_add(r_mul(was, (r_sub(1, f))), r_mul(v_next, f))), here) else 0))
    NULL
  })
  method(cl, "lit_when", function(h = NULL, r = NULL, ...) {
    k <- m_index_of(self$holes, h)
    hx <- (if (truthy((if (truthy(.x <- lt(k, 0))) .x else le(len(self$tracks), k)))) NULL else elem(self$tracks, k))
    n <- (if (truthy(eq(hx, NULL))) 0 else r_div(len(hx), 2))
    back <- m_round(r)
    at <- r_sub(r_sub(n, 1), back)
    if (truthy((if (truthy(.x <- lt(n, 1))) .x else lt(at, 0)))) {
      return(self$lit_at(h$x, h$y))
    }
    return(eq(r_mod((r_add(r_add(r_sub(self$ticks, back), m_round(elem(hx, r_mul(2, at)))), m_round(elem(hx, r_add(r_mul(2, at), 1))))), 2), 0))
    NULL
  })
  method(cl, "sent_to", function(z = NULL, x = NULL, y = NULL, ...) {
    h <- self$body_of(z)
    if (truthy(eq(h, NULL))) {
      return(lst(0, 0, 0))
    }
    way <- self$out_from(h, x, y)
    if (truthy((if (truthy(.x <- self$phase)) self$lit_when(h, elem(way, 2)) else .x))) {
      return(lst(0, elem(way, 0), elem(way, 1)))
    }
    return(lst(self$sent_at(z, elem(way, 2)), elem(way, 0), elem(way, 1)))
    NULL
  })
  field(cl, "fold", function() filled(self$cells, 0))
  field(cl, "lean_x", function() filled(self$cells, 0))
  field(cl, "lean_y", function() filled(self$cells, 0))
  field(cl, "growth", function() filled(self$cells, 0))
  field(cl, "gone", function() filled(self$cells, 0))
  field(cl, "blocks", function() filled(self$cells, 0))
  field(cl, "holes", function() lst())
  method(cl, "face_of", function(h = NULL, ...) {
    return((if (truthy(eq(h, NULL))) self$aggregate$NEAR else ((if (truthy(gt(h$face, self$aggregate$NEAR))) h$face else self$aggregate$NEAR))))
    NULL
  })
  method(cl, "skin_of", function(h = NULL, ...) {
    near <- self$aggregate$NEAR
    face <- self$face_of(h)
    at_one <- r_sub(1, self$aggregate$reach_at(near))
    got <- r_sub(1, self$aggregate$reach_at(face))
    return((if (truthy(gt(at_one, 0))) r_div(got, at_one) else 1))
    NULL
  })
  getter(cl, "ways_wide", function() {
    return(r_div((2 * pi), self$DEG))
    NULL
  })
  field(cl, "ROUNDS", function() 4)
  method(cl, "was_at", function(h = NULL, x = NULL, y = NULL, ...) {
    hx <- elem(self$tracks, m_index_of(self$holes, h))
    n <- (if (truthy(eq(hx, NULL))) 0 else r_div(len(hx), 2))
    if (truthy((if (truthy(.x <- (!truthy(self$retard)))) .x else lt(n, 2)))) {
      return(lst(h$x, h$y))
    }
    px <- h$x
    py <- h$y
    R <- r_div(Fmt$hypot(r_sub(px, x), r_sub(py, y)), self$K)
    .r <- for_range(self$ROUNDS, function(i) {
      back <- m_round(R)
      if (truthy(gt(back, r_sub(n, 1)))) {
        .w("back", r_sub(n, 1))
      }
      at <- r_sub(r_sub(n, 1), back)
      vx <- (if (truthy(gt(at, 0))) r_sub(elem(hx, r_mul(2, at)), elem(hx, r_sub(r_mul(2, at), 2))) else 0)
      vy <- (if (truthy(gt(at, 0))) r_sub(elem(hx, r_add(r_mul(2, at), 1)), elem(hx, r_sub(r_mul(2, at), 1))) else 0)
      .w("px", r_add(elem(hx, r_mul(2, at)), r_mul(vx, back)))
      .w("py", r_add(elem(hx, r_add(r_mul(2, at), 1)), r_mul(vy, back)))
      .w("R", r_div(Fmt$hypot(r_sub(px, x), r_sub(py, y)), self$K))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(lst(px, py))
    NULL
  })
  field(cl, "retard", function() FALSE)
  field(cl, "tracks", function() lst())
  getter(cl, "keep_track", function() {
    if (truthy((!truthy(self$retard)))) {
      return(NULL)
    }
    .r <- for_range(len(self$holes), function(k) {
      if (truthy(le(len(self$tracks), k))) {
        m_push(self$tracks, lst())
      }
      m_push(elem(self$tracks, k), elem(self$holes, k)$x)
      m_push(elem(self$tracks, k), elem(self$holes, k)$y)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  method(cl, "out_from", function(h = NULL, x = NULL, y = NULL, ...) {
    seen <- self$was_at(h, x, y)
    dx <- r_sub(x, elem(seen, 0))
    dy <- r_sub(y, elem(seen, 1))
    d <- Fmt$hypot(dx, dy)
    near <- self$face_of(h)
    if (truthy(le(d, 0))) {
      return(lst(0, 0, near))
    }
    return(lst(r_div(dx, d), r_div(dy, d), Fmt$max(near, r_div(d, self$K))))
    NULL
  })
  method(cl, "facing_share", function(ax = NULL, ay = NULL, bx = NULL, by = NULL, ...) {
    ux <- r_sub(0, bx)
    uy <- r_sub(0, by)
    if (truthy(le(r_add(r_mul(ax, ux), r_mul(ay, uy)), m_cos(self$ways_wide)))) {
      return(0)
    }
    angle <- m_abs(m_atan2((r_sub(r_mul(ax, uy), r_mul(ay, ux))), r_add(r_mul(ax, ux), r_mul(ay, uy))))
    got <- r_sub(1, r_div(angle, self$ways_wide))
    return((if (truthy(lt(got, 0))) 0 else got))
    NULL
  })
  method(cl, "body_of", function(z = NULL, ...) {
    return((if (truthy(self$apart)) ((if (truthy((if (truthy(.x <- ge(z, 1))) le(z, len(self$holes)) else .x))) elem(self$holes, r_sub(z, 1)) else NULL)) else m_first(filt(self$holes, function(h = NULL, ...) {
      return(eq(self$plane_of(h), z))
      NULL
    }))))
    NULL
  })
  getter(cl, "terms", function() {
    return(self$theory$equation$terms)
    NULL
  })
  field(cl, "meets", function() filt(self$terms, function(t = NULL, ...) {
    return((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (!truthy(t$settles)))) (!truthy(t$transport)) else .x))) (!truthy(t$outside)) else .x))) (!truthy(t$doing$trades)) else .x))) eq(t$degree, 2) else .x))
    NULL
  }))
  field(cl, "points", function() filt(self$terms, function(t = NULL, ...) {
    return((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (!truthy(t$settles)))) (!truthy(t$transport)) else .x))) (!truthy(t$outside)) else .x))) (!truthy(t$doing$trades)) else .x))) eq(t$degree, 0) else .x))
    NULL
  }))
  field(cl, "singles", function() filt(self$terms, function(t = NULL, ...) {
    return((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (!truthy(t$settles)))) (!truthy(t$transport)) else .x))) (!truthy(t$outside)) else .x))) (!truthy(t$doing$trades)) else .x))) eq(t$degree, 1) else .x))
    NULL
  }))
  field(cl, "carrying", function() m_first(filt(self$terms, function(t = NULL, ...) {
    return((if (truthy(.x <- t$transport)) (!eq(t$leans, NULL)) else .x))
    NULL
  })))
  field(cl, "turned", function() (if (truthy(eq(self$carrying, NULL))) "kept" else self$carrying$turned))
  field(cl, "trading", function() filt(self$terms, function(t = NULL, ...) {
    return(t$doing$trades)
    NULL
  }))
  method(cl, "beta", function(h = NULL, ...) {
    v <- r_div(h$momentum$norm, h$mass)
    return((if (truthy(lt(v, 0))) 0 else ((if (truthy(gt(v, 1))) 1 else v))))
    NULL
  })
  field(cl, "own", function() 0)
  method(cl, "felt_by", function(k = NULL, ...) {
    if (truthy(le(len(self$pulled), k))) {
      return(0)
    }
    g <- elem(self$pulled, k)
    return(Fmt$hypot(elem(g, 0), elem(g, 1)))
    NULL
  })
  method(cl, "drifting", function(h = NULL, ...) {
    if (truthy((!eq(self$own, 1)))) {
      return(1)
    }
    k <- m_index_of(self$holes, h)
    g <- self$felt_by(k)
    a0 <- self$a0_vacuum
    if (truthy((if (truthy(.x <- (!truthy((gt(g, 0)))))) .x else (!truthy((gt(a0, 0))))))) {
      return(1)
    }
    return(r_add(1, r_div(a0, g)))
    NULL
  })
  method(cl, "per_way", function(h = NULL, ...) {
    c <- self$at(m_round(h$x), m_round(h$y))
    s <- self$symbols((if (truthy((if (truthy(.x <- ge(c, 0))) (!truthy(m_empty(self$rho_was))) else .x))) elem(self$rho_was, c) else 0), 0)
    .set(s, key_("β"), self$beta(h))
    got <- r_mul(r_div(h$mass, self$DEG), self$skin_of(h))
    .r <- for_each(filt(self$terms, function(t = NULL, ...) {
      return(t$outside)
      NULL
    }), function(t) {
      .w("got", r_mul(r_mul(got, self$share(t, s)), t$doing$rays$at(s)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(r_mul(got, self$drifting(h)))
    NULL
  })
  field(cl, "vacuum", function() FALSE)
  field(cl, "facing", function() FALSE)
  field(cl, "a0_share", function() 1)
  field(cl, "model", function() Model$new(theory = self$theory))
  getter(cl, "model_a0", function() {
    f <- self$model$fact("a_{0}")
    return((if (truthy(eq(f, NULL))) 0 else self$model$at(f$to, self$model$settled(self$DEG))))
    NULL
  })
  field(cl, "a0_chain", function() self$model_a0)
  getter(cl, "a0_vacuum", function() {
    return(r_mul(self$a0_chain, self$a0_share))
    NULL
  })
  field(cl, "a0_from", function() 0)
  field(cl, "scale_fact", function() self$model$fact("a_{0} along the path"))
  field(cl, "scale_env", function() self$model$settled(self$DEG))
  method(cl, "scale_at", function(avg = NULL, ...) {
    if (truthy(eq(self$scale_fact, NULL))) {
      return(1)
    }
    e <- Model$copy(self$scale_env)
    .set(e, key_("\\langle\\rho\\rangle"), avg)
    return(self$model$at(self$scale_fact$to, e))
    NULL
  })
  field(cl, "scale_inf", function() self$scale_at(self$rho_inf))
  field(cl, "CROSSING", function() 16)
  method(cl, "crossed_at", function(x = NULL, y = NULL, ...) {
    h <- self$nearest(x, y)
    if (truthy(eq(h, NULL))) {
      return(self$rho_inf)
    }
    got <- 0
    .r <- for_range(self$CROSSING, function(i) {
      f <- r_div((r_add(i, 0.5)), self$CROSSING)
      .w("got", r_add(got, self$tap(self$vac, 0, r_add(h$x, r_mul((r_sub(x, h$x)), f)), r_add(h$y, r_mul((r_sub(y, h$y)), f)), self$rho_inf)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(r_div(got, self$CROSSING))
    NULL
  })
  method(cl, "a0_at_place", function(x = NULL, y = NULL, ...) {
    if (truthy(eq(self$a0_from, 2))) {
      return((if (truthy(gt(self$scale_inf, 0))) r_div(r_mul(self$a0_vacuum, self$scale_at(self$crossed_at(x, y))), self$scale_inf) else self$a0_vacuum))
    }
    if (truthy((if (truthy(.x <- (!eq(self$a0_from, 1)))) .x else (!truthy((gt(self$rho_inf, 0))))))) {
      return(self$a0_vacuum)
    }
    got <- self$tap(self$rho_was, 0, x, y, 0)
    return(r_div(r_mul(self$a0_vacuum, got), self$rho_inf))
    NULL
  })
  method(cl, "symbols", function(rho = NULL, nf = NULL, ...) {
    s <- Node$new()
    .set(s, key_("ρ"), rho)
    .set(s, key_("n_f"), (if (truthy(self$vacuum)) r_add(nf, self$nf_inf) else nf))
    .set(s, key_("DEG"), self$DEG)
    fac <- mem(self$aggregate$base, key_("F"))
    .set(s, key_("F"), (if (truthy((if (truthy(.x <- self$facing)) (!eq(fac, NULL)) else .x))) fac else 1))
    om <- mem(self$aggregate$base, key_("\\omega"))
    .set(s, key_("ω"), (if (truthy(eq(om, NULL))) 1 else om))
    .set(s, key_("β"), 0)
    .set(s, key_("m_l"), 0)
    .r <- for_each(self$terms, function(t) {
      if (truthy((if (truthy(.x <- (!eq(t$rate, NULL)))) eq(elem(s, t$rate), NULL) else .x))) {
        set_at(s, t$rate, 1)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(s)
    NULL
  })
  method(cl, "share", function(t = NULL, s = NULL, ...) {
    v <- t$doing$share$at(s)
    return((if (truthy(lt(v, 0))) 0 else ((if (truthy(gt(v, 1))) 1 else v))))
    NULL
  })
  method(cl, "activity", function(x = NULL, ...) {
    return((if (truthy(lt(x, 0))) 0 else ((if (truthy(gt(x, 1))) 1 else x))))
    NULL
  })
  method(cl, "at", function(x = NULL, y = NULL, ...) {
    return((if (truthy(((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- lt(x, 0))) .x else lt(y, 0)))) .x else ge(x, self$N)))) .x else ge(y, self$N))))) neg(1) else r_add(r_mul(y, self$N), x)))
    NULL
  })
  method(cl, "column_of", function(c = NULL, ...) {
    return(r_mod(c, self$N))
    NULL
  })
  method(cl, "row_of", function(c = NULL, ...) {
    return(r_div((r_sub(c, r_mod(c, self$N))), self$N))
    NULL
  })
  method(cl, "plane_of", function(h = NULL, ...) {
    return((if (truthy((if (truthy(.x <- self$apart)) .x else self$local_rays))) r_add(m_index_of(self$holes, h), 1) else ((if (truthy(((if (truthy(.x <- eq(h$tag, NULL))) .x else lt(h$tag, 1))))) 0 else ((if (truthy(lt(h$tag, self$planes))) h$tag else r_sub(self$planes, 1)))))))
    NULL
  })
  method(cl, "add", function(h = NULL, ...) {
    .set(h, "momentum", Vector$new(components = lst(h$px, h$py)))
    .set(h, "advance", Vector$zero(2))
    m_push(self$holes, h)
    if (truthy(self$apart)) {
      m_push(self$beam, filled(self$rungs, 0))
      m_push(self$swept, filled(self$cells, 0))
    }
    if (truthy((if (truthy(.x <- self$local_rays)) lt(len(self$swept), 2) else .x))) {
      m_push(self$swept, filled(self$cells, 0))
    }
    self$block
    return(h)
    NULL
  })
  method(cl, "under", function(h = NULL, ...) {
    half <- m_floor((r_div((r_sub(self$K, 1)), 2)))
    out <- lst()
    .r <- for_range(self$K, function(dy) {
      .r <- for_range(self$K, function(dx) {
        c <- self$at(r_add(r_sub(m_round(h$x), half), dx), r_add(r_sub(m_round(h$y), half), dy))
        if (truthy(ge(c, 0))) {
          m_push(out, c)
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  method(cl, "spread", function(h = NULL, ...) {
    half <- r_div(r_sub(self$K, 1), 2)
    out <- lst()
    .r <- for_range(self$K, function(dy) {
      .r <- for_range(self$K, function(dx) {
        px <- r_add(r_sub(h$x, half), dx)
        py <- r_add(r_sub(h$y, half), dy)
        x0 <- m_floor(px)
        y0 <- m_floor(py)
        ax <- r_sub(px, x0)
        ay <- r_sub(py, y0)
        .r <- for_range(2, function(j) {
          .r <- for_range(2, function(i) {
            c <- self$at(r_add(x0, i), r_add(y0, j))
            w <- r_mul(((if (truthy(eq(i, 0))) r_sub(1, ax) else ax)), ((if (truthy(eq(j, 0))) r_sub(1, ay) else ay)))
            if (truthy((if (truthy(.x <- ge(c, 0))) gt(w, 0) else .x))) {
              m_push(out, lst(c, w))
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  getter(cl, "block", function() {
    .r <- for_range(self$cells, function(c) {
      set_at(self$blocks, c, 0)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_range(len(self$holes), function(k) {
      .r <- for_each(self$under(elem(self$holes, k)), function(c) {
        set_at(self$blocks, c, r_add(k, 1))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
