  method(cl, "tap", function(f = NULL, base = NULL, x = NULL, y = NULL, outside = NULL, ...) {
    x0 <- m_floor(x)
    y0 <- m_floor(y)
    ax <- r_sub(x, x0)
    ay <- r_sub(y, y0)
    cell_value <- function(i = NULL, j = NULL, ...) {
      k <- self$at(i, j)
      return((if (truthy(ge(k, 0))) elem(f, r_add(base, k)) else outside))
      NULL
    }
    got <- r_mul(r_mul((r_sub(1, ax)), (r_sub(1, ay))), (cell_value)(x0, y0))
    .w("got", r_add(got, r_mul(r_mul(ax, (r_sub(1, ay))), (cell_value)(r_add(x0, 1), y0))))
    .w("got", r_add(got, r_mul(r_mul((r_sub(1, ax)), ay), (cell_value)(x0, r_add(y0, 1)))))
    return(r_add(got, r_mul(r_mul(ax, ay), (cell_value)(r_add(x0, 1), r_add(y0, 1)))))
    NULL
  })
  method(cl, "slice", function(h = NULL, x = NULL, y = NULL, bx = NULL, by = NULL, ...) {
    if (truthy((if (truthy(.x <- le(self$D, 2))) .x else eq(h, NULL)))) {
      return(1)
    }
    near <- self$face_of(h)
    here <- Fmt$max(near, r_div(Fmt$hypot(r_sub(x, h$x), r_sub(y, h$y)), self$K))
    back <- Fmt$max(near, r_div(Fmt$hypot(r_sub(bx, h$x), r_sub(by, h$y)), self$K))
    return(r_pow((r_div(back, here)), r_sub(self$D, 2)))
    NULL
  })
  method(cl, "nearest", function(x = NULL, y = NULL, ...) {
    best <- NULL
    far <- 0
    .r <- for_each(self$holes, function(h) {
      d <- Fmt$hypot(r_sub(x, h$x), r_sub(y, h$y))
      if (truthy((if (truthy(.x <- eq(best, NULL))) .x else lt(d, far)))) {
        .w("best", h)
        .w("far", d)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(best)
    NULL
  })
