  method(cl, "now_from", function(m = NULL, x = NULL, y = NULL, ...) {
    sx <- r_div(elem(m, 1), elem(m, 0))
    sy <- r_div(elem(m, 2), elem(m, 0))
    age <- r_div(Fmt$hypot(r_sub(x, sx), r_sub(y, sy)), self$K)
    return(lst(r_add(sx, r_mul(r_div(elem(m, 3), elem(m, 0)), age)), r_add(sy, r_mul(r_div(elem(m, 4), elem(m, 0)), age))))
    NULL
  })
  method(cl, "reads", function(m = NULL, x = NULL, y = NULL, ...) {
    if (truthy((!truthy((gt(elem(m, 0), 0)))))) {
      return(lst(0, 0, 0))
    }
    s <- self$now_from(m, x, y)
    dx <- r_sub(x, elem(s, 0))
    dy <- r_sub(y, elem(s, 1))
    d <- Fmt$hypot(dx, dy)
    r <- Fmt$max(r_div(elem(m, 5), elem(m, 0)), r_div(d, self$K))
    got <- Fmt$min(1, r_mul(r_div(elem(m, 0), (r_pow(r, r_sub(self$D, 1)))), ((if (truthy(gt(r, r_div(elem(m, 5), elem(m, 0))))) self$spread_of(m, d) else 1))))
    if (truthy(le(d, 0))) {
      return(lst(got, 0, 0))
    }
    return(lst(got, r_div(dx, d), r_div(dy, d)))
    NULL
  })
  method(cl, "moments", function(k = NULL, ...) {
    return(lst(elem(self$bq, k), elem(self$bsx, k), elem(self$bsy, k), elem(self$bvx, k), elem(self$bvy, k), elem(self$bface, k), elem(self$bwho, k), elem(self$bspread, k)))
