  method(cl, "gathered", function(a = NULL, b = NULL, x = NULL, y = NULL, ...) {
    return(lst(r_add(elem(a, 0), elem(b, 0)), r_add(elem(a, 1), elem(b, 1)), r_add(elem(a, 2), elem(b, 2)), r_add(elem(a, 3), elem(b, 3)), r_add(elem(a, 4), elem(b, 4)), r_add(elem(a, 5), elem(b, 5)), (if (truthy(eq(elem(a, 6), elem(b, 6)))) elem(a, 6) else neg(1)), self$spread_with(a, b, x, y)))
    NULL
  })
  method(cl, "spread_with", function(a = NULL, b = NULL, x = NULL, y = NULL, ...) {
    if (truthy((!truthy(((if (truthy(.x <- gt(elem(a, 0), 0))) gt(elem(b, 0), 0) else .x)))))) {
      return(r_add(elem(a, 7), elem(b, 7)))
    }
    q <- r_add(elem(a, 0), elem(b, 0))
    ex <- r_sub(x, r_div((r_add(elem(a, 1), elem(b, 1))), q))
    ey <- r_sub(y, r_div((r_add(elem(a, 2), elem(b, 2))), q))
    e <- Fmt$hypot(ex, ey)
    along <- (if (truthy(gt(e, 0))) r_div((r_add(r_mul((r_sub(r_div(elem(a, 1), elem(a, 0)), r_div(elem(b, 1), elem(b, 0)))), ex), r_mul((r_sub(r_div(elem(a, 2), elem(a, 0)), r_div(elem(b, 2), elem(b, 0)))), ey))), e) else 0)
    return(r_add(r_add(elem(a, 7), elem(b, 7)), r_mul(r_mul(r_div(r_mul(elem(a, 0), elem(b, 0)), q), along), along)))
    NULL
  })
  method(cl, "spread_of", function(m = NULL, d = NULL, ...) {
    n <- r_sub(self$D, 1)
    if (truthy((!truthy(((if (truthy(.x <- gt(d, 0))) gt(elem(m, 0), 0) else .x)))))) {
      return(1)
    }
    return(Fmt$max(0.5, r_add(1, r_div(r_mul(r_div(r_mul(n, (r_add(n, 1))), 2), elem(m, 7)), (r_mul(r_mul(elem(m, 0), d), d))))))
    NULL
  })
  method(cl, "spread_toward", function(e = NULL, cx = NULL, cy = NULL, tx = NULL, ty = NULL, ...) {
    if (truthy((if (truthy(.x <- lt(len(e), 11))) .x else (!truthy((gt(elem(e, 0), 0))))))) {
      return(0)
    }
    q <- elem(e, 0)
    mx <- r_sub(r_div(elem(e, 1), q), cx)
    my <- r_sub(r_div(elem(e, 2), q), cy)
    sxx <- r_sub(r_div(elem(e, 8), q), r_mul(mx, mx))
    sxy <- r_sub(r_div(elem(e, 9), q), r_mul(mx, my))
    syy <- r_sub(r_div(elem(e, 10), q), r_mul(my, my))
    ux <- r_sub(tx, r_div(elem(e, 1), q))
    uy <- r_sub(ty, r_div(elem(e, 2), q))
    d2 <- r_add(r_mul(ux, ux), r_mul(uy, uy))
    if (truthy((!truthy((gt(d2, 0)))))) {
      return(0)
    }
    along <- r_div((r_add(r_add(r_mul(r_mul(sxx, ux), ux), r_mul(r_mul(r_mul(2, sxy), ux), uy)), r_mul(r_mul(syy, uy), uy))), d2)
    n <- r_sub(self$D, 1)
    return(r_mul(q, (r_sub(along, r_div((r_sub(r_add(sxx, syy), along)), (r_add(n, 1)))))))
    NULL
  })
  method(cl, "apart_seen", function(a = NULL, b = NULL, x = NULL, y = NULL, ...) {
    ax <- r_div(elem(a, 1), elem(a, 0))
    ay <- r_div(elem(a, 2), elem(a, 0))
    bx <- r_div(elem(b, 1), elem(b, 0))
    by <- r_div(elem(b, 2), elem(b, 0))
    near <- Fmt$min(Fmt$hypot(r_sub(x, ax), r_sub(y, ay)), Fmt$hypot(r_sub(x, bx), r_sub(y, by)))
    return(r_div(Fmt$hypot(r_sub(ax, bx), r_sub(ay, by)), Fmt$max(near, 1)))
    NULL
  })
  method(cl, "fresh", function(m = NULL, x = NULL, y = NULL, ...) {
