  method(cl, "lay", function(c = NULL, b = NULL, got = NULL, ...) {
    x <- self$column_of(c)
    y <- self$row_of(c)
    group_now <- filt(got, function(m = NULL, ...) {
      return(gt(elem(m, 0), 0))
      NULL
    })
    while (truthy(gt(len(group_now), self$keeps))) {
      fr <- m_map(group_now, function(m = NULL, ...) {
        return(self$fresh(m, x, y))
        NULL
      })
      best <- 0
      bi <- neg(1)
      bj <- neg(1)
      .r <- for_range(2, function(tries) {
        if (truthy(lt(bi, 0))) {
          .r <- for_range(len(group_now), function(i) {
            .r <- for_range(len(group_now), function(j) {
              if (truthy((if (truthy(.x <- gt(j, i))) ((if (truthy(.x <- eq(tries, 1))) .x else eq(elem(fr, i), elem(fr, j)))) else .x))) {
                seen <- self$apart_seen(elem(group_now, i), elem(group_now, j), x, y)
                if (truthy((if (truthy(.x <- lt(bi, 0))) .x else lt(seen, best)))) {
                  .w("best", seen)
                  .w("bi", i)
                  .w("bj", j)
                }
              }
              CONTINUE
            })
            if (!is.null(.r)) return(.r[[1]])
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      merged <- self$gathered(elem(group_now, bi), elem(group_now, bj), x, y)
      .w("group_now", m_concat(m_map(filt(rng(len(group_now)), function(i = NULL, ...) {
        return((if (truthy(.x <- (!eq(i, bi)))) (!eq(i, bj)) else .x))
        NULL
      }), function(i = NULL, ...) {
        return(elem(group_now, i))
        NULL
      }), lst(merged)))
    }
    base <- self$first_slot(c, b)
    .r <- for_range(self$keeps, function(j) {
      m <- (if (truthy(lt(j, len(group_now)))) elem(group_now, j) else lst(0, 0, 0, 0, 0, 0, neg(1), 0))
      set_at(self$bq, r_add(base, j), elem(m, 0))
      set_at(self$bsx, r_add(base, j), elem(m, 1))
      set_at(self$bsy, r_add(base, j), elem(m, 2))
      set_at(self$bvx, r_add(base, j), elem(m, 3))
      set_at(self$bvy, r_add(base, j), elem(m, 4))
      set_at(self$bface, r_add(base, j), elem(m, 5))
      set_at(self$bwho, r_add(base, j), elem(m, 6))
      set_at(self$bspread, r_add(base, j), elem(m, 7))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  method(cl, "held_on", function(c = NULL, b = NULL, ...) {
    base <- self$first_slot(c, b)
    return(filt(m_map(rng(self$keeps), function(j = NULL, ...) {
