    return(lst(q, r_mul(q, h$x), r_mul(q, h$y), r_mul(r_div(r_mul(q, elem(h$momentum$components, 0)), h$mass), self$K), r_mul(r_div(r_mul(q, elem(h$momentum$components, 1)), h$mass), self$K), r_mul(q, near), m_index_of(self$holes, h), 0))
    NULL
  })
  method(cl, "left_for", function(e = NULL, d = NULL, ...) {
    back <- r_div(d, self$K)
    return(lst(elem(e, 0), r_sub(elem(e, 1), r_mul(elem(e, 3), back)), r_sub(elem(e, 2), r_mul(elem(e, 4), back)), elem(e, 3), elem(e, 4), elem(e, 5), elem(e, 6), elem(e, 7)))
    NULL
  })
  method(cl, "put_middle", function(c = NULL, e = NULL, ...) {
    got <- Fmt$min(1, r_div(elem(e, 0), (r_pow((r_div(elem(e, 5), elem(e, 0))), r_sub(self$D, 1)))))
    set_at(self$middle_who, c, (if (truthy((if (truthy(.x <- gt(elem(self$middle, c), 0))) (!eq(elem(self$middle_who, c), elem(e, 6))) else .x))) neg(1) else elem(e, 6)))
    set_at(self$middle, c, r_add(elem(self$middle, c), got))
    NULL
  })
  getter(cl, "shine_local", function() {
    self$bundles_ready
    .r <- for_range(self$cells, function(c) {
      set_at(self$middle, c, 0)
      set_at(self$middle_who, c, neg(1))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    src <- self$cell_sources
    self$shone <- src
    reach <- r_add(m_floor(self$edge), 1)
    .r <- for_range(self$cells, function(c) {
      x <- self$column_of(c)
      y <- self$row_of(c)
      laid <- m_map(rng(self$gather), function(b = NULL, ...) {
        return(lst())
        NULL
      })
      .r <- for_range(r_add(r_mul(2, reach), 1), function(j) {
        .r <- for_range(r_add(r_mul(2, reach), 1), function(i) {
          sc <- self$at(r_add(r_sub(self$column_of(c), reach), i), r_add(r_sub(self$row_of(c), reach), j))
          e <- (if (truthy(ge(sc, 0))) elem(src, sc) else NULL)
          if (truthy((if (truthy(.x <- (!eq(e, NULL)))) gt(elem(e, 0), 0) else .x))) {
            dx <- r_sub(x, r_div(elem(e, 1), elem(e, 0)))
            dy <- r_sub(y, r_div(elem(e, 2), elem(e, 0)))
            d <- Fmt$hypot(dx, dy)
            if (truthy(le(d, 0.001))) {
              self$put_middle(c, e)
            }
            if (truthy((if (truthy(.x <- gt(d, 0.001))) le(d, self$edge) else .x))) {
              lf <- self$left_for(e, d)
              set_at(lf, 7, self$spread_toward(e, self$column_of(sc), self$row_of(sc), x, y))
              m_push(elem(laid, self$bin_of(dx, dy)), lf)
            }
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .r <- for_range(self$gather, function(b) {
        held <- self$held_on(c, b)
        kept <- filt(held, function(m = NULL, ...) {
          return((!truthy(self$relaid(m, x, y))))
          NULL
        })
        if (truthy((if (truthy(.x <- (!eq(len(kept), len(held))))) .x else (!truthy(m_empty(elem(laid, b))))))) {
          self$lay(c, b, m_concat(kept, elem(laid, b)))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  method(cl, "relaid", function(m = NULL, x = NULL, y = NULL, ...) {
    if (truthy((if (truthy(.x <- lt(elem(m, 6), 0))) .x else ge(elem(m, 6), len(self$holes))))) {
      return(self$fresh(m, x, y))
    }
    h <- elem(self$holes, m_round(elem(m, 6)))
    return(le(Fmt$hypot(r_sub(x, h$x), r_sub(y, h$y)), self$edge))
    NULL
  })
  getter(cl, "cell_sources", function() {
    src <- filled(self$cells, NULL)
    .r <- for_each(self$holes, function(h) {
      c <- self$at(m_round(h$x), m_round(h$y))
      if (truthy(ge(c, 0))) {
        e0 <- self$emitted(h)
        dx <- r_sub(h$x, self$column_of(c))
        dy <- r_sub(h$y, self$row_of(c))
        e <- m_concat(e0, lst(r_mul(r_mul(elem(e0, 0), dx), dx), r_mul(r_mul(elem(e0, 0), dx), dy), r_mul(r_mul(elem(e0, 0), dy), dy)))
        had <- elem(src, c)
