    self$bsy <- filled(n, 0)
    self$bvx <- filled(n, 0)
    self$bvy <- filled(n, 0)
    self$bface <- filled(n, 0)
    self$bwho <- filled(n, neg(1))
    self$bspread <- filled(n, 0)
    .r <- for_range(self$cells, function(c) {
      x <- self$column_of(c)
      y <- self$row_of(c)
      .r <- for_range(B, function(t) {
        groups <- lst()
        a0 <- r_div(r_mul((2 * pi), (r_sub(t, 0.5))), B)
        a1 <- r_div(r_mul((2 * pi), (r_add(t, 0.5))), B)
        p0x <- r_sub(x, r_mul(self$K, m_cos(a0)))
        p0y <- r_sub(y, r_mul(self$K, m_sin(a0)))
        p1x <- r_sub(x, r_mul(self$K, m_cos(a1)))
        p1y <- r_sub(y, r_mul(self$K, m_sin(a1)))
        lx <- m_floor(Fmt$min(p0x, p1x))
        ly <- m_floor(Fmt$min(p0y, p1y))
        nx <- r_sub(r_add(m_floor(Fmt$max(p0x, p1x)), 2), lx)
        ny <- r_sub(r_add(m_floor(Fmt$max(p0y, p1y)), 2), ly)
        .r <- for_range(ny, function(j) {
          .r <- for_range(nx, function(i) {
            u <- self$at(r_add(lx, i), r_add(ly, j))
            if (truthy(ge(u, 0))) {
              ux <- r_add(lx, i)
              uy <- r_add(ly, j)
              .r <- for_range(r_add(r_mul(2, self$window), 1), function(o) {
                base <- r_mul((r_add(r_mul(u, B), r_mod((r_sub(r_add(r_add(t, B), o), self$window)), B))), S)
                .r <- for_range(S, function(sl) {
                  k <- r_add(base, sl)
                  q <- elem(elem(was, 0), k)
                  if (truthy(gt(q, 0))) {
                    m <- lst(q, elem(elem(was, 1), k), elem(elem(was, 2), k), elem(elem(was, 3), k), elem(elem(was, 4), k), elem(elem(was, 5), k), elem(elem(was, 6), k), elem(elem(was, 7), k))
                    dx <- r_sub(x, r_div(elem(m, 1), q))
                    dy <- r_sub(y, r_div(elem(m, 2), q))
                    d <- Fmt$hypot(dx, dy)
                    now <- self$now_from(m, x, y)
                    if (truthy((if (truthy(.x <- (if (truthy(.x <- gt(d, 0))) eq(self$bin_of(dx, dy), t) else .x))) gt(Fmt$hypot(r_sub(x, elem(now, 0)), r_sub(y, elem(now, 1))), self$zone) else .x))) {
                      cx <- r_sub(x, r_div(r_mul(self$K, dx), d))
                      cy <- r_sub(y, r_div(r_mul(self$K, dy), d))
                      w <- r_div(r_mul(self$tent(r_sub(ux, cx)), self$tent(r_sub(uy, cy))), self$inside_at(cx, cy))
                      if (truthy(gt(w, 0))) {
                        g <- neg(1)
                        .r <- for_range(len(groups), function(gi) {
                          h <- elem(groups, gi)
                          same <- (if (truthy(.x <- ((if (truthy(.x <- (!eq(elem(m, 6), neg(1))))) eq(elem(h, 6), elem(m, 6)) else .x)))) .x else ((if (truthy(.x <- (if (truthy(.x <- eq(elem(m, 6), neg(1)))) eq(elem(h, 6), neg(1)) else .x))) lt(Fmt$hypot(r_sub(r_div(elem(h, 1), elem(h, 0)), r_div(elem(m, 1), q)), r_sub(r_div(elem(h, 2), elem(h, 0)), r_div(elem(m, 2), q))), r_add(0.5, r_mul(0.05, d))) else .x)))
                          if (truthy((if (truthy(.x <- lt(g, 0))) same else .x))) {
                            .w("g", gi)
                          }
                          CONTINUE
                        })
                        if (!is.null(.r)) return(.r[[1]])
                        part <- lst(r_mul(w, elem(m, 0)), r_mul(w, elem(m, 1)), r_mul(w, elem(m, 2)), r_mul(w, elem(m, 3)), r_mul(w, elem(m, 4)), r_mul(w, elem(m, 5)), elem(m, 6), r_mul(w, elem(m, 7)))
                        if (truthy(lt(g, 0))) {
                          m_push(groups, part)
                        } else {
                          h <- elem(groups, g)
                          set_at(groups, g, lst(r_add(elem(h, 0), elem(part, 0)), r_add(elem(h, 1), elem(part, 1)), r_add(elem(h, 2), elem(part, 2)), r_add(elem(h, 3), elem(part, 3)), r_add(elem(h, 4), elem(part, 4)), r_add(elem(h, 5), elem(part, 5)), elem(h, 6), self$spread_with(h, part, x, y)))
                        }
                      }
                    }
                  }
                  CONTINUE
                })
                if (!is.null(.r)) return(.r[[1]])
                CONTINUE
              })
              if (!is.null(.r)) return(.r[[1]])
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        if (truthy((!truthy(m_empty(groups))))) {
          self$lay(c, t, groups)
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
