  method(cl, "arriving_at", function(x = NULL, y = NULL, zown = NULL, ...) {
    B <- self$gather
    S <- self$keeps
    u <- self$at(m_round(x), m_round(y))
    if (truthy(lt(u, 0))) {
      return(lst(0, 0, 0))
    }
    own <- (if (truthy((if (truthy(.x <- (if (truthy(.x <- self$local_rays)) ge(zown, 1) else .x))) le(zown, len(self$holes)) else .x))) elem(self$holes, r_sub(zown, 1)) else NULL)
    srcid <- (if (truthy(eq(own, NULL))) 0.5 else r_sub(neg(2), self$at(m_round(own$x), m_round(own$y))))
    whole <- self$own_gathering(own)
    mine <- (if (truthy(eq(own, NULL))) lst(0, 0, 0, 0, 0, 0, neg(1), 0) else ((if (truthy(eq(whole, NULL))) self$emitted(own) else lst(elem(whole, 0), elem(whole, 1), elem(whole, 2), elem(whole, 3), elem(whole, 4), elem(whole, 5), elem(whole, 6), 0))))
    me <- (if (truthy(eq(whole, NULL))) r_sub(zown, 1) else srcid)
