    uy <- self$row_of(u)
    owns <- (if (truthy(eq(own, NULL))) neg(1) else self$bin_of(r_sub(ux, r_div(elem(mine, 1), elem(mine, 0))), r_sub(uy, r_div(elem(mine, 2), elem(mine, 0)))))
