      return(m_some(rng(S), function(sl = NULL, ...) {
        return(eq(elem(self$bwho, r_add(r_mul((r_add(r_mul(u, B), r_mod((r_sub(r_add(r_add(owns, B), o), 2)), B))), S), sl)), me))
        NULL
