    })
    if (!is.null(.r)) return(.r[[1]])
    e <- (if (truthy(eq(len(self$shone), self$cells))) elem(self$shone, u) else NULL)
    if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (!eq(e, NULL)))) gt(elem(e, 0), 0) else .x))) le(Fmt$hypot(r_sub(ux, r_div(elem(e, 1), elem(e, 0))), r_sub(uy, r_div(elem(e, 2), elem(e, 0)))), 0.001) else .x))) (!truthy(((if (truthy(.x <- (!eq(own, NULL)))) eq(elem(e, 6), me) else .x)))) else .x))) {
      m <- e
