        .w("gx", r_add(gx, r_mul(elem(got, 0), elem(got, 1))))
        .w("gy", r_add(gy, r_mul(elem(got, 0), elem(got, 2))))
      }
    }
    return(lst(sum, gx, gy))
    NULL
