  method(cl, "far_of", function(m = NULL, ux = NULL, uy = NULL, ...) {
    s <- self$now_from(m, ux, uy)
    d <- Fmt$hypot(r_sub(ux, elem(s, 0)), r_sub(uy, elem(s, 1)))
    r <- r_div(d, self$K)
    return((if (truthy(.x <- (if (truthy(.x <- gt(d, Medium$NEAR_CELLS))) gt(r, r_div(elem(m, 5), elem(m, 0))) else .x))) lt(r_div(elem(m, 0), (r_pow(r, r_sub(self$D, 1)))), 1) else .x))
    NULL
  })
  method(cl, "expanded", function(m = NULL, ux = NULL, uy = NULL, dx = NULL, dy = NULL, ...) {
    s <- self$now_from(m, ux, uy)
    ex <- r_sub(ux, elem(s, 0))
    ey <- r_sub(uy, elem(s, 1))
    r2 <- r_add(r_mul(ex, ex), r_mul(ey, ey))
    Dd <- self$D
    C <- r_mul(r_mul(elem(m, 0), (r_pow(self$K, (r_sub(Dd, 1))))), self$spread_of(m, m_sqrt(r2)))
    rD <- r_pow(r2, (r_div(Dd, 2)))
    a <- r_div(C, rD)
    b <- r_div(r_mul(Dd, C), (r_mul(rD, r2)))
    c <- r_div(r_mul(r_mul(Dd, (r_add(Dd, 2))), C), (r_mul(r_mul(rD, r2), r2)))
    jxx <- r_sub(a, r_mul(r_mul(b, ex), ex))
    jxy <- r_sub(0, r_mul(r_mul(b, ex), ey))
    jyy <- r_sub(a, r_mul(r_mul(b, ey), ey))
    hxxx <- r_add(r_sub(0, r_mul(r_mul(3, b), ex)), r_mul(r_mul(r_mul(c, ex), ex), ex))
    hxxy <- r_add(r_sub(0, r_mul(b, ey)), r_mul(r_mul(r_mul(c, ex), ex), ey))
    hxyy <- r_add(r_sub(0, r_mul(b, ex)), r_mul(r_mul(r_mul(c, ex), ey), ey))
    hyyy <- r_add(r_sub(0, r_mul(r_mul(3, b), ey)), r_mul(r_mul(r_mul(c, ey), ey), ey))
    fx <- r_add(r_add(r_add(r_mul(a, ex), r_mul(jxx, dx)), r_mul(jxy, dy)), r_div((r_add(r_add(r_mul(r_mul(hxxx, dx), dx), r_mul(r_mul(r_mul(2, hxxy), dx), dy)), r_mul(r_mul(hxyy, dy), dy))), 2))
    fy <- r_add(r_add(r_add(r_mul(a, ey), r_mul(jxy, dx)), r_mul(jyy, dy)), r_div((r_add(r_add(r_mul(r_mul(hxxy, dx), dx), r_mul(r_mul(r_mul(2, hxyy), dx), dy)), r_mul(r_mul(hyyy, dy), dy))), 2))
    return(lst(fx, fy))
    NULL
  })
  method(cl, "nearest_gathering", function(way = NULL, h = NULL, ...) {
