        if (truthy((if (truthy(.x <- lt(best, 0))) .x else lt(d, far)))) {
          .w("best", sl)
          .w("far", d)
        }
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(best)
    NULL
  })
