  method(cl, "meet_bins", function(c = NULL, s = NULL, sums = NULL, wx = NULL, wy = NULL, ...) {
    B <- self$gather
    .r <- for_range(B, function(a) {
      if (truthy(gt(elem(sums, a), 0))) {
        na <- Fmt$hypot(elem(wx, a), elem(wy, a))
        ax <- (if (truthy(gt(na, 0))) r_div(elem(wx, a), na) else 0)
        ay <- (if (truthy(gt(na, 0))) r_div(elem(wy, a), na) else 0)
        .r <- for_range(B, function(b) {
          if (truthy((if (truthy(.x <- (!eq(b, a)))) gt(elem(sums, b), 0) else .x))) {
            nb <- Fmt$hypot(elem(wx, b), elem(wy, b))
            over <- (if (truthy(gt(nb, 0))) self$facing_share(ax, ay, r_div(elem(wx, b), nb), r_div(elem(wy, b), nb)) else 0)
            if (truthy(gt(over, 0))) {
              .r <- for_each(self$meets, function(t) {
                w <- r_mul(r_mul(r_mul(self$share(t, s), self$activity(elem(sums, a))), self$activity(elem(sums, b))), over)
                set_at(self$fold, c, Fmt$max(0, r_add(elem(self$fold, c), r_div(r_mul(w, t$doing$folds$at(s)), 2))))
                set_at(self$growth, c, r_add(elem(self$growth, c), r_div(r_mul(w, t$doing$space$at(s)), 2)))
                set_at(self$gone, c, r_add(elem(self$gone, c), r_div(r_mul(w, m_abs(t$doing$folds$at(s))), 2)))
                CONTINUE
              })
              if (!is.null(.r)) return(.r[[1]])
            }
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        if (truthy(self$vacuum)) {
          .r <- for_each(self$meets, function(t) {
            w <- r_div(r_mul(r_mul(self$share(t, s), self$activity(elem(sums, a))), self$activity(self$rho_inf)), self$DEG)
            set_at(self$fold, c, Fmt$max(0, r_add(elem(self$fold, c), r_div(r_mul(w, t$doing$folds$at(s)), 2))))
            set_at(self$growth, c, r_add(elem(self$growth, c), r_div(r_mul(w, t$doing$space$at(s)), 2)))
            set_at(self$gone, c, r_add(elem(self$gone, c), r_div(r_mul(w, m_abs(t$doing$folds$at(s))), 2)))
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
        }
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  getter(cl, "meet", function() {
    if (truthy(self$local_rays)) {
      return(self$meet_local)
    }
    if (truthy(self$apart)) {
      return(self$meet_gathered)
    }
    cells <- self$cells
    P <- self$planes
    .r <- for_range(cells, function(c) {
      x <- self$column_of(c)
      y <- self$row_of(c)
      s <- self$symbols(elem(self$rho_was, c), elem(self$nf_was, c))
      .r <- for_range(r_sub(P, 1), function(i) {
        z <- r_add(i, 1)
        ours <- self$sent_to(z, x, y)
        if (truthy(gt(elem(ours, 0), 0))) {
          .r <- for_range(r_sub(P, 1), function(j) {
            yy <- r_add(j, 1)
            if (truthy((!eq(yy, z)))) {
              theirs <- self$sent_to(yy, x, y)
              if (truthy(gt(elem(theirs, 0), 0))) {
                over <- self$facing_share(elem(ours, 1), elem(ours, 2), elem(theirs, 1), elem(theirs, 2))
                if (truthy(gt(over, 0))) {
                  .r <- for_each(self$meets, function(t) {
                    w <- r_mul(r_mul(r_mul(self$share(t, s), self$activity(elem(ours, 0))), self$activity(elem(theirs, 0))), over)
                    set_at(self$fold, c, Fmt$max(0, r_add(elem(self$fold, c), r_div(r_mul(w, t$doing$folds$at(s)), 2))))
                    set_at(self$growth, c, r_add(elem(self$growth, c), r_div(r_mul(w, t$doing$space$at(s)), 2)))
                    set_at(self$gone, c, r_add(elem(self$gone, c), r_div(r_mul(w, m_abs(t$doing$folds$at(s))), 2)))
                    CONTINUE
                  })
                  if (!is.null(.r)) return(.r[[1]])
                }
              }
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
        }
        if (truthy(self$vacuum)) {
          theirs <- self$rho_inf
          .r <- for_each(self$meets, function(t) {
            w <- r_div(r_mul(r_mul(self$share(t, s), self$activity(elem(ours, 0))), self$activity(theirs)), self$DEG)
            set_at(self$fold, c, Fmt$max(0, r_add(elem(self$fold, c), r_div(r_mul(w, t$doing$folds$at(s)), 2))))
            set_at(self$growth, c, r_add(elem(self$growth, c), r_div(r_mul(w, t$doing$space$at(s)), 2)))
            set_at(self$gone, c, r_add(elem(self$gone, c), r_div(r_mul(w, m_abs(t$doing$folds$at(s))), 2)))
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  getter(cl, "unfold", function() {
    cells <- self$cells
    self$stand <- m_map(rng(cells), function(c = NULL, ...) {
      return(elem(self$nf_was, c))
      NULL
    })
    if (!truthy(self$lit)) {
      .r <- for_range(cells, function(c) {
        s <- self$symbols(elem(self$rho_was, c), elem(self$nf_was, c))
        .set(s, key_("n_f"), elem(self$nf_was, c))
        .r <- for_each(self$points, function(t) {
          back <- t$doing$folds$at(s)
          if (truthy((!eq(back, 0)))) {
            h <- r_mul(self$share(t, s), back)
            set_at(self$fold, c, Fmt$max(0, r_add(elem(self$fold, c), h)))
            set_at(self$stand, c, Fmt$max(0, r_add(elem(self$stand, c), h)))
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
    }
    NULL
  })
  getter(cl, "stream", function() {
    .r <- for_range(r_sub(self$planes, 1), function(i) {
      z <- r_add(i, 1)
      near <- self$face_of(self$body_of(z))
      was <- m_map(rng(self$rungs), function(r = NULL, ...) {
        return(elem(elem(self$beam, z), r))
        NULL
      })
      .r <- for_range(self$rungs, function(r) {
        here <- Fmt$max(near, r)
        back <- Fmt$max(near, r_sub(r, 1))
        set_at(elem(self$beam, z), r, (if (truthy(eq(r, 0))) 0 else r_mul(elem(was, r_sub(r, 1)), (r_pow((r_div(back, here)), r_sub(self$D, 1))))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  field(cl, "vac", function() filled(self$cells, self$aggregate$rho_inf))
  method(cl, "nets", function(rho = NULL, nf = NULL, ...) {
    s <- self$symbols(rho, nf)
    got <- 0
    .r <- for_each(self$points, function(t) {
      .w("got", r_add(got, r_mul(self$share(t, s), t$doing$rays$at(s))))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_each(self$singles, function(t) {
      .w("got", r_add(got, r_mul(r_mul(self$share(t, s), mem(s, key_("ρ"))), t$doing$rays$at(s))))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_each(self$meets, function(t) {
      .w("got", r_add(got, r_mul(r_mul(r_mul(self$share(t, s), mem(s, key_("ρ"))), mem(s, key_("ρ"))), t$doing$rays$at(s))))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(got)
    NULL
  })
  getter(cl, "settle_rho", function() {
    if (truthy((!truthy(self$vacuum)))) {
      return(NULL)
    }
    .r <- for_range(self$cells, function(c) {
      mine <- r_sub(elem(self$rho_was, c), elem(self$vac, c))
      theirs <- (if (truthy(lt(mine, 0))) 0 else mine)
      nf <- elem(self$nf_was, c)
      lo <- 0
      hi <- 1
      .r <- for_range(24, function(i) {
        mid <- r_div((r_add(lo, hi)), 2)
        both <- r_add(mid, theirs)
        if (truthy(gt(self$nets((if (truthy(gt(both, 1))) 1 else both), nf), 0))) {
          .w("lo", mid)
        } else {
          .w("hi", mid)
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      set_at(self$vac, c, r_div((r_add(lo, hi)), 2))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  getter(cl, "make", function() {
    cells <- self$cells
    .r <- for_range(cells, function(c) {
