      .r <- for_each(self$points, function(t) {
        set_at(self$growth, c, r_add(elem(self$growth, c), r_mul(self$share(t, s), t$doing$space$at(s))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .r <- for_each(self$singles, function(t) {
        set_at(self$growth, c, r_add(elem(self$growth, c), r_mul(r_mul(self$share(t, s), elem(self$rho_was, c)), t$doing$space$at(s))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
