  getter(cl, "shine", function() {
    .r <- for_each(self$holes, function(h) {
      z <- self$plane_of(h)
      set_at(elem(self$beam, z), 0, r_add(elem(elem(self$beam, z), 0), self$per_way(h)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_range(self$planes, function(z) {
      .r <- for_range(self$rungs, function(r) {
        set_at(elem(self$beam, z), r, Fmt$min(1, elem(elem(self$beam, z), r)))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
