  method(cl, "recur_at", function(x = NULL, y = NULL, gn = NULL, ...) {
    if (truthy((if (truthy(.x <- (!eq(self$own, 2)))) .x else (!truthy((gt(gn, 0))))))) {
      return(1)
    }
    a0 <- self$a0_at_place(x, y)
    if (truthy((!truthy((gt(a0, 0)))))) {
      return(1)
    }
    gx <- self$tap(self$lean_x, 0, x, y, 0)
    gy <- self$tap(self$lean_y, 0, x, y, 0)
    was <- Fmt$hypot(gx, gy)
    return(r_div(r_pow((r_mul(gn, (r_add(was, a0)))), 0.5), gn))
    NULL
  })
  field(cl, "crowd", function() TRUE)
  method(cl, "pull_at", function(x = NULL, y = NULL, zown = NULL, vx = NULL, vy = NULL, ...) {
    held <- (if (truthy(self$local_rays)) self$pull_local(x, y, zown) else lst(0, 0))
    if (truthy(self$local_rays)) {
      return(self$recurred(x, y, held))
    }
    half <- r_div(r_sub(self$K, 1), 2)
    gx <- 0
    gy <- 0
    .r <- for_range(self$K, function(dy) {
      .r <- for_range(self$K, function(dx) {
        px <- r_add(r_sub(x, half), dx)
        py <- r_add(r_sub(y, half), dy)
        s <- self$symbols(self$tap(self$rho_was, 0, px, py, 0), self$tap(self$nf_was, 0, px, py, 0))
        rate <- 0
        .r <- for_each(self$meets, function(t) {
          .w("rate", r_add(rate, r_div(r_mul(self$share(t, s), t$doing$folds$at(s)), 2)))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        stood <- self$tap(self$stand, 0, px, py, 0)
        .r <- for_range(r_sub(self$planes, 1), function(i) {
          z <- r_add(i, 1)
          if (!truthy(eq(z, zown))) {
            came <- self$sent_to(z, px, py)
            share <- r_div(r_mul(rate, self$activity(elem(came, 0))), ((if (truthy(self$crowd)) r_add(1, stood) else 1)))
            .w("gx", r_sub(gx, r_mul(share, elem(came, 1))))
            .w("gy", r_sub(gy, r_mul(share, elem(came, 2))))
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(self$recurred(x, y, lst(gx, gy)))
    NULL
  })
  field(cl, "cell_pull", function() TRUE)
  method(cl, "own_gathering", function(h = NULL, ...) {
    if (truthy((if (truthy(.x <- (if (truthy(.x <- eq(h, NULL))) .x else (!truthy(self$cell_pull))))) .x else (!eq(len(self$shone), self$cells))))) {
      return(NULL)
    }
    c <- self$at(m_round(h$x), m_round(h$y))
    if (truthy(lt(c, 0))) {
      return(NULL)
    }
    e <- elem(self$shone, c)
    if (truthy(eq(e, NULL))) {
      return(NULL)
    }
    return((if (truthy((if (truthy(.x <- eq(elem(e, 6), r_sub(neg(2), c)))) gt(elem(e, 0), 0) else .x))) e else NULL))
    NULL
  })
  method(cl, "recurred", function(x = NULL, y = NULL, g = NULL, ...) {
    n <- r_mul(self$K, self$K)
    f <- self$recur_at(x, y, Fmt$hypot(r_div(elem(g, 0), n), r_div(elem(g, 1), n)))
    return(lst(r_mul(r_div(elem(g, 0), n), f), r_mul(r_div(elem(g, 1), n), f)))
    NULL
  })
  method(cl, "per_at", function(px = NULL, py = NULL, ...) {
    s <- self$symbols(self$tap(self$rho_was, 0, px, py, 0), self$tap(self$nf_was, 0, px, py, 0))
    rate <- 0
    .r <- for_each(self$meets, function(t) {
      .w("rate", r_add(rate, r_div(r_mul(self$share(t, s), t$doing$folds$at(s)), 2)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(r_div(rate, ((if (truthy(self$crowd)) r_add(1, self$tap(self$stand, 0, px, py, 0)) else 1))))
    NULL
  })
  method(cl, "pull_local", function(x = NULL, y = NULL, zown = NULL, ...) {
    half <- r_div(r_sub(self$K, 1), 2)
    whole <- self$own_gathering((if (truthy((if (truthy(.x <- ge(zown, 1))) le(zown, len(self$holes)) else .x))) elem(self$holes, r_sub(zown, 1)) else NULL))
    cx <- (if (truthy(eq(whole, NULL))) x else r_div(elem(whole, 1), elem(whole, 0)))
    cy <- (if (truthy(eq(whole, NULL))) y else r_div(elem(whole, 2), elem(whole, 0)))
    gx <- 0
    gy <- 0
    .r <- for_range(self$K, function(dy) {
      .r <- for_range(self$K, function(dx) {
        px <- r_add(r_sub(cx, half), dx)
        py <- r_add(r_sub(cy, half), dy)
        per <- self$per_at(px, py)
        came <- self$arriving_at(px, py, zown)
        .w("gx", r_sub(gx, r_mul(per, elem(came, 1))))
        .w("gy", r_sub(gy, r_mul(per, elem(came, 2))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(lst(gx, gy))
    NULL
  })
  getter(cl, "lean", function() {
    .r <- for_range(self$cells, function(c) {
      own <- (if (truthy(gt(elem(self$blocks, c), 0))) self$plane_of(elem(self$holes, r_sub(elem(self$blocks, c), 1))) else 0)
      g <- self$pull_at(self$column_of(c), self$row_of(c), own, 0, 0)
      set_at(self$lean_x, c, elem(g, 0))
      set_at(self$lean_y, c, elem(g, 1))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  field(cl, "swept", function() m_map(rng(self$planes), function(z = NULL, ...) {
