  getter(cl, "tick", function() {
    if (truthy(self$local_rays)) {
      self$stream_local
      self$shine_local
    } else {
      self$stream
      self$shine
    }
    self$open
    self$meet
    self$unfold
    self$make
    self$settle_rho
