  method(cl, "lean_under", function(h = NULL, ...) {
    return(self$pull_at(h$x, h$y, self$plane_of(h), r_div(elem(h$momentum$components, 0), h$mass), r_div(elem(h$momentum$components, 1), h$mass)))
    NULL
