  getter(cl, "seed", function() {
    if (truthy(self$local_rays)) {
      return(self$seed_local)
    }
    .r <- for_range(self$planes, function(z) {
      .r <- for_range(self$rungs, function(r) {
        set_at(elem(self$beam, z), r, 0)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_each(self$holes, function(h) {
      z <- self$plane_of(h)
      per <- self$per_way(h)
      near <- self$face_of(h)
      .r <- for_range(self$rungs, function(r) {
        here <- Fmt$max(near, r)
        set_at(elem(self$beam, z), r, Fmt$min(1, r_add(elem(elem(self$beam, z), r), r_mul(per, (r_pow((r_div(near, here)), r_sub(self$D, 1)))))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  getter(cl, "settle", function() {
    self$seed
    before <- 0
    done <- FALSE
    .r <- for_range(r_mul(4, self$crossing), function(i) {
      if (!truthy(done)) {
        self$tick
        if (truthy(eq(r_mod(self$ticks, 2), 0))) {
          now <- 0
          .r <- for_each(self$holes, function(h) {
            g <- self$lean_under(h)
            .w("now", r_add(now, Fmt$hypot(elem(g, 0), elem(g, 1))))
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          if (truthy((if (truthy(.x <- (if (truthy(.x <- gt(i, 2))) gt(now, 0) else .x))) lt(m_abs((r_sub(now, before))), r_div(now, 1000)) else .x))) {
            .w("done", TRUE)
          }
          .w("before", now)
        }
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
