  method(cl, "thrown", function(x = NULL, y = NULL, mx = NULL, ways = NULL, px = NULL, py = NULL, tag = NULL, ...) {
    h <- Hole$new(x = x, y = y, mx = mx, ways = ways)
    .set(h, "px", px)
    .set(h, "py", py)
    .set(h, "tag", tag)
    .set(h, "moves", TRUE)
    self$add(h)
    return(self)
    NULL
  })
})

