Cached <- ray_class("Cached", Played, function(cl) {
  field(cl, "film", NULL)
  field(cl, "names", NULL)
  field(cl, "sizes", NULL)
  method(cl, "at", function(frame_at = NULL, ...) {
    out <- Node$new()
    all <- mem(self$film$columns, key_("frames"))
    width <- m_sum(self$sizes)
    from_at <- r_mul(frame_at, width)
    .r <- for_range(len(self$names), function(i) {
      set_at(out, elem(self$names, i), m_take(m_drop(all, from_at), elem(self$sizes, i)))
      .w("from_at", r_add(from_at, elem(self$sizes, i)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
})

Live <- ray_class("Live", Played, function(cl) {
  field(cl, "recording", NULL)
  field(cl, "buf", function() Node$new())
  field(cl, "v_next", function() 0)
  field(cl, "started", function() FALSE)
  method(cl, "at", function(frame_at = NULL, ...) {
    if (!truthy(self$started)) {
      .r <- for_range(len(self$recording$names), function(i) {
        set_at(self$buf, elem(self$recording$names, i), filled(elem(self$recording$sizes, i), 0))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      self$recording$start
      self$started <- TRUE
    }
    if (truthy(lt(frame_at, r_sub(self$v_next, 1)))) {
      (fail)("frame " %+% text_of(frame_at) %+% " was asked for after " %+% text_of(r_sub(self$v_next, 1)) %+% ", and a world that is being run cannot go back - record it first")
    }
    while (truthy(le(self$v_next, frame_at))) {
      self$recording$frame(self$buf)
      self$v_next <- r_add(self$v_next, 1)
    }
    return(self$buf)
    NULL
  })
})

