  field(cl, "paint", NULL)
  getter(cl, "played", function() {
    r <- self$record
    if (truthy(eq(r, NULL))) {
      return(NULL)
    }
    film <- Measured$of("" %+% text_of(self$id) %+% ".frames")
    if (truthy((if (truthy(.x <- (if (truthy(.x <- (!eq(film, NULL)))) eq(mem(film$header, key_("stamp")), r$stamp) else .x))) eq(film$rows, r_mul(r$width, self$frames)) else .x))) {
      return(Cached$new(cached = TRUE, film = film, names = r$names, sizes = r$sizes))
    }
    return(Live$new(cached = FALSE, recording = r))
    NULL
  })
  getter(cl, "painter", function() {
    return(self$paint(self$played))
    NULL
  })
  statik(cl, "still", function(id = NULL, what = NULL, width = NULL, height = NULL, paints = NULL, ...) {
    return(Picture$new(id = id, what = what, width = width, height = height, frames = 1, paint = function(played = NULL, ...) {
