      NULL
    }))
    NULL
  })
})

Fmt <- ray_class("Fmt", Node, function(cl) {
  statik(cl, "log10", function(x = NULL, ...) {
    return(r_div(m_ln(x), m_ln(10)))
    NULL
  })
  statik(cl, "finite", function(x = NULL, ...) {
    return((if (truthy(.x <- eq(x, x))) lt(m_abs(x), r_pow(10, 300)) else .x))
    NULL
  })
  statik(cl, "fixed", function(x = NULL, d = NULL, ...) {
    if (truthy((!eq(x, x)))) {
      return("NaN")
    }
    scale <- r_pow(10, d)
    r <- m_round((r_mul(m_abs(x), scale)))
    whole <- m_floor((r_div(r, scale)))
    frac <- r_sub(r, r_mul(whole, scale))
    sign <- (if (truthy((if (truthy(.x <- lt(x, 0))) gt(r, 0) else .x))) "-" else "")
    if (truthy(eq(d, 0))) {
      return("" %+% text_of(sign) %+% "" %+% text_of(whole) %+% "")
    }
    digits <- "" %+% text_of(frac) %+% ""
    while (truthy(lt(len(digits), d))) {
      .w("digits", "0" %+% text_of(digits) %+% "")
    }
    return("" %+% text_of(sign) %+% "" %+% text_of(whole) %+% "." %+% text_of(digits) %+% "")
    NULL
  })
  statik(cl, "exponential", function(x = NULL, d = NULL, ...) {
    if (truthy((!eq(x, x)))) {
      return("NaN")
    }
    zeros <- "0"$v_repeat(d)
    if (truthy(eq(x, 0))) {
      return((if (truthy(gt(d, 0))) "0." %+% text_of(zeros) %+% "e+0" else "0e+0"))
    }
    e <- m_floor(Fmt$log10(m_abs(x)))
    m <- r_div(m_abs(x), r_pow(10, e))
    if (truthy(ge(m_round((r_mul(m, r_pow(10, d)))), r_pow(10, (r_add(d, 1)))))) {
      .w("m", r_div(m, 10))
      .w("e", r_add(e, 1))
    }
    if (truthy(lt(m, 1))) {
      .w("m", r_mul(m, 10))
      .w("e", r_sub(e, 1))
    }
    sign <- (if (truthy(lt(x, 0))) "-" else "")
    mant <- Fmt$fixed(m, d)
    return((if (truthy(ge(e, 0))) "" %+% text_of(sign) %+% "" %+% text_of(mant) %+% "e+" %+% text_of(e) %+% "" else "" %+% text_of(sign) %+% "" %+% text_of(mant) %+% "e-" %+% text_of(m_abs(e)) %+% ""))
    NULL
  })
  statik(cl, "min", function(p = NULL, q = NULL, ...) {
    return((if (truthy(lt(p, q))) p else q))
    NULL
  })
  statik(cl, "max", function(p = NULL, q = NULL, ...) {
    return((if (truthy(gt(p, q))) p else q))
    NULL
  })
  statik(cl, "hypot", function(x = NULL, y = NULL, ...) {
    return(m_sqrt((r_add(r_mul(x, x), r_mul(y, y)))))
    NULL
  })
  statik(cl, "median", function(xs_ = NULL, ...) {
    if (truthy(m_empty(xs_))) {
      return(NaN)
    }
    s <- Expr$sorted(xs_)
    return(elem(s, m_floor((r_div(len(s), 2)))))
    NULL
  })
})

