Setup <- ray_class("Setup", Node, function(cl) {
  field(cl, "id", NULL)
  field(cl, "what", NULL)
  field(cl, "width", NULL)
  field(cl, "height", NULL)
  field(cl, "theory", NULL)
  field(cl, "DEG", function() self$theory$lattice$DEG)
  field(cl, "D", function() self$theory$lattice$D)
  field(cl, "VIEW", function() 20)
  field(cl, "MARGIN", function() 8)
  field(cl, "A", function() 96)
  field(cl, "K", function() 3)
  field(cl, "PIX", function() 3)
  field(cl, "GAP", function() 20)
  field(cl, "bodies", function() 2)
  field(cl, "TICKS", function() 2)
  field(cl, "RUN", function() 150)
  field(cl, "BURN", function() 0)
  field(cl, "RANGE", function() "instant")
  field(cl, "tags", function() 2)
  field(cl, "stamp", function() "")
  field(cl, "colours", function() lst())
  field(cl, "probe", function() NULL)
  field(cl, "leans", function() lst())
  field(cl, "trial", function() NULL)
  field(cl, "orbits", function() lst())
  field(cl, "orbits", function() lst())
  field(cl, "found", function() lst())
  field(cl, "place", NULL)
  field(cl, "spent", function() NULL)
  field(cl, "view", NULL)
  field(cl, "ring", function() NULL)
  getter(cl, "side", function() {
    return(r_add(r_mul(r_mul(2, (r_add(self$VIEW, self$MARGIN))), self$K), 1))
    NULL
  })
  getter(cl, "centre", function() {
    return(r_div((r_sub(self$side, 1)), 2))
    NULL
  })
  getter(cl, "reach", function() {
    return(r_mul(self$VIEW, self$PIX))
    NULL
  })
  getter(cl, "box_side", function() {
    return(r_add(r_mul(2, self$reach), 1))
    NULL
  })
  method(cl, "box", function(x = NULL, y = NULL, ...) {
    return(r_add(r_mul((r_add(y, self$reach)), self$box_side), (r_add(x, self$reach))))
    NULL
  })
  getter(cl, "coarse_side", function() {
    return(r_add(r_mul(2, self$VIEW), 1))
    NULL
  })
  method(cl, "coarse", function(x = NULL, y = NULL, ...) {
    cx <- r_add(m_round((r_div(x, self$PIX))), self$VIEW)
    cy <- r_add(m_round((r_div(y, self$PIX))), self$VIEW)
    if (truthy(lt(cx, 0))) {
      .w("cx", 0)
    }
    if (truthy(lt(cy, 0))) {
      .w("cy", 0)
    }
    if (truthy(gt(cx, r_sub(self$coarse_side, 1)))) {
      .w("cx", r_sub(self$coarse_side, 1))
    }
    if (truthy(gt(cy, r_sub(self$coarse_side, 1)))) {
      .w("cy", r_sub(self$coarse_side, 1))
    }
    return(r_add(r_mul(cy, self$coarse_side), cx))
    NULL
  })
  statik(cl, "middle", function(holes = NULL, ...) {
    m <- 0
    x <- 0
    y <- 0
    .r <- for_each(holes, function(h) {
      .w("m", r_add(m, h$mass))
      .w("x", r_add(x, r_mul(h$x, h$mass)))
      .w("y", r_add(y, r_mul(h$y, h$mass)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return((if (truthy(gt(m, 0))) lst(r_div(x, m), r_div(y, m)) else lst(0, 0)))
    NULL
  })
  statik(cl, "rest_of", function(holes = NULL, k = NULL, ...) {
    held <- FALSE
    .r <- for_range(len(holes), function(i) {
      if (truthy((if (truthy(.x <- (!eq(i, k)))) (!truthy(elem(holes, i)$moves)) else .x))) {
        .w("held", TRUE)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    m <- 0
    x <- 0
    y <- 0
    .r <- for_range(len(holes), function(i) {
      if (truthy((if (truthy(.x <- (!eq(i, k)))) ((if (truthy(.x <- (!truthy(held)))) .x else (!truthy(elem(holes, i)$moves)))) else .x))) {
        .w("m", r_add(m, elem(holes, i)$mass))
        .w("x", r_add(x, r_mul(elem(holes, i)$x, elem(holes, i)$mass)))
        .w("y", r_add(y, r_mul(elem(holes, i)$y, elem(holes, i)$mass)))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return((if (truthy(gt(m, 0))) lst(m, r_div(x, m), r_div(y, m)) else lst(0, 0, 0)))
    NULL
  })
  statik(cl, "work", function(pulls = NULL, ...) {
    got <- 0
    .r <- for_range(r_sub(len(pulls), 1), function(i) {
      dr <- r_sub(elem(elem(pulls, r_add(i, 1)), 0), elem(elem(pulls, i), 0))
      .w("got", r_add(got, r_mul(r_div((r_add(elem(elem(pulls, i), 1), elem(elem(pulls, r_add(i, 1)), 1))), 2), dr)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(got)
    NULL
  })
  statik(cl, "where_between", function(h = NULL, rest = NULL, e = NULL, K = NULL, steps = NULL, ...) {
    dx <- r_sub(elem(rest, 1), h$x)
    dy <- r_sub(elem(rest, 2), h$y)
    far <- r_div(Fmt$hypot(dx, dy), K)
    if (truthy(le(far, 0))) {
      return(lst())
    }
    near <- r_div(r_mul(far, (r_sub(1, e))), (r_add(1, e)))
    ux <- r_sub(0, r_div(dx, (r_mul(far, K))))
    uy <- r_sub(0, r_div(dy, (r_mul(far, K))))
    return(m_map(rng(r_add(steps, 1)), function(i = NULL, ...) {
      d <- r_add(near, r_div(r_mul((r_sub(far, near)), i), steps))
      return(lst(d, r_add(elem(rest, 1), r_mul(r_mul(ux, d), K)), r_add(elem(rest, 2), r_mul(r_mul(uy, d), K))))
      NULL
    }))
    NULL
  })
  statik(cl, "pulls_between", function(w = NULL, h = NULL, rest = NULL, e = NULL, K = NULL, steps = NULL, ...) {
    zown <- w$plane_of(h)
    return(m_map(Setup$where_between(h, rest, e, K, steps), function(at = NULL, ...) {
      return(lst(elem(at, 0), w$pull_toward(elem(at, 1), elem(at, 2), elem(rest, 1), elem(rest, 2), zown)))
      NULL
    }))
    NULL
  })
  statik(cl, "pull_at_r", function(pulls = NULL, r = NULL, ...) {
    n <- len(pulls)
    if (truthy(eq(n, 0))) {
      return(0)
    }
    if (truthy(le(r, elem(elem(pulls, 0), 0)))) {
      return(elem(elem(pulls, 0), 1))
    }
    if (truthy(ge(r, elem(elem(pulls, r_sub(n, 1)), 0)))) {
      return(elem(elem(pulls, r_sub(n, 1)), 1))
    }
    got <- elem(elem(pulls, r_sub(n, 1)), 1)
    found <- FALSE
    .r <- for_range(r_sub(n, 1), function(i) {
      if (!truthy(found)) {
        if (truthy((if (truthy(.x <- le(elem(elem(pulls, i), 0), r))) le(r, elem(elem(pulls, r_add(i, 1)), 0)) else .x))) {
          span <- r_sub(elem(elem(pulls, r_add(i, 1)), 0), elem(elem(pulls, i), 0))
          f <- (if (truthy(gt(span, 0))) r_div((r_sub(r, elem(elem(pulls, i), 0))), span) else 0)
          .w("got", r_add(r_mul(elem(elem(pulls, i), 1), (r_sub(1, f))), r_mul(elem(elem(pulls, r_add(i, 1)), 1), f)))
          .w("found", TRUE)
        }
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(got)
    NULL
  })
  statik(cl, "nearest", function(pulls = NULL, v = NULL, far = NULL, near = NULL, both = NULL, kappa = NULL, ticks = NULL, ...) {
    x <- far
    y <- 0
    vx <- 0
    vy <- v
    best <- far
    done <- FALSE
    .r <- for_range(ticks, function(i) {
      if (!truthy(done)) {
        r <- Fmt$hypot(x, y)
        .w("best", Fmt$min(best, r))
        if (truthy((if (truthy(.x <- lt(best, far))) gt(r, r_mul(best, 1.02)) else .x))) {
          .w("done", TRUE)
        }
        if (truthy(lt(r, r_div(near, 2)))) {
          .w("done", TRUE)
        }
        if (truthy(gt(r, r_mul(far, 1.05)))) {
          .w("done", TRUE)
        }
        less <- r_sub(1, r_mul(kappa, Fmt$hypot(vx, vy)))
        g <- r_mul(r_mul(Setup$pull_at_r(pulls, r), both), ((if (truthy(gt(less, 0))) less else 0)))
        if (truthy(gt(r, 0))) {
          .w("vx", r_sub(vx, r_div(r_mul(g, x), r)))
          .w("vy", r_sub(vy, r_div(r_mul(g, y), r)))
        }
        .w("x", r_add(x, vx))
        .w("y", r_add(y, vy))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(best)
    NULL
  })
  statik(cl, "thrown", function(pulls = NULL, far = NULL, near = NULL, both = NULL, kappa = NULL, guess = NULL, ...) {
    if (truthy((!truthy(((if (truthy(.x <- (if (truthy(.x <- gt(guess, 0))) gt(far, 0) else .x))) gt(near, 0) else .x)))))) {
      return(guess)
    }
    lo <- 0
    hi <- r_mul(guess, 2)
    .r <- for_range(40, function(i) {
      mid <- r_div((r_add(lo, hi)), 2)
      turn <- m_round((r_div(r_mul(r_mul(8, pi), far), ((if (truthy(gt(mid, 0))) mid else 1)))))
      ticks <- (if (truthy(gt(turn, 400000))) 400000 else ((if (truthy(lt(turn, 16))) 16 else turn)))
      if (truthy(lt(Setup$nearest(pulls, mid, far, near, both, kappa, ticks), near))) {
        .w("lo", mid)
      } else {
        .w("hi", mid)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(r_div((r_add(lo, hi)), 2))
    NULL
  })
  statik(cl, "slower", function(rest_far = NULL, moving_far = NULL, v = NULL, ...) {
    if (truthy((!truthy(((if (truthy(.x <- gt(rest_far, 0))) gt(v, 0) else .x)))))) {
      return(0)
    }
    return(r_div((r_sub(rest_far, moving_far)), (r_mul(rest_far, v))))
    NULL
  })
  statik(cl, "orbit", function(h = NULL, rest = NULL, pulls = NULL, e = NULL, px = NULL, py = NULL, K = NULL, kappa = NULL, ...) {
    dx <- r_sub(elem(rest, 1), h$x)
    dy <- r_sub(elem(rest, 2), h$y)
    far <- r_div(Fmt$hypot(dx, dy), K)
    if (truthy((if (truthy(.x <- (if (truthy(.x <- le(far, 0))) .x else lt(len(pulls), 2)))) .x else le(elem(rest, 0), 0)))) {
      return(lst(px, py))
    }
    near <- r_div(r_mul(far, (r_sub(1, e))), (r_add(1, e)))
    both <- r_div((r_add(h$mass, elem(rest, 0))), elem(rest, 0))
    w <- r_mul(Setup$work(pulls), both)
    ratio <- r_mul((r_div(far, near)), (r_div(far, near)))
    circle <- r_mul(r_mul(elem(elem(pulls, r_sub(len(pulls), 1)), 1), both), far)
    between <- (if (truthy(gt(ratio, 1.000001))) ((if (truthy(gt(w, 0))) m_sqrt((r_div(r_mul(2, w), (r_sub(ratio, 1))))) else 0)) else ((if (truthy(gt(circle, 0))) m_sqrt(circle) else 0)))
    run <- Setup$thrown(pulls, far, near, both, kappa, between)
    speed <- r_div(r_mul(run, elem(rest, 0)), (r_add(h$mass, elem(rest, 0))))
    tx <- r_sub(0, r_div(dy, (r_mul(far, K))))
    ty <- r_div(dx, (r_mul(far, K)))
    way <- (if (truthy(lt(r_add(r_mul(tx, px), r_mul(ty, py)), 0))) r_sub(0, 1) else 1)
    return(lst(r_mul(r_mul(r_mul(way, tx), speed), h$mass), r_mul(r_mul(r_mul(way, ty), speed), h$mass)))
    NULL
  })
})

Body <- ray_class("Body", Node, function(cl) {
  field(cl, "x", NULL)
  field(cl, "y", NULL)
  field(cl, "mx", NULL)
  field(cl, "ways", NULL)
  field(cl, "px", function() 0)
  field(cl, "py", function() 0)
  field(cl, "moves", function() FALSE)
  field(cl, "tag", function() 0)
  field(cl, "launch", function() "given")
  field(cl, "ecc", function() 0)
})

FieldRecording <- ray_class("FieldRecording", Recording, function(cl) {
  field(cl, "p", NULL)
  field(cl, "W", function() NULL)
  field(cl, "gone", function() filled(r_mul(self$p$side, self$p$side), 0))
  field(cl, "lx", function() filled(r_mul(self$p$side, self$p$side), 0))
  field(cl, "ly", function() filled(r_mul(self$p$side, self$p$side), 0))
  field(cl, "beat", function() filled(r_mul(self$p$side, self$p$side), 0))
  field(cl, "beat2", function() filled(r_mul(self$p$side, self$p$side), 0))
  field(cl, "per_tag", function() m_map(rng((if (truthy(gt(self$p$tags, 2))) r_sub(self$p$tags, 2) else 1)), function(z = NULL, ...) {
    return(filled(r_mul(self$p$side, self$p$side), 0))
    NULL
  }))
  field(cl, "spanned", function() 0)
  getter(cl, "lay", function() {
    p <- self$p
    w <- p$theory$medium(p$side, p$A, p$K, p$DEG, p$tags, p$D)
    placed <- p$place(p)
    .r <- for_each(placed, function(b) {
      h <- Hole$new(x = r_add(p$centre, r_mul(b$x, p$K)), y = r_add(p$centre, r_mul(b$y, p$K)), mx = b$mx, ways = b$ways)
      .set(h, "tag", b$tag)
      .set(h, "moves", FALSE)
      w$add(h)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    if (truthy(eq(p$RANGE, "instant"))) {
      w$settle
    } else {
      .r <- for_range(p$BURN, function(i) {
        w$tick
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
    }
    if (truthy(m_some(placed, function(b = NULL, ...) {
      return(eq(b$launch, "orbit"))
      NULL
    }))) {
      w$tick
    }
    .r <- for_range(len(placed), function(k) {
      .set(elem(w$holes, k), "moves", elem(placed, k)$moves)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    reads <- m_map(rng(len(placed)), function(k = NULL, ...) {
      return((if (truthy(eq(elem(placed, k)$launch, "orbit"))) Setup$pulls_between(w, elem(w$holes, k), Setup$rest_of(w$holes, k), elem(placed, k)$ecc, p$K, 64) else lst()))
      NULL
    })
    .r <- for_range(len(placed), function(k) {
      h <- elem(w$holes, k)
      b <- elem(placed, k)
      v <- (if (truthy(eq(b$launch, "orbit"))) Setup$orbit(h, Setup$rest_of(w$holes, k), elem(reads, k), b$ecc, b$px, b$py, p$K, 0) else lst(b$px, b$py))
      .set(h, "px", elem(v, 0))
      .set(h, "py", elem(v, 1))
      .set(h, "momentum", Vector$new(components = lst(elem(v, 0), elem(v, 1))))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    w$seed
    .r <- for_range(len(placed), function(k) {
      b <- elem(placed, k)
      if (truthy(eq(b$launch, "orbit"))) {
        h <- elem(w$holes, k)
        rest <- Setup$rest_of(w$holes, k)
        moving <- Setup$pulls_between(w, h, rest, b$ecc, p$K, 64)
        at <- r_sub(len(elem(reads, k)), 1)
        vrel <- r_div(r_mul(r_div(Fmt$hypot(h$px, h$py), h$mass), (r_add(h$mass, elem(rest, 0)))), elem(rest, 0))
        kappa <- Setup$slower(elem(elem(elem(reads, k), at), 1), elem(elem(moving, at), 1), vrel)
        v <- Setup$orbit(h, rest, elem(reads, k), b$ecc, b$px, b$py, p$K, kappa)
        .set(h, "px", elem(v, 0))
        .set(h, "py", elem(v, 1))
        .set(h, "momentum", Vector$new(components = lst(elem(v, 0), elem(v, 1))))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    self$W <- w
    NULL
  })
  getter(cl, "start", function() {
    return(self$lay)
    NULL
  })
  getter(cl, "begin_frame", function() {
    cells <- r_mul(self$p$side, self$p$side)
    .r <- for_range(cells, function(c) {
      set_at(self$gone, c, 0)
      set_at(self$lx, c, 0)
      set_at(self$ly, c, 0)
      set_at(self$beat, c, 0)
      set_at(self$beat2, c, 0)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_each(self$per_tag, function(e) {
      .r <- for_range(cells, function(c) {
        set_at(e, c, 0)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    self$spanned <- 0
    NULL
  })
  method(cl, "take", function(w = NULL, ...) {
    p <- self$p
    cells <- r_mul(p$side, p$side)
    .r <- for_range(cells, function(c) {
      set_at(self$gone, c, r_add(elem(self$gone, c), w$crossed(c)))
      set_at(self$lx, c, r_add(elem(self$lx, c), w$pull_x(c)))
      set_at(self$ly, c, r_add(elem(self$ly, c), w$pull_y(c)))
      set_at(self$beat, c, r_add(elem(self$beat, c), w$arrived(1, c)))
      .r <- for_range((if (truthy(gt(p$tags, 2))) r_sub(p$tags, 2) else 1), function(k) {
        v <- w$arrived(r_add(k, 2), c)
        set_at(self$beat2, c, r_add(elem(self$beat2, c), v))
        set_at(elem(self$per_tag, k), c, r_add(elem(elem(self$per_tag, k), c), v))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    self$spanned <- r_add(self$spanned, 1)
    NULL
  })
  method(cl, "positions", function(w = NULL, ...) {
    return(m_map(w$holes, function(h = NULL, ...) {
      return(Body$new(x = r_div((r_sub(h$x, self$p$centre)), self$p$K), y = r_div((r_sub(h$y, self$p$centre)), self$p$K), mx = h$mx, ways = h$ways))
      NULL
    }))
    NULL
  })
  method(cl, "finish", function(into = NULL, w = NULL, ...) {
    p <- self$p
    level <- 0
    seen <- 0
    R <- p$reach
    step <- r_div(p$K, p$PIX)
    one <- mem(into, key_("one"))
    two <- mem(into, key_("two"))
    gone <- mem(into, key_("gone"))
    bys <- m_map(rng(len(self$per_tag)), function(k = NULL, ...) {
      return(mem(into, key_("by" %+% text_of(k) %+% "")))
      NULL
    })
    marks <- mem(into, key_("marks"))
    span <- (if (truthy(lt(self$spanned, 1))) 1 else self$spanned)
    .r <- for_range(r_add(r_mul(2, R), 1), function(yi) {
      y <- r_sub(yi, R)
      .r <- for_range(r_add(r_mul(2, R), 1), function(xi) {
        x <- r_sub(xi, R)
        c <- w$at(m_round((r_add(p$centre, r_mul(x, step)))), m_round((r_add(p$centre, r_mul(y, step)))))
        i <- p$box(x, y)
        if (truthy(lt(c, 0))) {
          set_at(one, i, 0)
          set_at(two, i, 0)
          set_at(gone, i, 0)
          .r <- for_range(len(bys), function(k) {
            if (truthy((if (truthy(.x <- (if (truthy(.x <- (!eq(elem(bys, k), NULL)))) eq(r_mod((r_add(x, R)), p$PIX), 0) else .x))) eq(r_mod((r_add(y, R)), p$PIX), 0) else .x))) {
              set_at(elem(bys, k), p$coarse(x, y), 0)
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
        } else {
          blocked <- gt(elem(w$blocks, c), 0)
          set_at(one, i, (if (truthy(blocked)) neg(1) else r_div(elem(self$beat, c), span)))
          set_at(two, i, (if (truthy(blocked)) neg(1) else r_div(elem(self$beat2, c), span)))
          .r <- for_range(len(bys), function(k) {
            if (truthy((if (truthy(.x <- (if (truthy(.x <- (!eq(elem(bys, k), NULL)))) eq(r_mod((r_add(x, R)), p$PIX), 0) else .x))) eq(r_mod((r_add(y, R)), p$PIX), 0) else .x))) {
              set_at(elem(bys, k), p$coarse(x, y), r_div(elem(elem(self$per_tag, k), c), span))
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          set_at(gone, i, elem(self$gone, c))
          if (!truthy(blocked)) {
            .w("level", r_add(level, elem(self$gone, c)))
            .w("seen", r_add(seen, 1))
          }
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    set_at(marks, r_mul(6, p$bodies), (if (truthy(gt(seen, 0))) r_div(level, seen) else 0))
    .r <- for_range(len(w$holes), function(k) {
      if (truthy(lt(k, p$bodies))) {
        b <- elem(w$holes, k)
        set_at(marks, r_mul(k, 6), r_div((r_sub(b$x, p$centre)), p$K))
        set_at(marks, r_add(r_mul(k, 6), 1), r_div((r_sub(b$y, p$centre)), p$K))
        set_at(marks, r_add(r_mul(k, 6), 2), b$px_now)
        set_at(marks, r_add(r_mul(k, 6), 3), b$py_now)
        set_at(marks, r_add(r_mul(k, 6), 4), w$t)
        set_at(marks, r_add(r_mul(k, 6), 5), b$mass)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  method(cl, "frame", function(into = NULL, ...) {
    p <- self$p
    self$begin_frame
    .r <- for_range(p$TICKS, function(i) {
      w <- self$W
      if (truthy((if (truthy(.x <- (!eq(p$spent, NULL)))) p$spent(self$positions(w)) else .x))) {
        self$lay
      } else {
        w$tick
        m_take(self, w)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(self$finish(into, self$W))
    NULL
  })
})

FieldPainter <- ray_class("FieldPainter", Painter, function(cl) {
  field(cl, "p", NULL)
  field(cl, "played", NULL)
  field(cl, "at_frame", function() 0)
  field(cl, "accumulated", function() filled(r_mul(self$p$box_side, self$p$box_side), 0))
  field(cl, "count", function() 0)
  field(cl, "trail", function() m_map(rng(self$p$bodies), function(k = NULL, ...) {
    return(lst())
    NULL
  }))
  method(cl, "frame", function(s = NULL, dt = NULL, ...) {
    ch <- (if (truthy(eq(self$played, NULL))) Node$new() else self$played$at(self$at_frame))
    if (truthy((!eq(mem(ch, key_("one")), NULL)))) {
      gone <- mem(ch, key_("gone"))
      .r <- for_range(len(self$accumulated), function(i) {
        set_at(self$accumulated, i, r_add(elem(self$accumulated, i), elem(gone, i)))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      self$count <- r_add(self$count, 1)
      marks <- mem(ch, key_("marks"))
      .r <- for_range(self$p$bodies, function(k) {
        m_push(elem(self$trail, k), elem(marks, r_mul(k, 6)))
        m_push(elem(self$trail, k), elem(marks, r_add(r_mul(k, 6), 1)))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      Panel$paint(self$p, s, ch, r_mul(self$at_frame, self$p$TICKS), self$accumulated, self$count, self$trail)
    }
    self$at_frame <- r_add(self$at_frame, 1)
    NULL
  })
})

Panel <- ray_class("Panel", Node, function(cl) {
  static_field(cl, "BACK", function() "#08090d")
  static_field(cl, "SEEN", function() "#eef0f5")
  static_field(cl, "ONE", function() "#4aa8eb")
  static_field(cl, "TWO", function() "#8bd48b")
  static_field(cl, "PAIR", function() "#eef0f5")
  statik(cl, "lg", function(v = NULL, floor = NULL, ...) {
    return((if (truthy(le(v, 0))) 0 else r_div(m_ln((r_add(1, r_div(v, floor)))), m_ln((r_add(1, r_div(1, floor)))))))
    NULL
  })
  statik(cl, "hex", function(c = NULL, at = NULL, ...) {
    hi <- Panel$digit(elem(m_chars(c), at))
    lo <- Panel$digit(elem(m_chars(c), r_add(at, 1)))
    return(r_add(r_mul(hi, 16), lo))
    NULL
  })
  statik(cl, "digit", function(c = NULL, ...) {
    return((if (truthy(ge(c, 97))) r_sub(c, 87) else ((if (truthy(ge(c, 65))) r_sub(c, 55) else r_sub(c, 48)))))
    NULL
  })
  statik(cl, "mix", function(a = NULL, b = NULL, f = NULL, ...) {
    r <- m_round((r_add(r_mul(Panel$hex(a, 1), (r_sub(1, f))), r_mul(Panel$hex(b, 1), f))))
    g <- m_round((r_add(r_mul(Panel$hex(a, 3), (r_sub(1, f))), r_mul(Panel$hex(b, 3), f))))
    bl <- m_round((r_add(r_mul(Panel$hex(a, 5), (r_sub(1, f))), r_mul(Panel$hex(b, 5), f))))
    return("rgb(" %+% text_of(r) %+% "," %+% text_of(g) %+% "," %+% text_of(bl) %+% ")")
    NULL
  })
  statik(cl, "blend", function(p = NULL, bys = NULL, i = NULL, ...) {
    r <- 0
    g <- 0
    b <- 0
    total <- 0
    .r <- for_range(len(bys), function(k) {
      w <- (if (truthy(eq(elem(bys, k), NULL))) 0 else Fmt$max(0, elem(elem(bys, k), i)))
      c <- or_else(elem(p$colours, k), Panel$TWO)
      .w("r", r_add(r, r_mul(w, Panel$hex(c, 1))))
      .w("g", r_add(g, r_mul(w, Panel$hex(c, 3))))
      .w("b", r_add(b, r_mul(w, Panel$hex(c, 5))))
      .w("total", r_add(total, w))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    if (truthy((!truthy((gt(total, 0)))))) {
      return(Panel$TWO)
    }
    return("#" %+% text_of(Panel$hex2(m_round((r_div(r, total))))) %+% "" %+% text_of(Panel$hex2(m_round((r_div(g, total))))) %+% "" %+% text_of(Panel$hex2(m_round((r_div(b, total))))) %+% "")
    NULL
  })
  statik(cl, "hex2", function(v = NULL, ...) {
    digits <- "0123456789abcdef"
    n <- (if (truthy(lt(v, 0))) 0 else ((if (truthy(gt(v, 255))) 255 else v)))
    hi <- m_floor((r_div(n, 16)))
    lo <- r_sub(n, r_mul(hi, 16))
    return("" %+% text_of(from_codepoints(lst(elem(m_chars(digits), hi)))) %+% "" %+% text_of(from_codepoints(lst(elem(m_chars(digits), lo)))) %+% "")
    NULL
  })
  statik(cl, "paint", function(p = NULL, s = NULL, ch = NULL, t = NULL, accumulated = NULL, count = NULL, trail = NULL, ...) {
    width <- s$width
    H <- s$height
    s$clear_rect(0, 0, width, H)
    s$fill_style(Panel$BACK)
    s$fill_rect(0, 0, width, H)
    TOP <- 14
    BOT <- 14
    GAP2 <- 10
    cw <- r_div((r_sub(width, GAP2)), 2)
    side <- Fmt$min(cw, r_sub(r_sub(H, TOP), BOT))
    view <- p$view(t)
    pz <- r_div(side, (r_add(r_mul(r_mul(2, view), p$PIX), 1)))
    top <- r_add(TOP, Fmt$max(0, r_div((r_sub(r_sub(r_sub(H, TOP), BOT), side)), 2)))
    one <- mem(ch, key_("one"))
    two <- mem(ch, key_("two"))
    bys <- m_map(rng((if (truthy(gt(p$tags, 2))) r_sub(p$tags, 2) else 1)), function(k = NULL, ...) {
      return(mem(ch, key_("by" %+% text_of(k) %+% "")))
      NULL
    })
    marks <- mem(ch, key_("marks"))
    peakA <- 0.000000000000000000000000000001
    peakB <- peakA
    peakG <- peakA
    R <- m_round((r_mul(view, p$PIX)))
    .r <- for_range(r_add(r_mul(2, R), 1), function(yi) {
      y <- r_sub(yi, R)
      .r <- for_range(r_add(r_mul(2, R), 1), function(xi) {
        x <- r_sub(xi, R)
        i <- p$box(x, y)
        if (!truthy(lt(elem(one, i), 0))) {
          .w("peakA", Fmt$max(peakA, elem(one, i)))
          .w("peakB", Fmt$max(peakB, elem(two, i)))
          .w("peakG", Fmt$max(peakG, r_div(elem(accumulated, i), count)))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    floorAB <- 0.0015
    .r <- for_range(r_add(r_mul(2, R), 1), function(yi) {
      y <- r_sub(yi, R)
      .r <- for_range(r_add(r_mul(2, R), 1), function(xi) {
        x <- r_sub(xi, R)
        i <- p$box(x, y)
        if (!truthy(lt(elem(one, i), 0))) {
          tot <- r_add(r_div(Fmt$max(0, elem(one, i)), peakA), r_div(Fmt$max(0, elem(two, i)), peakB))
          if (truthy(gt(tot, 0))) {
            .w("floorAB", Fmt$min(floorAB, tot))
          }
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    centre <- 0
    .r <- for_range(p$bodies, function(k) {
      if (truthy(gt(elem(marks, r_add(r_mul(k, 6), 5)), elem(marks, r_add(r_mul(centre, 6), 5))))) {
        .w("centre", k)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    weight <- 0
    .r <- for_range(p$bodies, function(k) {
      .w("weight", r_add(weight, elem(marks, r_add(r_mul(k, 6), 5))))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    frames <- r_div(len(elem(trail, centre)), 2)
    midx <- m_map(rng(frames), function(i = NULL, ...) {
      return(0)
      NULL
    })
    midy <- m_map(rng(frames), function(i = NULL, ...) {
      return(0)
      NULL
    })
    .r <- for_range(frames, function(i) {
      mx <- 0
      my <- 0
      .r <- for_range(p$bodies, function(k) {
        .w("mx", r_add(mx, r_mul(elem(marks, r_add(r_mul(k, 6), 5)), elem(elem(trail, k), r_mul(2, i)))))
        .w("my", r_add(my, r_mul(elem(marks, r_add(r_mul(k, 6), 5)), elem(elem(trail, k), r_add(r_mul(2, i), 1)))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      set_at(midx, i, (if (truthy(gt(weight, 0))) r_div(mx, weight) else 0))
      set_at(midy, i, (if (truthy(gt(weight, 0))) r_div(my, weight) else 0))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    biggest <- 0
    nears <- m_map(rng(p$bodies), function(k = NULL, ...) {
      return(0)
      NULL
    })
    fars <- m_map(rng(p$bodies), function(k = NULL, ...) {
      return(0)
      NULL
    })
    .r <- for_range(p$bodies, function(k) {
      near <- 0
      far <- 0
      .r <- for_range(frames, function(i) {
        d <- Fmt$hypot(r_sub(elem(elem(trail, k), r_mul(2, i)), elem(midx, i)), r_sub(elem(elem(trail, k), r_add(r_mul(2, i), 1)), elem(midy, i)))
        .w("near", (if (truthy(eq(i, 0))) d else Fmt$min(near, d)))
        .w("far", Fmt$max(far, d))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      set_at(nears, k, near)
      set_at(fars, k, far)
      .w("biggest", Fmt$max(biggest, far))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    goes <- m_map(rng(p$bodies), function(k = NULL, ...) {
      return((if (truthy(.x <- gt(elem(fars, k), r_div(biggest, 50)))) gt(elem(fars, k), r_add(elem(nears, k), 0.0001)) else .x))
      NULL
    })
    .r <- for_each(lst(0, 1), function(col) {
      cx <- (if (truthy(eq(col, 0))) r_div(cw, 2) else r_add(r_add(cw, GAP2), r_div(cw, 2)))
      cy <- r_add(top, r_div(side, 2))
      s$fill_style("#0b1119")
      s$fill_rect(r_sub(cx, r_div(side, 2)), r_sub(cy, r_div(side, 2)), side, side)
      .r <- for_range(r_add(r_mul(2, R), 1), function(yi) {
        y <- r_sub(yi, R)
        .r <- for_range(r_add(r_mul(2, R), 1), function(xi) {
          x <- r_sub(xi, R)
          i <- p$box(x, y)
          if (!truthy(lt(elem(one, i), 0))) {
            if (truthy(eq(col, 1))) {
              ink <- Panel$lg(r_div(Fmt$max(0, r_div(elem(accumulated, i), count)), peakG), 0.004)
              if (truthy(gt(ink, 0.015))) {
                s$alpha(Fmt$min(1, ink))
                s$fill_style(Panel$PAIR)
                s$fill_rect(r_sub(r_add(cx, r_mul(x, pz)), r_div(pz, 2)), r_sub(r_add(cy, r_mul(y, pz)), r_div(pz, 2)), r_add(pz, 0.6), r_add(pz, 0.6))
              }
            } else {
              a <- r_div(Fmt$max(0, elem(one, i)), peakA)
              b <- r_div(Fmt$max(0, elem(two, i)), peakB)
              tot <- r_add(a, b)
              if (truthy(gt(tot, 0))) {
                shade <- Panel$lg(tot, floorAB)
                if (truthy(gt(shade, 0.012))) {
                  f <- r_div(b, tot)
                  other <- (if (truthy(((if (truthy(.x <- m_empty(p$colours))) .x else eq(elem(bys, 0), NULL))))) Panel$TWO else Panel$blend(p, bys, p$coarse(x, y)))
                  s$alpha(Fmt$min(1, shade))
                  s$fill_style(Panel$mix(Panel$ONE, other, f))
                  s$fill_rect(r_sub(r_add(cx, r_mul(x, pz)), r_div(pz, 2)), r_sub(r_add(cy, r_mul(y, pz)), r_div(pz, 2)), r_add(pz, 0.6), r_add(pz, 0.6))
                }
              }
            }
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .r <- for_range(p$bodies, function(k) {
        n <- r_div(len(elem(trail, k)), 2)
        if (truthy((if (truthy(.x <- gt(n, 1))) elem(goes, k) else .x))) {
          colour <- (if (truthy(eq(p$ring, NULL))) Panel$SEEN else p$ring(k))
          s$stroke_style(colour)
          s$line_width(1)
          s$alpha(0.3)
          s$dash(lst(3, 4))
          s$begin_path
          s$arc(r_add(cx, r_mul(r_mul(elem(midx, r_sub(frames, 1)), p$PIX), pz)), r_add(cy, r_mul(r_mul(elem(midy, r_sub(frames, 1)), p$PIX), pz)), r_mul(r_mul(elem(fars, k), p$PIX), pz), 0, r_mul(2, pi))
          s$stroke
          if (truthy(gt(elem(nears, k), 0))) {
            s$begin_path
            s$arc(r_add(cx, r_mul(r_mul(elem(midx, r_sub(frames, 1)), p$PIX), pz)), r_add(cy, r_mul(r_mul(elem(midy, r_sub(frames, 1)), p$PIX), pz)), r_mul(r_mul(elem(nears, k), p$PIX), pz), 0, r_mul(2, pi))
            s$stroke
          }
          s$dash(lst())
          s$alpha(0.65)
          s$begin_path
          .r <- for_range(n, function(i) {
            px <- r_add(cx, r_mul(r_mul(elem(elem(trail, k), r_mul(2, i)), p$PIX), pz))
            py <- r_add(cy, r_mul(r_mul(elem(elem(trail, k), r_add(r_mul(2, i), 1)), p$PIX), pz))
            if (truthy(eq(i, 0))) {
              s$move_to(px, py)
            } else {
              s$line_to(px, py)
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          s$stroke
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      s$alpha(1)
      heaviest <- 0.000000000000000000000000000001
      .r <- for_range(p$bodies, function(k) {
        .w("heaviest", Fmt$max(heaviest, elem(marks, r_add(r_mul(k, 6), 5))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .r <- for_range(p$bodies, function(k) {
        bx <- r_mul(elem(marks, r_mul(k, 6)), p$PIX)
        by <- r_mul(elem(marks, r_add(r_mul(k, 6), 1)), p$PIX)
        heavy <- r_div(elem(marks, r_add(r_mul(k, 6), 5)), heaviest)
        r <- r_mul(r_mul(Fmt$max(1.6, r_mul(3.5, m_sqrt(heavy))), pz), p$PIX)
        s$stroke_style((if (truthy(eq(p$ring, NULL))) Panel$SEEN else p$ring(k)))
        s$line_width(1.1)
        s$begin_path
        s$arc(r_add(cx, r_mul(bx, pz)), r_add(cy, r_mul(by, pz)), r, 0, r_mul(2, pi))
        s$stroke
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  statik(cl, "of", function(p = NULL, ...) {
    BOX <- r_mul(p$box_side, p$box_side)
    names <- lst("one", "two", "gone")
    sizes <- lst(BOX, BOX, BOX)
    COARSE <- r_mul(p$coarse_side, p$coarse_side)
    if (!truthy(m_empty(p$colours))) {
      .r <- for_range((if (truthy(gt(p$tags, 2))) r_sub(p$tags, 2) else 1), function(k) {
        m_push(names, "by" %+% text_of(k) %+% "")
        m_push(sizes, COARSE)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
    }
    m_push(names, "marks")
    m_push(sizes, r_add(r_mul(6, p$bodies), 1))
    r <- FieldRecording$new(stamp = "" %+% text_of(p$stamp) %+% "/shares", names = names, sizes = sizes, p = p)
    v <- Picture$new(id = p$id, what = p$what, width = p$width, height = p$height, frames = p$RUN, paint = function(played = NULL, ...) {
      return(FieldPainter$new(p = p, played = played))
      NULL
    })
    .set(v, "record", r)
    return(v)
    NULL
  })
})

Ink <- ray_class("Ink", Node, function(cl) {
  static_field(cl, "BACK", function() "#08090d")
  static_field(cl, "NEUTRAL", function() "140,147,168")
  static_field(cl, "RED", function() "205,92,92")
  static_field(cl, "BLUE", function() "74,168,235")
  static_field(cl, "SOURCE", function() "74,168,235")
  field(cl, "ray_ink", function() NULL)
  method(cl, "ink_of", function(r = NULL, ...) {
    return((if (truthy(eq(self$ray_ink, NULL))) Ink$NEUTRAL else self$ray_ink(r)))
    NULL
  })
  field(cl, "behind", function() 0.32)
  field(cl, "front", function() 1)
  field(cl, "head", function() 0.97)
  field(cl, "dot", function() 0.60)
  field(cl, "line", function() 0.16)
  field(cl, "every", function() FALSE)
  field(cl, "top", function() 0)
  field(cl, "centre", function() NULL)
})

Side <- ray_class("Side", Node, function(cl) {
  field(cl, "at", NULL)
  field(cl, "sign", NULL)
  field(cl, "ink", NULL)
})

Lane <- ray_class("Lane", Node, function(cl) {
  field(cl, "points", NULL)
  field(cl, "sides", NULL)
  field(cl, "sources", function() lst())
  field(cl, "says", function() "")
})

Strip <- ray_class("Strip", Node, function(cl) {
  static_field(cl, "PAD", function() 12)
  static_field(cl, "MID", function() 30)
  static_field(cl, "PANE", function() r_add(r_div((r_sub(r_sub(900, r_mul(2, 12)), 30)), 2), r_mul(2, 12)))
  statik(cl, "line", function(theory = NULL, N = NULL, ...) {
    return(theory$seed(g_LINE2(), N, 0, 250000, 2))
    NULL
  })
  statik(cl, "exit_toward", function(w = NULL, sign = NULL, ...) {
    return(m_first(filt(rng(w$geometry$DEG), function(d = NULL, ...) {
      return(gt(r_mul(elem(w$geometry$V(d)$components, 0), sign), 0))
      NULL
    })))
    NULL
  })
  statik(cl, "point_at", function(w = NULL, at = NULL, ...) {
    return(w$at(Vector$new(components = lst(at))))
    NULL
  })
  statik(cl, "light", function(w = NULL, at = NULL, sign = NULL, ...) {
    return(elem(Strip$point_at(w, at)$rays, Strip$exit_toward(w, sign))$activate)
    NULL
  })
  statik(cl, "meeting", function(theory = NULL, ...) {
    w <- Strip$line(theory, 2)
    Strip$light(w, 0, 1)
    Strip$light(w, 1, r_sub(0, 1))
    return(w)
    NULL
  })
  statik(cl, "left", function(theory = NULL, laying = NULL, ids = NULL, ...) {
    w <- (laying)(theory)
    Strip$run(w, ids)
    return(w)
    NULL
  })
  statik(cl, "point", function(theory = NULL, ...) {
    return(theory$seed(g_LINE2(), 1, 0, 250000, 16))
    NULL
  })
  statik(cl, "heading", function(theory = NULL, sign = NULL, ...) {
    w <- Strip$line(theory, 3)
    Strip$light(w, 1, sign)
    return(w)
    NULL
  })
  statik(cl, "run", function(w = NULL, ids = NULL, ...) {
    .r <- for_each(ids, function(rid) {
      rule <- m_first(filt(w$theory$rules, function(r = NULL, ...) {
        return(eq(r$id, rid))
        NULL
      }))
      if (truthy(eq(rule, NULL))) {
        (fail)("" %+% text_of(w$theory$name) %+% " has no rule " %+% text_of(rid) %+% "")
      }
      .r <- for_each(rule$matches(w), function(x) {
        rule$apply(x)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  statik(cl, "begin", function(w = NULL, ...) {
    .set(w, "ticks", r_add(w$ticks, 1))
    .r <- for_each(w$sources, function(s) {
      .set(s, "stepped", FALSE)
      .set(s, "moved_along", NULL)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  statik(cl, "lit", function(was = NULL, now = NULL, ...) {
    return(filt(now$sides, function(sd = NULL, ...) {
      return(m_every(was$sides, function(o = NULL, ...) {
        return((if (truthy(.x <- (!eq(o$at, sd$at)))) .x else (!eq(o$sign, sd$sign))))
        NULL
      }))
      NULL
    }))
    NULL
  })
  statik(cl, "emitting", function(was = NULL, now = NULL, ...) {
    new_rays <- Strip$lit(was, now)
    left <- m_some(new_rays, function(sd = NULL, ...) {
      return(lt(sd$sign, 0))
      NULL
    })
    right <- m_some(new_rays, function(sd = NULL, ...) {
      return(gt(sd$sign, 0))
      NULL
    })
    if (truthy((if (truthy(.x <- left)) right else .x))) {
      return("emits both ways")
    }
    if (truthy(left)) {
      return("emits left")
    }
    if (truthy(right)) {
      return("emits right")
    }
    return("")
    NULL
  })
  statik(cl, "lane", function(w = NULL, ink = NULL, ...) {
    pts <- m_map(w$live, function(v = NULL, ...) {
      return(elem(v$at$components, 0))
      NULL
    })
    sides <- lst()
    .r <- for_each(w$live, function(v) {
      .r <- for_each(v$rays, function(r) {
        if (truthy(r$active)) {
          m_push(sides, Side$new(at = elem(v$at$components, 0), sign = elem(r$along$components, 0), ink = ink$ink_of(r)))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    l <- Lane$new(points = pts, sides = sides)
    .r <- for_each(w$sources, function(s) {
      .r <- for_each(s$cells, function(c) {
        m_push(l$sources, elem(c$at$components, 0))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(l)
    NULL
  })
  statik(cl, "of", function(id = NULL, what = NULL, theory = NULL, ids = NULL, seeds = NULL, ink = NULL, ...) {
    rows <- m_map(seeds, function(laying = NULL, ...) {
      w <- (laying)(theory)
      before <- Strip$lane(w, ink)
      Strip$run(w, ids)
      return(lst(before, Strip$lane(w, ink)))
      NULL
    })
    H <- r_mul(70, len(rows))
    pic <- Picture$still(id, what, 900, H, function(s = NULL, ...) {
      return(Strip$paint(s, rows, ink, lst(0, 1)))
      NULL
    })
    .set(pic, "panes", lst(Pane$new(name = "before", width = Strip$PANE, height = H, paints = function(s = NULL, ...) {
      return(Strip$paint(s, rows, ink, lst(0)))
      NULL
    }), Pane$new(name = "after", width = Strip$PANE, height = H, paints = function(s = NULL, ...) {
      return(Strip$paint(s, rows, ink, lst(1)))
      NULL
    })))
    return(pic)
    NULL
  })
  statik(cl, "history", function(theory = NULL, laying = NULL, ticks = NULL, ink = NULL, ...) {
    w <- (laying)(theory)
    lanes <- lst(Strip$lane(w, ink))
    .r <- for_range(ticks, function(t) {
      w$tick
      m_push(lanes, Strip$lane(w, ink))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(lanes)
    NULL
  })
  statik(cl, "film", function(id = NULL, what = NULL, theory = NULL, laying = NULL, ticks = NULL, ink = NULL, ...) {
    lanes <- Strip$history(theory, laying, ticks, ink)
    .set(ink, "centre", Strip$centre_of(lanes))
    PER <- 14
    HOLD <- 3
    return(Picture$new(id = id, what = what, width = 900, height = 90, frames = r_mul((r_add(r_add(ticks, 1), HOLD)), PER), paint = function(played = NULL, ...) {
      return(Unrolling$new(lanes = lanes, ink = ink, per = PER))
      NULL
    }))
    NULL
  })
  statik(cl, "tell", function(id = NULL, what = NULL, lanes = NULL, ink = NULL, ...) {
    .set(ink, "centre", Strip$centre_of(lanes))
    PER <- 40
    HOLD <- 1
    return(Picture$new(id = id, what = what, width = 900, height = 110, frames = r_mul((r_add(len(lanes), HOLD)), PER), paint = function(played = NULL, ...) {
      return(Unrolling$new(lanes = lanes, ink = ink, per = PER))
      NULL
    }))
    NULL
  })
  statik(cl, "relevant", function(pair = NULL, ...) {
    rel <- Node$new()
    .r <- for_each(pair, function(l) {
      .r <- for_each(l$sides, function(sd) {
        .set(rel, key_("" %+% text_of(sd$at) %+% ""), TRUE)
        .set(rel, key_("" %+% text_of(r_add(sd$at, sd$sign)) %+% ""), TRUE)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_each(pair, function(l) {
      .r <- for_each(l$sources, function(p) {
        .set(rel, key_("" %+% text_of(p) %+% ""), TRUE)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    has0 <- Node$new()
    has1 <- Node$new()
    .r <- for_each(elem(pair, 0)$points, function(p) {
      .set(has0, key_("" %+% text_of(p) %+% ""), TRUE)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_each(elem(pair, 1)$points, function(p) {
      .set(has1, key_("" %+% text_of(p) %+% ""), TRUE)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_each(elem(pair, 0)$points, function(p) {
      if (truthy(eq(mem(has1, key_("" %+% text_of(p) %+% "")), NULL))) {
        .set(rel, key_("" %+% text_of(p) %+% ""), TRUE)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_each(elem(pair, 1)$points, function(p) {
      if (truthy(eq(mem(has0, key_("" %+% text_of(p) %+% "")), NULL))) {
        .set(rel, key_("" %+% text_of(p) %+% ""), TRUE)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(rel)
    NULL
  })
  statik(cl, "centre_of", function(lanes = NULL, ...) {
    xs <- lst()
    .r <- for_each(lanes, function(l) {
      .r <- for_each(l$sources, function(p) {
        m_push(xs, p)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    if (truthy(m_empty(xs))) {
      .w("xs", m_first(lanes)$points)
    }
    if (truthy(m_empty(xs))) {
      return(0)
    }
    return(r_div((r_add(m_reduce(xs, m_first(xs), function(a_ = NULL, b_ = NULL, ...) {
      return(Fmt$min(a_, b_))
      NULL
    }), m_reduce(xs, m_first(xs), function(a_ = NULL, b_ = NULL, ...) {
      return(Fmt$max(a_, b_))
      NULL
    }))), 2))
    NULL
  })
  statik(cl, "paint", function(s = NULL, rows = NULL, ink = NULL, lanes = NULL, ...) {
    width <- s$width
    H <- s$height
    s$clear_rect(0, 0, width, H)
    s$fill_style(Ink$BACK)
    s$fill_rect(0, 0, width, H)
    if (truthy(m_empty(rows))) {
      return(NULL)
    }
    seen <- FALSE
    lo <- 0
    hi <- 0
    .r <- for_each(rows, function(pair) {
      .r <- for_each(pair, function(l) {
        .r <- for_each(l$sides, function(sd) {
          to <- r_add(sd$at, sd$sign)
          if (!truthy(seen)) {
            .w("lo", sd$at)
            .w("hi", sd$at)
            .w("seen", TRUE)
          }
          .w("lo", Fmt$min(lo, Fmt$min(sd$at, to)))
          .w("hi", Fmt$max(hi, Fmt$max(sd$at, to)))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_each(rows, function(pair) {
      .r <- for_each(pair, function(l) {
        .r <- for_each(l$sources, function(p) {
          if (!truthy(seen)) {
            .w("lo", p)
            .w("hi", p)
            .w("seen", TRUE)
          }
          .w("lo", Fmt$min(lo, r_sub(p, 1)))
          .w("hi", Fmt$max(hi, r_add(p, 1)))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    if (!truthy(ink$every)) {
      .r <- for_each(rows, function(pair) {
        rel <- Strip$relevant(pair)
        .r <- for_each(pair, function(l) {
          .r <- for_each(l$points, function(p) {
            if (truthy((!eq(mem(rel, key_("" %+% text_of(p) %+% "")), NULL)))) {
              if (!truthy(seen)) {
                .w("lo", p)
                .w("hi", p)
                .w("seen", TRUE)
              }
              .w("lo", Fmt$min(lo, p))
              .w("hi", Fmt$max(hi, p))
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
    }
    if (!truthy(seen)) {
      .w("lo", r_sub(0, 1))
      .w("hi", 0)
    }
    EXT <- r_add(r_div((r_sub(hi, lo)), 2), 0.4)
    if (truthy((!eq(ink$centre, NULL)))) {
      .w("EXT", r_add(Fmt$max(r_sub(ink$centre, lo), r_sub(hi, ink$centre)), 0.4))
    }
    HEAD <- ink$top
    PAD <- Strip$PAD
    MID <- Strip$MID
    lanew <- r_div((r_sub(r_sub(width, r_mul(2, PAD)), r_mul(MID, (r_sub(len(lanes), 1))))), len(lanes))
    origin <- function(k_ = NULL, ...) {
      return(r_add(PAD, r_mul(k_, (r_add(lanew, MID)))))
      NULL
    }
    rowH <- r_div((r_sub(H, HEAD)), len(rows))
    CELL <- r_div(lanew, (r_add(r_mul(2, EXT), 1)))
    MID_AT <- 0
    X <- function(k_ = NULL, x = NULL, ...) {
      return(r_add(r_add((origin)(k_), r_div(lanew, 2)), r_mul((r_sub(x, MID_AT)), CELL)))
      NULL
    }
    .r <- for_range(len(rows), function(r) {
      pair <- elem(rows, r)
      y <- r_add(HEAD, r_mul(rowH, (r_add(r, 0.5))))
      rel <- Strip$relevant(pair)
      .r <- for_range(len(lanes), function(k_) {
        fi <- elem(lanes, k_)
        l <- elem(pair, fi)
        ox <- (origin)(k_)
        if (truthy((!eq(ink$centre, NULL)))) {
          .w("MID_AT", ink$centre)
        } else {
          xs <- lst()
          .r <- for_each(l$sides, function(sd) {
            m_push(xs, r_sub(sd$at, 0.25))
            m_push(xs, r_add(sd$at, 0.25))
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          .r <- for_each(l$sources, function(p) {
            m_push(xs, r_sub(p, 0.3))
            m_push(xs, r_add(p, 0.3))
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          .r <- for_each(l$points, function(p) {
            if (truthy((if (truthy(.x <- ink$every)) .x else (!eq(mem(rel, key_("" %+% text_of(p) %+% "")), NULL))))) {
              m_push(xs, p)
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          .w("MID_AT", (if (truthy(m_empty(xs))) r_div((r_add(lo, hi)), 2) else r_div((r_add(m_reduce(xs, m_first(xs), function(a_ = NULL, b_ = NULL, ...) {
            return(Fmt$min(a_, b_))
            NULL
          }), m_reduce(xs, m_first(xs), function(a_ = NULL, b_ = NULL, ...) {
            return(Fmt$max(a_, b_))
            NULL
          }))), 2)))
        }
        s$stroke_style("rgba(" %+% text_of(Ink$NEUTRAL) %+% "," %+% text_of(ink$line) %+% ")")
        s$line_width(1)
        s$begin_path
        s$move_to(ox, y)
        s$line_to(r_add(ox, lanew), y)
        s$stroke
        .r <- for_each(l$points, function(p) {
          if (truthy((if (truthy(.x <- ink$every)) .x else (!eq(mem(rel, key_("" %+% text_of(p) %+% "")), NULL))))) {
            s$fill_style("rgba(" %+% text_of(Ink$NEUTRAL) %+% "," %+% text_of(ink$dot) %+% ")")
            s$begin_path
            s$arc((X)(k_, p), y, 2.6, 0, r_mul(2, pi))
            s$fill
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        .r <- for_each(l$sources, function(p) {
          half <- Fmt$max(9, Fmt$min(18, r_mul(CELL, 0.3)))
          sx <- (X)(k_, p)
          s$fill_style("rgba(" %+% text_of(Ink$SOURCE) %+% ",0.14)")
          s$fill_rect(r_sub(sx, half), r_sub(y, half), r_mul(2, half), r_mul(2, half))
          s$stroke_style("rgba(" %+% text_of(Ink$SOURCE) %+% ",0.9)")
          s$line_width(1.5)
          s$stroke_rect(r_sub(sx, half), r_sub(y, half), r_mul(2, half), r_mul(2, half))
          if (!truthy(m_empty(l$says))) {
            s$stroke_style("rgba(" %+% text_of(Ink$SOURCE) %+% ",0.9)")
            s$line_width(1)
            s$begin_path
            s$move_to(sx, r_sub(y, half))
            s$line_to(sx, r_sub(r_sub(y, half), 16))
            s$stroke
            s$fill_style("rgba(" %+% text_of(Ink$SOURCE) %+% ",1)")
            s$font("13px ui-monospace, monospace")
            s$text_align("center")
            s$text_baseline("bottom")
            s$fill_text(l$says, sx, r_sub(r_sub(y, half), 20))
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        HEADW <- Fmt$max(7, Fmt$min(12, r_mul(CELL, 0.20)))
        REACH <- r_mul(CELL, 0.25)
        BAR <- Fmt$max(2.5, Fmt$min(4.5, r_mul(CELL, 0.075)))
        BASE <- r_mul(HEADW, 0.45)
        TIP <- r_mul(HEADW, 0.55)
        LEN <- r_sub(REACH, BASE)
        SEEN <- r_sub(TIP, r_div(BAR, 0.84))
        .r <- for_each(l$sides, function(sd) {
          px <- (X)(k_, sd$at)
          s$stroke_style("rgba(" %+% text_of(sd$ink) %+% "," %+% text_of(ink$behind) %+% ")")
          s$line_width(BAR)
          s$begin_path
          s$move_to(r_sub(px, r_mul(sd$sign, (r_add(BASE, LEN)))), y)
          s$line_to(r_sub(px, r_mul(sd$sign, BASE)), y)
          s$stroke
          s$stroke_style("rgba(" %+% text_of(sd$ink) %+% "," %+% text_of(ink$front) %+% ")")
          s$begin_path
          s$move_to(px, y)
          s$line_to(r_add(px, r_mul(sd$sign, (r_add(SEEN, LEN)))), y)
          s$stroke
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        .r <- for_each(l$sides, function(sd) {
          px <- (X)(k_, sd$at)
          s$fill_style("rgba(" %+% text_of(sd$ink) %+% "," %+% text_of(ink$head) %+% ")")
          s$begin_path
          s$move_to(r_add(px, r_mul(sd$sign, TIP)), y)
          s$line_to(r_sub(px, r_mul(sd$sign, BASE)), r_sub(y, r_mul(HEADW, 0.42)))
          s$line_to(r_sub(px, r_mul(sd$sign, BASE)), r_add(y, r_mul(HEADW, 0.42)))
          s$fill
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
})

Unrolling <- ray_class("Unrolling", Painter, function(cl) {
  field(cl, "lanes", NULL)
  field(cl, "ink", NULL)
  field(cl, "per", NULL)
  field(cl, "at", function() 0)
  method(cl, "frame", function(s = NULL, dt = NULL, ...) {
    k <- Fmt$min(r_sub(len(self$lanes), 1), m_floor((r_div(self$at, self$per))))
    Strip$paint(s, lst(lst(elem(self$lanes, k), m_last(self$lanes))), self$ink, lst(0))
    self$at <- r_add(self$at, 1)
    NULL
  })
})

Scripted <- ray_class("Scripted", Source, function(cl) {
  field(cl, "plan", NULL)
  field(cl, "weight", NULL)
  method(cl, "choose emit?", function(exit = NULL, ...) {
    ways <- or_else(elem(self$plan, r_sub(self$world$ticks, 1)), "")
    return((if (truthy(gt(elem(self$world$geometry$V(exit)$components, 0), 0))) m_contains(ways, "+") else m_contains(ways, "-")))
    NULL
  })
  method(cl, "choose mass", function(...) {
    return(self$weight)
    NULL
  })
})

