Sparc <- ray_class("Sparc", Node, function(cl) {
  static_field(cl, "KPC", function() r_mul(3.0856775814913673, r_pow(10, 19)))
  static_field(cl, "KMS", function() 1000)
  static_field(cl, "MSUN", function() r_mul(1.98892, r_pow(10, 30)))
  static_field(cl, "G_NEWTON", function() r_div(6.67430, r_pow(10, 11)))
  static_field(cl, "C_LIGHT", function() 299792458)
  static_field(cl, "YD", function() 0.5)
  static_field(cl, "YB", function() 0.7)
  static_field(cl, "CACHE", function() Node$new())
  static_getter(cl, "sample", function() {
    if (truthy(eq(mem(Sparc$CACHE, key_("sample")), NULL))) {
      .set(Sparc$CACHE, key_("sample"), Measured$of("sparc-galaxies"))
    }
    if (truthy(eq(mem(Sparc$CACHE, key_("sample")), NULL))) {
      (fail)("sparc-galaxies is not on disk - run `npx ray data` and try again")
    }
    return(mem(Sparc$CACHE, key_("sample")))
    NULL
  })
  static_getter(cl, "curves", function() {
    if (truthy(eq(mem(Sparc$CACHE, key_("curves")), NULL))) {
      .set(Sparc$CACHE, key_("curves"), Measured$of("sparc-curves"))
    }
    if (truthy(eq(mem(Sparc$CACHE, key_("curves")), NULL))) {
      (fail)("sparc-curves is not on disk - run `npx ray data` and try again")
    }
    return(mem(Sparc$CACHE, key_("curves")))
    NULL
  })
  static_getter(cl, "names", function() {
    return(mem(Sparc$sample$header, key_("names")))
    NULL
  })
  statik(cl, "usable", function(g = NULL, ...) {
    S <- Sparc$sample$columns
    return((if (truthy(.x <- lt(elem(mem(S, key_("Q")), g), 3))) ge(elem(mem(S, key_("Inc")), g), 30) else .x))
    NULL
  })
  statik(cl, "mass_of", function(g = NULL, ...) {
    S <- Sparc$sample$columns
    return(r_mul(r_mul((r_add(r_mul(0.5, elem(mem(S, key_("L[3.6]")), g)), r_mul(1.33, elem(mem(S, key_("MHI")), g)))), r_pow(10, 9)), Sparc$MSUN))
    NULL
  })
  static_getter(cl, "rar", function() {
    if (truthy((!eq(mem(Sparc$CACHE, key_("rar")), NULL)))) {
      return(mem(Sparc$CACHE, key_("rar")))
    }
    .set(Sparc$CACHE, key_("rar"), Sparc$rar_at(Sparc$YD))
    return(mem(Sparc$CACHE, key_("rar")))
    NULL
  })
  statik(cl, "rar_at", function(YD = NULL, ...) {
    t <- Sparc$curves
    C <- t$columns
    out <- lst()
    .r <- for_range(t$rows, function(i) {
      g <- elem(mem(C, key_("galaxy")), i)
      R <- r_mul(elem(mem(C, key_("R")), i), Sparc$KPC)
      v <- r_mul(elem(mem(C, key_("Vobs")), i), Sparc$KMS)
      if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- Sparc$usable(g))) gt(R, 0) else .x))) gt(v, 0) else .x))) le(elem(mem(C, key_("e_Vobs")), i), r_mul(0.1, elem(mem(C, key_("Vobs")), i))) else .x))) {
        gas <- r_mul(elem(mem(C, key_("Vgas")), i), Sparc$KMS)
        disk <- r_mul(elem(mem(C, key_("Vdisk")), i), Sparc$KMS)
        bul <- r_mul(elem(mem(C, key_("Vbul")), i), Sparc$KMS)
        YB <- (if (truthy(gt(Sparc$YD, 0))) r_div(r_mul(YD, Sparc$YB), Sparc$YD) else YD)
        gbar <- r_div((r_add(r_add(r_mul(gas, m_abs(gas)), r_mul(r_mul(YD, disk), m_abs(disk))), r_mul(r_mul(YB, bul), m_abs(bul)))), R)
        if (truthy(gt(gbar, 0))) {
          m_push(out, RarPoint$new(gbar = gbar, gobs = r_div(r_mul(v, v), R), galaxy = g, R = R))
        }
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  static_getter(cl, "flat", function() {
    if (truthy((!eq(mem(Sparc$CACHE, key_("flat")), NULL)))) {
      return(mem(Sparc$CACHE, key_("flat")))
    }
    best <- Node$new()
    .r <- for_each(Sparc$rar, function(p) {
      had <- elem(best, p$galaxy)
      if (truthy((if (truthy(.x <- eq(had, NULL))) .x else gt(p$R, had$R)))) {
        set_at(best, p$galaxy, p)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    out <- lst()
    names <- Sparc$names
    .r <- for_range(len(names), function(g) {
      p <- elem(best, g)
      if (truthy((!eq(p, NULL)))) {
        q <- RarPoint$new(gbar = p$gbar, gobs = p$gobs, galaxy = p$galaxy, R = p$R)
        .set(q, "name", elem(names, g))
        m_push(out, q)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .set(Sparc$CACHE, key_("flat"), out)
    return(out)
    NULL
  })
  static_getter(cl, "btfr", function() {
    if (truthy((!eq(mem(Sparc$CACHE, key_("btfr")), NULL)))) {
      return(mem(Sparc$CACHE, key_("btfr")))
    }
    t <- Measured$of("sparc-btfr")
    if (truthy(eq(t, NULL))) {
      (fail)("sparc-btfr is not on disk - run `npx ray data` and try again")
    }
    c <- t$columns
    names <- mem(t$header, key_("names"))
    out <- lst()
    .r <- for_range(t$rows, function(i) {
      if (truthy(gt(elem(mem(c, key_("Vf")), i), 0))) {
        m_push(out, Btfr$new(name = elem(names, i), galaxy = elem(mem(c, key_("galaxy")), i), vf = elem(mem(c, key_("Vf")), i), err = elem(mem(c, key_("e_Vf")), i), mass = r_mul(r_pow(10, elem(mem(c, key_("log(Mb)")), i)), Sparc$MSUN), err_mass = elem(mem(c, key_("e_log(Mb)")), i)))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .set(Sparc$CACHE, key_("btfr"), out)
    return(out)
    NULL
  })
  static_getter(cl, "discs", function() {
    if (truthy((!eq(mem(Sparc$CACHE, key_("discs")), NULL)))) {
      return(mem(Sparc$CACHE, key_("discs")))
    }
    d <- Measured$of("genzel-discs")
    if (truthy(eq(d, NULL))) {
      (fail)("genzel-discs is not on disk - run `npx ray data` and try again")
    }
    c <- d$columns
    names <- mem(d$header, key_("names"))
    out <- m_map(rng(len(names)), function(i = NULL, ...) {
      return(HighZ$new(name = elem(names, i), redshift = elem(mem(c, key_("z")), i), Mb = elem(mem(c, key_("Mb")), i), Re = elem(mem(c, key_("Re")), i), fraction = elem(mem(c, key_("fDM")), i), err = elem(mem(c, key_("e_fDM")), i), limit = gt(elem(mem(c, key_("limit")), i), 0.5)))
      NULL
    })
    .set(Sparc$CACHE, key_("discs"), out)
    return(out)
    NULL
  })
  statik(cl, "disc_arrival", function(d = NULL, ...) {
    return(r_div(r_mul(r_mul(r_mul(Sparc$G_NEWTON, d$Mb), r_pow(10, 11)), Sparc$MSUN), r_pow((r_mul(d$Re, Sparc$KPC)), 2)))
    NULL
  })
  statik(cl, "disc_felt", function(d = NULL, ...) {
    return((if (truthy(lt(d$fraction, 1))) r_div(Sparc$disc_arrival(d), (r_sub(1, d$fraction))) else NaN))
    NULL
  })
})

Law <- ray_class("Law", Node, function(cl) {
  static_field(cl, "CACHE", function() Node$new())
  static_getter(cl, "law", function() {
    if (truthy(eq(mem(Law$CACHE, key_("law")), NULL))) {
      .set(Law$CACHE, key_("law"), Measured$of("law"))
    }
    if (truthy(eq(mem(Law$CACHE, key_("law")), NULL))) {
      (fail)("law is not on disk - run `npx ray measure` and try again")
    }
    return(mem(Law$CACHE, key_("law")))
    NULL
  })
  static_getter(cl, "a0", function() {
    return(mem(Law$law$header, key_("a0")))
    NULL
  })
  static_getter(cl, "carries", function() {
    return(or_else(mem(Law$law$header, key_("carries")), 0))
    NULL
  })
  static_getter(cl, "theory", function() {
    return(or_else(mem(Law$law$header, key_("theory")), "G"))
    NULL
  })
  statik(cl, "boost", function(gN = NULL, scale = NULL, ...) {
    A0 <- Law$a0
    xs_ <- mem(Law$law$columns, key_("gN"))
    ys_ <- mem(Law$law$columns, key_("g"))
    want <- r_mul((r_div(gN, scale)), A0)
    lo <- 0
    hi <- r_sub(Law$law$rows, 1)
    if (truthy(le(want, elem(xs_, 0)))) {
      return(r_mul((r_div(elem(ys_, 0), A0)), scale))
    }
    if (truthy(ge(want, elem(xs_, hi)))) {
      return(r_mul((r_div(elem(ys_, hi), A0)), scale))
    }
    while (truthy(gt(r_sub(hi, lo), 1))) {
      mid <- m_floor((r_div((r_add(lo, hi)), 2)))
      if (truthy(le(elem(xs_, mid), want))) {
        .w("lo", mid)
      } else {
        .w("hi", mid)
      }
    }
    t <- r_div((r_sub(m_ln(want), m_ln(elem(xs_, lo)))), (r_sub(m_ln(elem(xs_, hi)), m_ln(elem(xs_, lo)))))
    return(r_mul((r_div(m_exp((r_add(m_ln(elem(ys_, lo)), r_mul(t, (r_sub(m_ln(elem(ys_, hi)), m_ln(elem(ys_, lo)))))))), A0)), scale))
    NULL
  })
})

Galaxies <- ray_class("Galaxies", Node, function(cl) {
  static_field(cl, "A0_DATA", function() r_div(1.2, r_pow(10, 10)))
  static_field(cl, "YLIGHT", function() 0.3)
  static_field(cl, "YHEAVY", function() 0.8)
  static_field(cl, "BACK", function() "#08090d")
  static_field(cl, "FAINT", function() "#5a5f6e")
  static_field(cl, "GRID", function() "rgba(120,127,148,0.13)")
  static_field(cl, "SEEN", function() "#eef0f5")
  static_field(cl, "MODEL", function() "#4aa8eb")
  static_field(cl, "RUN", function() "#f2e05a")
  static_field(cl, "NEWT", function() "#eb964a")
  static_field(cl, "DISCC", function() "#c98bd4")
  static_field(cl, "BTFRC", function() "#cd5c5c")
  static_field(cl, "POINTS", function() "rgba(255,255,255,0.70)")
  static_field(cl, "POINTS_LABEL", function() "#ffffff")
  static_field(cl, "GALAXY", function() "#5fd18a")
  static_field(cl, "GALAXY_LABEL", function() "#8ce0a8")
  static_field(cl, "XMIN", function() neg(4))
  static_field(cl, "XMAX", function() 3)
  static_field(cl, "YMIN", function() neg(3))
  static_field(cl, "YMAX", function() 3)
  static_field(cl, "SEVERAL", function() lst(86, 168, 235))
  static_field(cl, "FREEDOMS", function() lst("mass", "face", "moving", "spread"))
  static_field(cl, "TINTS", function() lst(lst(232, 193, 90), lst(90, 212, 193), lst(240, 122, 178), lst(169, 139, 224)))
  static_field(cl, "NAMES_NOW", function() lst("mass", "face", "moving", "spread"))
  static_field(cl, "LEVELS", function() lst(neg(4), neg(2), 0, 1, 2, 3))
  static_field(cl, "WIDTHS", function() lst(0, 2))
  static_field(cl, "DISK_ID", function() "law.disk")
  static_field(cl, "DISKC", function() "#8be9fd")
  static_field(cl, "MEDIUM_ID", function() "law.medium")
  static_field(cl, "H0", function() 70)
  static_field(cl, "SETTLE", function() 24)
  static_field(cl, "CURVE_ROWS", function() 3)
  static_field(cl, "CURVE_COLS", function() 4)
  static_field(cl, "SIMULATED", function() "npx ray measure galaxy.simulated")
  static_field(cl, "FITTED", function() "#9fd3f5")
  static_field(cl, "ARMS", function() Node$new())
  statik(cl, "freedoms_of", function(data = NULL, ...) {
    return(or_else(mem(data$header, key_("freedoms")), Galaxies$FREEDOMS))
    NULL
  })
  statik(cl, "bit", function(mask = NULL, at = NULL, ...) {
    return(eq((r_mod(m_floor((r_div(mask, r_pow(2, at)))), 2)), 1))
    NULL
  })
  statik(cl, "tint_of", function(mask = NULL, ...) {
    if (truthy(eq(mask, 0))) {
      return(Galaxies$SEVERAL)
    }
    r <- 0
    g <- 0
    bl <- 0
    n <- 0
    .r <- for_range(len(Galaxies$FREEDOMS), function(i) {
      if (truthy(Galaxies$bit(mask, i))) {
        .w("r", r_add(r, elem(elem(Galaxies$TINTS, i), 0)))
        .w("g", r_add(g, elem(elem(Galaxies$TINTS, i), 1)))
        .w("bl", r_add(bl, elem(elem(Galaxies$TINTS, i), 2)))
        .w("n", r_add(n, 1))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return((if (truthy(gt(n, 0))) lst(r_div(r, n), r_div(g, n), r_div(bl, n)) else Galaxies$SEVERAL))
    NULL
  })
  statik(cl, "name_of", function(mask = NULL, ...) {
    if (truthy(eq(mask, 0))) {
      return("the source as it starts")
    }
    parts <- lst()
    .r <- for_range(len(Galaxies$NAMES_NOW), function(i) {
      if (truthy(Galaxies$bit(mask, i))) {
        m_push(parts, elem(Galaxies$NAMES_NOW, i))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    joined <- m_join(parts, " + ")
    return("needs " %+% text_of(joined) %+% "")
    NULL
  })
  statik(cl, "rgb", function(c = NULL, ...) {
    r <- m_round(elem(c, 0))
    g <- m_round(elem(c, 1))
    bl <- m_round(elem(c, 2))
    return("rgb(" %+% text_of(r) %+% "," %+% text_of(g) %+% "," %+% text_of(bl) %+% ")")
    NULL
  })
  statik(cl, "discs_at", function(lx = NULL, ...) {
    best <- NaN
    far <- 0
    .r <- for_each(Sparc$discs, function(d) {
      x <- Fmt$log10(r_div(Sparc$disc_arrival(d), Galaxies$A0_DATA))
      y <- Fmt$log10(r_div(Sparc$disc_felt(d), Galaxies$A0_DATA))
      if (truthy((if (truthy(.x <- Fmt$finite(y))) ((if (truthy(.x <- (!truthy(Fmt$finite(best))))) .x else lt(m_abs((r_sub(x, lx))), far))) else .x))) {
        .w("best", y)
        .w("far", m_abs((r_sub(x, lx))))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(best)
    NULL
  })
  statik(cl, "mass_text", function(level = NULL, ...) {
    if (truthy(eq(level, 0))) {
      return("×1 mass")
    }
    if (truthy(eq(level, 1))) {
      return("×10 mass")
    }
    return("×10^" %+% text_of(Fmt$fixed(level, 0)) %+% " mass")
    NULL
  })
  statik(cl, "law_at", function(lx = NULL, ...) {
    a0 <- Law$a0
    return(Fmt$log10(r_div(Law$boost(r_mul(r_pow(10, lx), a0), a0), a0)))
    NULL
  })
  static_getter(cl, "carries", function() {
    return(Law$carries)
    NULL
  })
  statik(cl, "band_at", function(lx = NULL, ...) {
    return(lst(Galaxies$law_at(lx), Galaxies$law_at(r_sub(lx, Galaxies$carries))))
    NULL
  })
  statik(cl, "offsets", function(YD = NULL, ...) {
    t <- Sparc$curves
    C <- t$columns
    out <- lst()
    YB <- (if (truthy(gt(Sparc$YD, 0))) r_div(r_mul(YD, Sparc$YB), Sparc$YD) else YD)
    .r <- for_range(t$rows, function(i) {
      g <- elem(mem(C, key_("galaxy")), i)
      R <- r_mul(elem(mem(C, key_("R")), i), Sparc$KPC)
      v <- r_mul(elem(mem(C, key_("Vobs")), i), Sparc$KMS)
      if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- Sparc$usable(g))) gt(R, 0) else .x))) gt(v, 0) else .x))) le(elem(mem(C, key_("e_Vobs")), i), r_mul(0.1, elem(mem(C, key_("Vobs")), i))) else .x))) {
        gas <- r_mul(elem(mem(C, key_("Vgas")), i), Sparc$KMS)
        disk <- r_mul(elem(mem(C, key_("Vdisk")), i), Sparc$KMS)
        bul <- r_mul(elem(mem(C, key_("Vbul")), i), Sparc$KMS)
        gbar <- r_div((r_add(r_add(r_mul(gas, m_abs(gas)), r_mul(r_mul(YD, disk), m_abs(disk))), r_mul(r_mul(YB, bul), m_abs(bul)))), R)
        if (truthy(gt(gbar, 0))) {
          m_push(out, r_sub(Fmt$log10(r_div(r_div(r_mul(v, v), R), Galaxies$A0_DATA)), Galaxies$law_at(Fmt$log10(r_div(gbar, Galaxies$A0_DATA)))))
        }
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  statik(cl, "middle", function(xs = NULL, ...) {
    if (truthy(m_empty(xs))) {
      return(NaN)
    }
    sorted <- Expr$sorted(xs)
    return(elem(sorted, m_floor((r_div(len(sorted), 2)))))
    NULL
  })
  static_getter(cl, "asks", function() {
    lo <- 0.05
    hi <- 2
    .r <- for_range(30, function(i) {
      mid <- r_div((r_add(lo, hi)), 2)
      if (truthy(gt(Galaxies$middle(Galaxies$offsets(mid)), 0))) {
        .w("lo", mid)
      } else {
        .w("hi", mid)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(r_div((r_add(lo, hi)), 2))
    NULL
  })
  statik(cl, "medium_at", function(lx = NULL, ...) {
    m <- Measured$of(Galaxies$MEDIUM_ID)
    if (truthy(eq(m, NULL))) {
      return(NaN)
    }
    xs_ <- mem(m$columns, key_("gN"))
    ys_ <- mem(m$columns, key_("g"))
    a0 <- Law$a0
    want <- r_mul(r_pow(10, lx), a0)
    n <- m$rows
    if (truthy((if (truthy(.x <- (if (truthy(.x <- lt(n, 2))) .x else lt(want, elem(xs_, 0))))) .x else gt(want, elem(xs_, r_sub(n, 1)))))) {
      return(NaN)
    }
    lo <- 0
    hi <- r_sub(n, 1)
    while (truthy(gt(r_sub(hi, lo), 1))) {
      mid <- m_floor((r_div((r_add(lo, hi)), 2)))
      if (truthy(le(elem(xs_, mid), want))) {
        .w("lo", mid)
      } else {
        .w("hi", mid)
      }
    }
    span <- r_sub(elem(xs_, hi), elem(xs_, lo))
    f <- (if (truthy(gt(span, 0))) r_div((r_sub(want, elem(xs_, lo))), span) else 0)
    got <- r_add(r_mul(elem(ys_, lo), (r_sub(1, f))), r_mul(elem(ys_, hi), f))
    return((if (truthy(gt(got, 0))) Fmt$log10(r_div(got, a0)) else NaN))
    NULL
  })
  statik(cl, "along", function(s = NULL, at = NULL, t = NULL, text = NULL, colour = NULL, lift = NULL, leans = NULL, ...) {
    p0 <- (leans)(r_sub(t, 0.01))
    p1 <- (leans)(r_add(t, 0.01))
    c <- (at)(t)
    angle <- m_atan2((r_sub(elem(p1, 1), elem(p0, 1))), r_sub(elem(p1, 0), elem(p0, 0)))
    s$save
    s$translate(elem(c, 0), elem(c, 1))
    s$rotate(angle)
    s$font("11px ui-monospace, monospace")
    s$text_align("center")
    s$text_baseline("alphabetic")
    w <- s$measure(text)
    s$fill_style(Galaxies$BACK)
    s$fill_rect(r_sub(r_sub(0, r_div(w, 2)), 4), r_sub(lift, 9), r_add(w, 8), 12)
    s$fill_style(colour)
    s$fill_text(text, 0, lift)
    s$restore
    return(s$text_baseline("alphabetic"))
    NULL
  })
  statik(cl, "ceiling_of", function(data = NULL, ...) {
    x <- mem(data$columns, key_("x"))
    y <- mem(data$columns, key_("y"))
    p <- mem(data$columns, key_("p"))
    grid <- mem(data$header, key_("grid"))
    XS <- mem(mem(grid, key_("arrives")), key_("n"))
    YS <- mem(mem(grid, key_("felt")), key_("n"))
    from_x <- mem(mem(grid, key_("arrives")), key_("from"))
    dx <- r_div((r_sub(mem(mem(grid, key_("arrives")), key_("to")), from_x)), (r_sub(XS, 1)))
    top <- filled(XS, NaN)
    .r <- for_range(XS, function(gx) {
      gy <- r_sub(YS, 1)
      while (truthy(ge(gy, 0))) {
        if (truthy(gt(elem(p, r_add(r_mul(gy, XS), gx)), 0))) {
          set_at(top, gx, elem(y, r_add(r_mul(gy, XS), gx)))
          .w("gy", neg(1))
        } else {
          .w("gy", r_sub(gy, 1))
        }
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(function(lx = NULL, fallback = NULL, ...) {
      gx <- m_round((r_div((r_sub(lx, from_x)), dx)))
      if (truthy((if (truthy(.x <- (if (truthy(.x <- lt(gx, 0))) .x else ge(gx, XS)))) .x else (!truthy(Fmt$finite(elem(top, gx))))))) {
        return(fallback)
      }
      return(Fmt$max(elem(top, gx), fallback))
      NULL
    })
    NULL
  })
  statik(cl, "possible_at", function(deg = NULL, ...) {
    got <- Measured$of("galaxy.possible")
    if (truthy(eq(got, NULL))) {
      (fail)("galaxy.possible is not on disk - run the galaxies (`" %+% text_of(Galaxies$SIMULATED) %+% "`) and try again")
    }
    ds <- mem(got$columns, key_("deg"))
    k <- 0
    .r <- for_range(got$rows, function(i) {
      if (truthy(lt(m_abs((r_sub(elem(ds, i), deg))), m_abs((r_sub(elem(ds, k), deg)))))) {
        .w("k", i)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(elem(mem(got$header, key_("bins")), k))
    NULL
  })
  statik(cl, "panel", function(s = NULL, data = NULL, what = NULL, deg = NULL, support = NULL, possible = NULL, ...) {
    s$fill_style(Galaxies$BACK)
    s$fill_rect(0, 0, s$width, s$height)
    s$font("12px ui-monospace, monospace")
    a0 <- Law$a0
    bx0 <- 92
    bx1 <- r_sub(s$width, 26)
    by0 <- 82
    by1 <- r_sub(s$height, 132)
    XMIN <- Galaxies$XMIN
    XMAX <- Galaxies$XMAX
    YMIN <- Galaxies$YMIN
    YMAX <- Galaxies$YMAX
    X <- function(l = NULL, ...) {
      return(r_add(bx0, r_mul(r_div((r_sub(l, XMIN)), (r_sub(XMAX, XMIN))), (r_sub(bx1, bx0)))))
      NULL
    }
    Y <- function(l = NULL, ...) {
      return(r_sub(by1, r_mul(r_div((r_sub(l, YMIN)), (r_sub(YMAX, YMIN))), (r_sub(by1, by0)))))
      NULL
    }
    .set(Galaxies, "NAMES_NOW", Galaxies$freedoms_of(data))
    shift <- Galaxies$shift_at(data, deg)
    law_drawn <- function(t = NULL, ...) {
      return(r_add(Galaxies$law_at(r_sub(t, shift)), shift))
      NULL
    }
    s$stroke_style(Galaxies$GRID)
    s$line_width(1)
    s$fill_style(Galaxies$FAINT)
    s$text_align("center")
    l <- XMIN
    while (truthy(le(l, XMAX))) {
      s$begin_path
      s$move_to((X)(l), by0)
      s$line_to((X)(l), by1)
      s$stroke
      s$fill_text("10^" %+% text_of(l) %+% "", (X)(l), r_add(by1, 17))
      .w("l", r_add(l, 1))
    }
    s$text_align("right")
    .w("l", YMIN)
    while (truthy(le(l, YMAX))) {
      s$begin_path
      s$move_to(bx0, (Y)(l))
      s$line_to(bx1, (Y)(l))
      s$stroke
      s$fill_text("10^" %+% text_of(l) %+% "", r_sub(bx0, 8), r_add((Y)(l), 4))
      .w("l", r_add(l, 1))
    }
    implied <- lst()
    .r <- for_each(Sparc$btfr, function(g) {
      M <- g$mass
      v <- r_mul(g$vf, 1000)
      if (truthy((if (truthy(.x <- gt(M, 0))) gt(v, 0) else .x))) {
        m_push(implied, Fmt$log10(r_div(r_div(r_mul(r_mul(r_mul(v, v), v), v), (r_mul(Sparc$G_NEWTON, M))), Galaxies$A0_DATA)))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .w("implied", Expr$sorted(implied))
    med <- (if (truthy(m_empty(implied))) NaN else elem(implied, m_floor((r_div(len(implied), 2)))))
    s$line_width(1)
    .r <- for_each(implied, function(o) {
      s$gradient_stroke((X)(XMIN), (X)(0.2), lst("rgba(205,92,92,0.62)", "rgba(205,92,92,0.40)", "rgba(205,92,92,0)"), lst(0, 0.62, 1))
      s$begin_path
      s$move_to((X)(XMIN), (Y)(r_mul(0.5, (r_add(XMIN, o)))))
      s$line_to((X)(0.2), (Y)(r_mul(0.5, (r_add(0.2, o)))))
      s$stroke
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    x <- mem(data$columns, key_("x"))
    y <- mem(data$columns, key_("y"))
    p <- mem(data$columns, key_("p"))
    by <- mem(data$columns, key_("by"))
    grid <- mem(data$header, key_("grid"))
    most <- 0
    .r <- for_each(p, function(v) {
      if (truthy((if (truthy(.x <- Fmt$finite(v))) gt(v, most) else .x))) {
        .w("most", v)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    if (truthy(gt(most, 0))) {
      wpx <- r_div(r_mul(r_div((r_sub(bx1, bx0)), (r_sub(mem(mem(grid, key_("arrives")), key_("n")), 1))), (r_sub(mem(mem(grid, key_("arrives")), key_("to")), mem(mem(grid, key_("arrives")), key_("from"))))), (r_sub(XMAX, XMIN)))
      hpx <- r_div(r_mul(r_div((r_sub(by1, by0)), (r_sub(mem(mem(grid, key_("felt")), key_("n")), 1))), (r_sub(mem(mem(grid, key_("felt")), key_("to")), mem(mem(grid, key_("felt")), key_("from"))))), (r_sub(YMAX, YMIN)))
      live <- lst()
      .r <- for_each(p, function(v) {
        if (truthy(gt(v, 0))) {
          m_push(live, v)
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .w("live", m_sorted_by(live, function(v = NULL, ...) {
        return(v)
        NULL
      }))
      rank <- function(v = NULL, ...) {
        lo <- 0
        hi <- len(live)
        while (truthy(lt(lo, hi))) {
          mid <- m_floor((r_div((r_add(lo, hi)), 2)))
          if (truthy(lt(elem(live, mid), v))) {
            .w("lo", r_add(mid, 1))
          } else {
            .w("hi", mid)
          }
        }
        return(r_div(lo, len(live)))
        NULL
      }
      .r <- for_range(len(p), function(i) {
        if (truthy(gt(elem(p, i), 0))) {
          t <- (rank)(elem(p, i))
          px <- (X)(r_add(elem(x, i), shift))
          py <- (Y)(r_add(elem(y, i), shift))
          if (!truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- lt(px, r_sub(bx0, wpx)))) .x else gt(px, bx1)))) .x else lt(py, by0)))) .x else gt(py, r_add(by1, hpx))))) {
            tint <- Galaxies$tint_of((if (truthy(eq(by, NULL))) 0 else m_round(elem(by, i))))
            k <- r_add(0.60, r_mul(0.40, t))
            r <- m_round((r_mul(elem(tint, 0), k)))
            g <- m_round((r_mul(elem(tint, 1), k)))
            bl <- m_round((r_mul(elem(tint, 2), k)))
            al <- Fmt$fixed(r_add(0.38, r_mul(0.47, t)), 3)
            s$fill_style("rgba(" %+% text_of(r) %+% "," %+% text_of(g) %+% "," %+% text_of(bl) %+% "," %+% text_of(al) %+% ")")
            s$fill_rect(r_sub(px, r_div(wpx, 2)), r_sub(py, r_div(hpx, 2)), r_add(wpx, 1), r_add(hpx, 1))
          }
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
    }
    XS <- mem(mem(grid, key_("arrives")), key_("n"))
    YS <- mem(mem(grid, key_("felt")), key_("n"))
    reach <- function(what = NULL, holds = NULL, ink = NULL, text_ink = NULL, text = NULL, ...) {
      s$stroke_style(ink)
      s$begin_path
      started <- FALSE
      last_x <- 0
      last_y <- 0
      .r <- for_range(XS, function(gx) {
        top <- neg(1)
        gy <- r_sub(YS, 1)
        while (truthy(ge(gy, 0))) {
          if (truthy((if (truthy(.x <- gt(elem(p, r_add(r_mul(gy, XS), gx)), 0))) (holds)(elem(what, r_add(r_mul(gy, XS), gx))) else .x))) {
            .w("top", gy)
            .w("gy", neg(1))
          } else {
            .w("gy", r_sub(gy, 1))
          }
        }
        if (truthy(ge(top, 0))) {
          px <- (X)(r_add(elem(x, r_add(r_mul(top, XS), gx)), shift))
          py <- (Y)(r_add(elem(y, r_add(r_mul(top, XS), gx)), shift))
          if (!truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- lt(px, bx0))) .x else gt(px, bx1)))) .x else lt(py, by0)))) .x else gt(py, by1)))) {
            if (truthy(started)) {
              s$line_to(px, py)
            } else {
              s$move_to(px, py)
            }
            .w("started", TRUE)
            .w("last_x", px)
            .w("last_y", py)
          }
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      s$stroke
      if (truthy(started)) {
        s$fill_style(text_ink)
        return(s$fill_text(text, r_add(last_x, 4), r_add(last_y, 3)))
      }
      NULL
    }
    nds <- mem(data$columns, key_("needs"))
    szs <- mem(data$columns, key_("size"))
    s$line_width(1)
    s$font("9px ui-monospace, monospace")
    s$text_align("left")
    if (truthy((!eq(nds, NULL)))) {
      .r <- for_each(Galaxies$LEVELS, function(level) {
        (reach)(nds, function(v = NULL, ...) {
          return(le(v, level))
          NULL
        }, "rgba(238,240,245,0.30)", "rgba(238,240,245,0.45)", Galaxies$mass_text(level))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
    }
    if (truthy((!eq(szs, NULL)))) {
      s$dash(lst(4, 3))
      .r <- for_each(Galaxies$WIDTHS, function(level) {
        (reach)(szs, function(v = NULL, ...) {
          return(le(v, level))
          NULL
        }, "rgba(139,233,253,0.35)", "rgba(139,233,253,0.55)", "" %+% text_of(Galaxies$mass_text(level)) %+% ", spread")
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      s$dash(lst())
    }
    s$dash(lst())
    s$font("12px ui-monospace, monospace")
    s$fill_style(Galaxies$POINTS)
    shown <- 0
    .r <- for_each(Sparc$rar, function(q) {
      if (truthy((if (truthy(.x <- gt(q$gbar, 0))) gt(q$gobs, 0) else .x))) {
        px <- (X)(Fmt$log10(r_div(q$gbar, Galaxies$A0_DATA)))
        py <- (Y)(Fmt$log10(r_div(q$gobs, Galaxies$A0_DATA)))
        if (!truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- lt(px, bx0))) .x else gt(px, bx1)))) .x else lt(py, by0)))) .x else gt(py, by1)))) {
          s$fill_rect(r_sub(px, 0.7), r_sub(py, 0.7), 1.4, 1.4)
          .w("shown", r_add(shown, 1))
        }
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    galaxies <- 0
    .r <- for_each(Sparc$flat, function(q) {
      px <- (X)(Fmt$log10(r_div(q$gbar, Galaxies$A0_DATA)))
      py <- (Y)(Fmt$log10(r_div(q$gobs, Galaxies$A0_DATA)))
      if (!truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- lt(px, bx0))) .x else gt(px, bx1)))) .x else lt(py, by0)))) .x else gt(py, by1)))) {
        s$begin_path
        s$arc(px, py, 2.6, 0, 7)
        s$fill_style(Galaxies$GALAXY)
        s$fill
        s$stroke_style("rgba(8,9,13,0.85)")
        s$line_width(0.9)
        s$stroke
        .w("galaxies", r_add(galaxies, 1))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    s$stroke_style(Galaxies$NEWT)
    s$line_width(1.5)
    s$dash(lst(6, 5))
    n0 <- Fmt$max(XMIN, YMIN)
    n1 <- Fmt$min(XMAX, YMAX)
    s$begin_path
    s$move_to((X)(n0), (Y)(n0))
    s$line_to((X)(n1), (Y)(n1))
    s$stroke
    s$dash(lst())
    s$stroke_style(Galaxies$BTFRC)
    s$line_width(1.5)
    s$dash(lst(2, 4))
    s$begin_path
    .w("l", XMIN)
    while (truthy(le(l, r_add(XMAX, 0.000001)))) {
      if (truthy(eq(l, XMIN))) {
        s$move_to((X)(l), (Y)(r_mul(0.5, l)))
      } else {
        s$line_to((X)(l), (Y)(r_mul(0.5, l)))
      }
      .w("l", r_add(l, 0.05))
    }
    s$stroke
    s$dash(lst())
    s$stroke_style(Galaxies$MODEL)
    s$line_width(1.2)
    s$alpha(0.4)
    s$dash(lst(5, 4))
    s$begin_path
    .w("l", XMIN)
    while (truthy(le(l, r_add(XMAX, 0.000001)))) {
      if (truthy(eq(l, XMIN))) {
        s$move_to((X)(l), (Y)((law_drawn)(l)))
      } else {
        s$line_to((X)(l), (Y)((law_drawn)(l)))
      }
      .w("l", r_add(l, 0.02))
    }
    s$stroke
    s$dash(lst())
    s$alpha(1)
    landed <- elem(possible, 0)
    mid <- elem(possible, 1)
    step <- Simulation$BIN
    s$fill_style("rgba(74,168,235,0.35)")
    .r <- for_range(len(mid), function(i) {
      if (truthy(gt(elem(landed, i), 0))) {
        px <- (X)(r_add(Galaxies$XMIN, r_mul(i, step)))
        top_ <- (Y)(elem(elem(possible, 3), i))
        low_ <- (Y)(elem(elem(possible, 2), i))
        s$fill_rect(r_sub(px, 1.5), r_sub(top_, 1.5), 3, r_add(r_sub(low_, top_), 3))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    s$stroke_style(Galaxies$MODEL)
    s$line_width(3)
    s$begin_path
    started <- FALSE
    .r <- for_range(len(mid), function(i) {
      v <- elem(mid, i)
      if (truthy((if (truthy(.x <- gt(elem(landed, i), 0))) Fmt$finite(v) else .x))) {
        px <- (X)(r_add(Galaxies$XMIN, r_mul(i, step)))
        py <- (Y)(v)
        if (truthy(started)) {
          s$line_to(px, py)
        } else {
          s$move_to(px, py)
        }
        .w("started", TRUE)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    s$stroke
    .r <- for_each(Sparc$discs, function(d) {
      lx <- Fmt$log10(r_div(Sparc$disc_arrival(d), Galaxies$A0_DATA))
      ly <- Fmt$log10(r_div(Sparc$disc_felt(d), Galaxies$A0_DATA))
      s$fill_style(Galaxies$DISCC)
