    key <- lst(lst(Galaxies$POINTS, "SPARC mass models (Table2.mrt) — " %+% text_of(shown) %+% " of " %+% text_of(rar_n) %+% " in frame, one point per measured radius (borrowed)"), lst(Galaxies$GALAXY, "SPARC galaxy sample (Table1.mrt) — " %+% text_of(galaxies) %+% " of " %+% text_of(names_n) %+% ", each at its outermost radius (" %+% text_of(cut) %+% " cut, borrowed)"), lst(Galaxies$BTFRC, "Tully–Fisher (Lelli+2019): " %+% text_of(btfr_n) %+% " galaxies, one line each (a₀ = v_f⁴/GM), median " %+% text_of(med_text) %+% " dex from the theory's"), lst(Galaxies$DISCC, "Genzel high-z discs (borrowed)"))
    ky <- r_add(by1, 52)
    s$font("11px ui-monospace, monospace")
    .r <- for_each(key, function(row) {
      if (truthy(le(ky, r_sub(s$height, 8)))) {
