  statik(cl, "ratio_at", function(data = NULL, deg = NULL, ...) {
    table <- mem(data$header, key_("coincidence"))
    if (truthy(eq(table, NULL))) {
      (fail)("the space carries no a_0/cH table - rerun it (record.gpu RAY_SPACE)")
    }
    ds <- mem(table, key_("deg"))
    rs <- mem(table, key_("ratio"))
    if (truthy(le(deg, elem(ds, 0)))) {
      return(elem(rs, 0))
    }
    if (truthy(ge(deg, elem(ds, r_sub(len(ds), 1))))) {
      return(elem(rs, r_sub(len(ds), 1)))
    }
    k <- 0
    while (truthy(lt(elem(ds, r_add(k, 1)), deg))) {
      .w("k", r_add(k, 1))
    }
    f <- r_div((r_sub(deg, elem(ds, k))), (r_sub(elem(ds, r_add(k, 1)), elem(ds, k))))
    return(r_add(r_mul(elem(rs, k), (r_sub(1, f))), r_mul(elem(rs, r_add(k, 1)), f)))
    NULL
  })
  statik(cl, "shift_at", function(data = NULL, deg = NULL, ...) {
    H <- r_div(r_mul(Galaxies$H0, 1000), (r_mul(Sparc$KPC, 1000)))
    return(Fmt$log10(r_div(r_mul(r_mul(Galaxies$ratio_at(data, deg), Sparc$C_LIGHT), H), Galaxies$A0_DATA)))
    NULL
  })
  statik(cl, "frame_of", function(solved = NULL, k = NULL, ...) {
    grid <- mem(solved$header, key_("grid"))
    XS <- mem(mem(grid, key_("arrives")), key_("n"))
    YS <- mem(mem(grid, key_("felt")), key_("n"))
    fx <- mem(mem(grid, key_("arrives")), key_("from"))
    fy <- mem(mem(grid, key_("felt")), key_("from"))
    dx <- r_div((r_sub(mem(mem(grid, key_("arrives")), key_("to")), fx)), (r_sub(XS, 1)))
    dy <- r_div((r_sub(mem(mem(grid, key_("felt")), key_("to")), fy)), (r_sub(YS, 1)))
    x <- filled(r_mul(XS, YS), 0)
    y <- filled(r_mul(XS, YS), 0)
    p <- filled(r_mul(XS, YS), 0)
    by <- filled(r_mul(XS, YS), 0)
    needs <- filled(r_mul(XS, YS), NaN)
    across <- filled(r_mul(XS, YS), NaN)
    .r <- for_range(YS, function(gy) {
      .r <- for_range(XS, function(gx) {
        set_at(x, r_add(r_mul(gy, XS), gx), r_add(fx, r_mul(gx, dx)))
        set_at(y, r_add(r_mul(gy, XS), gx), r_add(fy, r_mul(gy, dy)))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    cells <- mem(solved$columns, key_("cell"))
    ps <- mem(solved$columns, key_("p"))
    bys <- mem(solved$columns, key_("by"))
    nds <- mem(solved$columns, key_("needs"))
    szs <- mem(solved$columns, key_("size"))
    starts <- mem(solved$header, key_("starts"))
    stop <- (if (truthy(lt(r_add(k, 1), len(starts)))) elem(starts, r_add(k, 1)) else solved$rows)
    i <- elem(starts, k)
    while (truthy(lt(i, stop))) {
      c <- m_round(elem(cells, i))
      set_at(p, c, elem(ps, i))
      set_at(by, c, elem(bys, i))
      if (truthy((!eq(nds, NULL)))) {
        set_at(needs, c, elem(nds, i))
      }
      if (truthy((!eq(szs, NULL)))) {
        set_at(across, c, elem(szs, i))
      }
      .w("i", r_add(i, 1))
    }
    header <- Node$new()
    .set(header, key_("grid"), grid)
    .set(header, key_("coincidence"), mem(solved$header, key_("coincidence")))
    .set(header, key_("rows"), r_mul(XS, YS))
    columns <- Node$new()
    .set(columns, key_("x"), x)
    .set(columns, key_("y"), y)
    .set(columns, key_("p"), p)
    .set(columns, key_("by"), by)
    .set(columns, key_("needs"), needs)
    .set(columns, key_("size"), across)
    return(Measured$new(header = header, columns = columns))
    NULL
  })
  statik(cl, "support_at", function(solved = NULL, k = NULL, ...) {
    grid <- mem(solved$header, key_("grid"))
    XS <- mem(mem(grid, key_("arrives")), key_("n"))
    YS <- mem(mem(grid, key_("felt")), key_("n"))
    out <- filled(r_mul(XS, YS), 0)
    cells <- mem(solved$columns, key_("cell"))
    starts <- mem(solved$header, key_("starts"))
    stop <- (if (truthy(lt(r_add(k, 1), len(starts)))) elem(starts, r_add(k, 1)) else solved$rows)
    i <- elem(starts, k)
    while (truthy(lt(i, stop))) {
      c <- m_round(elem(cells, i))
      gx <- r_mod(c, XS)
      gy <- r_div((r_sub(c, gx)), XS)
      .r <- for_range(5, function(j) {
        .r <- for_range(5, function(m) {
          xx <- r_sub(r_add(gx, m), 2)
          yy <- r_sub(r_add(gy, j), 2)
          if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- ge(xx, 0))) ge(yy, 0) else .x))) lt(xx, XS) else .x))) lt(yy, YS) else .x))) {
            set_at(out, r_add(r_mul(yy, XS), xx), 1)
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .w("i", r_add(i, 1))
    }
    return(out)
    NULL
  })
  statik(cl, "inside", function(data = NULL, support = NULL, shift = NULL, ...) {
    grid <- mem(data$header, key_("grid"))
    XS <- mem(mem(grid, key_("arrives")), key_("n"))
    YS <- mem(mem(grid, key_("felt")), key_("n"))
    fx <- mem(mem(grid, key_("arrives")), key_("from"))
    fy <- mem(mem(grid, key_("felt")), key_("from"))
    dx <- r_div((r_sub(mem(mem(grid, key_("arrives")), key_("to")), fx)), (r_sub(XS, 1)))
    dy <- r_div((r_sub(mem(mem(grid, key_("felt")), key_("to")), fy)), (r_sub(YS, 1)))
    n <- 0
    hit <- 0
    .r <- for_each(Sparc$rar, function(q) {
      if (truthy((if (truthy(.x <- gt(q$gbar, 0))) gt(q$gobs, 0) else .x))) {
        gx <- m_round((r_div((r_sub(r_sub(Fmt$log10(r_div(q$gbar, Galaxies$A0_DATA)), shift), fx)), dx)))
        gy <- m_round((r_div((r_sub(r_sub(Fmt$log10(r_div(q$gobs, Galaxies$A0_DATA)), shift), fy)), dy)))
        .w("n", r_add(n, 1))
        if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- ge(gx, 0))) ge(gy, 0) else .x))) lt(gx, XS) else .x))) lt(gy, YS) else .x))) gt(elem(support, r_add(r_mul(gy, XS), gx)), 0) else .x))) {
          .w("hit", r_add(hit, 1))
        }
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return((if (truthy(gt(n, 0))) r_div(hit, n) else 0))
    NULL
  })
  statik(cl, "sweep_of", function(solved = NULL, ...) {
    ds <- mem(solved$header, key_("degs"))
    n <- len(ds)
    home <- or_else(mem(solved$header, key_("theory_deg")), 18)
    rest <- 0
    .r <- for_range(n, function(k) {
      if (truthy(lt(m_abs((r_sub(elem(ds, k), home))), m_abs((r_sub(elem(ds, rest), home)))))) {
        .w("rest", k)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    out <- lst()
    .r <- for_range(n, function(k) {
      m_push(out, r_sub(r_sub(n, 1), k))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_range(Galaxies$SETTLE, function(k) {
      f <- r_div((r_add(k, 1)), Galaxies$SETTLE)
      m_push(out, m_round((r_mul(r_mul(r_mul(rest, f), f), (r_sub(3, r_mul(2, f)))))))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  statik(cl, "of", function(id = NULL, what = NULL, title = NULL, ...) {
