    })
    out <- lst()
    .r <- for_range(want, function(k) {
      m_push(out, elem(sorted, m_round((r_div(r_mul((r_sub(len(sorted), 1)), k), (r_sub(want, 1)))))))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
