  statik(cl, "rows_in", function(m = NULL, g = NULL, ...) {
    col <- mem(m$columns, key_("galaxy"))
    out <- lst()
    .r <- for_range(m$rows, function(i) {
      if (truthy(eq(elem(col, i), g))) {
        m_push(out, i)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  statik(cl, "off_of", function(g = NULL, fitted = NULL, ...) {
    sim <- Galaxies$simulated
    j <- m_index_of(mem(sim$header, key_("ids")), g)
    if (truthy(eq(j, NULL))) {
      return(NaN)
    }
    return((if (truthy(fitted)) elem(mem(sim$header, key_("rms1")), j) else elem(mem(sim$header, key_("rms0")), j)))
    NULL
  })
  statik(cl, "percent", function(dex = NULL, ...) {
    return((if (truthy(Fmt$finite(dex))) "" %+% text_of(Fmt$fixed(r_mul(100, (r_sub(r_pow(10, dex), 1))), 0)) %+% "%" else "—"))
    NULL
  })
  statik(cl, "curve_box", function(s = NULL, g = NULL, bx0 = NULL, by0 = NULL, bx1 = NULL, by1 = NULL, ...) {
    sim <- Galaxies$simulated
    fld <- Galaxies$fields
    S <- sim$columns
    F <- fld$columns
    rows <- Galaxies$rows_in(sim, g)
    tab <- Galaxies$rows_in(fld, g)
    top <- 0
    reach <- 0
    .r <- for_each(rows, function(i) {
      .w("top", Fmt$max(top, r_add(elem(mem(S, key_("Vobs")), i), elem(mem(S, key_("e_Vobs")), i))))
      .w("reach", Fmt$max(reach, elem(mem(S, key_("R")), i)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .w("top", r_mul(top, 1.15))
    .w("reach", r_mul(reach, 1.05))
    X <- function(r = NULL, ...) {
      return(r_add(bx0, r_mul(r_div(r, reach), (r_sub(bx1, bx0)))))
      NULL
    }
    Y <- function(v = NULL, ...) {
      return(r_sub(by1, r_mul(r_div(v, top), (r_sub(by1, by0)))))
      NULL
    }
    s$stroke_style(Galaxies$GRID)
    s$line_width(1)
    s$stroke_rect(bx0, by0, r_sub(bx1, bx0), r_sub(by1, by0))
    line <- function(column = NULL, ...) {
      s$begin_path
      started <- FALSE
      .r <- for_each(tab, function(i) {
        r <- elem(mem(F, key_("r")), i)
        v <- elem(elem(F, column), i)
        if (truthy((if (truthy(.x <- le(r, reach))) Fmt$finite(v) else .x))) {
          if (truthy(started)) {
            s$line_to((X)(r), (Y)(Fmt$min(v, top)))
          } else {
            s$move_to((X)(r), (Y)(Fmt$min(v, top)))
          }
          .w("started", TRUE)
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      return(s$stroke)
      NULL
    }
    s$stroke_style(Galaxies$NEWT)
    s$line_width(1)
    s$dash(lst(5, 4))
    (line)("vN")
    s$dash(lst(3, 3))
    s$stroke_style(Galaxies$FITTED)
    (line)("v1")
    s$dash(lst())
    s$stroke_style(Galaxies$MODEL)
    s$line_width(2)
    (line)("v0")
    s$stroke_style(Galaxies$MODEL)
    s$line_width(1)
    .r <- for_each(rows, function(i) {
      v <- elem(mem(S, key_("vs")), i)
      if (truthy(Fmt$finite(v))) {
        s$begin_path
        s$arc((X)(elem(mem(S, key_("R")), i)), (Y)(Fmt$min(v, top)), 2.4, 0, 7)
        s$stroke
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    s$stroke_style(Galaxies$POINTS)
    s$fill_style(Galaxies$POINTS)
    .r <- for_each(rows, function(i) {
      px <- (X)(elem(mem(S, key_("R")), i))
      s$begin_path
      s$move_to(px, (Y)(r_sub(elem(mem(S, key_("Vobs")), i), elem(mem(S, key_("e_Vobs")), i))))
      s$line_to(px, (Y)(Fmt$min(r_add(elem(mem(S, key_("Vobs")), i), elem(mem(S, key_("e_Vobs")), i)), top)))
      s$stroke
      s$fill_rect(r_sub(px, 1.4), r_sub((Y)(elem(mem(S, key_("Vobs")), i)), 1.4), 2.8, 2.8)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    s$font("10px ui-monospace, monospace")
    s$text_align("left")
    s$fill_style(Galaxies$SEEN)
    s$fill_text("" %+% text_of(elem(Sparc$names, g)) %+% "", r_add(bx0, 4), r_add(by0, 12))
    off0 <- Galaxies$percent(Galaxies$off_of(g, FALSE))
    off1 <- Galaxies$percent(Galaxies$off_of(g, TRUE))
    s$fill_style(Galaxies$MODEL)
    s$fill_text("" %+% text_of(off0) %+% " off", r_add(bx0, 4), r_add(by0, 24))
    s$fill_style(Galaxies$FITTED)
    s$fill_text("" %+% text_of(off1) %+% " fitted", r_add(r_add(bx0, 4), s$measure("" %+% text_of(off0) %+% " off  ")), r_add(by0, 24))
    s$fill_style(Galaxies$FAINT)
    s$fill_text("" %+% text_of(Fmt$fixed(top, 0)) %+% "", r_sub(bx0, 32), r_add(by0, 8))
    s$fill_text("0", r_sub(bx0, 32), by1)
    s$text_align("right")
    s$fill_text("" %+% text_of(Fmt$fixed(reach, 0)) %+% " kpc", bx1, r_add(by1, 14))
    return(s$text_align("left"))
    NULL
  })
  statik(cl, "curve_key", function(s = NULL, y = NULL, ...) {
    s$font("11px ui-monospace, monospace")
    s$text_align("left")
    s$fill_style(Galaxies$POINTS)
    s$fill_text("■ measured (SPARC, borrowed)", 22, y)
    s$fill_style(Galaxies$MODEL)
    s$fill_text("— run, SPARC's own Υ, D, i   ○ its tracers", 232, y)
    s$fill_style(Galaxies$FITTED)
    s$fill_text("-- run, the data's freedoms fitted", 560, y)
    s$fill_style(Galaxies$NEWT)
    return(s$fill_text("-- Newton", 820, y))
    NULL
  })
  statik(cl, "sample_off", function(fitted = NULL, ...) {
    S <- Galaxies$simulated$columns
    n <- Galaxies$simulated$rows
    s <- 0
    m <- 0
    .r <- for_range(n, function(i) {
      v <- (if (truthy(fitted)) elem(mem(S, key_("v1")), i) else elem(mem(S, key_("v0")), i))
      if (truthy((if (truthy(.x <- gt(elem(mem(S, key_("kept")), i), 0))) gt(v, 0) else .x))) {
        d <- Fmt$log10(r_div(v, elem(mem(S, key_("Vobs")), i)))
        .w("s", r_add(s, r_mul(d, d)))
        .w("m", r_add(m, 1))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return((if (truthy(gt(m, 0))) m_sqrt((r_div(s, m))) else NaN))
    NULL
  })
  statik(cl, "curves_panel", function(s = NULL, ...) {
    s$fill_style(Galaxies$BACK)
    s$fill_rect(0, 0, s$width, s$height)
    sim <- Galaxies$simulated
    picked <- Galaxies$curve_pick
    s$font("13px ui-monospace, monospace")
    s$fill_style(Galaxies$SEEN)
    s$text_align("left")
    s$fill_text("ROTATION CURVES, EACH GALAXY RUN", 22, 26)
    s$font("11px ui-monospace, monospace")
    s$fill_style(Galaxies$FAINT)
    a0_text <- Fmt$exponential(mem(sim$header, key_("a0")), 3)
    deg_text <- Fmt$fixed(mem(sim$header, key_("deg")), 1)
    whole0 <- Galaxies$percent(Galaxies$sample_off(FALSE))
    whole1 <- Galaxies$percent(Galaxies$sample_off(TRUE))
    s$fill_text("each laid from its own gas, disc and bulge and run; a₀ " %+% text_of(a0_text) %+% " m/s² (DEG " %+% text_of(deg_text) %+% "); all " %+% text_of(whole0) %+% " off, " %+% text_of(whole1) %+% " with Υ, D, i fitted", 22, 44)
    W <- r_div((r_sub(s$width, 44)), Galaxies$CURVE_COLS)
    H <- r_div((r_sub(s$height, 96)), Galaxies$CURVE_ROWS)
    .r <- for_range(len(picked), function(k) {
      col <- r_mod(k, Galaxies$CURVE_COLS)
      row <- m_round((r_div((r_sub(k, col)), Galaxies$CURVE_COLS)))
      ox <- r_add(22, r_mul(col, W))
      oy <- r_add(62, r_mul(row, H))
      Galaxies$curve_box(s, elem(picked, k), r_add(ox, 34), r_add(oy, 16), r_sub(r_add(ox, W), 10), r_sub(r_add(oy, H), 26))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(Galaxies$curve_key(s, r_sub(s$height, 16)))
    NULL
  })
