    return(Picture$still("galaxy.curves", "the rotation curves themselves: twelve galaxies across the sample, each laid from its own gas, disc and bulge and run - the speed a circle needs on its field, what its tracers moved at, and the same with the data's own freedoms fitted, against what was measured", 960, 720, function(s = NULL, ...) {
