  statik(cl, "orbit_panel", function(s = NULL, stars = NULL, frame_at = NULL, ...) {
    s$fill_style(Galaxies$BACK)
    s$fill_rect(0, 0, s$width, s$height)
    film <- mem(stars$header, key_("film"))
    NS <- mem(stars$header, key_("stars"))
    FR <- mem(stars$header, key_("frames"))
    X_ <- mem(stars$columns, key_("x"))
    Y_ <- mem(stars$columns, key_("y"))
    sim <- Galaxies$simulated
    s$font("13px ui-monospace, monospace")
    s$fill_style(Galaxies$SEEN)
    s$text_align("left")
    s$fill_text("GALAXIES, RUN", 22, 26)
    s$font("11px ui-monospace, monospace")
    s$fill_style(Galaxies$FAINT)
    a0_text <- Fmt$exponential(mem(sim$header, key_("a0")), 3)
    deg_text <- Fmt$fixed(mem(sim$header, key_("deg")), 1)
    s$fill_text("laid from the gas, disc and bulge SPARC measured; every tracer pulled at what is felt where it is (a₀ " %+% text_of(a0_text) %+% " m/s², DEG " %+% text_of(deg_text) %+% ")", 22, 44)
    rows <- r_add(m_floor((r_div(len(film), 2))), r_mod(len(film), 2))
    H <- r_div((r_sub(s$height, 96)), Fmt$max(rows, 1))
    W <- r_div((r_sub(s$width, 44)), 2)
    .r <- for_range(len(film), function(k) {
      g <- elem(film, k)
      col <- r_mod(k, 2)
      row <- m_round((r_div((r_sub(k, col)), 2)))
      ox <- r_add(22, r_mul(col, W))
      oy <- r_add(58, r_mul(row, H))
      side <- Fmt$min(r_sub(H, 20), r_mul(W, 0.48))
      cx <- r_add(r_add(ox, r_div(side, 2)), 4)
      cy <- r_add(r_add(oy, r_div(side, 2)), 6)
      reach <- elem(mem(stars$header, key_("reach")), k)
      scale <- r_div(r_div(side, 2), reach)
      s$stroke_style(Galaxies$GRID)
      s$line_width(1)
      s$stroke_rect(r_sub(cx, r_div(side, 2)), r_sub(cy, r_div(side, 2)), side, side)
      .r <- for_range(NS, function(q) {
        at <- r_add(r_mul((r_add(r_mul(k, NS), q)), FR), Fmt$min(frame_at, r_sub(FR, 1)))
        x <- elem(X_, at)
        y <- elem(Y_, at)
        r <- r_div(Fmt$hypot(x, y), reach)
        if (truthy((if (truthy(.x <- Fmt$finite(x))) lt(r, 1.4) else .x))) {
          warm <- Fmt$min(1, r)
          red <- m_round((r_add(120, r_mul(120, (r_sub(1, warm))))))
          green <- m_round((r_add(170, r_mul(50, (r_sub(1, warm))))))
          s$fill_style("rgba(" %+% text_of(red) %+% "," %+% text_of(green) %+% ",245,0.55)")
          px <- r_add(cx, r_mul(x, scale))
          py <- r_sub(cy, r_mul(y, scale))
          if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- gt(px, r_sub(cx, r_div(side, 2))))) lt(px, r_add(cx, r_div(side, 2))) else .x))) gt(py, r_sub(cy, r_div(side, 2))) else .x))) lt(py, r_add(cy, r_div(side, 2))) else .x))) {
            s$fill_rect(r_sub(px, 0.6), r_sub(py, 0.6), 1.2, 1.2)
          }
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      s$fill_style(Galaxies$FAINT)
      s$font("10px ui-monospace, monospace")
      across <- Fmt$fixed(r_mul(2, reach), 0)
      s$fill_text("" %+% text_of(across) %+% " kpc across", r_add(r_sub(cx, r_div(side, 2)), 4), r_sub(r_add(cy, r_div(side, 2)), 6))
      span <- mem(stars$header, key_("span"))
      source <- mem(stars$header, key_("source"))
      if (truthy((!eq(span, NULL)))) {
        myr <- Fmt$fixed(r_div(r_mul(elem(span, k), Fmt$min(frame_at, r_sub(FR, 1))), r_sub(FR, 1)), 0)
        s$fill_text("" %+% text_of(elem(source, k)) %+% ", +" %+% text_of(myr) %+% " Myr", r_add(r_sub(cx, r_div(side, 2)), 4), r_add(r_sub(cy, r_div(side, 2)), 12))
      }
      Galaxies$curve_box(s, g, r_add(r_add(cx, r_div(side, 2)), 40), r_add(oy, 12), r_sub(r_add(ox, W), 12), r_add(oy, side))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(Galaxies$curve_key(s, r_sub(s$height, 16)))
    NULL
  })
