  statik(cl, "medium_panel", function(s = NULL, formed = NULL, frame_at = NULL, ...) {
    s$fill_style(Galaxies$BACK)
    s$fill_rect(0, 0, s$width, s$height)
    H <- formed$header
    G <- mem(H, key_("grid"))
    FR <- mem(H, key_("frames"))
    f <- Fmt$min(frame_at, r_sub(FR, 1))
    D <- mem(formed$columns, key_("density"))
    s$font("13px ui-monospace, monospace")
    s$fill_style(Galaxies$SEEN)
    s$text_align("left")
    s$fill_text("A GALAXY IN THE MEDIUM, EVERY STAR ITS OWN", 22, 26)
    s$font("11px ui-monospace, monospace")
    s$fill_style(Galaxies$FAINT)
    stars_n <- mem(H, key_("stars"))
    tick <- elem(mem(H, key_("ticks")), f)
    deg <- mem(H, key_("deg"))
    side_n <- mem(H, key_("side"))
    s$fill_text("" %+% text_of(stars_n) %+% " stars, each its own body, held where the rays are - every step local, nothing but the medium (DEG " %+% text_of(deg) %+% ", a " %+% text_of(side_n) %+% "-cell box) - tick " %+% text_of(tick) %+% "", 22, 44)
    side <- Fmt$min(r_sub(s$width, 44), r_sub(s$height, 230))
    ox <- r_div((r_sub(s$width, side)), 2)
    oy <- 60
    base <- r_mul(r_mul(f, G), G)
    top <- 0
    .r <- for_range(r_mul(G, G), function(c) {
      .w("top", Fmt$max(top, elem(D, r_add(base, c))))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    cell <- r_div(side, G)
    .r <- for_range(G, function(cy) {
      .r <- for_range(G, function(cx) {
        v <- elem(D, r_add(r_add(base, r_mul(cy, G)), cx))
        if (truthy(gt(v, 0))) {
          t <- Fmt$min(1, r_div(m_ln((r_add(1, v))), m_ln((r_add(1, top)))))
          r <- m_round((r_add(40, r_mul(r_mul(215, t), t))))
          gr <- m_round((r_add(60, r_mul(190, t))))
          b <- m_round((r_add(110, r_mul(145, Fmt$min(1, r_mul(1.6, t))))))
          s$fill_style("rgb(" %+% text_of(r) %+% "," %+% text_of(gr) %+% "," %+% text_of(b) %+% ")")
          s$fill_rect(r_add(ox, r_mul(cx, cell)), r_add(oy, r_mul((r_sub(r_sub(G, 1), cy)), cell)), r_add(cell, 0.5), r_add(cell, 0.5))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    s$stroke_style(Galaxies$GRID)
    s$stroke_rect(ox, oy, side, side)
    rd <- Fmt$fixed(elem(mem(H, key_("scale")), 0), 1)
    across <- Fmt$fixed(r_mul(2, elem(mem(H, key_("span")), 0)), 0)
    speed <- Fmt$fixed(mem(H, key_("speed")), 4)
    s$fill_style(Galaxies$SEEN)
    s$fill_text("R_d " %+% text_of(rd) %+% " c-bar, " %+% text_of(across) %+% " c-bar across; circling at R_d " %+% text_of(speed) %+% " c-bar a tick", ox, r_add(r_add(oy, side), 18))
    series <- Galaxies$arms_of(formed, 0)
    sx0 <- ox
    sx1 <- r_add(ox, side)
    sy0 <- r_add(r_add(oy, side), 46)
    sy1 <- r_add(r_add(oy, side), 136)
    topA <- 0.6
    s$stroke_style(Galaxies$GRID)
    s$stroke_rect(sx0, sy0, r_sub(sx1, sx0), r_sub(sy1, sy0))
    inks <- lst("#4aa8eb", "#f2e05a", "#eb964a")
    .r <- for_range(3, function(k) {
      s$stroke_style(elem(inks, k))
      s$line_width(1.5)
      s$begin_path
      .r <- for_range(r_add(f, 1), function(j) {
        px <- r_add(sx0, r_div(r_mul((r_sub(sx1, sx0)), j), r_sub(FR, 1)))
        py <- r_sub(sy1, r_mul((r_sub(sy1, sy0)), Fmt$min(r_div(elem(elem(series, j), r_add(k, 2)), topA), 1)))
        if (truthy(eq(j, 0))) {
          s$move_to(px, py)
        } else {
          s$line_to(px, py)
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      s$stroke
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    s$line_width(1)
    s$font("10px ui-monospace, monospace")
    now <- elem(series, f)
    a2 <- Fmt$fixed(elem(now, 2), 3)
    a3 <- Fmt$fixed(elem(now, 3), 3)
    a4 <- Fmt$fixed(elem(now, 4), 3)
    s$fill_style(elem(inks, 0))
    s$fill_text("m=2 " %+% text_of(a2) %+% "", sx0, r_sub(sy0, 4))
    s$fill_style(elem(inks, 1))
    s$fill_text("m=3 " %+% text_of(a3) %+% "", r_add(sx0, 90), r_sub(sy0, 4))
    s$fill_style(elem(inks, 2))
    s$fill_text("m=4 " %+% text_of(a4) %+% "", r_add(sx0, 176), r_sub(sy0, 4))
    s$fill_style(Galaxies$FAINT)
    s$fill_text("arm strength, 1-3 R_d, 0 to 0.6 (smooth ≈ 1/sqrt of the stars)", sx0, r_add(sy1, 14))
    return(s$font("11px ui-monospace, monospace"))
    NULL
  })
  statik(cl, "formed_panel", function(s = NULL, formed = NULL, frame_at = NULL, ...) {
    s$fill_style(Galaxies$BACK)
    s$fill_rect(0, 0, s$width, s$height)
    H <- formed$header
    G <- mem(H, key_("grid"))
    FR <- mem(H, key_("frames"))
    f <- Fmt$min(frame_at, r_sub(FR, 1))
    D <- mem(formed$columns, key_("density"))
    names <- mem(H, key_("names"))
    s$font("13px ui-monospace, monospace")
    s$fill_style(Galaxies$SEEN)
    s$text_align("left")
    s$fill_text("GALAXIES LEFT TO THEMSELVES", 22, 26)
    s$font("11px ui-monospace, monospace")
    s$fill_style(Galaxies$FAINT)
    gyr <- Fmt$fixed(r_div(r_mul(mem(H, key_("gyr")), f), r_sub(FR, 1)), 2)
    stars_n <- mem(H, key_("stars"))
    q_text <- Fmt$fixed(mem(H, key_("Q")), 1)
    a0_text <- Fmt$exponential(mem(H, key_("a0")), 3)
    s$fill_text("" %+% text_of(stars_n) %+% " stars each, every one pulled by every other through the law (a₀ " %+% text_of(a0_text) %+% " m/s²), no halo; launched smooth at Q " %+% text_of(q_text) %+% " — t = " %+% text_of(gyr) %+% " Gyr", 22, 44)
    side <- Fmt$min(r_div((r_sub(s$width, 66)), 2), r_sub(s$height, 110))
    .r <- for_range(len(names), function(g) {
      ox <- r_add(22, r_mul(g, (r_add(side, 22))))
      oy <- 60
      base <- r_mul(r_mul((r_add(r_mul(g, FR), f)), G), G)
      top <- 0
      .r <- for_range(r_mul(G, G), function(c) {
        .w("top", Fmt$max(top, elem(D, r_add(base, c))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      cell <- r_div(side, G)
      .r <- for_range(G, function(cy) {
        .r <- for_range(G, function(cx) {
          v <- elem(D, r_add(r_add(base, r_mul(cy, G)), cx))
          if (truthy(gt(v, 0))) {
            t <- Fmt$min(1, r_div(m_ln((r_add(1, v))), m_ln((r_add(1, top)))))
            r <- m_round((r_add(40, r_mul(r_mul(215, t), t))))
            gr <- m_round((r_add(60, r_mul(190, t))))
            b <- m_round((r_add(110, r_mul(145, Fmt$min(1, r_mul(1.6, t))))))
            s$fill_style("rgb(" %+% text_of(r) %+% "," %+% text_of(gr) %+% "," %+% text_of(b) %+% ")")
            s$fill_rect(r_add(ox, r_mul(cx, cell)), r_add(oy, r_mul((r_sub(r_sub(G, 1), cy)), cell)), r_add(cell, 0.5), r_add(cell, 0.5))
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      s$stroke_style(Galaxies$GRID)
      s$stroke_rect(ox, oy, side, side)
      mass <- Fmt$exponential(elem(mem(H, key_("mass")), g), 1)
      rd <- Fmt$fixed(elem(mem(H, key_("scale")), g), 1)
      across <- Fmt$fixed(r_mul(2, elem(mem(H, key_("span")), g)), 0)
      s$fill_style(Galaxies$SEEN)
      s$fill_text("" %+% text_of(elem(names, g)) %+% ": " %+% text_of(mass) %+% " suns, R_d " %+% text_of(rd) %+% " kpc", ox, r_add(r_add(oy, side), 18))
      s$fill_style(Galaxies$FAINT)
      mids <- mem(H, key_("middles"))
      moved <- ""
      if (truthy((!eq(mids, NULL)))) {
        m <- elem(elem(mids, f), g)
        gone <- Fmt$fixed(Fmt$hypot(elem(m, 0), elem(m, 1)), 1)
        speed <- Fmt$fixed(Fmt$hypot(elem(m, 2), elem(m, 3)), 1)
        .w("moved", "; followed - moved " %+% text_of(gone) %+% " kpc, going " %+% text_of(speed) %+% " km/s")
      }
      s$fill_text("" %+% text_of(across) %+% " kpc across" %+% text_of(moved) %+% "", ox, r_add(r_add(oy, side), 34))
      series <- Galaxies$arms_of(formed, g)
      sx0 <- ox
      sx1 <- r_add(ox, side)
      sy0 <- r_add(r_add(oy, side), 58)
      sy1 <- r_add(r_add(oy, side), 148)
      topA <- 0.6
      s$stroke_style(Galaxies$GRID)
      s$stroke_rect(sx0, sy0, r_sub(sx1, sx0), r_sub(sy1, sy0))
      inks <- lst("#4aa8eb", "#f2e05a", "#eb964a")
      .r <- for_range(3, function(k) {
        s$stroke_style(elem(inks, k))
        s$line_width(1.5)
        s$begin_path
        .r <- for_range(r_add(f, 1), function(j) {
          px <- r_add(sx0, r_div(r_mul((r_sub(sx1, sx0)), j), r_sub(FR, 1)))
          py <- r_sub(sy1, r_mul((r_sub(sy1, sy0)), Fmt$min(r_div(elem(elem(series, j), r_add(k, 2)), topA), 1)))
          if (truthy(eq(j, 0))) {
            s$move_to(px, py)
          } else {
            s$line_to(px, py)
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        s$stroke
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      s$line_width(1)
      s$font("10px ui-monospace, monospace")
      now <- elem(series, f)
      a2 <- Fmt$fixed(elem(now, 2), 3)
      a3 <- Fmt$fixed(elem(now, 3), 3)
      a4 <- Fmt$fixed(elem(now, 4), 3)
      s$fill_style(elem(inks, 0))
      s$fill_text("m=2 " %+% text_of(a2) %+% "", sx0, r_sub(sy0, 4))
      s$fill_style(elem(inks, 1))
      s$fill_text("m=3 " %+% text_of(a3) %+% "", r_add(sx0, 90), r_sub(sy0, 4))
      s$fill_style(elem(inks, 2))
      s$fill_text("m=4 " %+% text_of(a4) %+% "", r_add(sx0, 176), r_sub(sy0, 4))
      s$fill_style(Galaxies$FAINT)
      s$text_align("left")
      s$fill_text("arm strength, 1-3 R_d, 0 to 0.6 (smooth ≈ 0.01)", sx0, r_add(sy1, 14))
      s$text_align("left")
      s$font("11px ui-monospace, monospace")
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  statik(cl, "arms_of", function(formed = NULL, g = NULL, ...) {
    H <- formed$header
    about <- mem(H, key_("about"))
    key <- "" %+% text_of(g) %+% ":" %+% text_of(about) %+% ""
    if (truthy((!eq(elem(Galaxies$ARMS, key), NULL)))) {
      return(elem(Galaxies$ARMS, key))
    }
    G <- mem(H, key_("grid"))
    FR <- mem(H, key_("frames"))
    D <- mem(formed$columns, key_("density"))
    per_scale <- r_div(G, (r_div(r_mul(2, elem(mem(H, key_("span")), g)), elem(mem(H, key_("scale")), g))))
    out <- m_map(rng(FR), function(f = NULL, ...) {
      base <- r_mul(r_mul((r_add(r_mul(g, FR), f)), G), G)
      w <- 0
      mx <- 0
      my <- 0
      .r <- for_range(G, function(cy) {
        .r <- for_range(G, function(cx) {
          v <- elem(D, r_add(r_add(base, r_mul(cy, G)), cx))
          .w("w", r_add(w, r_mul(v, v)))
          .w("mx", r_add(mx, r_mul(r_mul(v, v), cx)))
          .w("my", r_add(my, r_mul(r_mul(v, v), cy)))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .w("mx", (if (truthy(gt(w, 0))) r_div(mx, w) else r_div(G, 2)))
      .w("my", (if (truthy(gt(w, 0))) r_div(my, w) else r_div(G, 2)))
      re <- lst(0, 0, 0, 0, 0)
      im <- lst(0, 0, 0, 0, 0)
      total <- 0
      .r <- for_range(G, function(cy) {
        .r <- for_range(G, function(cx) {
          v <- elem(D, r_add(r_add(base, r_mul(cy, G)), cx))
          dx <- r_sub(r_add(cx, 0.5), mx)
          dy <- r_sub(r_add(cy, 0.5), my)
          r <- r_div(Fmt$hypot(dx, dy), per_scale)
          if (truthy((if (truthy(.x <- (if (truthy(.x <- gt(v, 0))) ge(r, 1) else .x))) le(r, 3) else .x))) {
            th <- m_atan2(dy, dx)
            .w("total", r_add(total, v))
            .r <- for_range(5, function(m) {
              set_at(re, m, r_add(elem(re, m), r_mul(v, m_cos((r_mul(m, th))))))
              set_at(im, m, r_add(elem(im, m), r_mul(v, m_sin((r_mul(m, th))))))
              CONTINUE
            })
            if (!is.null(.r)) return(.r[[1]])
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      return(m_drop(m_map(rng(5), function(m = NULL, ...) {
        return((if (truthy(gt(total, 0))) r_div(Fmt$hypot(elem(re, m), elem(im, m)), total) else 0))
        NULL
      }), 0))
      NULL
    })
    set_at(Galaxies$ARMS, key, out)
    return(out)
    NULL
  })
  static_getter(cl, "rar", function() {
    pic <- Picture$still("galaxy.rar", "the radial acceleration relation, simulated: every galaxy run at every measured radius, against the data at SPARC's own freedoms and with them fitted", 960, 720, function(s = NULL, ...) {
      return(Galaxies$rar_panel(s))
      NULL
    })
    .set(pic, "on_request", TRUE)
    return(pic)
    NULL
  })
  statik(cl, "rar_panel", function(s = NULL, ...) {
    s$fill_style(Galaxies$BACK)
    s$fill_rect(0, 0, s$width, s$height)
    sim <- Galaxies$simulated
    S <- sim$columns
    unit <- mem(sim$header, key_("unit"))
    ids <- mem(sim$header, key_("ids"))
    bx0 <- 92
    bx1 <- r_sub(s$width, 26)
    by0 <- 70
    by1 <- r_sub(s$height, 80)
    XMIN <- neg(4)
    XMAX <- 2
    YMIN <- neg(3)
    YMAX <- 2
    X <- function(l = NULL, ...) {
      return(r_add(bx0, r_mul(r_div((r_sub(l, XMIN)), (r_sub(XMAX, XMIN))), (r_sub(bx1, bx0)))))
      NULL
    }
    Y <- function(l = NULL, ...) {
      return(r_sub(by1, r_mul(r_div((r_sub(l, YMIN)), (r_sub(YMAX, YMIN))), (r_sub(by1, by0)))))
      NULL
    }
    s$stroke_style(Galaxies$GRID)
    s$line_width(1)
    s$fill_style(Galaxies$FAINT)
    s$font("11px ui-monospace, monospace")
    s$text_align("center")
    l <- XMIN
    while (truthy(le(l, XMAX))) {
      s$begin_path
      s$move_to((X)(l), by0)
      s$line_to((X)(l), by1)
      s$stroke
      s$fill_text("10^" %+% text_of(l) %+% "", (X)(l), r_add(by1, 16))
      .w("l", r_add(l, 1))
    }
    s$text_align("right")
    .w("l", YMIN)
    while (truthy(le(l, YMAX))) {
      s$begin_path
      s$move_to(bx0, (Y)(l))
      s$line_to(bx1, (Y)(l))
      s$stroke
      s$fill_text("10^" %+% text_of(l) %+% "", r_sub(bx0, 8), r_add((Y)(l), 4))
      .w("l", r_add(l, 1))
    }
    lg <- function(v = NULL, ...) {
      return(Fmt$log10(r_div(v, Galaxies$A0_DATA)))
      NULL
    }
    spread0 <- lst()
    spread1 <- lst()
    .r <- for_range(sim$rows, function(i) {
      if (truthy(gt(elem(mem(S, key_("kept")), i), 0))) {
        g <- elem(mem(S, key_("galaxy")), i)
        j <- m_index_of(ids, g)
        R <- elem(mem(S, key_("R")), i)
        V <- elem(mem(S, key_("Vobs")), i)
        gbar0 <- r_mul((r_add(r_add(r_mul(Sparc$YD, elem(mem(S, key_("gd")), i)), r_mul(Sparc$YB, elem(mem(S, key_("gb")), i))), elem(mem(S, key_("gg")), i))), unit)
        gbar1 <- r_mul((r_add(r_add(r_mul(elem(mem(sim$header, key_("Y_disk")), j), elem(mem(S, key_("gd")), i)), r_mul(elem(mem(sim$header, key_("Y_bulge")), j), elem(mem(S, key_("gb")), i))), elem(mem(S, key_("gg")), i))), unit)
        f <- r_div(elem(mem(sim$header, key_("D")), j), elem(mem(Sparc$sample$columns, key_("D")), g))
        sn <- r_div(m_sin((r_div(r_mul(elem(mem(Sparc$sample$columns, key_("Inc")), g), pi), 180))), m_sin((r_div(r_mul(elem(mem(sim$header, key_("Inc")), j), pi), 180))))
        gobs0 <- r_mul(r_div(r_mul(V, V), R), unit)
        gobs1 <- r_mul(r_div(r_mul((r_mul(V, sn)), (r_mul(V, sn))), (r_mul(R, f))), unit)
        if (truthy((if (truthy(.x <- gt(gbar0, 0))) gt(gbar1, 0) else .x))) {
          s$fill_style("rgba(238,240,245,0.35)")
          s$fill_rect(r_sub((X)((lg)(gbar0)), 0.7), r_sub((Y)((lg)(gobs0)), 0.7), 1.4, 1.4)
          s$fill_style("rgba(159,211,245,0.8)")
          s$fill_rect(r_sub((X)((lg)(gbar1)), 0.8), r_sub((Y)((lg)(gobs1)), 0.8), 1.6, 1.6)
          m0 <- elem(mem(S, key_("v0")), i)
          m1 <- elem(mem(S, key_("v1")), i)
          if (truthy(gt(m0, 0))) {
            m_push(spread0, Fmt$log10(r_div(m0, V)))
          }
          if (truthy(gt(m1, 0))) {
            m_push(spread1, Fmt$log10(r_div(m1, V)))
          }
        }
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    a0 <- mem(sim$header, key_("a0"))
    s$stroke_style(Galaxies$MODEL)
    s$line_width(2)
    s$begin_path
    .w("l", XMIN)
    while (truthy(le(l, r_add(XMAX, 0.000001)))) {
      gN <- r_mul(r_pow(10, l), Galaxies$A0_DATA)
      y <- (lg)(Law$boost(gN, a0))
      if (truthy(eq(l, XMIN))) {
        s$move_to((X)(l), (Y)(y))
      } else {
        s$line_to((X)(l), (Y)(y))
      }
      .w("l", r_add(l, 0.02))
    }
    s$stroke
    s$stroke_style(Galaxies$NEWT)
    s$dash(lst(6, 5))
    s$begin_path
    s$move_to((X)(Fmt$max(XMIN, YMIN)), (Y)(Fmt$max(XMIN, YMIN)))
    s$line_to((X)(Fmt$min(XMAX, YMAX)), (Y)(Fmt$min(XMAX, YMAX)))
    s$stroke
    s$dash(lst())
    s$stroke_style("#1b2130")
    s$stroke_rect(bx0, by0, r_sub(bx1, bx0), r_sub(by1, by0))
    s$text_align("left")
    s$font("13px ui-monospace, monospace")
    s$fill_style(Galaxies$SEEN)
    s$fill_text("THE RADIAL ACCELERATION RELATION, EVERY GALAXY RUN", bx0, 26)
    s$font("11px ui-monospace, monospace")
    s$fill_style(Galaxies$FAINT)
    off0 <- Galaxies$percent(Simulation$rms(spread0))
    off1 <- Galaxies$percent(Simulation$rms(spread1))
    a0_text <- Fmt$exponential(a0, 3)
    deg_text <- Fmt$fixed(mem(sim$header, key_("deg")), 1)
    radii_n <- len(spread0)
    seen <- Node$new()
    .r <- for_range(sim$rows, function(i) {
      which <- elem(mem(S, key_("galaxy")), i)
      if (truthy(gt(elem(mem(S, key_("kept")), i), 0))) {
        .set(seen, key_("" %+% text_of(which) %+% ""), TRUE)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    ids_n <- len(filt(ids, function(g = NULL, ...) {
      return((!eq(mem(seen, key_("" %+% text_of(g) %+% "")), NULL)))
      NULL
    }))
    s$fill_text("" %+% text_of(radii_n) %+% " radii, " %+% text_of(ids_n) %+% " galaxies: " %+% text_of(off0) %+% " off in speed at the published Υ, D, i, " %+% text_of(off1) %+% " fitted (a₀ " %+% text_of(a0_text) %+% " m/s², DEG " %+% text_of(deg_text) %+% ")", bx0, 44)
    s$fill_style("rgba(238,240,245,0.7)")
    s$fill_text("■ SPARC at its own freedoms", bx0, r_sub(s$height, 22))
    s$fill_style(Galaxies$FITTED)
    s$fill_text("■ the same radii with Υ, D, i fitted", r_add(bx0, 240), r_sub(s$height, 22))
    s$fill_style(Galaxies$MODEL)
    s$fill_text("— where the run puts them: the law, at the run's a₀", r_add(bx0, 520), r_sub(s$height, 22))
    s$fill_style(Galaxies$FAINT)
    s$text_align("center")
    return(s$fill_text("g_baryons / 1.2e-10 m/s²", r_div((r_add(bx0, bx1)), 2), r_add(by1, 34)))
    NULL
  })
  static_getter(cl, "point", function() {
    return(Galaxies$of("galaxy.point", "a galaxy as ONE source - the whole of its mass behind one face, so what it sends saturates at the face. Where the model puts galaxies, against every measurement", "A GALAXY AS ONE SOURCE"))
    NULL
  })
  static_getter(cl, "many", function() {
    return(Galaxies$of("galaxy.many", "and as its stars - each thin enough to send all of itself, so what is sent is the total mass. The same axes, the same law, the other limit of the skin", "A GALAXY AS MANY SOURCES, ONE PER STAR"))
    NULL
  })
})

Sweeping <- ray_class("Sweeping", Painter, function(cl) {
  field(cl, "solved", NULL)
  field(cl, "title", NULL)
  field(cl, "ks", NULL)
  field(cl, "shown_frames", function() 0)
  method(cl, "frame", function(s = NULL, dt = NULL, ...) {
    k <- elem(self$ks, (if (truthy(lt(self$shown_frames, len(self$ks)))) self$shown_frames else r_sub(len(self$ks), 1)))
    deg <- elem(mem(self$solved$header, key_("degs")), k)
    Galaxies$panel(s, Galaxies$frame_of(self$solved, k), self$title, deg, Galaxies$support_at(self$solved, k), Galaxies$possible_at(deg))
    self$shown_frames <- r_add(self$shown_frames, 1)
    NULL
  })
})

