    NULL
  })
  getter(cl, "reach", function() {
    return(r_add(r_mul(3, self$resolution$cells), 4))
    NULL
  })
  getter(cl, "tile_side", function() {
    return(r_add(m_floor((r_div(r_sub(r_add(self$box_side, self$batching$tiles), 1), self$batching$tiles))), r_mul(r_mul(2, self$reach), self$batching$ticks)))
    NULL
  })
  getter(cl, "tile_cells", function() {
    return((if (truthy(eq(self$batching$tiles, 1))) self$box_cells else r_mul(self$tile_side, self$tile_side)))
    NULL
  })
  getter(cl, "tile_sources", function() {
    return(r_div(r_mul(self$sources, self$tile_cells), self$box_cells))
    NULL
  })
  getter(cl, "parts", function() {
    c <- self$tile_cells
    s <- self$tile_sources
    r <- self$resolution
    held <- r_mul(r_mul(c, (r_add(r_add(r_add(r_add(r_add(r_add(r_add(r_add(r_add(r_add(r_mul(r_mul(r$ways, r$keeps), 8), 1), r$ways), 12), 2), 4), 4), 9), r$near_list), 1), 1))), 4)
    each <- (if (truthy(self$budget$compact)) 0 else r_add(r_add(r_add(12, 4), 2), 1))
    ledgers <- r_mul((r_add(r_add(r_mul(c, r_add(r_add(11, 384), 2)), r_mul(s, each)), r_mul(r_mul(4096, 64), 4))), 4)
    lists <- (if (truthy(self$budget$compact)) r_mul((r_add(r_mul(10, c), r_mul(1024, 1024))), 4) else r_mul((r_add(r_mul(2, c), s)), 4))
    base <- lst(lst("held rays (a box)", held, TRUE), lst("held rays (the other)", held, TRUE), lst("ledgers and sources", ledgers, TRUE), lst("sources by cell", lists, TRUE), lst("planes", r_mul(r_mul(3, c), 4), TRUE))
    shards <- (if (truthy(self$budget$compact)) filt(m_map(rng(8), function(k = NULL, ...) {
      return(Fmt$max(0, Fmt$min(178956970, r_sub(s, r_mul(k, 178956970)))))
      NULL
    }), function(n = NULL, ...) {
      return(gt(n, 0))
      NULL
    }) else lst())
    return(m_concat(base, m_map(rng(len(shards)), function(k = NULL, ...) {
      return(lst("sources (shard " %+% text_of(k) %+% ")", r_mul(elem(shards, k), 12), TRUE))
      NULL
    })))
    NULL
  })
  getter(cl, "total", function() {
    sum <- 0
    .r <- for_each(self$parts, function(p) {
      .w("sum", r_add(sum, elem(p, 1)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(sum)
    NULL
  })
  getter(cl, "per_source", function() {
    return((if (truthy(self$budget$compact)) 12 else r_mul(r_add(r_add(r_add(r_add(12, 4), 2), 1), 1), 4)))
    NULL
  })
  method(cl, "fits", function(memory = NULL, binding = NULL, ...) {
    cap <- (if (truthy(gt(self$budget$memory, 0))) self$budget$memory else memory)
    one <- (if (truthy(gt(self$budget$binding, 0))) self$budget$binding else binding)
    return((if (truthy(.x <- le(self$total, cap))) m_every(self$parts, function(p = NULL, ...) {
      return(le(elem(p, 1), one))
      NULL
    }) else .x))
    NULL
  })
  method(cl, "report", function(memory = NULL, binding = NULL, ...) {
    cap <- (if (truthy(gt(self$budget$memory, 0))) self$budget$memory else memory)
    one <- (if (truthy(gt(self$budget$binding, 0))) self$budget$binding else binding)
    over <- " - more than one binding holds (" %+% text_of(Fmt$fixed(r_div(one, 1048576), 0)) %+% " MiB)"
    lines <- m_map(self$parts, function(p = NULL, ...) {
      tail <- (if (truthy(gt(elem(p, 1), one))) over else "")
      return("  " %+% text_of(elem(p, 0)) %+% ": " %+% text_of(Fmt$fixed(r_div(elem(p, 1), 1048576), 0)) %+% " MiB" %+% text_of(tail) %+% "")
      NULL
    })
    head <- "" %+% text_of(Fmt$fixed(self$sources, 0)) %+% " sources on a " %+% text_of(self$side) %+% "-cell view in a " %+% text_of(self$box_side) %+% "-cell box (" %+% text_of(r_mul(self$batching$tiles, self$batching$tiles)) %+% " tile(s), " %+% text_of(self$resolution$cells) %+% " cells to a c-bar, " %+% text_of(self$resolution$ways) %+% " ways): " %+% text_of(Fmt$fixed(r_div(self$total, 1073741824), 2)) %+% " GiB of " %+% text_of(Fmt$fixed(r_div(cap, 1073741824), 2)) %+% " GiB, " %+% text_of(Fmt$fixed(self$per_source, 0)) %+% " bytes a source"
    verdict <- (if (truthy(self$fits(memory, binding))) "  fits" else "  does not fit")
    return(m_join(m_concat(m_concat(lst(head), lines), lst(verdict)), "\n"))
    NULL
  })
})

Annulus <- ray_class("Annulus", Node, function(cl) {
  field(cl, "inner", NULL)
  field(cl, "outer", NULL)
  field(cl, "thick", NULL)
  method(cl, "pull", function(r = NULL, nsub = NULL, nphi = NULL, ...) {
    total <- 0
    weight <- 0
    .r <- for_range(nsub, function(s) {
      rs <- r_add(self$inner, r_div(r_mul((r_sub(self$outer, self$inner)), (r_add(s, 0.5))), nsub))
      ring <- 0
      .r <- for_range(nphi, function(p) {
        half <- m_sin((r_div(r_div(r_mul(pi, (r_add(p, 0.5))), nphi), 2)))
        bend <- r_mul(r_mul(2, half), half)
        d2 <- r_add(r_add(r_mul((r_sub(r, rs)), (r_sub(r, rs))), r_mul(r_mul(r_mul(2, r), rs), bend)), r_mul(self$thick, self$thick))
        .w("ring", r_add(ring, r_div((r_add((r_sub(r, rs)), r_mul(rs, bend))), (r_mul(d2, m_sqrt(d2))))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .w("total", r_add(total, r_div(r_mul(rs, ring), nphi)))
      .w("weight", r_add(weight, rs))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return((if (truthy(gt(weight, 0))) r_div(total, weight) else 0))
    NULL
  })
  method(cl, "arrives", function(r = NULL, nsub = NULL, nphi = NULL, ...) {
    total <- 0
    weight <- 0
    .r <- for_range(nsub, function(s) {
      rs <- r_add(self$inner, r_div(r_mul((r_sub(self$outer, self$inner)), (r_add(s, 0.5))), nsub))
      ring <- 0
      .r <- for_range(nphi, function(p) {
        half <- m_sin((r_div(r_div(r_mul(pi, (r_add(p, 0.5))), nphi), 2)))
        d2 <- r_add(r_add(r_mul((r_sub(r, rs)), (r_sub(r, rs))), r_mul(r_mul(r_mul(r_mul(4, r), rs), half), half)), r_mul(self$thick, self$thick))
        .w("ring", r_add(ring, r_div(1, d2)))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .w("total", r_add(total, r_div(r_mul(rs, ring), nphi)))
      .w("weight", r_add(weight, rs))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return((if (truthy(gt(weight, 0))) r_div(total, weight) else 0))
    NULL
  })
})

Simulation <- ray_class("Simulation", Node, function(cl) {
  field(cl, "deg", NULL)
  static_field(cl, "UNIT_G", function() r_div(r_mul(Sparc$KMS, Sparc$KMS), Sparc$KPC))
  static_field(cl, "G_KPC", function() r_div(r_mul(Sparc$G_NEWTON, Sparc$MSUN), (r_mul(r_mul(Sparc$KPC, Sparc$KMS), Sparc$KMS))))
  static_field(cl, "NSUB", function() 16)
  static_field(cl, "NPHI", function() 512)
  static_field(cl, "TABLE", function() 128)
  static_field(cl, "REACH", function() 1.3)
  static_field(cl, "STARS", function() 1024)
  static_field(cl, "ORBITS", function() 3)
  static_field(cl, "PER_ORBIT", function() 100)
  static_field(cl, "CAP", function() 40000)
  static_field(cl, "CHUNK", function() 250)
  static_field(cl, "SIGMA", function() 10)
  static_field(cl, "FRAMES", function() 120)
  static_field(cl, "FILM", function() 4)
  static_field(cl, "GRID", function() 17)
  static_field(cl, "FINE", function() 9)
  static_field(cl, "PRIOR_Y", function() 0.1)
  static_field(cl, "STEP_Y", function() 0.05)
  static_field(cl, "STEP_D", function() 0.5)
  static_field(cl, "STEP_I", function() 0.5)
  static_field(cl, "THREAD", function() "  let i: u32 = P[7] + gid.y * 65536u + gid.x;")
  static_field(cl, "ENTRY", function() "@compute @workgroup_size(64) fn")
  static_field(cl, "ID", function() "(@builtin(global_invocation_id) gid: vec3<u32>) {")
  static_field(cl, "OMEGA_M", function() 0.315)
  static_field(cl, "FILM_STARS", function() 4096)
  static_field(cl, "FILM_TURNS", function() 0.5)
  static_field(cl, "SKY_EDGE", function() 4)
  static_field(cl, "BRIGHTEST", function() 0.995)
  static_field(cl, "SURVEY_NAMES", function() lst("S4G 3.6um", "Spitzer IRAC1 3.6um", "unWISE W1 3.4um"))
  static_field(cl, "MYR", function() r_div(r_div(Sparc$KPC, Sparc$KMS), (r_mul(3.15576, r_pow(10, 13)))))
  static_field(cl, "SHAPE_H", function() 0.13)
  static_field(cl, "SHAPE_N", function() 200)
  static_field(cl, "SHAPE_EDGES", function() 120)
  static_field(cl, "MASSES", function() lst(6, 12, 25))
  static_field(cl, "SCALES", function() lst(neg(0.6), 1.2, 10))
  static_field(cl, "GAS", function() lst(0, 0.3, 0.6, 0.9))
  static_field(cl, "GAS_WIDE", function() lst(1, 2, 3))
  static_field(cl, "BULGE", function() lst(0, 0.3))
  static_field(cl, "BULGE_A", function() 0.1)
  static_field(cl, "RADII", function() 24)
  static_field(cl, "BIN", function() 0.05)
  statik(cl, "thickness_of", function(g = NULL, ...) {
    rd <- elem(mem(Sparc$sample$columns, key_("Rdisk")), g)
    return((if (truthy(gt(rd, 0))) Fmt$max(r_mul(0.196, m_exp((r_mul(0.633, m_ln(rd))))), 0.02) else 0.2))
    NULL
  })
  statik(cl, "kept", function(g = NULL, v = NULL, ev = NULL, ...) {
    return((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- Sparc$usable(g))) gt(v, 0) else .x))) gt(ev, 0) else .x))) le(ev, r_mul(0.1, v)) else .x))
    NULL
  })
  static_getter(cl, "law_wgsl", function() {
    return(m_join(lst("fn boost(gN: f32, a0: f32) -> f32 {", "  let n: u32 = arrayLength(&L) / 2u;", "  let want: f32 = log(gN / a0);", "  if (want <= L[0]) { return exp(L[n]) * a0; }", "  if (want >= L[n - 1u]) { return exp(L[2u * n - 1u]) * a0; }", "  var lo: u32 = 0u;", "  var hi: u32 = n - 1u;", "  loop {", "    if (hi - lo <= 1u) { break; }", "    let mid: u32 = (lo + hi) / 2u;", "    if (L[mid] <= want) { lo = mid; } else { hi = mid; }", "  }", "  let t: f32 = (want - L[lo]) / (L[hi] - L[lo]);", "  return exp(L[n + lo] + t * (L[n + hi] - L[n + lo])) * a0;", "}", "fn felt(gN: f32, a0: f32) -> f32 {", "  if (gN > 0.0) { return boost(gN, a0); }", "  if (gN < 0.0) { return -boost(-gN, a0); }", "  return 0.0;", "}"), "\n"))
    NULL
  })
  static_getter(cl, "pull_kernel", function() {
    pi <- Shaded$literal(pi)
    return(m_join(lst("// GENERATED from Simulation.ray: PULL - an annulus summed element by element at a radius in its plane, per unit of G M", "@group(0) @binding(0) var<storage, read> P: array<u32>;", "@group(0) @binding(1) var<storage, read> T: array<f32>;", "@group(0) @binding(2) var<storage, read_write> O: array<f32>;", "" %+% text_of(Simulation$ENTRY) %+% " PULL" %+% text_of(Simulation$ID) %+% "", Simulation$THREAD, "  if (i >= P[0]) { return; }", "  let r: f32 = T[4u * i];", "  let e0: f32 = T[4u * i + 1u];", "  let e1: f32 = T[4u * i + 2u];", "  let h: f32 = T[4u * i + 3u];", "  var total: f32 = 0.0;", "  var weight: f32 = 0.0;", "  for (var s: u32 = 0u; s < P[1]; s = s + 1u) {", "    let rs: f32 = e0 + (e1 - e0) * (f32(s) + 0.5) / f32(P[1]);", "    var ring: f32 = 0.0;", "    for (var p: u32 = 0u; p < P[2]; p = p + 1u) {", "      let sh: f32 = sin(" %+% text_of(pi) %+% " * (f32(p) + 0.5) / f32(P[2]) / 2.0);", "      let bend: f32 = 2.0 * sh * sh;", "      let d2: f32 = (r - rs) * (r - rs) + 2.0 * r * rs * bend + h * h;", "      if (P[3] == 1u) { ring = ring + 1.0 / d2; } else { ring = ring + ((r - rs) + rs * bend) / (d2 * sqrt(d2)); }", "    }", "    total = total + rs * ring / f32(P[2]);", "    weight = weight + rs;", "  }", "  if (weight > 0.0) { O[i] = total / weight; } else { O[i] = 0.0; }", "}"), "\n"))
    NULL
  })
  static_getter(cl, "law_kernel", function() {
    return(m_join(lst("// GENERATED from Simulation.ray: LAW - what is felt at every place of every galaxy", "@group(0) @binding(0) var<storage, read> P: array<u32>;", "@group(0) @binding(1) var<storage, read> L: array<f32>;", "@group(0) @binding(2) var<storage, read> Q: array<f32>;", "@group(0) @binding(3) var<storage, read> N: array<f32>;", "@group(0) @binding(4) var<storage, read_write> O: array<f32>;", Simulation$law_wgsl, "" %+% text_of(Simulation$ENTRY) %+% " LAW" %+% text_of(Simulation$ID) %+% "", Simulation$THREAD, "  if (i >= P[0]) { return; }", "  let slot: u32 = u32(Q[6u * i]);", "  let gN: f32 = N[4u * slot] * Q[6u * i + 2u] + N[4u * slot + 1u] * Q[6u * i + 4u] + Q[6u * i + 3u];", "  O[i] = felt(gN, N[4u * slot + 2u]);", "}"), "\n"))
    NULL
  })
  static_getter(cl, "fit_kernel", function() {
    pi <- Shaded$literal(pi)
    ln10 <- Shaded$literal(m_ln(10))
    lyd <- Shaded$literal(Fmt$log10(Sparc$YD))
    lyb <- Shaded$literal(Fmt$log10(Sparc$YB))
    py <- Shaded$literal(Simulation$PRIOR_Y)
    return(m_join(lst("// GENERATED from Simulation.ray: FIT - the log of the posterior of the data's own freedoms, on a grid", "@group(0) @binding(0) var<storage, read> P: array<u32>;", "@group(0) @binding(1) var<storage, read> L: array<f32>;", "@group(0) @binding(2) var<storage, read> Q: array<f32>;", "@group(0) @binding(3) var<storage, read> G: array<f32>;", "@group(0) @binding(4) var<storage, read_write> O: array<f32>;", Simulation$law_wgsl, "" %+% text_of(Simulation$ENTRY) %+% " FIT" %+% text_of(Simulation$ID) %+% "", Simulation$THREAD, "  let n: u32 = P[1];", "  let C: u32 = n * n * n * n;", "  if (i >= P[0] * C) { return; }", "  let j: u32 = i / C;", "  let c: u32 = i % C;", "  let h: f32 = f32((n - 1u) / 2u);", "  let b: u32 = 16u * j;", "  let D: f32 = G[b + 2u];", "  let eD: f32 = G[b + 3u];", "  let inc: f32 = G[b + 4u];", "  let einc: f32 = G[b + 5u];", "  let a0: f32 = G[b + 6u];", "  let ly: f32 = G[b + 8u] + (f32(c % n) - h) * G[b + 12u];", "  let lb: f32 = G[b + 9u] + (f32((c / n) % n) - h) * G[b + 12u];", "  let Dp: f32 = G[b + 10u] + (f32((c / (n * n)) % n) - h) * G[b + 13u] * eD;", "  let ip: f32 = G[b + 11u] + (f32(c / (n * n * n)) - h) * G[b + 14u] * einc;", "  if (Dp <= 0.0 || ip <= 0.5 || ip > 90.0) { O[i] = -1e30; return; }", "  let YD: f32 = exp(ly * " %+% text_of(ln10) %+% ");", "  let YB: f32 = exp(lb * " %+% text_of(ln10) %+% ");", "  let f: f32 = Dp / D;", "  let s: f32 = sin(inc * " %+% text_of(pi) %+% " / 180.0) / sin(ip * " %+% text_of(pi) %+% " / 180.0);", "  var chi: f32 = 0.0;", "  let start: u32 = u32(G[b]);", "  let stop: u32 = start + u32(G[b + 1u]);", "  for (var p: u32 = start; p < stop; p = p + 1u) {", "    let q: u32 = 8u * p;", "    let g: f32 = felt(YD * Q[q + 3u] + YB * Q[q + 5u] + Q[q + 4u], a0);", "    let vm: f32 = sqrt(max(f * Q[q] * g, 0.0));", "    let d: f32 = (Q[q + 1u] * s - vm) / (Q[q + 2u] * s);", "    chi = chi + d * d;", "  }", "  let py: f32 = (ly - " %+% text_of(lyd) %+% ") / " %+% text_of(py) %+% ";", "  let pb: f32 = G[b + 7u] * (lb - " %+% text_of(lyb) %+% ") / " %+% text_of(py) %+% ";", "  var pd: f32 = 0.0;", "  if (eD > 0.0) { pd = (Dp - D) / eD; }", "  var pi_: f32 = 0.0;", "  if (einc > 0.0) { pi_ = (ip - inc) / einc; }", "  O[i] = -0.5 * (chi + py * py + pb * pb + pd * pd + pi_ * pi_);", "}"), "\n"))
    NULL
  })
  static_getter(cl, "best_kernel", function() {
    return(m_join(lst("// GENERATED from Simulation.ray: BEST - each galaxy's best point of its grid", "@group(0) @binding(0) var<storage, read> P: array<u32>;", "@group(0) @binding(1) var<storage, read> V: array<f32>;", "@group(0) @binding(2) var<storage, read_write> O: array<f32>;", "" %+% text_of(Simulation$ENTRY) %+% " BEST" %+% text_of(Simulation$ID) %+% "", Simulation$THREAD, "  if (i >= P[0]) { return; }", "  var best: f32 = -3e38;", "  var pos: u32 = 0u;", "  for (var c: u32 = 0u; c < P[1]; c = c + 1u) {", "    let v: f32 = V[i * P[1] + c];", "    if (v > best) { best = v; pos = c; }", "  }", "  O[2u * i] = f32(pos);", "  O[2u * i + 1u] = best;", "}"), "\n"))
    NULL
  })
  static_getter(cl, "stars_kernel", function() {
    return(m_join(lst("// GENERATED from Simulation.ray: STARS - tracers followed on every galaxy's field", "@group(0) @binding(0) var<storage, read> P: array<u32>;", "@group(0) @binding(1) var<storage, read> L: array<f32>;", "@group(0) @binding(2) var<storage, read> GT: array<f32>;", "@group(0) @binding(3) var<storage, read> GI: array<f32>;", "@group(0) @binding(4) var<storage, read_write> S: array<f32>;", "@group(0) @binding(5) var<storage, read_write> F: array<f32>;", Simulation$law_wgsl, "fn g_at(j: u32, r: f32) -> f32 {", "  let rmax: f32 = GI[12u * j];", "  let T: u32 = P[2];", "  let base: u32 = j * T;", "  let u: f32 = r / rmax * f32(T);", "  if (u <= 1.0) { return GT[base] * u; }", "  if (u >= f32(T)) {", "    let q: f32 = rmax / r;", "    return felt(GI[12u * j + 5u] * q * q, GI[12u * j + 6u]);", "  }", "  let t0: u32 = u32(floor(u)) - 1u;", "  let fr: f32 = u - floor(u);", "  return GT[base + t0] * (1.0 - fr) + GT[base + t0 + 1u] * fr;", "}", "" %+% text_of(Simulation$ENTRY) %+% " START" %+% text_of(Simulation$ID) %+% "", Simulation$THREAD, "  if (i >= P[0]) { return; }", "  let j: u32 = i / P[1];", "  let k: u32 = 10u * i;", "  let r0: f32 = S[k];", "  let phi: f32 = S[k + 1u];", "  let sig: f32 = GI[12u * j + 9u];", "  let g: f32 = g_at(j, r0);", "  let vp: f32 = sqrt(max(r0 * g, 0.0)) + sig * S[k + 2u];", "  let vr: f32 = sig * S[k + 3u];", "  let c: f32 = cos(phi);", "  let s: f32 = sin(phi);", "  S[k] = r0 * c;", "  S[k + 1u] = r0 * s;", "  S[k + 2u] = vr * c - vp * s;", "  S[k + 3u] = vr * s + vp * c;", "  S[k + 4u] = 0.0 - g * c;", "  S[k + 5u] = 0.0 - g * s;", "  S[k + 6u] = 0.0;", "  S[k + 7u] = 0.0;", "  S[k + 8u] = 0.0;", "}", "" %+% text_of(Simulation$ENTRY) %+% " STEP" %+% text_of(Simulation$ID) %+% "", Simulation$THREAD, "  if (i >= P[0]) { return; }", "  let j: u32 = i / P[1];", "  let b: u32 = 12u * j;", "  let dt: f32 = GI[b + 1u];", "  let n: u32 = u32(GI[b + 2u]);", "  let avg_from: u32 = u32(GI[b + 3u]);", "  let film: f32 = GI[b + 4u];", "  let every: u32 = max(u32(GI[b + 7u]), 1u);", "  let ffrom: u32 = u32(GI[b + 8u]);", "  let k: u32 = 10u * i;", "  var x: f32 = S[k];", "  var y: f32 = S[k + 1u];", "  var vx: f32 = S[k + 2u];", "  var vy: f32 = S[k + 3u];", "  var ax: f32 = S[k + 4u];", "  var ay: f32 = S[k + 5u];", "  var sr: f32 = S[k + 6u];", "  var sv: f32 = S[k + 7u];", "  var sn: f32 = S[k + 8u];", "  let stop: u32 = min(P[4], n);", "  for (var t: u32 = P[3]; t < stop; t = t + 1u) {", "    vx = vx + 0.5 * ax * dt;", "    vy = vy + 0.5 * ay * dt;", "    x = x + vx * dt;", "    y = y + vy * dt;", "    let r: f32 = max(sqrt(x * x + y * y), 1e-6);", "    let g: f32 = g_at(j, r);", "    ax = 0.0 - g * x / r;", "    ay = 0.0 - g * y / r;", "    vx = vx + 0.5 * ax * dt;", "    vy = vy + 0.5 * ay * dt;", "    if (t >= avg_from) {", "      sr = sr + r;", "      sv = sv + (x * vy - y * vx) / r;", "      sn = sn + 1.0;", "    }", "    let kk: u32 = t + 1u;", "    if (film >= 0.0 && kk > ffrom && (kk - ffrom) % every == 0u) {", "      let fr: u32 = (kk - ffrom) / every - 1u;", "      if (fr < P[5]) {", "        let o: u32 = ((u32(film) * P[1] + i % P[1]) * P[5] + fr) * 2u;", "        F[o] = x;", "        F[o + 1u] = y;", "      }", "    }", "  }", "  S[k] = x;", "  S[k + 1u] = y;", "  S[k + 2u] = vx;", "  S[k + 3u] = vy;", "  S[k + 4u] = ax;", "  S[k + 5u] = ay;", "  S[k + 6u] = sr;", "  S[k + 7u] = sv;", "  S[k + 8u] = sn;", "}"), "\n"))
    NULL
  })
  static_getter(cl, "runnable", function() {
