    out <- lst()
    .r <- for_range(len(Sparc$names), function(g) {
      if (truthy(ge((or_else(mem(counts, key_("" %+% text_of(g) %+% "")), 0)), 3))) {
        m_push(out, g)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
