  statik(cl, "bulge_at", function(rs = NULL, r = NULL, ...) {
    n <- len(rs)
    inside <- lst()
    most <- 0
    .r <- for_each(rs, function(row) {
      .w("most", Fmt$max(most, r_mul(r_mul(elem(row, 5), m_abs(elem(row, 5))), elem(row, 0))))
      m_push(inside, most)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    if (truthy((if (truthy(.x <- le(most, 0))) .x else le(r, 0)))) {
      return(0)
    }
    if (truthy(le(r, elem(elem(rs, 0), 0)))) {
      return(r_div(r_mul(elem(inside, 0), r_pow((r_div(r, elem(elem(rs, 0), 0))), 3)), (r_mul(r, r))))
    }
    if (truthy(ge(r, elem(elem(rs, r_sub(n, 1)), 0)))) {
      return(r_div(elem(inside, r_sub(n, 1)), (r_mul(r, r))))
    }
    k <- 0
    while (truthy(lt(elem(elem(rs, r_add(k, 1)), 0), r))) {
      .w("k", r_add(k, 1))
    }
    f <- r_div((r_sub(r, elem(elem(rs, k), 0))), (r_sub(elem(elem(rs, r_add(k, 1)), 0), elem(elem(rs, k), 0))))
    return(r_div((r_add(r_mul(elem(inside, k), (r_sub(1, f))), r_mul(elem(inside, r_add(k, 1)), f))), (r_mul(r, r))))
    NULL
  })
  statik(cl, "linear", function(A = NULL, bv = NULL, ...) {
    n <- len(bv)
    M <- m_map(rng(n), function(i = NULL, ...) {
      return(m_concat(m_map(rng(n), function(j = NULL, ...) {
        return(elem(elem(A, i), j))
        NULL
      }), lst(elem(bv, i))))
      NULL
    })
    .r <- for_range(n, function(c) {
      p <- c
      .r <- for_range(r_sub(n, c), function(k) {
        if (truthy(gt(m_abs(elem(elem(M, r_add(c, k)), c)), m_abs(elem(elem(M, p), c))))) {
          .w("p", r_add(c, k))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      swap <- elem(M, c)
      set_at(M, c, elem(M, p))
      set_at(M, p, swap)
      if (truthy((!eq(elem(elem(M, c), c), 0)))) {
        .r <- for_range(r_sub(r_sub(n, c), 1), function(k) {
          r <- r_add(r_add(c, 1), k)
          f <- r_div(elem(elem(M, r), c), elem(elem(M, c), c))
          .r <- for_range(r_sub(r_add(n, 1), c), function(m) {
            set_at(elem(M, r), r_add(c, m), r_sub(elem(elem(M, r), r_add(c, m)), r_mul(f, elem(elem(M, c), r_add(c, m)))))
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    x <- filled(n, 0)
    .r <- for_range(n, function(k) {
      r <- r_sub(r_sub(n, 1), k)
      s <- elem(elem(M, r), n)
      .r <- for_range(r_sub(r_sub(n, r), 1), function(m) {
        .w("s", r_sub(s, r_mul(elem(elem(M, r), r_add(r_add(r, 1), m)), elem(x, r_add(r_add(r, 1), m)))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      set_at(x, r, (if (truthy((!eq(elem(elem(M, r), r), 0)))) r_div(s, elem(elem(M, r), r)) else 0))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(x)
    NULL
  })
  statik(cl, "nnls", function(K = NULL, want = NULL, ...) {
    m <- len(want)
    n <- len(elem(K, 0))
    top <- 0
    .r <- for_each(want, function(t) {
      .w("top", Fmt$max(top, m_abs(t)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    if (truthy(le(top, 0))) {
      return(filled(n, 0))
    }
    wt <- m_map(want, function(t = NULL, ...) {
      return(r_div(1, Fmt$max(m_abs(t), r_mul(0.02, top))))
      NULL
    })
    A <- m_map(rng(n), function(a = NULL, ...) {
      return(m_map(rng(n), function(b = NULL, ...) {
        s <- 0
        .r <- for_range(m, function(i) {
          .w("s", r_add(s, r_mul(r_mul(r_mul(elem(wt, i), elem(wt, i)), elem(elem(K, i), a)), elem(elem(K, i), b))))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        return(s)
        NULL
      }))
      NULL
    })
    bv <- m_map(rng(n), function(a = NULL, ...) {
      s <- 0
      .r <- for_range(m, function(i) {
        .w("s", r_add(s, r_mul(r_mul(r_mul(elem(wt, i), elem(wt, i)), elem(elem(K, i), a)), elem(want, i))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      return(s)
      NULL
    })
    w <- filled(n, 0)
    held <- filled(n, FALSE)
    most <- 0
    .r <- for_each(bv, function(v) {
      .w("most", Fmt$max(most, m_abs(v)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    tol <- r_mul(most, r_pow(10, (r_sub(0, 12))))
    solved <- function(hold = NULL, ...) {
      on <- filt(rng(n), function(a = NULL, ...) {
        return(elem(hold, a))
        NULL
      })
      got <- Simulation$linear(m_map(on, function(a = NULL, ...) {
        return(m_map(on, function(b = NULL, ...) {
          return(elem(elem(A, a), b))
          NULL
        }))
        NULL
      }), m_map(on, function(a = NULL, ...) {
        return(elem(bv, a))
        NULL
      }))
      z <- filled(n, 0)
      .r <- for_range(len(on), function(k) {
        set_at(z, elem(on, k), elem(got, k))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      return(z)
      NULL
    }
    rounds <- 0
    going <- TRUE
    while (truthy((if (truthy(.x <- going)) lt(rounds, r_mul(3, n)) else .x))) {
      .w("rounds", r_add(rounds, 1))
      grad <- m_map(rng(n), function(a = NULL, ...) {
        s <- elem(bv, a)
        .r <- for_range(n, function(b) {
          .w("s", r_sub(s, r_mul(elem(elem(A, a), b), elem(w, b))))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        return(s)
        NULL
      })
      pick <- neg(1)
      .r <- for_range(n, function(a) {
        if (truthy((if (truthy(.x <- (if (truthy(.x <- (!truthy(elem(held, a))))) gt(elem(grad, a), tol) else .x))) ((if (truthy(.x <- lt(pick, 0))) .x else gt(elem(grad, a), elem(grad, pick)))) else .x))) {
          .w("pick", a)
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      if (truthy(lt(pick, 0))) {
        .w("going", FALSE)
      } else {
        set_at(held, pick, TRUE)
        inner <- TRUE
        while (truthy(inner)) {
          z <- (solved)(held)
          if (truthy(m_every(rng(n), function(a = NULL, ...) {
            return((if (truthy(.x <- (!truthy(elem(held, a))))) .x else gt(elem(z, a), 0)))
            NULL
          }))) {
            .w("w", z)
            .w("inner", FALSE)
          } else {
            step <- 1
            .r <- for_range(n, function(a) {
              if (truthy((if (truthy(.x <- elem(held, a))) le(elem(z, a), 0) else .x))) {
                .w("step", Fmt$min(step, r_div(elem(w, a), (r_sub(elem(w, a), elem(z, a))))))
              }
              CONTINUE
            })
            if (!is.null(.r)) return(.r[[1]])
            .r <- for_range(n, function(a) {
              if (truthy(elem(held, a))) {
                set_at(w, a, r_add(elem(w, a), r_mul(step, (r_sub(elem(z, a), elem(w, a))))))
              }
              CONTINUE
            })
            if (!is.null(.r)) return(.r[[1]])
            wtop <- 0
            .r <- for_each(w, function(v) {
              .w("wtop", Fmt$max(wtop, v))
              CONTINUE
            })
            if (!is.null(.r)) return(.r[[1]])
            .r <- for_range(n, function(a) {
              if (truthy((if (truthy(.x <- elem(held, a))) le(elem(w, a), r_mul(wtop, r_pow(10, (r_sub(0, 12))))) else .x))) {
                set_at(held, a, FALSE)
                set_at(w, a, 0)
              }
              CONTINUE
            })
            if (!is.null(.r)) return(.r[[1]])
            .w("inner", m_some(rng(n), function(a = NULL, ...) {
              return(elem(held, a))
              NULL
            }))
          }
        }
      }
    }
    return(w)
    NULL
  })
