          NULL
        }, w_disc)
        gg <- (sum_at)(function(a = NULL, ...) {
          return(elem(elem(K, i), a))
          NULL
        }, w_gas)
        gb <- Simulation$bulge_at(rs, elem(elem(rs, i), 0))
        m_push(here, lst(gd, gg, gb))
        R <- elem(elem(rs, i), 0)
        sp <- function(v = NULL, ...) {
          return(r_mul(m_sqrt(m_abs(v)), ((if (truthy(lt(v, 0))) neg(1) else 1))))
          NULL
        }
        .w("worst", Fmt$max(worst, Fmt$max(m_abs((r_sub((sp)(r_mul(gd, R)), elem(elem(rs, i), 4)))), m_abs((r_sub((sp)(r_mul(gg, R)), elem(elem(rs, i), 3)))))))
        .w("top", Fmt$max(top, Fmt$max(m_abs(elem(elem(rs, i), 4)), m_abs(elem(elem(rs, i), 3)))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      m_push(self$at_rows, here)
      m_push(self$w_discs, w_disc)
      m_push(self$w_gases, w_gas)
      m_push(self$repro, (if (truthy(gt(top, 0))) r_div(worst, top) else 0))
      tab <- lst()
      .r <- for_range(Simulation$TABLE, function(t) {
        base <- r_add(elem(self$tabled_at, j), r_mul(t, n))
        gd <- (sum_at)(function(a = NULL, ...) {
          return(elem(pulls, r_add(base, a)))
          NULL
        }, w_disc)
        gg <- (sum_at)(function(a = NULL, ...) {
          return(elem(pulls, r_add(base, a)))
          NULL
        }, w_gas)
        m_push(tab, lst(self$table_r(j, t), gd, gg, Simulation$bulge_at(rs, self$table_r(j, t))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      m_push(self$tables, tab)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
