  method(cl, "arrive", function(spulls = NULL, ...) {
    self$seen_rows <- lst()
    .r <- for_range(len(self$ids), function(j) {
      rs <- elem(self$rows, j)
      n <- r_sub(len(elem(self$edges, j)), 1)
      here <- lst()
      .r <- for_range(len(rs), function(i) {
        sd <- 0
        sg <- 0
        .r <- for_range(n, function(a) {
          k <- elem(spulls, r_add(r_add(elem(self$measured_at, j), r_mul(i, n)), a))
          .w("sd", r_add(sd, r_mul(k, elem(elem(self$w_discs, j), a))))
          .w("sg", r_add(sg, r_mul(k, elem(elem(self$w_gases, j), a))))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        m_push(here, lst(sd, sg, Simulation$bulge_arrives(rs, elem(elem(rs, i), 0), elem(self$thick, j))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      m_push(self$seen_rows, here)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    NULL
  })
  statik(cl, "lift_coefficients", function(theory = NULL, deg = NULL, ...) {
    model <- Model$new(theory = theory)
    e <- model$settled(deg)
    line <- model$fact("the space line nets")
    slope <- (if (truthy(eq(line, NULL))) NaN else model$at(Expr$d(line$to, "\\rho"), e))
    v <- model$value_of("\\frac{a_{0}}{cH}", e)
    m <- theory$medium(11, 96, 3, deg, 2)
    .set(m, "vacuum", TRUE)
    .set(m, "facing", TRUE)
    s <- m$symbols(m$rho_inf, 0)
    rate <- 0
    .r <- for_each(m$meets, function(t) {
      .w("rate", r_add(rate, r_div(r_mul(m$share(t, s), t$doing$folds$at(s)), 2)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    sf <- r_mul(mem(e, key_("\\sigma")), mem(e, key_("F")))
    D <- theory$lattice$D
    return(lst(r_div(r_mul(m_abs(slope), v), (r_mul(rate, D))), r_div(r_mul(r_mul(4, sf), v), (r_mul(rate, D))), m_abs(slope), v, rate, sf))
    NULL
  })
