  statik(cl, "epochs", function(shape = NULL, a0 = NULL, how = NULL, ...) {
    return(m_map(Sparc$discs, function(d = NULL, ...) {
      rd <- r_div(d$Re, 1.678)
      gbar <- r_mul(r_div(r_mul(r_mul(r_mul(Sparc$G_NEWTON, d$Mb), r_pow(10, 11)), Sparc$MSUN), (r_pow((r_mul(rd, Sparc$KPC)), 2))), Simulation$shape_at(shape, 1.678))
      a <- Simulation$a0_then(a0, d$redshift, how)
      g <- r_add(r_div(gbar, 2), m_sqrt((r_add(r_div(r_mul(gbar, gbar), 4), r_mul(gbar, a)))))
      return(lst(d$redshift, gbar, d$fraction, d$err, (if (truthy(d$limit)) 1 else 0), r_sub(1, r_div(gbar, g))))
      NULL
    }))
    NULL
  })
  method(cl, "lift_test", function(kappa = NULL, a0 = NULL, ...) {
    off <- lst()
    .r <- for_range(len(self$ids), function(j) {
      .r <- for_range(len(elem(self$rows, j)), function(i) {
        row <- elem(elem(self$rows, j), i)
        if (truthy(gt(elem(row, 6), 0))) {
          p <- elem(elem(self$at_rows, j), i)
          q <- elem(elem(self$seen_rows, j), i)
          gN <- r_add(r_add(r_mul(Sparc$YD, elem(p, 0)), r_mul(Sparc$YB, elem(p, 2))), elem(p, 1))
          gs <- r_add(r_add(r_mul(Sparc$YD, elem(q, 0)), r_mul(Sparc$YB, elem(q, 2))), elem(q, 1))
          a <- r_add(a0, r_mul(kappa, Fmt$max(gs, 0)))
          g <- (if (truthy(gt(gN, 0))) Law$boost(gN, a) else ((if (truthy(lt(gN, 0))) r_sub(0, Law$boost(r_sub(0, gN), a)) else 0)))
          v <- m_sqrt(Fmt$max(r_mul(elem(row, 0), g), 0))
          if (truthy(gt(v, 0))) {
            m_push(off, Fmt$log10(r_div(v, elem(row, 1))))
          }
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(lst(Simulation$rms(off), Fmt$median(off)))
    NULL
  })
