  method(cl, "combo", function(j = NULL, c = NULL, n = NULL, ...) {
    S <- Sparc$sample$columns
    g <- elem(self$ids, j)
    h <- r_div((r_sub(n, 1)), 2)
    iy <- r_mod(c, n)
    ib <- r_mod(m_floor((r_div(c, n))), n)
    id <- r_mod(m_floor((r_div(c, (r_mul(n, n))))), n)
    ii <- m_floor((r_div(c, (r_mul(r_mul(n, n), n)))))
    return(lst(r_add(elem(self$centre_y, j), r_mul(r_mul((r_sub(iy, h)), Simulation$STEP_Y), self$spacing)), r_add(elem(self$centre_b, j), r_mul(r_mul((r_sub(ib, h)), Simulation$STEP_Y), self$spacing)), r_add(elem(self$centre_d, j), r_mul(r_mul(r_mul((r_sub(id, h)), Simulation$STEP_D), self$spacing), elem(mem(S, key_("e_D")), g))), r_add(elem(self$centre_i, j), r_mul(r_mul(r_mul((r_sub(ii, h)), Simulation$STEP_I), self$spacing), elem(mem(S, key_("e_Inc")), g)))))
    NULL
  })
  method(cl, "logpost", function(j = NULL, at = NULL, ...) {
    S <- Sparc$sample$columns
    g <- elem(self$ids, j)
    D <- elem(mem(S, key_("D")), g)
    eD <- elem(mem(S, key_("e_D")), g)
    inc <- elem(mem(S, key_("Inc")), g)
    einc <- elem(mem(S, key_("e_Inc")), g)
    if (truthy((if (truthy(.x <- (if (truthy(.x <- le(elem(at, 2), 0))) .x else le(elem(at, 3), 0.5)))) .x else gt(elem(at, 3), 90)))) {
      return(r_mul(neg(1), r_pow(10, 30)))
    }
    YD <- r_pow(10, elem(at, 0))
    YB <- r_pow(10, elem(at, 1))
    f <- r_div(elem(at, 2), D)
    s <- r_div(m_sin((r_div(r_mul(inc, pi), 180))), m_sin((r_div(r_mul(elem(at, 3), pi), 180))))
    chi <- 0
    .r <- for_range(len(elem(self$rows, j)), function(i) {
      row <- elem(elem(self$rows, j), i)
      if (truthy(gt(elem(row, 6), 0))) {
        p <- elem(elem(self$at_rows, j), i)
        vm <- m_sqrt(Fmt$max(r_mul(r_mul(f, elem(row, 0)), self$felt(r_add(r_add(r_mul(YD, elem(p, 0)), r_mul(YB, elem(p, 2))), elem(p, 1)))), 0))
        d <- r_div((r_sub(r_mul(elem(row, 1), s), vm)), (r_mul(elem(row, 2), s)))
        .w("chi", r_add(chi, r_mul(d, d)))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    py <- r_div((r_sub(elem(at, 0), Fmt$log10(Sparc$YD))), Simulation$PRIOR_Y)
    pb <- (if (truthy(self$has_bulge(j))) r_div((r_sub(elem(at, 1), Fmt$log10(Sparc$YB))), Simulation$PRIOR_Y) else 0)
    pd <- (if (truthy(gt(eD, 0))) r_div((r_sub(elem(at, 2), D)), eD) else 0)
    pi <- (if (truthy(gt(einc, 0))) r_div((r_sub(elem(at, 3), inc)), einc) else 0)
    return(r_mul(neg(0.5), (r_add(r_add(r_add(r_add(chi, r_mul(py, py)), r_mul(pb, pb)), r_mul(pd, pd)), r_mul(pi, pi)))))
    NULL
  })
  method(cl, "settle_fit", function(best = NULL, n = NULL, last = NULL, ...) {
    .r <- for_range(len(self$ids), function(j) {
      at <- self$combo(j, m_round(elem(best, r_mul(2, j))), n)
      set_at(self$centre_y, j, elem(at, 0))
      set_at(self$centre_b, j, elem(at, 1))
      set_at(self$centre_d, j, elem(at, 2))
      set_at(self$centre_i, j, elem(at, 3))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    self$spacing <- r_div(self$spacing, 4)
    if (truthy(last)) {
      self$best_y <- m_map(self$centre_y, function(v = NULL, ...) {
        return(r_pow(10, v))
        NULL
      })
      self$best_b <- m_map(self$centre_b, function(v = NULL, ...) {
        return(r_pow(10, v))
        NULL
      })
      self$best_d <- m_map(self$centre_d, function(v = NULL, ...) {
        return(v)
        NULL
      })
      self$best_i <- m_map(self$centre_i, function(v = NULL, ...) {
        return(v)
        NULL
      })
    }
    NULL
  })
