        th <- r_mul((2 * pi), rng$v_next)
        .r <- for_each(lst(r_add(r0, r_mul((r_sub(r1, r0)), u)), phi, r_mul(mag, m_cos(th)), r_mul(mag, m_sin(th)), 0, 0, 0, 0, 0, 0), function(v) {
          m_push(out, v)
