  field(cl, "film_angles", function() lst())
  field(cl, "film_steps", function() lst())
  field(cl, "film_times", function() lst())
  static_getter(cl, "orientation", function() {
    return(Measured$of("sparc-orientation"))
    NULL
  })
  static_getter(cl, "pixels", function() {
    return(Measured$of("sparc-images"))
    NULL
  })
  static_getter(cl, "image_side", function() {
    I <- Simulation$pixels
    return((if (truthy(eq(I, NULL))) 0 else m_round(m_sqrt((r_div(I$rows, len(Sparc$names)))))))
    NULL
  })
  method(cl, "face_on", function(g = NULL, j = NULL, ...) {
    O <- Simulation$orientation
    I <- Simulation$pixels
    if (truthy((if (truthy(.x <- eq(O, NULL))) .x else eq(I, NULL)))) {
      return(lst(lst(), NaN, neg(1)))
    }
    which <- elem(mem(O$columns, key_("survey")), g)
    if (truthy(lt(which, 0))) {
      return(lst(lst(), NaN, neg(1)))
    }
    P <- Simulation$image_side
    fov <- elem(mem(O$columns, key_("fov")), g)
    D <- elem(mem(Sparc$sample$columns, key_("D")), g)
    inc <- r_div(r_mul(elem(mem(Sparc$sample$columns, key_("Inc")), g), pi), 180)
    per_pixel <- r_mul(r_mul(r_div(r_mul(r_div(fov, P), pi), 180), D), 1000)
    light <- mem(I$columns, key_("light"))
    base <- r_mul(r_mul(g, P), P)
    edge <- lst()
    .r <- for_range(P, function(r) {
      .r <- for_range(P, function(c) {
        if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- lt(r, Simulation$SKY_EDGE))) .x else lt(c, Simulation$SKY_EDGE)))) .x else ge(r, r_sub(P, Simulation$SKY_EDGE))))) .x else ge(c, r_sub(P, Simulation$SKY_EDGE))))) {
          m_push(edge, elem(light, r_add(r_add(base, r_mul(r, P)), c)))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    sky <- Fmt$median(edge)
    reach <- elem(self$reach, j)
    east <- function(c = NULL, ...) {
      return(r_sub(0, r_mul((r_sub(r_add(c, 0.5), r_div(P, 2))), per_pixel)))
      NULL
    }
    north <- function(r = NULL, ...) {
      return(r_mul((r_sub(r_add(r, 0.5), r_div(P, 2))), per_pixel))
      NULL
    }
    pa <- elem(mem(O$columns, key_("pa")), g)
    if (truthy((!truthy(Fmt$finite(pa))))) {
      xx <- 0
      yy <- 0
      xy <- 0
      .r <- for_range(P, function(r) {
        .r <- for_range(P, function(c) {
          f <- Fmt$max(r_sub(elem(light, r_add(r_add(base, r_mul(r, P)), c)), sky), 0)
          e <- (east)(c)
          n <- (north)(r)
          if (truthy(le(Fmt$hypot(e, n), reach))) {
            .w("xx", r_add(xx, r_mul(r_mul(f, e), e)))
            .w("yy", r_add(yy, r_mul(r_mul(f, n), n)))
            .w("xy", r_add(xy, r_mul(r_mul(f, e), n)))
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .w("pa", r_sub(90, r_div(r_mul(r_mul(0.5, m_atan2((r_mul(2, xy)), r_sub(xx, yy))), 180), pi)))
    }
    s <- m_sin((r_div(r_mul(pa, pi), 180)))
    co <- m_cos((r_div(r_mul(pa, pi), 180)))
    squash <- Fmt$max(m_cos(inc), 0.2)
    out <- lst()
    .r <- for_range(P, function(r) {
      .r <- for_range(P, function(c) {
        f <- r_sub(elem(light, r_add(r_add(base, r_mul(r, P)), c)), sky)
        e <- (east)(c)
        n <- (north)(r)
        x <- r_add(r_mul(e, s), r_mul(n, co))
        y <- r_div((r_add(r_sub(0, r_mul(e, co)), r_mul(n, s))), squash)
        if (truthy((if (truthy(.x <- gt(f, 0))) le(Fmt$hypot(x, y), reach) else .x))) {
          m_push(out, lst(x, y, f))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(lst(out, pa, which))
    NULL
  })
  getter(cl, "film_seeds", function() {
    rng <- Random$new(seed = 11)
    out <- lst()
    self$film_sources <- lst()
    self$film_angles <- lst()
    stir <- function(unused = NULL, ...) {
      mag <- m_sqrt((r_mul(neg(2), m_ln(Fmt$max(rng$v_next, 0.000001)))))
      th <- r_mul((2 * pi), rng$v_next)
      return(lst(r_mul(mag, m_cos(th)), r_mul(mag, m_sin(th))))
      NULL
    }
    .r <- for_each(self$film_ids, function(g) {
      j <- m_index_of(self$ids, g)
      laid <- self$face_on(g, j)
      pixels <- elem(laid, 0)
      if (truthy(gt(len(pixels), 0))) {
        m_push(self$film_sources, elem(Simulation$SURVEY_NAMES, elem(laid, 2)))
        m_push(self$film_angles, elem(laid, 1))
        fs <- Expr$sorted(m_map(pixels, function(p = NULL, ...) {
          return(elem(p, 2))
          NULL
        }))
        cap <- elem(fs, m_floor((r_mul((r_sub(len(fs), 1)), Simulation$BRIGHTEST))))
        run <- lst()
        total <- 0
        .r <- for_each(pixels, function(p) {
          .w("total", r_add(total, Fmt$min(elem(p, 2), cap)))
          m_push(run, total)
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        O <- Simulation$orientation
        width <- r_mul(r_mul(r_div(r_mul(r_div(elem(mem(O$columns, key_("fov")), g), Simulation$image_side), pi), 180), elem(mem(Sparc$sample$columns, key_("D")), g)), 1000)
        .r <- for_range(Simulation$FILM_STARS, function(k) {
          want <- r_mul(rng$v_next, total)
          lo <- 0
          hi <- r_sub(len(run), 1)
          while (truthy(lt(lo, hi))) {
            mid <- m_floor((r_div((r_add(lo, hi)), 2)))
            if (truthy(lt(elem(run, mid), want))) {
              .w("lo", r_add(mid, 1))
            } else {
              .w("hi", mid)
            }
          }
          x <- r_add(elem(elem(pixels, lo), 0), r_mul((r_sub(rng$v_next, 0.5)), width))
          y <- r_add(elem(elem(pixels, lo), 1), r_mul((r_sub(rng$v_next, 0.5)), width))
          kick <- (stir)(0)
          .r <- for_each(lst(Fmt$hypot(x, y), m_atan2(y, x), elem(kick, 0), elem(kick, 1), 0, 0, 0, 0, 0, 0), function(v) {
            m_push(out, v)
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
      } else {
        m_push(self$film_sources, "the run's own annuli")
        m_push(self$film_angles, NaN)
        es <- elem(self$edges, j)
        rs <- elem(self$rows, j)
        masses <- lst()
        .r <- for_range(r_sub(len(es), 1), function(a) {
          m_push(masses, lst(elem(es, a), elem(es, r_add(a, 1)), r_add(r_mul(Sparc$YD, elem(elem(self$w_discs, j), a)), elem(elem(self$w_gases, j), a))))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        last <- 0
        .r <- for_range(len(rs), function(i) {
          inside <- r_mul(r_mul(r_mul(Sparc$YB, elem(elem(rs, i), 5)), m_abs(elem(elem(rs, i), 5))), elem(elem(rs, i), 0))
          if (truthy(gt(inside, last))) {
            m_push(masses, lst((if (truthy(eq(i, 0))) 0 else elem(elem(rs, r_sub(i, 1)), 0)), elem(elem(rs, i), 0), r_sub(inside, last)))
            .w("last", inside)
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        run <- lst()
        total <- 0
        .r <- for_each(masses, function(m) {
          .w("total", r_add(total, Fmt$max(elem(m, 2), 0)))
          m_push(run, total)
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        .r <- for_range(Simulation$FILM_STARS, function(k) {
          want <- r_mul(rng$v_next, total)
          a <- 0
          while (truthy((if (truthy(.x <- lt(a, r_sub(len(run), 1)))) lt(elem(run, a), want) else .x))) {
            .w("a", r_add(a, 1))
          }
          e0 <- elem(elem(masses, a), 0)
          e1 <- elem(elem(masses, a), 1)
          r <- m_sqrt((r_add(r_mul(e0, e0), r_mul(rng$v_next, (r_sub(r_mul(e1, e1), r_mul(e0, e0)))))))
          kick <- (stir)(0)
          .r <- for_each(lst(r, r_mul((2 * pi), rng$v_next), elem(kick, 0), elem(kick, 1), 0, 0, 0, 0, 0, 0), function(v) {
            m_push(out, v)
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  method(cl, "film_table", function(felt_table = NULL, ...) {
    out <- lst()
    .r <- for_each(self$film_ids, function(g) {
