      .r <- for_range(Simulation$TABLE, function(t) {
        m_push(out, elem(felt_table, r_add(r_mul(j, Simulation$TABLE), t)))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  method(cl, "film_runs", function(felt_table = NULL, ...) {
    out <- lst()
    self$film_steps <- lst()
    self$film_times <- lst()
    .r <- for_range(len(self$film_ids), function(k) {
      j <- m_index_of(self$ids, elem(self$film_ids, k))
      rs <- elem(self$rows, j)
      inner <- self$turn(felt_table, j, elem(elem(rs, 0), 0))
      outer <- self$turn(felt_table, j, elem(elem(rs, r_sub(len(rs), 1)), 0))
      ok <- (if (truthy(.x <- (if (truthy(.x <- Fmt$finite(inner))) Fmt$finite(outer) else .x))) gt(inner, 0) else .x)
      total <- (if (truthy(ok)) r_mul(Simulation$FILM_TURNS, outer) else 0)
      n <- (if (truthy(ok)) Fmt$min(Simulation$CAP, r_add(m_floor((r_div(total, (r_div(inner, Simulation$PER_ORBIT))))), 1)) else 0)
      dt <- (if (truthy(gt(n, 0))) r_div(total, n) else 0)
      every <- Fmt$max(1, m_floor((r_div(n, Simulation$FRAMES))))
      last <- elem(elem(self$tables, j), r_sub(Simulation$TABLE, 1))
      edge <- r_add(r_add(r_mul(Sparc$YD, elem(last, 1)), r_mul(Sparc$YB, elem(last, 3))), elem(last, 2))
      m_push(self$film_steps, r_mul(every, Simulation$FRAMES))
      m_push(self$film_times, r_mul(r_mul(r_mul(dt, every), Simulation$FRAMES), Simulation$MYR))
      .r <- for_each(lst(elem(self$reach, j), dt, r_mul(every, Simulation$FRAMES), r_mul(every, Simulation$FRAMES), k, edge, self$a0, every, 0, Simulation$SIGMA, 0, 0), function(v) {
        m_push(out, v)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  getter(cl, "most_film_steps", function() {
    m <- 0
    .r <- for_each(self$film_steps, function(n) {
      .w("m", Fmt$max(m, n))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(m)
    NULL
  })
  method(cl, "save", function(felt0 = NULL, felt1 = NULL, stars = NULL, frames = NULL, ...) {
    S <- Sparc$sample$columns
    T <- Simulation$TABLE
    nrows <- 0
    .r <- for_each(self$rows, function(rs) {
      .w("nrows", r_add(nrows, len(rs)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    cols <- Node$new()
    names <- lst("galaxy", "R", "Vobs", "e_Vobs", "gd", "gg", "gb", "v0", "v1", "vs", "kept")
    .r <- for_each(names, function(nm_) {
      set_at(cols, nm_, lst())
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    rms0 <- lst()
    rms1 <- lst()
    k <- 0
    .r <- for_range(len(self$ids), function(j) {
      g <- elem(self$ids, j)
      rs <- elem(self$rows, j)
      es <- elem(self$edges, j)
      f <- r_div(elem(self$best_d, j), elem(mem(S, key_("D")), g))
      s <- r_div(m_sin((r_div(r_mul(elem(mem(S, key_("Inc")), g), pi), 180))), m_sin((r_div(r_mul(elem(self$best_i, j), pi), 180))))
      heap <- m_map(rng(len(rs)), function(i = NULL, ...) {
        return(lst())
        NULL
      })
      .r <- for_range(Simulation$STARS, function(q) {
        at <- r_mul((r_add(r_mul(j, Simulation$STARS), q)), 10)
        if (truthy(gt(elem(stars, r_add(at, 8)), 0))) {
          r <- r_div(elem(stars, r_add(at, 6)), elem(stars, r_add(at, 8)))
          v <- r_div(elem(stars, r_add(at, 7)), elem(stars, r_add(at, 8)))
          b <- 0
          while (truthy((if (truthy(.x <- lt(b, len(rs)))) lt(elem(es, r_add(b, 2)), r) else .x))) {
            .w("b", r_add(b, 1))
          }
          if (truthy(lt(b, len(rs)))) {
            m_push(elem(heap, b), v)
          }
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      o0 <- lst()
      o1 <- lst()
      .r <- for_range(len(rs), function(i) {
        row <- elem(rs, i)
        p <- elem(elem(self$at_rows, j), i)
        v0 <- m_sqrt(Fmt$max(r_mul(elem(row, 0), elem(felt0, k)), 0))
        v1 <- r_div(m_sqrt(Fmt$max(r_mul(r_mul(f, elem(row, 0)), elem(felt1, k)), 0)), s)
        vs <- (if (truthy(m_empty(elem(heap, i)))) NaN else Fmt$median(elem(heap, i)))
        vals <- lst(g, elem(row, 0), elem(row, 1), elem(row, 2), elem(p, 0), elem(p, 1), elem(p, 2), v0, v1, vs, elem(row, 6))
        .r <- for_range(len(names), function(c) {
          m_push(elem(cols, elem(names, c)), elem(vals, c))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        if (truthy((if (truthy(.x <- (if (truthy(.x <- gt(elem(row, 6), 0))) gt(v0, 0) else .x))) gt(v1, 0) else .x))) {
          m_push(o0, Fmt$log10(r_div(v0, elem(row, 1))))
          m_push(o1, Fmt$log10(r_div(v1, elem(row, 1))))
        }
        .w("k", r_add(k, 1))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      m_push(rms0, Simulation$rms(o0))
      m_push(rms1, Simulation$rms(o1))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    extra <- Node$new()
    .set(extra, key_("deg"), self$deg)
    .set(extra, key_("a0"), self$a0_si)
    .set(extra, key_("unit"), Simulation$UNIT_G)
    .set(extra, key_("ids"), self$ids)
    .set(extra, key_("names"), m_map(self$ids, function(g = NULL, ...) {
      return(elem(Sparc$names, g))
      NULL
    }))
    .set(extra, key_("Y_disk"), self$best_y)
    .set(extra, key_("Y_bulge"), self$best_b)
    .set(extra, key_("D"), self$best_d)
    .set(extra, key_("Inc"), self$best_i)
    .set(extra, key_("rms0"), rms0)
    .set(extra, key_("rms1"), rms1)
    .set(extra, key_("repro"), self$repro)
    .set(extra, key_("stir"), Simulation$SIGMA)
    .set(extra, key_("about"), "every measured radius of every galaxy run: the laid galaxy's disc, gas and bulge pull (mass-to-light one, (km/s)^2/kpc), the circular speed at SPARC's own freedoms (v0) and at the fitted ones as the data would see them (v1), what the tracers moved at (vs); per galaxy in the header the fitted freedoms and the rms in dex")
    Measure$save("galaxy.simulated", names, cols, extra)
    fields <- Node$new()
    fnames <- lst("galaxy", "r", "gd", "gg", "gb", "v0", "v1", "vN")
    .r <- for_each(fnames, function(nm_) {
      set_at(fields, nm_, lst())
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_range(len(self$ids), function(j) {
      g <- elem(self$ids, j)
      f <- r_div(elem(self$best_d, j), elem(mem(S, key_("D")), g))
      s <- r_div(m_sin((r_div(r_mul(elem(mem(S, key_("Inc")), g), pi), 180))), m_sin((r_div(r_mul(elem(self$best_i, j), pi), 180))))
      .r <- for_range(T, function(t) {
        row <- elem(elem(self$tables, j), t)
        gN <- r_add(r_add(r_mul(Sparc$YD, elem(row, 1)), r_mul(Sparc$YB, elem(row, 3))), elem(row, 2))
        v0 <- m_sqrt(Fmt$max(r_mul(elem(row, 0), elem(felt0, r_add(k, t))), 0))
        v1 <- r_div(m_sqrt(Fmt$max(r_mul(r_mul(f, elem(row, 0)), elem(felt1, r_add(k, t))), 0)), s)
        vals <- lst(g, elem(row, 0), elem(row, 1), elem(row, 2), elem(row, 3), v0, v1, m_sqrt(Fmt$max(r_mul(elem(row, 0), gN), 0)))
        .r <- for_range(len(fnames), function(c) {
          m_push(elem(fields, elem(fnames, c)), elem(vals, c))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .w("k", r_add(k, T))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    fextra <- Node$new()
    .set(fextra, key_("ids"), self$ids)
    .set(fextra, key_("table"), T)
    .set(fextra, key_("about"), "the laid galaxy's field on the table, every galaxy run: disc, gas and bulge at mass-to-light one, the circular speed at SPARC's freedoms (v0), at the fitted ones as the data would see them (v1), and Newton at SPARC's (vN)")
    Measure$save("galaxy.fields", fnames, fields, fextra)
    if (truthy((!truthy(m_empty(self$film_ids))))) {
      film <- Node$new()
      .set(film, key_("x"), lst())
      .set(film, key_("y"), lst())
      .r <- for_range(m_floor((r_div(len(frames), 2))), function(i) {
        m_push(mem(film, key_("x")), elem(frames, r_mul(2, i)))
        m_push(mem(film, key_("y")), elem(frames, r_add(r_mul(2, i), 1)))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      sextra <- Node$new()
      .set(sextra, key_("film"), self$film_ids)
      .set(sextra, key_("names"), m_map(self$film_ids, function(g = NULL, ...) {
        return(elem(Sparc$names, g))
        NULL
      }))
      .set(sextra, key_("stars"), Simulation$FILM_STARS)
      .set(sextra, key_("frames"), Simulation$FRAMES)
      .set(sextra, key_("reach"), m_map(self$film_ids, function(g = NULL, ...) {
        return(elem(self$reach, m_index_of(self$ids, g)))
        NULL
      }))
      .set(sextra, key_("source"), self$film_sources)
      .set(sextra, key_("pa"), self$film_angles)
      .set(sextra, key_("span"), self$film_times)
      .set(sextra, key_("about"), "the filmed galaxies face on, their stars laid where the light is (or the laid mass, where there is no image): x and y in kpc, star after star, frame after frame, from the moment the picture was taken, over FILM_TURNS of the outermost radius; span in Myr")
      return(Measure$save("galaxy.stars", lst("x", "y"), film, sextra))
    }
    NULL
  })
  statik(cl, "rms", function(xs_ = NULL, ...) {
    if (truthy(m_empty(xs_))) {
      return(NaN)
    }
    s <- 0
    .r <- for_each(xs_, function(v) {
      .w("s", r_add(s, r_mul(v, v)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(m_sqrt((r_div(s, len(xs_)))))
    NULL
  })
  statik(cl, "shape_x", function(i = NULL, ...) {
    return(r_pow(10, (r_add(neg(2), r_div(r_mul(3.6, i), r_sub(Simulation$SHAPE_N, 1))))))
    NULL
  })
  statik(cl, "shape_edge", function(a = NULL, ...) {
    return(r_div(r_mul(15, a), Simulation$SHAPE_EDGES))
    NULL
  })
  statik(cl, "shape_mass", function(a = NULL, ...) {
    e0 <- Simulation$shape_edge(a)
    e1 <- Simulation$shape_edge(r_add(a, 1))
    return(r_sub(r_mul((r_add(1, e0)), m_exp((r_sub(0, e0)))), r_mul((r_add(1, e1)), m_exp((r_sub(0, e1))))))
    NULL
  })
  static_getter(cl, "shape_tasks", function() {
    out <- lst()
    .r <- for_range(Simulation$SHAPE_N, function(i) {
      .r <- for_range(Simulation$SHAPE_EDGES, function(a) {
        .r <- for_each(lst(Simulation$shape_x(i), Simulation$shape_edge(a), Simulation$shape_edge(r_add(a, 1)), Simulation$SHAPE_H), function(v) {
          m_push(out, v)
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  statik(cl, "shape_of", function(pulls = NULL, ...) {
    return(m_map(rng(Simulation$SHAPE_N), function(i = NULL, ...) {
      s <- 0
      .r <- for_range(Simulation$SHAPE_EDGES, function(a) {
        .w("s", r_add(s, r_mul(Simulation$shape_mass(a), elem(pulls, r_add(r_mul(i, Simulation$SHAPE_EDGES), a)))))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      return(s)
      NULL
    }))
    NULL
  })
  statik(cl, "shape_at", function(shape = NULL, x = NULL, ...) {
    lx <- Fmt$log10(x)
    u <- r_mul(r_div((r_add(lx, 2)), 3.6), r_sub(Simulation$SHAPE_N, 1))
    if (truthy(le(u, 0))) {
      return(r_div(r_mul(elem(shape, 0), x), Simulation$shape_x(0)))
    }
    if (truthy(ge(u, r_sub(Simulation$SHAPE_N, 1)))) {
      return(r_mul(elem(shape, r_sub(Simulation$SHAPE_N, 1)), r_pow((r_div(Simulation$shape_x(r_sub(Simulation$SHAPE_N, 1)), x)), 2)))
    }
    i <- m_floor(u)
    f <- r_sub(u, i)
    return(r_add(r_mul(elem(shape, i), (r_sub(1, f))), r_mul(elem(shape, r_add(i, 1)), f)))
    NULL
  })
  statik(cl, "axis", function(a = NULL, i = NULL, ...) {
    return(r_add(elem(a, 0), r_div(r_mul((r_sub(elem(a, 1), elem(a, 0))), i), r_sub(elem(a, 2), 1))))
    NULL
  })
  statik(cl, "possible_points", function(shape = NULL, ...) {
    out <- lst()
    .r <- for_range(elem(Simulation$MASSES, 2), function(which_m) {
      M <- r_pow(10, Simulation$axis(Simulation$MASSES, which_m))
      .r <- for_range(elem(Simulation$SCALES, 2), function(which_s) {
        rd <- r_pow(10, Simulation$axis(Simulation$SCALES, which_s))
        .r <- for_each(Simulation$GAS, function(fg) {
          .r <- for_each(Simulation$GAS_WIDE, function(wide) {
            .r <- for_each(Simulation$BULGE, function(fb) {
              GM <- r_mul(Simulation$G_KPC, M)
              disc <- r_mul(r_mul(GM, (r_sub(1, fg))), (r_sub(1, fb)))
              gas <- r_mul(GM, fg)
              bul <- r_mul(r_mul(GM, (r_sub(1, fg))), fb)
              rg <- r_mul(rd, wide)
              .r <- for_range(Simulation$RADII, function(k) {
                r <- r_mul(rd, r_pow(10, (r_add(neg(0.7), r_div(r_mul(1.6, k), r_sub(Simulation$RADII, 1))))))
                gN <- r_add(r_add(r_mul(r_div(disc, (r_mul(rd, rd))), Simulation$shape_at(shape, r_div(r, rd))), r_mul(r_div(gas, (r_mul(rg, rg))), Simulation$shape_at(shape, r_div(r, rg)))), r_div(bul, (r_pow((r_add(r, r_mul(Simulation$BULGE_A, rd))), 2))))
                .r <- for_each(lst(0, r, gN, 0, 0, 0), function(v) {
                  m_push(out, v)
                  CONTINUE
                })
                if (!is.null(.r)) return(.r[[1]])
                CONTINUE
              })
              if (!is.null(.r)) return(.r[[1]])
              CONTINUE
            })
            if (!is.null(.r)) return(.r[[1]])
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  statik(cl, "binned", function(points = NULL, felt = NULL, ...) {
    n <- r_add(m_round((r_div((r_sub(Galaxies$XMAX, Galaxies$XMIN)), Simulation$BIN))), 1)
    landed <- filled(n, 0)
    heights <- filled(n, 0)
    lo <- filled(n, NaN)
    hi <- filled(n, NaN)
    .r <- for_range(len(felt), function(i) {
      gN <- elem(points, r_add(r_mul(6, i), 2))
      g <- elem(felt, i)
      if (truthy((if (truthy(.x <- gt(gN, 0))) gt(g, 0) else .x))) {
        x <- Fmt$log10(r_div(r_mul(gN, Simulation$UNIT_G), Galaxies$A0_DATA))
        y <- Fmt$log10(r_div(r_mul(g, Simulation$UNIT_G), Galaxies$A0_DATA))
        b <- m_round((r_div((r_sub(x, Galaxies$XMIN)), Simulation$BIN)))
        if (truthy((if (truthy(.x <- ge(b, 0))) lt(b, n) else .x))) {
          set_at(landed, b, r_add(elem(landed, b), 1))
          set_at(heights, b, r_add(elem(heights, b), y))
          set_at(lo, b, (if (truthy(Fmt$finite(elem(lo, b)))) Fmt$min(elem(lo, b), y) else y))
          set_at(hi, b, (if (truthy(Fmt$finite(elem(hi, b)))) Fmt$max(elem(hi, b), y) else y))
        }
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(lst(landed, m_map(rng(n), function(b = NULL, ...) {
      return((if (truthy(gt(elem(landed, b), 0))) r_div(elem(heights, b), elem(landed, b)) else NaN))
      NULL
    }), lo, hi))
    NULL
  })
  statik(cl, "save_possible", function(degs = NULL, a0s = NULL, bins = NULL, ...) {
    cols <- Node$new()
    .set(cols, key_("deg"), degs)
    .set(cols, key_("a0"), a0s)
    extra <- Node$new()
    .set(extra, key_("bins"), bins)
    .set(extra, key_("from"), Galaxies$XMIN)
    .set(extra, key_("step"), Simulation$BIN)
    .set(extra, key_("axes"), lst("log M (Msun)", Simulation$MASSES, "log R_d (kpc)", Simulation$SCALES, "gas share", Simulation$GAS, "gas scale / R_d", Simulation$GAS_WIDE, "bulge share of the stars", Simulation$BULGE))
    .set(extra, key_("about"), "every galaxy there could be, run through the same field and law, per lattice: in bins of log(g_bar / 1.2e-10), how many (galaxy, radius) land there, and log(g / 1.2e-10) - mean, lowest, highest")
    return(Measure$save("galaxy.possible", lst("deg", "a0"), cols, extra))
    NULL
  })
})

Formed <- ray_class("Formed", Node, function(cl) {
  field(cl, "deg", NULL)
  static_field(cl, "N", function() 16384)
  static_field(cl, "TILE", function() 256)
  static_field(cl, "Q", function() 1.2)
  static_field(cl, "STEPS", function() 3000)
  static_field(cl, "DT", function() 0.001)
  static_field(cl, "FRAMES", function() 120)
  static_field(cl, "GRID", function() 128)
  static_field(cl, "TRUNC", function() 5)
  static_field(cl, "SPAN", function() 6)
  static_field(cl, "RINGS", function() 48)
  static_field(cl, "DISCS", function() lst(lst(10.7, 3), lst(9.3, 2)))
  static_field(cl, "WHAT", function() lst("a bright disc", "a dwarf"))
  field(cl, "a0", function() r_div(Galaxies$a0_at(self$deg), Simulation$UNIT_G))
  field(cl, "newton", function() FALSE)
  getter(cl, "scale_a0", function() {
    return((if (truthy(self$newton)) 0 else self$a0))
    NULL
  })
  getter(cl, "discs_n", function() {
    return(len(Formed$DISCS))
    NULL
  })
  method(cl, "GM", function(g = NULL, ...) {
    return(r_mul(Simulation$G_KPC, r_pow(10, elem(elem(Formed$DISCS, g), 0))))
    NULL
  })
  method(cl, "scale", function(g = NULL, ...) {
    return(elem(elem(Formed$DISCS, g), 1))
    NULL
  })
  method(cl, "soft", function(g = NULL, ...) {
    return(r_mul(Simulation$SHAPE_H, self$scale(g)))
    NULL
  })
  statik(cl, "inside", function(x = NULL, ...) {
    return(r_sub(1, r_mul((r_add(1, x)), m_exp((r_sub(0, x))))))
    NULL
  })
  getter(cl, "seeds", function() {
    rng <- Random$new(seed = 23)
    out <- lst()
    .r <- for_range(self$discs_n, function(g) {
      rd <- self$scale(g)
      top <- Formed$inside(Formed$TRUNC)
      .r <- for_range(Formed$N, function(k) {
        want <- r_mul(rng$v_next, top)
        lo <- 0
        hi <- Formed$TRUNC
        .r <- for_range(40, function(it) {
          mid <- r_div((r_add(lo, hi)), 2)
          if (truthy(lt(Formed$inside(mid), want))) {
            .w("lo", mid)
          } else {
            .w("hi", mid)
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        r <- r_mul(r_div((r_add(lo, hi)), 2), rd)
        th <- r_mul((2 * pi), rng$v_next)
        .r <- for_each(lst(r_mul(r, m_cos(th)), r_mul(r, m_sin(th)), 0, 0), function(v) {
          m_push(out, v)
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  getter(cl, "constants", function() {
    out <- lst()
    .r <- for_range(self$discs_n, function(g) {
      .r <- for_each(lst(r_div(self$GM(g), Formed$N), self$soft(g), self$scale_a0, Formed$DT), function(v) {
        m_push(out, v)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  method(cl, "accel_cpu", function(state = NULL, i = NULL, ...) {
    g <- m_floor((r_div(i, Formed$N)))
    e2 <- r_mul(self$soft(g), self$soft(g))
    px <- elem(state, r_mul(4, i))
    py <- elem(state, r_add(r_mul(4, i), 1))
    sx <- 0
    sy <- 0
    .r <- for_range(Formed$N, function(k) {
      j <- r_add(r_mul(g, Formed$N), k)
      dx <- r_sub(elem(state, r_mul(4, j)), px)
      dy <- r_sub(elem(state, r_add(r_mul(4, j), 1)), py)
      r2 <- r_add(r_add(r_mul(dx, dx), r_mul(dy, dy)), e2)
      w <- r_div(1, (r_mul(r2, m_sqrt(r2))))
      .w("sx", r_add(sx, r_mul(dx, w)))
      .w("sy", r_add(sy, r_mul(dy, w)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    m <- r_div(self$GM(g), Formed$N)
    gx <- r_mul(m, sx)
    gy <- r_mul(m, sy)
    mag <- Fmt$hypot(gx, gy)
    f <- (if (truthy(gt(mag, 0))) ((if (truthy(self$newton)) mag else Law$boost(mag, self$a0))) else 0)
    return((if (truthy(gt(mag, 0))) lst(r_mul(r_div(gx, mag), f), r_mul(r_div(gy, mag), f), mag, f) else lst(0, 0, 0, 0)))
    NULL
  })
  method(cl, "launch", function(state = NULL, acc = NULL, ...) {
    rng <- Random$new(seed = 29)
    out <- m_map(state, function(v = NULL, ...) {
      return(v)
      NULL
    })
    .r <- for_range(self$discs_n, function(g) {
      rd <- self$scale(g)
      width <- r_div(r_mul(Formed$TRUNC, rd), Formed$RINGS)
      pull <- filled(Formed$RINGS, 0)
      lift <- filled(Formed$RINGS, 0)
      many <- filled(Formed$RINGS, 0)
      .r <- for_range(Formed$N, function(k) {
        i <- r_add(r_mul(g, Formed$N), k)
        x <- elem(state, r_mul(4, i))
        y <- elem(state, r_add(r_mul(4, i), 1))
        r <- Fmt$hypot(x, y)
        b <- m_floor((r_div(r, width)))
        if (truthy((if (truthy(.x <- lt(b, Formed$RINGS))) gt(r, 0) else .x))) {
          set_at(pull, b, r_add(elem(pull, b), r_div((r_sub(r_sub(0, r_mul(elem(acc, r_mul(4, i)), x)), r_mul(elem(acc, r_add(r_mul(4, i), 1)), y))), r)))
          set_at(lift, b, r_add(elem(lift, b), ((if (truthy(gt(elem(acc, r_add(r_mul(4, i), 2)), 0))) r_div(elem(acc, r_add(r_mul(4, i), 3)), elem(acc, r_add(r_mul(4, i), 2))) else 1))))
          set_at(many, b, r_add(elem(many, b), 1))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      ring_r <- function(b = NULL, ...) {
        return(r_mul((r_add(b, 0.5)), width))
        NULL
      }
      omega2 <- m_map(rng(Formed$RINGS), function(b = NULL, ...) {
        return((if (truthy(gt(elem(many, b), 0))) r_div(Fmt$max(r_div(elem(pull, b), elem(many, b)), 0), (ring_r)(b)) else 0))
        NULL
      })
      nu <- m_map(rng(Formed$RINGS), function(b = NULL, ...) {
        return((if (truthy(gt(elem(many, b), 0))) r_div(elem(lift, b), elem(many, b)) else 1))
        NULL
      })
      kappa2 <- m_map(rng(Formed$RINGS), function(b = NULL, ...) {
        lo <- Fmt$max(r_sub(b, 1), 0)
        hi <- Fmt$min(r_add(b, 1), r_sub(Formed$RINGS, 1))
        slope <- r_div((r_sub(elem(omega2, hi), elem(omega2, lo))), (r_sub((ring_r)(hi), (ring_r)(lo))))
        return(Fmt$max(r_add(r_mul((ring_r)(b), slope), r_mul(4, elem(omega2, b))), r_mul(0.25, elem(omega2, b))))
        NULL
      })
      sigma_gm <- r_div(self$GM(g), (r_mul(r_mul(r_mul(r_mul(2, pi), rd), rd), Formed$inside(Formed$TRUNC))))
      .r <- for_range(Formed$N, function(k) {
        i <- r_add(r_mul(g, Formed$N), k)
        x <- elem(state, r_mul(4, i))
        y <- elem(state, r_add(r_mul(4, i), 1))
        r <- Fmt$hypot(x, y)
        b <- Fmt$min(m_floor((r_div(r, width))), r_sub(Formed$RINGS, 1))
        o2 <- elem(omega2, b)
        k2 <- elem(kappa2, b)
        surface <- r_mul(sigma_gm, m_exp((r_sub(0, r_div(r, rd)))))
        sr <- (if (truthy(gt(k2, 0))) r_div(r_mul(r_mul(r_mul(Formed$Q, 3.36), elem(nu, b)), surface), m_sqrt(k2)) else 0)
        sp <- (if (truthy(gt(o2, 0))) r_div(r_mul(sr, m_sqrt(k2)), (r_mul(2, m_sqrt(o2)))) else 0)
        vc2 <- r_mul(r_mul(o2, r), r)
        vphi <- m_sqrt(Fmt$max(r_add(vc2, r_mul(r_mul(sr, sr), (r_sub(r_sub(1, ((if (truthy(gt(o2, 0))) r_div(k2, (r_mul(4, o2))) else 1))), r_div(r_mul(2, r), rd))))), 0))
        mag <- m_sqrt((r_mul(neg(2), m_ln(Fmt$max(rng$v_next, 0.000001)))))
        th <- r_mul((2 * pi), rng$v_next)
        vr <- r_mul(r_mul(sr, mag), m_cos(th))
        vt <- r_add(vphi, r_mul(r_mul(sp, mag), m_sin(th)))
        ux <- (if (truthy(gt(r, 0))) r_div(x, r) else 1)
        uy <- (if (truthy(gt(r, 0))) r_div(y, r) else 0)
        set_at(out, r_add(r_mul(4, i), 2), r_sub(r_mul(vr, ux), r_mul(vt, uy)))
        set_at(out, r_add(r_mul(4, i), 3), r_add(r_mul(vr, uy), r_mul(vt, ux)))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      .r <- for_range(4, function(slot) {
        mean <- 0
        .r <- for_range(Formed$N, function(k) {
          .w("mean", r_add(mean, elem(out, r_add(r_mul(4, (r_add(r_mul(g, Formed$N), k))), slot))))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        .w("mean", r_div(mean, Formed$N))
        .r <- for_range(Formed$N, function(k) {
          set_at(out, r_add(r_mul(4, (r_add(r_mul(g, Formed$N), k))), slot), r_sub(elem(out, r_add(r_mul(4, (r_add(r_mul(g, Formed$N), k))), slot)), mean))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  field(cl, "middles", function() lst())
  method(cl, "binned", function(state = NULL, ...) {
    G <- Formed$GRID
    out <- filled(r_mul(r_mul(self$discs_n, G), G), 0)
    here <- lst()
    .r <- for_range(self$discs_n, function(g) {
      half <- r_mul(Formed$SPAN, self$scale(g))
      mid <- lst(0, 0, 0, 0)
      .r <- for_range(Formed$N, function(k) {
        .r <- for_range(4, function(slot) {
          set_at(mid, slot, r_add(elem(mid, slot), r_div(elem(state, r_add(r_mul(4, (r_add(r_mul(g, Formed$N), k))), slot)), Formed$N)))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      m_push(here, mid)
      .r <- for_range(Formed$N, function(k) {
        i <- r_add(r_mul(g, Formed$N), k)
        cx <- m_floor((r_mul(r_div((r_add(r_sub(elem(state, r_mul(4, i)), elem(mid, 0)), half)), (r_mul(2, half))), G)))
        cy <- m_floor((r_mul(r_div((r_add(r_sub(elem(state, r_add(r_mul(4, i), 1)), elem(mid, 1)), half)), (r_mul(2, half))), G)))
        if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- ge(cx, 0))) ge(cy, 0) else .x))) lt(cx, G) else .x))) lt(cy, G) else .x))) {
          at <- r_add(r_add(r_mul(r_mul(g, G), G), r_mul(cy, G)), cx)
          set_at(out, at, r_add(elem(out, at), 1))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    m_push(self$middles, here)
    return(out)
    NULL
  })
  method(cl, "save", function(frames = NULL, ...) {
    G <- Formed$GRID
    density <- lst()
    .r <- for_range(self$discs_n, function(g) {
      .r <- for_each(frames, function(f) {
        .r <- for_range(r_mul(G, G), function(c) {
          m_push(density, elem(f, r_add(r_mul(r_mul(g, G), G), c)))
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    cols <- Node$new()
    .set(cols, key_("density"), density)
    extra <- Node$new()
    .set(extra, key_("names"), Formed$WHAT)
    .set(extra, key_("mass"), m_map(Formed$DISCS, function(d = NULL, ...) {
      return(r_pow(10, elem(d, 0)))
      NULL
    }))
    .set(extra, key_("scale"), m_map(Formed$DISCS, function(d = NULL, ...) {
      return(elem(d, 1))
      NULL
    }))
    .set(extra, key_("span"), m_map(Formed$DISCS, function(d = NULL, ...) {
      return(r_mul(Formed$SPAN, elem(d, 1)))
      NULL
    }))
    .set(extra, key_("stars"), Formed$N)
    .set(extra, key_("Q"), Formed$Q)
    .set(extra, key_("frames"), len(frames))
    .set(extra, key_("grid"), G)
    .set(extra, key_("gyr"), r_div(r_mul(r_mul(Formed$STEPS, Formed$DT), Simulation$MYR), 1000))
    .set(extra, key_("middles"), self$middles)
    .set(extra, key_("deg"), self$deg)
    .set(extra, key_("a0"), r_mul(self$a0, Simulation$UNIT_G))
    .set(extra, key_("about"), "discs of stars that pull each other through the law, from smooth to whatever forms: star counts on grid x grid cells, span kpc either side of the middle, frame after frame, galaxy after galaxy")
    return(Measure$save("galaxy.formed", lst("density"), cols, extra))
    NULL
  })
  static_getter(cl, "kernel", function() {
    return(m_join(lst("// GENERATED from Formed.ray: stars that pull each other through the law", "@group(0) @binding(0) var<storage, read> P: array<u32>;", "@group(0) @binding(1) var<storage, read> L: array<f32>;", "@group(0) @binding(2) var<storage, read> C: array<f32>;", "@group(0) @binding(3) var<storage, read_write> X: array<f32>;", "@group(0) @binding(4) var<storage, read_write> A: array<f32>;", "var<workgroup> tile: array<vec2<f32>, " %+% text_of(Formed$TILE) %+% ">;", Simulation$law_wgsl, "@compute @workgroup_size(" %+% text_of(Formed$TILE) %+% ") fn ACCEL(@builtin(global_invocation_id) gid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>) {", "  let i: u32 = P[7] + gid.x;", "  let per: u32 = P[1];", "  let g: u32 = i / per;", "  let base: u32 = g * per;", "  let me: vec2<f32> = vec2<f32>(X[4u * i], X[4u * i + 1u]);", "  let e2: f32 = C[4u * g + 1u] * C[4u * g + 1u];", "  var s: vec2<f32> = vec2<f32>(0.0, 0.0);", "  for (var t: u32 = 0u; t < per; t = t + " %+% text_of(Formed$TILE) %+% "u) {", "    let j: u32 = base + t + lid.x;", "    tile[lid.x] = vec2<f32>(X[4u * j], X[4u * j + 1u]);", "    workgroupBarrier();", "    for (var k: u32 = 0u; k < " %+% text_of(Formed$TILE) %+% "u; k = k + 1u) {", "      let d: vec2<f32> = tile[k] - me;", "      let inv: f32 = inverseSqrt(dot(d, d) + e2);", "      s = s + d * (inv * inv * inv);", "    }", "    workgroupBarrier();", "  }", "  let gN: vec2<f32> = C[4u * g] * s;", "  let mag: f32 = length(gN);", "  var a: vec2<f32> = vec2<f32>(0.0, 0.0);", "  var f: f32 = 0.0;", "  if (mag > 0.0) {", "    f = mag;", "    if (C[4u * g + 2u] > 0.0) { f = felt(mag, C[4u * g + 2u]); }", "    a = gN / mag * f;", "  }", "  A[4u * i] = a.x;", "  A[4u * i + 1u] = a.y;", "  A[4u * i + 2u] = mag;", "  A[4u * i + 3u] = f;", "}", "" %+% text_of(Simulation$ENTRY) %+% " KICKDRIFT" %+% text_of(Simulation$ID) %+% "", Simulation$THREAD, "  if (i >= P[0]) { return; }", "  let dt: f32 = C[4u * (i / P[1]) + 3u];", "  X[4u * i + 2u] = X[4u * i + 2u] + 0.5 * A[4u * i] * dt;", "  X[4u * i + 3u] = X[4u * i + 3u] + 0.5 * A[4u * i + 1u] * dt;", "  X[4u * i] = X[4u * i] + X[4u * i + 2u] * dt;", "  X[4u * i + 1u] = X[4u * i + 1u] + X[4u * i + 3u] * dt;", "}", "" %+% text_of(Simulation$ENTRY) %+% " KICK" %+% text_of(Simulation$ID) %+% "", Simulation$THREAD, "  if (i >= P[0]) { return; }", "  let dt: f32 = C[4u * (i / P[1]) + 3u];", "  X[4u * i + 2u] = X[4u * i + 2u] + 0.5 * A[4u * i] * dt;", "  X[4u * i + 3u] = X[4u * i + 3u] + 0.5 * A[4u * i + 1u] * dt;", "}"), "\n"))
    NULL
  })
})

Model <- ray_class("Model", Node, function(cl) {
  field(cl, "theory", NULL)
  static_field(cl, "NAMES", function() lst("\\langle\\rho\\rangle", "D", "DEG", "l.DEG", "\\nu", "\\sigma", "F", "\\bar{c}", "m'", "A'", "\\bar{R}'", "m_{\\Sigma}", "m_{\\Sigma}'", "\\mathcal{D}", "\\mathcal{D}'", "\\beta'", "\\beta\\cdot\\hat{d}", "\\beta'\\cdot\\hat{d}", "\\rho", "\\omega", "R", "r", "\\bar{r}", "\\bar{m}_{x}", "A", "\\bar{R}", "\\beta", "n_{f}", "\\sigma_{tr}", "L", "m", "\\delta", "g_{N}", "a_{0}", "\\Phi"))
  static_field(cl, "RD", function() 30)
  field(cl, "store", function() Prover$new(theory = self$theory)$closure)
  field(cl, "cache", function() Node$new())
  method(cl, "fact", function(of_ = NULL, ...) {
    found <- NULL
    .r <- for_each(self$store$all("is"), function(f) {
      if (truthy((if (truthy(.x <- eq(found, NULL))) eq(f$of, of_) else .x))) {
        .w("found", f)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(found)
    NULL
  })
  statik(cl, "copy", function(env = NULL, ...) {
    out <- Node$new()
    .r <- for_each(Model$NAMES, function(k) {
      if (truthy((!eq(elem(env, k), NULL)))) {
        set_at(out, k, elem(env, k))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  statik(cl, "lattice", function(e = NULL, ...) {
    k <- e$kind
    if (truthy((if (truthy(.x <- eq(k, "add"))) .x else eq(k, "mul")))) {
      out <- Expr$new(kind = k)
      .set(out, "of", m_map(e$of, function(x = NULL, ...) {
        return(Model$lattice(x))
        NULL
      }))
      return(out)
    }
    if (truthy(eq(k, "pow"))) {
      return(Expr$to_power(Model$lattice(e$base), Model$lattice(e$power)))
    }
    if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- eq(k, "grad"))) .x else eq(k, "log")))) .x else eq(k, "exp")))) .x else eq(k, "root")))) .x else eq(k, "limit")))) {
      out <- Expr$new(kind = k)
      .set(out, "base", Model$lattice(e$base))
      .set(out, "bound", e$bound)
      return(out)
    }
    if (truthy(eq(k, "choose"))) {
      return(Expr$choose(Model$lattice(e$first_), Model$lattice(e$second_)))
    }
    if (truthy(eq(k, "gammaInc"))) {
      return(Expr$gamma_inc(Model$lattice(e$first_), Model$lattice(e$second_)))
    }
    if (truthy(eq(k, "call"))) {
      inner <- Model$lattice(e$base)
      return((if (truthy(eq(e$label, "l.choose"))) inner else Expr$call(e$label, inner)))
    }
    return(e)
    NULL
  })
  statik(cl, "unbound", function(e = NULL, ...) {
    out <- lst()
    Model$walk_names(e, out)
    return(out)
    NULL
  })
  statik(cl, "walk_names", function(e = NULL, out = NULL, ...) {
    k <- e$kind
    if (truthy((if (truthy(.x <- eq(k, "sym"))) .x else eq(k, "field")))) {
      if (truthy((!truthy(m_contains(out, e$label))))) {
        m_push(out, e$label)
      }
    } else {
      if (truthy((if (truthy(.x <- eq(k, "add"))) .x else eq(k, "mul")))) {
        .r <- for_each(e$of, function(x) {
          Model$walk_names(x, out)
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
      } else {
        if (truthy(eq(k, "pow"))) {
          Model$walk_names(e$base, out)
          return(Model$walk_names(e$power, out))
        } else {
          if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- eq(k, "grad"))) .x else eq(k, "log")))) .x else eq(k, "exp")))) .x else eq(k, "root")))) .x else eq(k, "limit")))) {
            return(Model$walk_names(e$base, out))
          } else {
            if (truthy((if (truthy(.x <- eq(k, "choose"))) .x else eq(k, "gammaInc")))) {
              Model$walk_names(e$first_, out)
              return(Model$walk_names(e$second_, out))
            } else {
              if (truthy(eq(k, "call"))) {
                called <- "" %+% text_of(e$label) %+% "\\paren{...}"
                if (truthy((!truthy(m_contains(out, called))))) {
                  m_push(out, called)
                }
                return(Model$walk_names(e$base, out))
              }
            }
          }
        }
      }
    }
    NULL
  })
  method(cl, "resolved", function(e = NULL, env = NULL, seen = NULL, ...) {
    if (truthy(gt(len(seen), 8))) {
      return(e)
    }
    missing <- filt(Model$unbound(e), function(n = NULL, ...) {
      return((if (truthy(.x <- (if (truthy(.x <- eq(elem(env, n), NULL))) (!truthy(m_contains(seen, n))) else .x))) (!truthy(m_ends_with(n, "\\paren{...}"))) else .x))
      NULL
    })
    out <- e
    grew <- FALSE
    .r <- for_each(missing, function(n) {
      f <- self$fact(n)
      if (truthy((!eq(f, NULL)))) {
        .w("out", Expr$replace(out, n, self$resolved(f$to, env, m_concat(seen, lst(n)))))
        .w("grew", TRUE)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return((if (truthy(grew)) out else e))
    NULL
  })
  field(cl, "ready", function() Node$new())
  method(cl, "prepared", function(e = NULL, env = NULL, ...) {
    bound <- m_join(filt(Model$NAMES, function(k = NULL, ...) {
      return((!eq(elem(env, k), NULL)))
      NULL
    }), ",")
    shown <- Expr$show(e)
    key <- "" %+% text_of(shown) %+% "|" %+% text_of(bound) %+% ""
    hit <- elem(self$ready, key)
    if (truthy((!eq(hit, NULL)))) {
      return(hit)
    }
    out <- Model$lattice(self$resolved(e, env, lst()))
    set_at(self$ready, key, out)
    return(out)
    NULL
  })
  method(cl, "at", function(e = NULL, env = NULL, ...) {
    return(Expr$numeric(self$prepared(e, env), env))
    NULL
  })
  method(cl, "value_of", function(name = NULL, env = NULL, ...) {
    f <- self$fact(name)
    return((if (truthy(eq(f, NULL))) NaN else self$at(f$to, env)))
    NULL
  })
  method(cl, "settled", function(DEG = NULL, ...) {
    if (truthy(eq(DEG, NULL))) {
      .w("DEG", NULL)
    }
    deg <- or_else(DEG, self$theory$lattice$DEG)
    base <- Node$new()
    .set(base, key_("D"), self$theory$lattice$D)
    .set(base, key_("DEG"), deg)
    .set(base, key_("l.DEG"), deg)
    .set(base, key_("\\nu"), 1)
    .set(base, key_("\\sigma"), 1)
    .set(base, key_("F"), 0.5)
    .set(base, key_("\\bar{c}"), 1)
    .set(base, key_("m'"), 1)
    .set(base, key_("A'"), 1)
    .set(base, key_("\\bar{R}'"), 1)
    .set(base, key_("m_{\\Sigma}"), 1)
    .set(base, key_("m_{\\Sigma}'"), 1)
    .set(base, key_("\\mathcal{D}"), 1)
    .set(base, key_("\\mathcal{D}'"), 1)
    .set(base, key_("\\beta'"), 0)
    .set(base, key_("\\beta\\cdot\\hat{d}"), 0)
    .set(base, key_("\\beta'\\cdot\\hat{d}"), 0)
    rho <- self$fact("\\rho_{\\infty}")
    if (truthy((!eq(rho, NULL)))) {
      .set(base, key_("\\rho"), self$at(rho$to, base))
    }
    om <- self$fact("\\omega")
    if (truthy((!eq(om, NULL)))) {
      .set(base, key_("\\omega"), self$at(om$to, base))
    }
    far <- Model$copy(base)
    .set(far, key_("R"), r_pow(10, 12))
    .set(far, key_("r"), r_pow(10, 12))
    .set(far, key_("\\bar{r}"), r_pow(10, 12))
    .set(far, key_("\\bar{m}_{x}"), 1)
    .set(far, key_("A"), 1)
    .set(far, key_("\\bar{R}"), 0)
    .set(far, key_("\\beta"), 0)
    .r <- for_each(lst("n_{f}", "\\sigma_{tr}", "L"), function(n) {
      f <- self$fact(n)
      if (truthy((!eq(f, NULL)))) {
        set_at(far, n, self$at(f$to, far))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(far)
    NULL
  })
  getter(cl, "a0_lattice", function() {
    if (truthy((!eq(mem(self$cache, key_("a0")), NULL)))) {
      return(mem(self$cache, key_("a0")))
    }
    a0 <- self$fact("a_{0}")
    .set(self$cache, key_("a0"), (if (truthy(eq(a0, NULL))) NaN else self$at(a0$to, self$settled(self$theory$lattice$DEG))))
    return(mem(self$cache, key_("a0")))
    NULL
  })
  method(cl, "boost", function(gN = NULL, a0 = NULL, ...) {
    F <- self$fact("F_{g}")
    if (truthy(eq(F, NULL))) {
      return(NaN)
    }
    env <- Node$new()
    .set(env, key_("D"), self$theory$lattice$D)
    .set(env, key_("DEG"), self$theory$lattice$DEG)
    .set(env, key_("g_{N}"), gN)
    .set(env, key_("a_{0}"), a0)
    got <- self$at(F$to, env)
    if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- (!truthy(Fmt$finite(got))))) Fmt$finite(gN) else .x))) gt(gN, 0) else .x))) Fmt$finite(a0) else .x))) {
      left <- Model$unbound(Expr$simplify(Expr$evaluate(F$to, env)))
      leans <- (if (truthy(m_empty(left))) "something" else m_join(left, ", "))
      (fail)("the law came to " %+% text_of(got) %+% " at g_N = " %+% text_of(gN) %+% ": " %+% text_of(F$of) %+% " leans on " %+% text_of(leans) %+% " and this seam binds none of it. Its derived form has changed - bind the new name here or fix the rule.")
    }
    return(got)
    NULL
  })
  method(cl, "delivered_by", function(sep = NULL, m = NULL, A = NULL, ...) {
    key <- "" %+% text_of(Fmt$exponential(sep, 2)) %+% "|" %+% text_of(m) %+% "|" %+% text_of(A) %+% ""
    hit <- elem(self$cache, key)
    if (truthy((!eq(hit, NULL)))) {
      return(hit)
    }
    e <- Node$new()
    .set(e, key_("D"), self$theory$lattice$D)
    .set(e, key_("DEG"), self$theory$lattice$DEG)
    .set(e, key_("\\bar{c}"), 1)
    .set(e, key_("\\bar{m}_{x}"), 1)
    .set(e, key_("\\beta"), 0)
    .set(e, key_("m'"), 1)
    .set(e, key_("A'"), 1)
    .set(e, key_("m_{\\Sigma}"), 1)
    .set(e, key_("m_{\\Sigma}'"), 1)
    .set(e, key_("\\beta'"), 0)
    .set(e, key_("\\beta\\cdot\\hat{d}"), 0)
    .set(e, key_("\\beta'\\cdot\\hat{d}"), 0)
    .set(e, key_("R"), sep)
    .set(e, key_("r"), sep)
    .set(e, key_("\\bar{r}"), sep)
    .set(e, key_("A"), A)
    .set(e, key_("m"), m)
    .set(e, key_("\\bar{R}"), r_div(m, A))
    .r <- for_each(lst("\\nu", "\\sigma", "F"), function(rate) {
      g <- self$fact(rate)
      if (truthy((!eq(g, NULL)))) {
        set_at(e, rate, self$at(g$to, e))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    rho <- self$fact("\\rho_{\\infty}")
    if (truthy((!eq(rho, NULL)))) {
      .set(e, key_("\\rho"), self$at(rho$to, e))
    }
    step <- function(name = NULL, into = NULL, ...) {
      g <- self$fact(name)
      if (truthy((!eq(g, NULL)))) {
        set_at(e, into, self$at(g$to, e))
      }
      NULL
    }
    (step)("n_{f}", "n_{f}")
    (step)("\\sigma_{tr}", "\\sigma_{tr}")
    (step)("L", "L")
    (step)("what a body puts into the medium", "\\delta")
    (step)("\\rho at R", "\\rho")
    (step)("n_{f}", "n_{f}")
    (step)("\\sigma_{tr}", "\\sigma_{tr}")
    (step)("L", "L")
    (step)("g_{N}", "g_{N}")
    (step)("a_{0}", "a_{0}")
    out <- lst(mem(e, key_("g_{N}")), mem(e, key_("a_{0}")))
    set_at(self$cache, key, out)
    return(out)
    NULL
  })
  statik(cl, "surface", function(r = NULL, M = NULL, rd = NULL, ...) {
    return(r_div(r_mul(M, m_exp((r_sub(0, r_div(r, rd))))), (r_mul(r_mul(r_mul(2, pi), rd), rd))))
    NULL
  })
  method(cl, "as_point_parts", function(R = NULL, M = NULL, rd = NULL, ...) {
    one_ <- self$delivered_by(R, M, r_mul(r_mul(pi, rd), rd))
    return(lst(elem(one_, 0), self$boost(elem(one_, 0), elem(one_, 1))))
    NULL
  })
  method(cl, "as_stars_parts", function(R = NULL, M = NULL, rd = NULL, ...) {
    rings <- 16
    spokes <- 24
    rmax <- r_mul(8, rd)
    gN <- 0
    .r <- for_range(rings, function(i) {
      r <- r_div(r_mul(rmax, (r_add(i, 0.5))), rings)
      dr <- r_div(rmax, rings)
      dm <- r_mul(r_mul(r_mul(r_mul(2, pi), r), dr), Model$surface(r, M, rd))
      if (truthy(gt(dm, 0))) {
        .r <- for_range(spokes, function(k) {
          th <- r_div(r_mul(r_mul(2, pi), (r_add(k, 0.5))), spokes)
          dx <- r_sub(R, r_mul(r, m_cos(th)))
          dy <- r_sub(0, r_mul(r, m_sin(th)))
          sep <- Fmt$hypot(dx, dy)
          if (truthy(ge(sep, 1))) {
            one_ <- self$delivered_by(sep, 1, 1)
            if (truthy(Fmt$finite(elem(one_, 0)))) {
              .w("gN", r_add(gN, r_mul(r_mul((r_div(dm, spokes)), elem(one_, 0)), (r_div(dx, sep)))))
            }
          }
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    a0 <- elem(self$delivered_by(R, M, r_mul(r_mul(pi, rd), rd)), 1)
    return(lst(gN, self$boost(gN, a0)))
    NULL
  })
  statik(cl, "speed", function(g = NULL, R = NULL, ...) {
    return((if (truthy(gt(g, 0))) m_sqrt((r_mul(R, g))) else NaN))
    NULL
  })
})

Axis <- ray_class("Axis", Node, function(cl) {
  field(cl, "lo", NULL)
  field(cl, "hi", NULL)
  field(cl, "n", NULL)
  field(cl, "linear", function() FALSE)
  method(cl, "value", function(i = NULL, ...) {
    t <- (if (truthy(gt(self$n, 1))) r_div(i, (r_sub(self$n, 1))) else 0.5)
    v <- r_add(self$lo, r_mul((r_sub(self$hi, self$lo)), t))
    return((if (truthy(self$linear)) v else r_pow(10, v)))
    NULL
  })
  getter(cl, "mid", function() {
    v <- r_add(self$lo, r_mul((r_sub(self$hi, self$lo)), 0.5))
    return((if (truthy(self$linear)) v else r_pow(10, v)))
    NULL
  })
  getter(cl, "values", function() {
    return(m_map(rng(self$n), function(i = NULL, ...) {
      return(self$value(i))
      NULL
    }))
    NULL
  })
})

Shaded <- ray_class("Shaded", Node, function(cl) {
  statik(cl, "literal", function(n = NULL, ...) {
    if (truthy((!eq(n, n)))) {
      return("1e30")
    }
    if (truthy(gt(m_abs(n), r_pow(10, 300)))) {
      return((if (truthy(lt(n, 0))) "(-1e30)" else "1e30"))
    }
    if (truthy((if (truthy(.x <- eq(n, m_floor(n)))) lt(m_abs(n), 1000000000) else .x))) {
      return("(" %+% text_of(n) %+% ".0)")
    }
    return("(" %+% text_of(n) %+% ")")
    NULL
  })
  statik(cl, "wgsl", function(e = NULL, names = NULL, bound = NULL, ...) {
    k <- e$kind
    if (truthy(eq(k, "num"))) {
      return(Shaded$literal(e$value))
    }
    if (truthy((if (truthy(.x <- eq(k, "sym"))) .x else eq(k, "field")))) {
      if (truthy((if (truthy(.x <- (!eq(bound, NULL)))) eq(e$label, bound) else .x))) {
        return("x")
      }
      i <- m_index_of(names, e$label)
      if (truthy(eq(i, NULL))) {
        (fail)("the law stands on " %+% text_of(e$label) %+% ", which the sweep does not bind")
      }
      return("e[" %+% text_of(i) %+% "]")
    }
    if (truthy(eq(k, "add"))) {
      parts <- m_map(e$of, function(x = NULL, ...) {
        return(Shaded$wgsl(x, names, bound))
        NULL
      })
      summed <- m_join(parts, " + ")
      return("(" %+% text_of(summed) %+% ")")
    }
    if (truthy(eq(k, "mul"))) {
      parts <- m_map(e$of, function(x = NULL, ...) {
        return(Shaded$wgsl(x, names, bound))
        NULL
      })
      multiplied <- m_join(parts, " * ")
      return("(" %+% text_of(multiplied) %+% ")")
    }
    if (truthy(eq(k, "pow"))) {
      base <- Shaded$wgsl(e$base, names, bound)
      if (truthy(eq(e$power$kind, "num"))) {
        n <- e$power$value
        if (truthy(eq(n, 0.5))) {
          return("sqrt(" %+% text_of(base) %+% ")")
        }
        if (truthy((if (truthy(.x <- eq(n, m_floor(n)))) le(m_abs(n), 64) else .x))) {
          return("powi(" %+% text_of(base) %+% ", " %+% text_of(m_round(n)) %+% ")")
        }
        return("pow(" %+% text_of(base) %+% ", " %+% text_of(Shaded$literal(n)) %+% ")")
      }
      return("pow(" %+% text_of(base) %+% ", " %+% text_of(Shaded$wgsl(e$power, names, bound)) %+% ")")
    }
    if (truthy(eq(k, "log"))) {
      return("log(" %+% text_of(Shaded$wgsl(e$base, names, bound)) %+% ")")
    }
    if (truthy(eq(k, "exp"))) {
      return("exp(" %+% text_of(Shaded$wgsl(e$base, names, bound)) %+% ")")
    }
    if (truthy(eq(k, "choose"))) {
      return("choose(" %+% text_of(Shaded$wgsl(e$first_, names, bound)) %+% ", " %+% text_of(Shaded$wgsl(e$second_, names, bound)) %+% ")")
    }
    return((fail)("a " %+% text_of(k) %+% " cannot be written as shader code - only a root at the top of a law is solved there"))
    NULL
  })
  static_getter(cl, "helpers", function() {
    return("fn powi(b: f32, n: i32) -> f32 {\n  var r: f32 = 1.0;\n  let m: i32 = abs(n);\n  for (var i: i32 = 0; i < m; i = i + 1) { r = r * b; }\n  if (n < 0) { return 1.0 / r; }\n  return r;\n}\nfn choose(n: f32, k: f32) -> f32 {\n  var r: f32 = 1.0;\n  var i: f32 = 0.0;\n  for (var c: i32 = 0; c < 64; c = c + 1) { if (i < k) { r = r * (n - i) / (i + 1.0); i = i + 1.0; } }\n  return r;\n}\nfn finite(v: f32) -> bool { return abs(v) < 1e30 && v == v; }")
    NULL
  })
  static_getter(cl, "points", function() {
    points <- lst()
    i <- 1
    while (truthy(le(i, 120))) {
      m_push(points, r_div(i, 120))
      .w("i", r_add(i, 1))
    }
    ex <- 0
    while (truthy(le(ex, 24))) {
      k <- 1
      while (truthy(lt(k, 8))) {
        m_push(points, r_mul((r_pow(10, (r_sub(ex, 12)))), (r_add(1, r_div(k, 2)))))
        .w("k", r_add(k, 1))
      }
      .w("ex", r_add(ex, 1))
    }
    return(Expr$sorted(points))
    NULL
  })
  statik(cl, "solver", function(name = NULL, f = NULL, ...) {
    pts <- Shaded$points
    lits <- m_join(m_map(pts, function(v = NULL, ...) {
      return(Shaded$literal(v))
      NULL
    }), ", ")
    return("const PTS_" %+% text_of(name) %+% ": array<f32, " %+% text_of(len(pts)) %+% "> = array<f32, " %+% text_of(len(pts)) %+% ">(" %+% text_of(lits) %+% ");\nfn " %+% text_of(name) %+% "() -> f32 {\n  var lo: f32 = 0.0;\n  var hi: f32 = 0.0;\n  var found: bool = false;\n  var px: f32 = PTS_" %+% text_of(name) %+% "[0];\n  var pf: f32 = " %+% text_of(f) %+% "(px);\n  for (var j: i32 = 1; j < " %+% text_of(len(pts)) %+% "; j = j + 1) {\n    let cx: f32 = PTS_" %+% text_of(name) %+% "[j];\n    let cf: f32 = " %+% text_of(f) %+% "(cx);\n    if (!found && finite(pf) && finite(cf) && pf * cf <= 0.0) { lo = px; hi = cx; found = true; }\n    px = cx;\n    pf = cf;\n  }\n  if (!found) { return 1e30; }\n  var flo: f32 = " %+% text_of(f) %+% "(lo);\n  for (var n: i32 = 0; n < 60; n = n + 1) {\n    let mid: f32 = (lo + hi) / 2.0;\n    let fm: f32 = " %+% text_of(f) %+% "(mid);\n    if (!finite(fm)) { break; }\n    if (flo * fm <= 0.0) { hi = mid; } else { lo = mid; flo = fm; }\n  }\n  return (lo + hi) / 2.0;\n}")
    NULL
  })
})

Sweep <- ray_class("Sweep", Node, function(cl) {
  field(cl, "model", NULL)
  field(cl, "how", NULL)
  field(cl, "arrival", function() self$model$fact("what arrives with the mass " %+% text_of(self$how) %+% ""))
  field(cl, "felt", function() self$model$fact("F_{g}"))
  field(cl, "rho_at", function() self$model$fact("\\rho at R"))
  field(cl, "scale", function() self$model$fact("a_{0} along the path"))
  field(cl, "a0", function() self$model$a0_lattice)
  field(cl, "base", function() Sweep$base_env(self$model))
  field(cl, "order", function() lst("mass", "face", "moving", "radiating"))
  field(cl, "axes", function() Sweep$axes_of)
  field(cl, "R0", function() neg(1))
  field(cl, "R1", function() 8)
  field(cl, "RS", function() 170)
  field(cl, "XS", function() 700)
  field(cl, "X0", function() neg(5))
  field(cl, "X1", function() 4)
  field(cl, "YS", function() 520)
  field(cl, "Y0", function() neg(4))
  field(cl, "Y1", function() 4)
  field(cl, "rad", function() m_map(rng(self$RS), function(i = NULL, ...) {
    return(r_pow(10, (r_add(self$R0, r_div(r_mul((r_sub(self$R1, self$R0)), i), (r_sub(self$RS, 1)))))))
    NULL
  }))
  field(cl, "env", function() m_map(self$rad, function(R = NULL, ...) {
    e <- Model$copy(self$base)
    .set(e, key_("R"), R)
    .set(e, key_("r"), R)
    .set(e, key_("\\bar{r}"), R)
    .r <- for_each(lst("n_{f}", "\\sigma_{tr}", "L"), function(n) {
      g <- self$model$fact(n)
      if (truthy((!eq(g, NULL)))) {
        set_at(e, n, self$model$at(g$to, e))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(e)
    NULL
  }))
  statik(cl, "base_env", function(model = NULL, ...) {
    base <- Node$new()
    .set(base, key_("D"), model$theory$lattice$D)
    .set(base, key_("DEG"), model$theory$lattice$DEG)
    .set(base, key_("\\bar{c}"), 1)
    .set(base, key_("m'"), 1)
    .set(base, key_("A'"), 1)
    .set(base, key_("\\bar{R}'"), 1)
    .set(base, key_("m_{\\Sigma}"), 1)
    .set(base, key_("m_{\\Sigma}'"), 1)
    .set(base, key_("\\mathcal{D}"), 1)
    .set(base, key_("\\mathcal{D}'"), 1)
    .set(base, key_("\\beta'"), 0)
    .set(base, key_("\\beta\\cdot\\hat{d}"), 0)
    .set(base, key_("\\beta'\\cdot\\hat{d}"), 0)
    .r <- for_each(lst("\\nu", "\\sigma", "F"), function(rate) {
      g <- model$fact(rate)
      if (truthy((!eq(g, NULL)))) {
        set_at(base, rate, model$at(g$to, base))
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    rho <- model$fact("\\rho_{\\infty}")
    if (truthy((!eq(rho, NULL)))) {
      .set(base, key_("\\rho"), model$at(rho$to, base))
    }
    om <- model$fact("\\omega")
    if (truthy((!eq(om, NULL)))) {
      .set(base, key_("\\omega"), model$at(om$to, base))
    }
    .set(base, key_("\\bar{m}_{x}"), 1)
    .set(base, key_("A"), 1)
    .set(base, key_("\\bar{R}"), 0)
    .set(base, key_("\\beta"), 0)
    return(base)
    NULL
  })
  static_getter(cl, "axes_of", function() {
    axes <- Node$new()
    .set(axes, key_("mass"), Axis$new(lo = 2, hi = 9, n = 46))
    .set(axes, key_("face"), Axis$new(lo = 1, hi = 6, n = 28))
    moving <- Axis$new(lo = 0, hi = 0.9, n = 5)
    .set(moving, "linear", TRUE)
    .set(axes, key_("moving"), moving)
    .set(axes, key_("radiating"), Axis$new(lo = neg(2), hi = 2, n = 5))
    return(axes)
    NULL
  })
  getter(cl, "dx", function() {
    return(r_div((r_sub(self$X1, self$X0)), (r_sub(self$XS, 1))))
    NULL
  })
  getter(cl, "dy", function() {
    return(r_div((r_sub(self$Y1, self$Y0)), (r_sub(self$YS, 1))))
    NULL
  })
  method(cl, "point", function(k = NULL, m = NULL, A = NULL, beta = NULL, S0 = NULL, ...) {
    e <- Model$copy(elem(self$env, k))
    .set(e, key_("m"), m)
    .set(e, key_("A"), A)
    .set(e, key_("\\bar{R}"), r_div(m, A))
    .set(e, key_("\\beta"), beta)
    .set(e, key_("m_{\\Sigma}"), S0)
    .set(e, key_("m_{\\Sigma}'"), S0)
    return(e)
    NULL
  })
  method(cl, "crossed", function(m = NULL, A = NULL, ...) {
    out <- filled(self$RS, 0)
    total <- 0
    last <- 0
    .r <- for_range(self$RS, function(k) {
      e <- self$point(k, m, A, 0, 1)
      r <- self$model$at(self$rho_at$to, e)
      here <- (if (truthy((if (truthy(.x <- (if (truthy(.x <- Fmt$finite(r))) gt(r, 0) else .x))) le(r, 1) else .x))) r else mem(self$base, key_("\\rho")))
      if (truthy(gt(k, 0))) {
        .w("total", r_add(total, r_mul(r_mul(0.5, (r_add(here, last))), (r_sub(elem(self$rad, k), elem(self$rad, r_sub(k, 1)))))))
      }
      .w("last", here)
      set_at(out, k, (if (truthy(eq(k, 0))) here else r_div(total, elem(self$rad, k))))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  method(cl, "landing", function(k = NULL, m = NULL, A = NULL, beta = NULL, S0 = NULL, avg_k = NULL, ...) {
    e <- self$point(k, m, A, beta, S0)
    gN <- self$model$at(self$arrival$to, e)
    .set(e, key_("g_{N}"), gN)
    .set(e, key_("\\langle\\rho\\rangle"), avg_k)
    .set(e, key_("a_{0}"), self$model$at(self$scale$to, e))
    g <- self$model$at(self$felt$to, e)
    return(lst((if (truthy(gt(gN, 0))) Fmt$log10(r_div(gN, self$a0)) else NaN), (if (truthy(gt(g, 0))) Fmt$log10(r_div(g, self$a0)) else NaN)))
    NULL
  })
  method(cl, "steps", function(vary = NULL, k = NULL, ...) {
    return((if (truthy(m_contains(vary, k))) elem(self$axes, k)$n else 1))
    NULL
  })
  method(cl, "pick", function(vary = NULL, k = NULL, i = NULL, ...) {
    return((if (truthy(m_contains(vary, k))) elem(self$axes, k)$value(i) else elem(self$axes, k)$mid))
    NULL
  })
  method(cl, "rasterise", function(xs_ = NULL, ys_ = NULL, tracks = NULL, ...) {
    grid <- filled(r_mul(self$XS, self$YS), 0)
    dx <- self$dx
    dy <- self$dy
    RS <- self$RS
    .r <- for_range(tracks, function(tr) {
      at0 <- r_mul(tr, RS)
      .r <- for_range(r_sub(RS, 1), function(k) {
        xa <- elem(xs_, r_add(at0, k))
        xb <- elem(xs_, r_add(r_add(at0, k), 1))
        ya <- elem(ys_, r_add(at0, k))
        yb <- elem(ys_, r_add(r_add(at0, k), 1))
        if (truthy((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- Fmt$finite(xa))) Fmt$finite(xb) else .x))) Fmt$finite(ya) else .x))) Fmt$finite(yb) else .x))) {
          st <- Fmt$max(1, r_sub(0, m_floor((r_sub(0, Fmt$max(r_div(m_abs((r_sub(xb, xa))), dx), r_div(m_abs((r_sub(yb, ya))), dy)))))))
          .r <- for_range(st, function(t) {
            f <- r_div((r_add(t, 0.5)), st)
            gx <- m_round((r_div((r_sub(r_add(xa, r_mul(f, (r_sub(xb, xa)))), self$X0)), dx)))
            gy <- m_round((r_div((r_sub(r_add(ya, r_mul(f, (r_sub(yb, ya)))), self$Y0)), dy)))
            if (truthy((!truthy(((if (truthy(.x <- (if (truthy(.x <- (if (truthy(.x <- lt(gx, 0))) .x else lt(gy, 0)))) .x else ge(gx, self$XS)))) .x else ge(gy, self$YS))))))) {
              set_at(grid, r_add(r_mul(gy, self$XS), gx), r_add(elem(grid, r_add(r_mul(gy, self$XS), gx)), r_div(1, st)))
            }
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(grid)
    NULL
  })
  method(cl, "tracks", function(vary = NULL, ...) {
    nM <- self$steps(vary, "mass")
    nA <- self$steps(vary, "face")
    nB <- self$steps(vary, "moving")
    nS <- self$steps(vary, "radiating")
    xs_ <- lst()
    ys_ <- lst()
    .r <- for_range(nM, function(mi) {
      m <- self$pick(vary, "mass", mi)
      .r <- for_range(nA, function(ai) {
        A <- self$pick(vary, "face", ai)
        avg <- self$crossed(m, A)
        .r <- for_range(nB, function(bi) {
          beta <- self$pick(vary, "moving", bi)
          .r <- for_range(nS, function(si) {
            S0 <- self$pick(vary, "radiating", si)
            .r <- for_range(self$RS, function(k) {
              got <- self$landing(k, m, A, beta, S0, elem(avg, k))
              m_push(xs_, elem(got, 0))
              m_push(ys_, elem(got, 1))
              CONTINUE
            })
            if (!is.null(.r)) return(.r[[1]])
            CONTINUE
          })
          if (!is.null(.r)) return(.r[[1]])
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    out <- Node$new()
    .set(out, key_("xs"), xs_)
    .set(out, key_("ys"), ys_)
    .set(out, key_("tracks"), r_mul(r_mul(r_mul(nM, nA), nB), nS))
    return(out)
    NULL
  })
  method(cl, "needs", function(grid = NULL, without = NULL, ...) {
    need <- filled(r_mul(self$XS, self$YS), 0)
    .r <- for_range(len(without), function(k) {
      g <- elem(without, k)
      .r <- for_range(len(need), function(i) {
        if (truthy((if (truthy(.x <- gt(elem(grid, i), 0))) (!truthy((gt(elem(g, i), 0)))) else .x))) {
          set_at(need, i, r_add(elem(need, i), r_pow(2, k)))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(need)
    NULL
  })
  method(cl, "save", function(id = NULL, grid = NULL, need = NULL, ...) {
    x <- lst()
    y <- lst()
    p <- lst()
    by <- lst()
    .r <- for_range(self$YS, function(gy) {
      .r <- for_range(self$XS, function(gx) {
        m_push(x, r_add(self$X0, r_mul(gx, self$dx)))
        m_push(y, r_add(self$Y0, r_mul(gy, self$dy)))
        m_push(p, elem(grid, r_add(r_mul(gy, self$XS), gx)))
        m_push(by, elem(need, r_add(r_mul(gy, self$XS), gx)))
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    most <- 0
    .r <- for_each(p, function(v) {
      if (truthy(gt(v, most))) {
        .w("most", v)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    columns <- Node$new()
    .set(columns, key_("x"), x)
    .set(columns, key_("y"), y)
    .set(columns, key_("p"), p)
    .set(columns, key_("by"), by)
    extra <- Node$new()
    .set(extra, key_("a0"), self$a0)
    .set(extra, key_("arrangement"), self$how)
    .set(extra, key_("most"), most)
    arrives <- Node$new()
    .set(arrives, key_("from"), self$X0)
    .set(arrives, key_("to"), self$X1)
    .set(arrives, key_("n"), self$XS)
    felt_axis <- Node$new()
    .set(felt_axis, key_("from"), self$Y0)
    .set(felt_axis, key_("to"), self$Y1)
    .set(felt_axis, key_("n"), self$YS)
    grid_meta <- Node$new()
    .set(grid_meta, key_("arrives"), arrives)
    .set(grid_meta, key_("felt"), felt_axis)
    .set(extra, key_("grid"), grid_meta)
    .set(extra, key_("freedoms"), self$order)
    .set(extra, key_("stages"), lst("nought is: reachable several ways; otherwise one bit per freedom, in the order of `freedoms`, for each one that is NECESSARY there"))
    .set(extra, key_("about"), "how much of the possible lands at each pair of what arrives and what is felt, and `by` is which freedom that cell NEEDS - found by taking each one away in turn, so it does not depend on any order they might be added in")
    return(Measure$save(id, lst("x", "y", "p", "by"), columns, extra))
    NULL
  })
  getter(cl, "probe", function() {
    e <- self$point(0, 1, 1, 0, 1)
    .set(e, key_("g_{N}"), 1)
    .set(e, key_("a_{0}"), 1)
    return(e)
    NULL
  })
  getter(cl, "names", function() {
    out <- lst()
    e0 <- self$probe
    .r <- for_each(lst(self$model$prepared(self$rho_at$to$base, e0), self$model$prepared(self$arrival$to, e0), self$model$prepared(self$felt$to, e0), self$model$prepared(self$scale$to, e0)), function(x) {
      .r <- for_each(Model$unbound(x), function(n) {
        if (truthy((!truthy(m_contains(out, n))))) {
          m_push(out, n)
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .r <- for_each(lst("g_{N}", "a_{0}", "\\rho", "\\langle\\rho\\rangle"), function(n) {
      if (truthy((!truthy(m_contains(out, n))))) {
        m_push(out, n)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  getter(cl, "constants", function() {
    return(m_map(self$names, function(n = NULL, ...) {
      return((if (truthy(eq(elem(self$base, n), NULL))) NaN else elem(self$base, n)))
      NULL
    }))
    NULL
  })
  method(cl, "slot", function(n = NULL, ...) {
    i <- m_index_of(self$names, n)
    return((if (truthy(eq(i, NULL))) neg(1) else i))
    NULL
  })
  getter(cl, "radii", function() {
    out <- lst()
    .r <- for_range(self$RS, function(k) {
      e <- elem(self$env, k)
      m_push(out, elem(self$rad, k))
      m_push(out, or_else(mem(e, key_("n_{f}")), NaN))
      m_push(out, or_else(mem(e, key_("\\sigma_{tr}")), NaN))
      m_push(out, or_else(mem(e, key_("L")), NaN))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(out)
    NULL
  })
  getter(cl, "kernel", function() {
    names <- self$names
    NV <- len(names)
    e0 <- self$probe
    f_rho <- Shaded$wgsl(self$model$prepared(self$rho_at$to$base, e0), names, self$rho_at$to$bound)
    f_arr <- Shaded$wgsl(self$model$prepared(self$arrival$to, e0), names, NULL)
    f_felt <- Shaded$wgsl(self$model$prepared(self$felt$to, e0), names, NULL)
    f_scale <- Shaded$wgsl(self$model$prepared(self$scale$to, e0), names, NULL)
    savg <- self$slot("\\langle\\rho\\rangle")
    sR <- self$slot("R")
    sr <- self$slot("r")
    srb <- self$slot("\\bar{r}")
    snf <- self$slot("n_{f}")
    sst <- self$slot("\\sigma_{tr}")
    sL <- self$slot("L")
    sm <- self$slot("m")
    sA <- self$slot("A")
    sRb <- self$slot("\\bar{R}")
    sb <- self$slot("\\beta")
    sS <- self$slot("m_{\\Sigma}")
    sS2 <- self$slot("m_{\\Sigma}'")
    sgN <- self$slot("g_{N}")
    sa0 <- self$slot("a_{0}")
    srho <- self$slot("\\rho")
    set <- function(i = NULL, v = NULL, ...) {
      return((if (truthy(lt(i, 0))) "" else "e[" %+% text_of(i) %+% "] = " %+% text_of(v) %+% ";"))
      NULL
    }
    helpers <- Shaded$helpers
    solver <- Shaded$solver("solve_rho", "f_rho")
    sigma <- mem(self$base, key_("\\sigma"))
    ambient <- mem(self$base, key_("\\rho"))
    r_R <- (set)(sR, "rad[4u * k]")
    r_r <- (set)(sr, "rad[4u * k]")
    r_rb <- (set)(srb, "rad[4u * k]")
    r_nf <- (set)(snf, "rad[4u * k + 1u]")
    r_st <- (set)(sst, "rad[4u * k + 2u]")
    r_L <- (set)(sL, "rad[4u * k + 3u]")
    radius <- "" %+% text_of(r_R) %+% " " %+% text_of(r_r) %+% " " %+% text_of(r_rb) %+% " " %+% text_of(r_nf) %+% " " %+% text_of(r_st) %+% " " %+% text_of(r_L) %+% ""
    s_m <- (set)(sm, "m")
    s_A <- (set)(sA, "A")
    s_Rb <- (set)(sRb, "m / A")
    s_b <- (set)(sb, "beta")
    s_S <- (set)(sS, "S0")
    s_S2 <- (set)(sS2, "S0")
    source <- "" %+% text_of(s_m) %+% " " %+% text_of(s_A) %+% " " %+% text_of(s_Rb) %+% " " %+% text_of(s_b) %+% " " %+% text_of(s_S) %+% " " %+% text_of(s_S2) %+% ""
    set_gN <- (set)(sgN, "gN")
    sigma_lit <- Shaded$literal(sigma)
    set_avg <- (set)(savg, "avg[pair * P.RS + k]")
    scale_call <- "f_scale()"
    set_scale <- (set)(sa0, scale_call)
    set_a0 <- "" %+% text_of(set_avg) %+% " " %+% text_of(set_scale) %+% ""
    ambient_lit <- Shaded$literal(ambient)
    a0_lit <- Shaded$literal(self$a0)
    fill <- "for (var i: u32 = 0u; i < " %+% text_of(NV) %+% "u; i = i + 1u) { e[i] = C[i]; }"
    return(m_join(lst("// GENERATED by `npx ray measure` from the closed theory: the possibility space, swept on the device", "struct Par { RS: u32, nM: u32, nA: u32, nB: u32, nS: u32, pad0: u32, pad1: u32, pad2: u32 }", "@group(0) @binding(0) var<storage, read> P: Par;", "@group(0) @binding(1) var<storage, read> C: array<f32>;", "@group(0) @binding(2) var<storage, read> rad: array<f32>;", "@group(0) @binding(3) var<storage, read> ax: array<f32>;", "@group(0) @binding(4) var<storage, read_write> avg: array<f32>;", "@group(0) @binding(5) var<storage, read_write> xs: array<f32>;", "@group(0) @binding(6) var<storage, read_write> ys: array<f32>;", "var<private> e: array<f32, " %+% text_of(NV) %+% ">;", helpers, "fn f_rho(x: f32) -> f32 { return " %+% text_of(f_rho) %+% "; }", "fn f_arrival() -> f32 { return " %+% text_of(f_arr) %+% "; }", "fn f_felt() -> f32 { return " %+% text_of(f_felt) %+% "; }", "fn f_scale() -> f32 { return " %+% text_of(f_scale) %+% "; }", solver, "@compute @workgroup_size(64) fn PROFILE(@builtin(global_invocation_id) gid: vec3<u32>) {\n  let i: u32 = gid.y * 1024u * 64u + gid.x;\n  if (i >= P.nM * P.nA) { return; }\n  let mi: u32 = i / P.nA;\n  let ai: u32 = i % P.nA;\n  let m: f32 = ax[mi];\n  let A: f32 = ax[P.nM + ai];\n  let beta: f32 = 0.0;\n  let S0: f32 = 1.0;\n  " %+% text_of(fill) %+% "\n  var total: f32 = 0.0;\n  var last: f32 = 0.0;\n  for (var k: u32 = 0u; k < P.RS; k = k + 1u) {\n    " %+% text_of(radius) %+% "\n    " %+% text_of(source) %+% "\n    let r: f32 = solve_rho();\n    var here: f32 = " %+% text_of(ambient_lit) %+% ";\n    if (finite(r) && r > 0.0 && r <= 1.0) { here = r; }\n    if (k > 0u) { total = total + 0.5 * (here + last) * (rad[4u * k] - rad[4u * (k - 1u)]); }\n    last = here;\n    if (k == 0u) { avg[i * P.RS + k] = here; } else { avg[i * P.RS + k] = total / rad[4u * k]; }\n  }\n}", "@compute @workgroup_size(64) fn TRACK(@builtin(global_invocation_id) gid: vec3<u32>) {\n  let i: u32 = gid.y * 1024u * 64u + gid.x;\n  let per: u32 = P.nB * P.nS * P.RS;\n  if (i >= P.nM * P.nA * per) { return; }\n  let pair: u32 = i / per;\n  let rest: u32 = i % per;\n  let bi: u32 = rest / (P.nS * P.RS);\n  let si: u32 = (rest / P.RS) % P.nS;\n  let k: u32 = rest % P.RS;\n  let mi: u32 = pair / P.nA;\n  let ai: u32 = pair % P.nA;\n  let m: f32 = ax[mi];\n  let A: f32 = ax[P.nM + ai];\n  let beta: f32 = ax[P.nM + P.nA + bi];\n  let S0: f32 = ax[P.nM + P.nA + P.nB + si];\n  " %+% text_of(fill) %+% "\n  " %+% text_of(radius) %+% "\n  " %+% text_of(source) %+% "\n  let gN: f32 = f_arrival();\n  " %+% text_of(set_gN) %+% "\n  " %+% text_of(set_a0) %+% "\n  let g: f32 = f_felt();\n  var lx: f32 = 1e30;\n  var ly: f32 = 1e30;\n  if (finite(gN) && gN > 0.0) { lx = log(gN / " %+% text_of(a0_lit) %+% ") / log(10.0); }\n  if (finite(g) && g > 0.0) { ly = log(g / " %+% text_of(a0_lit) %+% ") / log(10.0); }\n  xs[i] = lx;\n  ys[i] = ly;\n}"), "\n\n"))
    NULL
  })
})

Measure <- ray_class("Measure", Node, function(cl) {
  statik(cl, "save", function(id = NULL, names = NULL, columns = NULL, extra = NULL, ...) {
    rows <- len(elem(columns, elem(names, 0)))
    .r <- for_each(names, function(n) {
      if (truthy((!eq(len(elem(columns, n)), rows)))) {
        (fail)("" %+% text_of(id) %+% ": " %+% text_of(n) %+% " has " %+% text_of(len(elem(columns, n))) %+% " rows where " %+% text_of(elem(names, 0)) %+% " has " %+% text_of(rows) %+% "")
      }
      if (truthy((!truthy(m_some(elem(columns, n), function(v = NULL, ...) {
        return(Fmt$finite(v))
        NULL
      }))))) {
        (fail)("" %+% text_of(id) %+% ": column " %+% text_of(n) %+% " is not a number anywhere - the model did not answer, and a field of NaN drawn as a blank panel is worse than a failed run")
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(Measured$save("visuals", id, id, names, columns, extra))
    NULL
  })
  statik(cl, "density", function(model = NULL, id = NULL, how = NULL, ...) {
    sweep <- Sweep$new(model = model, how = how)
    if (truthy((if (truthy(.x <- (if (truthy(.x <- eq(sweep$arrival, NULL))) .x else eq(sweep$felt, NULL)))) .x else eq(sweep$rho_at, NULL)))) {
      (fail)("" %+% text_of(id) %+% ": nothing derived to integrate")
    }
    lay <- function(vary = NULL, ...) {
      got <- sweep$tracks(vary)
      return(sweep$rasterise(mem(got, key_("xs")), mem(got, key_("ys")), mem(got, key_("tracks"))))
      NULL
    }
    grid <- (lay)(sweep$order)
    without <- m_map(sweep$order, function(held = NULL, ...) {
      return((lay)(filt(sweep$order, function(n = NULL, ...) {
        return((!eq(n, held)))
        NULL
      })))
      NULL
    })
    return(sweep$save(id, grid, sweep$needs(grid, without)))
    NULL
  })
  statik(cl, "law", function(model = NULL, ...) {
    a0 <- model$a0_lattice
    gN <- lst()
    g <- lst()
    .r <- for_range(901, function(i) {
      x <- r_mul(r_pow(10, (r_add(neg(5), r_div(r_mul(9, i), 900)))), a0)
      m_push(gN, x)
      m_push(g, model$boost(x, a0))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    DEG <- model$theory$lattice$DEG
    e <- model$settled(DEG)
    .set(e, key_("D"), model$theory$lattice$D)
    .set(e, key_("DEG"), DEG)
    symbols <- Node$new()
    .set(symbols, key_("DEG"), DEG)
    .set(symbols, key_("\\nu"), mem(e, key_("\\nu")))
    .set(symbols, key_("\\sigma"), mem(e, key_("\\sigma")))
    .set(symbols, key_("F"), mem(e, key_("F")))
    om <- model$value_of("\\omega", e)
    .set(symbols, key_("\\omega"), (if (truthy(Fmt$finite(om))) om else mem(e, key_("\\omega"))))
    .set(symbols, key_("\\beta"), 0)
    .set(symbols, key_("\\rho"), mem(e, key_("\\rho")))
    .r <- for_each(lst("\\lambda", "n_{f}", "\\bar{m}_{l}"), function(n) {
      v <- model$value_of(n, e)
      if (truthy(Fmt$finite(v))) {
        set_at(symbols, n, v)
      }
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    .set(symbols, key_("\\bar{m}_{x}"), 1)
    columns <- Node$new()
    .set(columns, key_("gN"), gN)
    .set(columns, key_("g"), g)
    extra <- Node$new()
    .set(extra, key_("a0"), a0)
    .set(extra, key_("theory"), model$theory$name)
    .set(extra, key_("symbols"), symbols)
    .set(extra, key_("about"), "what arrives against what is felt, both in units of a_0")
    .set(extra, key_("carries"), Aggregate$of(model$theory, DEG, model$theory$lattice$D)$carries)
    return(Measure$save("law", lst("gN", "g"), columns, extra))
    NULL
  })
  statik(cl, "run", function(theory = NULL, only = NULL, ...) {
    model <- Model$new(theory = theory)
    want <- function(n = NULL, ...) {
      return((if (truthy(.x <- m_empty(only))) .x else m_some(only, function(o = NULL, ...) {
        return(m_contains(n, o))
        NULL
      })))
      NULL
    }
    if (truthy((want)("galaxy.point"))) {
      Measure$density(model, "galaxy.point", "gathered")
    }
    if (truthy((want)("galaxy.many"))) {
      Measure$density(model, "galaxy.many", "scattered")
    }
    if (truthy((want)("law"))) {
      Measure$law(model)
    }
    NULL
  })
})

GTheory <- ray_class("G", Theory, function(cl) {
  field(cl, "name", function() "G")
  getter(cl, "lattice", function() {
    return(g_BCC8())
    NULL
  })
  static_field(cl, "rule 1", function() Rule$new(`id` = "/1", `name` = "Annihilation", `rate` = "σ", `over` = "Edge", `single` = true, `where` = function(it = NULL, ...) {
    return(it$active)
    NULL
  }, `source` = "\"rule /1 \\\"Annihilation\\\" | σ (x: 1 Edge{active}) => x.ANNIHILATE\"", `body` = function(x = NULL, ...) {
    return(x$ANNIHILATE)
    NULL
  }))
  static_field(cl, "rule 2", function() Rule$new(`id` = "/2", `name` = "Creation", `rate` = "ν", `over` = "Vertex", `single` = true, `where` = function(it = NULL, ...) {
    return(it$neutral)
    NULL
  }, `source` = "\"rule /2 \\\"Creation\\\" | ν (x: Vertex{neutral}) => x.CREATE\"", `body` = function(x = NULL, ...) {
    return(x$CREATE)
    NULL
  }))
  static_field(cl, "rule c", function() Rule$new(`id` = "/c", `name` = "Movement", `rate` = "σ", `over` = "Ray", `single` = false, `where` = function(it = NULL, ...) {
    return(it$active)
    NULL
  }, `source` = "\"rule /c \\\"Movement\\\" | σ (x: Ray{active}) => x.MOVE\"", `body` = function(x = NULL, ...) {
    return(x$MOVE)
    NULL
  }))
  static_field(cl, "rule 4", function() Rule$new(`id` = "/4", `name` = "Arrival", `rate` = NULL, `over` = "Ray", `single` = false, `where` = NULL, `source` = "\"rule /4 \\\"Arrival\\\" (x: Ray) => x.SETTLE\"", `body` = function(x = NULL, ...) {
    return(x$SETTLE)
    NULL
  }))
  static_field(cl, "rule S.1", function() Rule$new(`id` = "/S.1", `name` = "Emission", `rate` = NULL, `over` = "Boundary", `single` = true, `where` = function(it = NULL, ...) {
    return((if (truthy(.x <- it$emits)) it$vertex$source$spare else .x))
    NULL
  }, `source` = "\"rule /S.1 \\\"Emission\\\" (x: 1 Boundary{emits & vertex.source.spare}) => {\\n  s := x.vertex.source\\n  out := x.ray.steps\\n  if out != None { ... }\\n}\"", `body` = function(x = NULL, ...) {
    s <- x$vertex$source
    out <- x$ray$steps
    if (truthy((!eq(out, NULL)))) {
      out$activate
      .set(s, "momentum", r_sub(s$momentum, x$ray$along))
    }
    NULL
  }))
  method(cl, "strip", function(id = NULL, ...) {
    ink <- Ink$new()
    if (truthy(eq(id, "rule.annihilation"))) {
      return(Strip$of(id, "two rays meet on the edge between two points and annihilate, leaving one neutral point - the other folded into it, and which way it was kept (G/1)", self, lst("/1"), lst(Strip$meeting), ink))
    }
    return(Strip$of(id, "a point nothing stands on is handed back a point of space - the one it held - and every exit it has is lit (G/2): annihilation, run backwards", self, lst("/2"), lst(function(t = NULL, ...) {
      return(Strip$left(t, Strip$meeting, lst("/1")))
      NULL
    }), ink))
    NULL
  })
  getter(cl, "movement_film", function() {
    ink <- Ink$new()
    .set(ink, "every", TRUE)
    w <- Strip$line(self, 10)
    Strip$light(w, 0, 1)
    lanes <- lst(Strip$lane(w, ink))
    .r <- for_range(8, function(t) {
      Strip$begin(w)
      Strip$run(w, lst("/c", "/4"))
      m_push(lanes, Strip$lane(w, ink))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(Strip$tell("rule.movement", "every active ray goes one step along its own exit, c-bar, into its neighbour, every tick (G/c, settled by G/4)", lanes, ink))
    NULL
  })
  getter(cl, "emission_film", function() {
    ink <- Ink$new()
    .set(ink, "every", TRUE)
    .set(ink, "top", 36)
    w <- Strip$line(self, 17)
    w$add(Scripted$new(at = Vector$new(components = lst(8)), plan = lst("", "+", "-", "", "+-", "", "+", "-"), weight = 1))
    lanes <- lst(Strip$lane(w, ink))
    .r <- for_range(8, function(t) {
      Strip$begin(w)
      Strip$run(w, lst("/c", "/4"))
      moved <- Strip$lane(w, ink)
      Strip$run(w, lst("/S.1"))
      now <- Strip$lane(w, ink)
      .set(now, "says", Strip$emitting(moved, now))
      m_push(lanes, now)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(Strip$tell("rule.emission", "a source on a line, held, choosing each tick whether to light a way and which: nothing, left, right or both - what it lights is the NEIGHBOUR's ray on that heading, and every ray already out moves on a step a tick (G/S.1, with G/c and G/4)", lanes, ink))
    NULL
  })
  getter(cl, "transport_film", function() {
    ink <- Ink$new()
    .set(ink, "every", TRUE)
    .set(ink, "top", 36)
    w <- Strip$line(self, 21)
    s <- w$add(Scripted$new(at = Vector$new(components = lst(9)), plan = lst("+-", "", "", "", "+-"), weight = 4))
    .set(s, "moves", TRUE)
    .set(s, "momentum", Vector$new(components = lst(1)))
    lanes <- lst(Strip$lane(w, ink))
    .r <- for_range(9, function(t) {
      Strip$begin(w)
      Strip$run(w, lst("/c", "/4"))
      moved <- Strip$lane(w, ink)
      Strip$run(w, lst("/S.1"))
      emitted <- Strip$emitting(moved, Strip$lane(w, ink))
      Strip$run(w, lst("/S.v"))
      now <- Strip$lane(w, ink)
      went <- ""
      if (truthy(s$stepped)) {
        .w("went", (if (truthy(gt(elem(w$geometry$V(s$moved_along)$components, 0), 0))) "steps right" else "steps left"))
      }
      .set(now, "says", (if (truthy(m_empty(went))) emitted else ((if (truthy(m_empty(emitted))) went else "" %+% text_of(went) %+% ", " %+% text_of(emitted) %+% ""))))
      m_push(lanes, now)
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    return(Strip$tell("rule.transport", "a source carrying a quarter of a step a tick: it stands still while the rays it lit run off at c-bar, and steps once it has earned a whole step - its choice each tick is to stand still or to go (G/S.v, with G/S.1, G/c and G/4)", lanes, ink))
    NULL
  })
  getter(cl, "expansion", function() {
    ink <- Ink$new()
    .set(ink, "every", TRUE)
    return(Strip$film("space.expansion", "one point on a line and nothing else, and every rule of the vacuum run on it a tick at a time: it splits (G/2), its rays go out a step a tick (G/c), and where two meet they fold back into one (G/1) - the ends have nothing to meet and are new space, so the line grows by a point each way every tick", self, Strip$point, 8, ink))
    NULL
  })
  getter(cl, "shadow", function() {
    env <- Node$new()
    .set(env, key_("\\bar{m}"), 1)
    MODEL <- Model$new(theory = self)$value_of("b_{c}", env)
    GR <- r_mul(3, m_sqrt(3))
    CRIT <- lst(GR, MODEL)
    W <- 900
    H <- 420
    SPAN <- 12
    BACK <- "#08090d"
    what <- "the same mass, the same camera - general relativity left of the seam, this model right. The bright ring is where rays pile up; the dashed arcs are the two critical impact parameters, " %+% text_of(Fmt$fixed(GR, 3)) %+% " and " %+% text_of(Fmt$fixed(MODEL, 3)) %+% " m-bar, and the step at the seam is the " %+% text_of(Fmt$fixed(r_mul(100, (r_sub(r_div(MODEL, GR), 1))), 2)) %+% " per cent the metric gives"
    return(Picture$still("gravity.shadow", what, W, H, function(s = NULL, ...) {
      s$clear_rect(0, 0, W, H)
      s$fill_style(BACK)
      s$fill_rect(0, 0, W, H)
      cx <- r_div(W, 2)
      cy <- r_div(H, 2)
      k <- r_div(Fmt$min(W, H), (r_mul(2, SPAN)))
      s$line_width(1.6)
      .r <- for_range(2, function(side) {
        crit <- elem(CRIT, side)
        from_ <- (if (truthy(eq(side, 0))) r_div(pi, 2) else r_sub(0, r_div(pi, 2)))
        px <- r_add(m_floor(Fmt$hypot(cx, cy)), 1)
        while (truthy(ge(px, 0))) {
          b_ <- r_div(px, k)
          colour <- "rgb(0,0,0)"
          if (truthy(ge(b_, crit))) {
            ring <- Fmt$max(0, r_sub(1, r_div(m_abs((r_sub(b_, crit))), 0.45)))
            glow <- r_mul(0.30, Fmt$min(1, r_div(3.2, (r_add(r_sub(b_, crit), 1.6)))))
            v <- Fmt$min(1, r_add(r_mul(ring, 0.95), glow))
            .w("colour", "rgb(" %+% text_of(m_round(Fmt$min(255, r_add(8, r_mul(v, 250))))) %+% "," %+% text_of(m_round(Fmt$min(255, r_add(9, r_mul(v, 175))))) %+% "," %+% text_of(m_round(Fmt$min(255, r_add(13, r_mul(v, 105))))) %+% ")")
          }
          s$stroke_style(colour)
          s$begin_path
          s$arc(cx, cy, px, from_, r_add(from_, pi))
          s$stroke
          .w("px", r_sub(px, 1))
        }
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      s$stroke_style("rgba(140,147,168,0.35)")
      s$line_width(1)
      s$begin_path
      s$move_to(cx, 0)
      s$line_to(cx, H)
      s$stroke
      s$dash(lst(3, 4))
      s$stroke_style("rgba(140,147,168,0.65)")
      .r <- for_range(2, function(side) {
        from_ <- (if (truthy(eq(side, 0))) r_div(pi, 2) else r_sub(0, r_div(pi, 2)))
        s$begin_path
        s$arc(cx, cy, r_mul(elem(CRIT, side), k), from_, r_add(from_, pi))
        s$stroke
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      s$dash(lst())
      s$font("11px system-ui, sans-serif")
      s$fill_style("rgba(140,147,168,0.9)")
      s$text_align("right")
      s$fill_text("general relativity · " %+% text_of(Fmt$fixed(GR, 3)) %+% " m̄", r_sub(cx, 10), r_sub(H, 12))
      s$text_align("left")
      return(s$fill_text("this model · " %+% text_of(Fmt$fixed(MODEL, 3)) %+% " m̄", r_add(cx, 10), r_sub(H, 12)))
      NULL
    }))
    NULL
  })
  method(cl, "pair", function(id = NULL, how = NULL, what = NULL, ...) {
    VIEW <- 20
    MARGIN <- 20
    GAP <- 20
    WAYS <- 4096
    MX <- 0.00006
    V_PASS <- 0.02
    PASS_GAP <- 16
    TICKS <- (if (truthy(eq(how, "thrown"))) 64 else ((if (truthy(eq(how, "passing"))) 16 else 2)))
    V0 <- 0.3
    RUN <- (if (truthy(eq(how, "rest"))) 2 else ((if (truthy(eq(how, "passing"))) 120 else 150)))
    K <- 3
    N <- r_add(r_mul(r_mul(2, (r_add(VIEW, MARGIN))), K), 1)
    coarse <- r_add(r_mul(2, (r_add(VIEW, MARGIN))), 1)
    ORBIT_R <- (if (truthy(eq(how, "rest"))) 12 else 36)
    NEAR_R <- r_div(ORBIT_R, 3)
    BURN <- r_mul(2, (r_add(VIEW, MARGIN)))
    LAW <- Aggregate$of(self)
    TURNS <- 3
    MEAN_R <- r_div((r_add(ORBIT_R, NEAR_R)), 2)
    V_MEAN <- LAW$circling(r_mul(MX, WAYS), MEAN_R, r_div(MEAN_R, 2))
    PERIOD <- (if (truthy(Fmt$finite(V_MEAN))) r_div(r_mul((2 * pi), (r_div(MEAN_R, 2))), V_MEAN) else r_mul(64, RUN))
    .w("TICKS", (if (truthy(eq(how, "thrown"))) r_mul(2, (r_add(m_floor((r_div(r_mul(TURNS, PERIOD), r_mul(2, RUN)))), 1))) else TICKS))
    V_ORBIT <- elem(LAW$launches(lst(r_mul(MX, WAYS), r_mul(MX, WAYS)), lst(0, ORBIT_R), lst(0, NEAR_R), FALSE, 3), 1)
    world <- "" %+% text_of(self$lattice$name) %+% "/D" %+% text_of(self$lattice$D) %+% "/slice"
    stamp <- "" %+% text_of(world) %+% "/" %+% text_of(coarse) %+% "/" %+% text_of(WAYS) %+% "/" %+% text_of(GAP) %+% "/" %+% text_of(MX) %+% "/" %+% text_of(TICKS) %+% "/" %+% text_of(V0) %+% "/" %+% text_of(VIEW) %+% ""
    .w("stamp", (if (truthy(eq(how, "held"))) "" %+% text_of(stamp) %+% "/held/" %+% text_of(N) %+% "/" %+% text_of(TICKS) %+% "/" %+% text_of(RUN) %+% "" else ((if (truthy(eq(how, "passing"))) "" %+% text_of(stamp) %+% "/passing/" %+% text_of(V_PASS) %+% "/" %+% text_of(PASS_GAP) %+% "/" %+% text_of(N) %+% "/" %+% text_of(TICKS) %+% "/" %+% text_of(RUN) %+% "" else "" %+% text_of(stamp) %+% "/orbit-derived"))))
    p <- Setup$new(id = id, what = what, width = 900, height = 460, theory = self, view = function(t = NULL, ...) {
      return((if (truthy(eq(how, "passing"))) VIEW else Fmt$max(r_add(r_div(GAP, 2), 6), Fmt$min(VIEW, r_add(r_add(r_div(GAP, 2), 6), t)))))
      NULL
    }, place = function(setup = NULL, ...) {
      R <- ORBIT_R
      V <- (if (truthy(Fmt$finite(V_ORBIT))) V_ORBIT else 0)
      return(m_map(lst(neg(1), 1), function(sign = NULL, ...) {
        b_ <- Body$new(x = r_div(r_mul(sign, GAP), 2), y = 0, mx = MX, ways = WAYS)
        .set(b_, "tag", r_add(r_div((r_add(sign, 1)), 2), 1))
        if (truthy((if (truthy(.x <- eq(how, "thrown"))) .x else eq(how, "rest")))) {
          .set(b_, "x", r_div(r_mul(sign, R), 2))
          .set(b_, "y", 0)
          .set(b_, "moves", TRUE)
          .set(b_, "py", (if (truthy(eq(how, "rest"))) 0 else r_sub(0, r_mul(r_mul(r_mul(sign, V), MX), WAYS))))
          if (truthy(eq(how, "thrown"))) {
            .set(b_, "launch", "orbit")
            .set(b_, "ecc", r_div(r_sub(ORBIT_R, NEAR_R), r_add(ORBIT_R, NEAR_R)))
            .set(b_, "py", r_sub(0, sign))
          }
        }
        if (truthy(eq(how, "passing"))) {
          .set(b_, "x", r_sub(0, r_mul(sign, (r_sub(VIEW, 2)))))
          .set(b_, "y", r_div(r_mul(sign, PASS_GAP), 2))
          .set(b_, "moves", TRUE)
          .set(b_, "px", r_mul(r_mul(r_mul(sign, V_PASS), MX), WAYS))
          .set(b_, "py", 0)
        }
        return(b_)
        NULL
      }))
      NULL
    })
    .set(p, "found", lst(lst(ORBIT_R, V_ORBIT, LAW$pull(r_mul(MX, WAYS), ORBIT_R), (if (truthy(Fmt$finite(V_ORBIT))) 1 else 0), NEAR_R)))
    .set(p, "VIEW", VIEW)
    .set(p, "MARGIN", MARGIN)
    .set(p, "GAP", GAP)
    .set(p, "A", 8)
    .set(p, "K", K)
    .set(p, "PIX", K)
    .set(p, "TICKS", TICKS)
    .set(p, "RUN", RUN)
    .set(p, "BURN", BURN)
    .set(p, "tags", 3)
    .set(p, "bodies", 2)
    .set(p, "stamp", stamp)
    .set(p, "spent", function(at = NULL, ...) {
      if (truthy((if (truthy(.x <- eq(how, "thrown"))) .x else eq(how, "passing")))) {
        m_every(at, function(b_ = NULL, ...) {
          return(gt(Fmt$hypot(b_$x, b_$y), VIEW))
          NULL
        })
      }
      NULL
    })
    return(Panel$of(p))
    NULL
  })
  getter(cl, "solar", function() {
    SOLAR <- Measured$of("solar-inner")
