    GM <- mem(SOLAR$columns, key_("GM"))
    AX <- mem(SOLAR$columns, key_("a"))
    EC <- mem(SOLAR$columns, key_("e"))
    PER <- mem(SOLAR$columns, key_("period"))
    RAD <- mem(SOLAR$columns, key_("radius"))
    COLOUR <- Node$new()
    .set(COLOUR, key_("Mercury"), "#9a9a9a")
    .set(COLOUR, key_("Venus"), "#e8d3a0")
    .set(COLOUR, key_("Earth"), "#4a90e2")
    .set(COLOUR, key_("Mars"), "#c1440e")
    PLANETS <- filt(rng(len(NAMES)), function(i = NULL, ...) {
      return(gt(elem(PER, i), 0))
      NULL
    })
    AU <- 149597870.7
    CKM <- 299792.458
    REACH <- 0
    .r <- for_each(PLANETS, function(i) {
      .w("REACH", Fmt$max(REACH, r_mul(elem(AX, i), (r_add(1, elem(EC, i))))))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    INNER <- 1000000
    .r <- for_each(PLANETS, function(i) {
      .w("INNER", Fmt$min(INNER, elem(AX, i)))
      CONTINUE
    })
    if (!is.null(.r)) return(.r[[1]])
    VIEW <- m_round((r_div(r_mul(12, REACH), INNER)))
    MARGIN <- m_round((r_div(VIEW, 3)))
    ANGLES <- 8
    PER_C <- 3
    N <- r_add(r_mul(r_mul(2, (r_add(VIEW, MARGIN))), PER_C), 1)
    CELL_AU <- r_div(REACH, VIEW)
    cells <- function(au = NULL, ...) {
      return(r_div(au, CELL_AU))
      NULL
    }
    TICKS <- 16
    RUN <- 400
    SUN_PULSE <- 0.00006
    WAYS_SUN <- 4096
    WAYS_PLANET <- 8
    ways <- function(i = NULL, ...) {
      return((if (truthy(eq(i, 0))) WAYS_SUN else WAYS_PLANET))
      NULL
    }
    pulse <- function(i = NULL, ...) {
      return((if (truthy(eq(i, 0))) SUN_PULSE else r_div(r_mul(r_div(r_mul(SUN_PULSE, WAYS_SUN), WAYS_PLANET), elem(GM, i)), elem(GM, 0))))
      NULL
    }
    per_planet <- m_join(m_map(PLANETS, function(i = NULL, ...) {
