      return("" %+% text_of(elem(NAMES, i)) %+% ":" %+% text_of(a_text) %+% ":" %+% text_of((ways)(i)) %+% ":" %+% text_of(Fmt$fixed(r_div(elem(GM, i), elem(GM, 0)), 12)) %+% "")
      NULL
    }), ",")
    world <- "" %+% text_of(self$lattice$name) %+% "/D" %+% text_of(self$lattice$D) %+% "/slice"
    stamp <- "" %+% text_of(world) %+% "/" %+% text_of(N) %+% "/" %+% text_of(VIEW) %+% "/" %+% text_of(RUN) %+% "/" %+% text_of(TICKS) %+% "/" %+% text_of(WAYS_SUN) %+% "/" %+% text_of(SUN_PULSE) %+% "/" %+% text_of(WAYS_PLANET) %+% "/" %+% text_of(per_planet) %+% "/solved"
    p <- Setup$new(id = "solar.inner", what = "JPL's inner solar system laid on the derivation's own scale: the Sun held, each planet at its semi-major axis and launched at the circling speed the record's slope there gives (the recorder prints v times the root of R for each, one number under an inverse-square pull) - and left to the medium, so where the planets go is what the derivation says, against Kepler", width = 900, height = 460, theory = self, view = function(t = NULL, ...) {
      return(VIEW)
      NULL
    }, place = function(setup = NULL, ...) {
      sun <- Body$new(x = 0, y = 0, mx = (pulse)(0), ways = (ways)(0))
      .set(sun, "tag", 1)
      out <- lst(sun)
      .r <- for_range(len(PLANETS), function(k) {
        i <- elem(PLANETS, k)
        b_ <- Body$new(x = (cells)(r_mul(elem(AX, i), (r_add(1, elem(EC, i))))), y = 0, mx = (pulse)(i), ways = (ways)(i))
        .set(b_, "tag", r_add(2, k))
        .set(b_, "moves", TRUE)
        v <- (if (truthy((if (truthy(.x <- gt(len(setup$found), k))) Fmt$finite(elem(elem(setup$found, k), 1)) else .x))) elem(elem(setup$found, k), 1) else 0)
        .set(b_, "py", r_sub(0, r_mul(r_mul(v, (pulse)(i)), (ways)(i))))
        .set(b_, "launch", "orbit")
        .set(b_, "ecc", elem(EC, i))
        .set(b_, "py", r_sub(0, 1))
        m_push(out, b_)
        CONTINUE
      })
      if (!is.null(.r)) return(.r[[1]])
      return(out)
      NULL
    })
    BURN <- r_mul(2, (r_add(VIEW, MARGIN)))
    LAW <- Aggregate$of(self)
    SUN <- r_mul((pulse)(0), (ways)(0))
    OUTER <- m_last(PLANETS)
    A_OUT <- (cells)(elem(AX, OUTER))
    V_OUT <- LAW$circling(SUN, A_OUT, A_OUT)
    YEAR <- (if (truthy(Fmt$finite(V_OUT))) r_div(r_mul((2 * pi), A_OUT), V_OUT) else r_mul(16, RUN))
    .w("TICKS", r_add(m_floor((r_div(YEAR, RUN))), 1))
    MASSES <- m_concat(lst(SUN), m_map(PLANETS, function(i = NULL, ...) {
      return(r_mul((pulse)(i), (ways)(i)))
      NULL
    }))
    FARS <- m_concat(lst(0), m_map(PLANETS, function(i = NULL, ...) {
      return((cells)(r_mul(elem(AX, i), (r_add(1, elem(EC, i))))))
      NULL
    }))
    NEARS <- m_concat(lst(0), m_map(PLANETS, function(i = NULL, ...) {
      return((cells)(r_mul(elem(AX, i), (r_sub(1, elem(EC, i))))))
      NULL
    }))
    SPEEDS <- LAW$launches(MASSES, FARS, NEARS, TRUE, 3)
    .set(p, "found", m_map(PLANETS, function(i = NULL, ...) {
      k <- r_add(m_index_of(PLANETS, i), 1)
      return(lst(elem(FARS, k), elem(SPEEDS, k), LAW$pull(SUN, elem(FARS, k)), (if (truthy(gt(elem(SPEEDS, k), 0))) 1 else 0), elem(NEARS, k)))
      NULL
    }))
    .set(p, "VIEW", VIEW)
    .set(p, "MARGIN", MARGIN)
    .set(p, "A", ANGLES)
    .set(p, "K", PER_C)
    .set(p, "PIX", PER_C)
    .set(p, "TICKS", TICKS)
    .set(p, "RUN", RUN)
    .set(p, "BURN", BURN)
    .set(p, "tags", r_add(2, len(PLANETS)))
    .set(p, "bodies", r_add(1, len(PLANETS)))
    .set(p, "GAP", r_mul(2, VIEW))
    .set(p, "stamp", "" %+% text_of(stamp) %+% "/" %+% text_of(TICKS) %+% "")
    .set(p, "colours", m_map(PLANETS, function(i = NULL, ...) {
      return(or_else(elem(COLOUR, elem(NAMES, i)), "#eef0f5"))
      NULL
    }))
    .set(p, "ring", function(k = NULL, ...) {
      return((if (truthy(eq(k, 0))) "#f0b429" else (or_else(elem(COLOUR, elem(NAMES, elem(PLANETS, r_sub(k, 1)))), "#eef0f5"))))
      NULL
    })
    return(Panel$of(p))
    NULL
  })
