    .set(x, "momentum", r_add(x$momentum, r_mul(m_first(x$cells)$sinks, x$mass)))
    if (truthy(gt(x$momentum$norm, x$mass))) {
      .set(x, "momentum", r_mul(x$momentum$unit, x$mass))
    }
    .set(x, "advance", r_add(x$advance, r_mul(x$momentum, (r_div(1, x$mass)))))
    g <- x$world$geometry
    d <- elem(m_most(rng(g$DEG), function(e = NULL, ...) {
      return(x$advance$along(g$V(e)))
      NULL
    }), 1)
    if (truthy(ge(x$advance$along(g$V(d)), g$steps(d)))) {
      there <- x$ahead(d)
      if (truthy((if (truthy(.x <- m_every(there, function(v = NULL, ...) {
        return((!eq(v, NULL)))
        NULL
      }))) m_every(there, function(v = NULL, ...) {
        return((if (truthy(.x <- v$vacuum)) .x else eq(v$source, x)))
        NULL
      }) else .x))) {
        .r <- for_each(x$cells, function(c) {
          .set(c, "source", NULL)
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        .set(x, "cells", there)
        .r <- for_each(x$cells, function(c) {
          .set(c, "source", x)
          CONTINUE
        })
        if (!is.null(.r)) return(.r[[1]])
        .set(x, "advance", r_sub(x$advance, r_mul(g$V(d), g$steps(d))))
        lean <- m_first(x$cells)$drift(d)
        .set(x, "advance", r_add(x$advance, lean))
        .set(x, "momentum", r_mul((r_add(x$momentum$unit, lean))$unit, x$momentum$norm))
        .set(x, "stepped", TRUE)
        .set(x, "moved_along", d)
      }
    }
    NULL
  }))
